def effect_driven_switch_transition_facts(
    switch_board: BoardView,
    origin_binding: ActiveBenchTransitionOriginBindingFacts,
    target_result: Optional[SimulationResult],
) -> ActiveBenchTransitionFacts:
    if (
        origin_binding.origin == ActiveBenchTransitionOrigin.RETREAT
        or origin_binding.origin not in {
            ActiveBenchTransitionOrigin.SURFING_BEACH,
            ActiveBenchTransitionOrigin.SUGURI,
            ActiveBenchTransitionOrigin.BOSS_FORCED_SWITCH,
        }
    ):
        return _unsupported_active_bench_transition(
            origin_binding,
            "transition_origin_not_supported",
        )
    if target_result is None or not _result_option_is_current(
        switch_board,
        target_result,
    ):
        return _unsupported_active_bench_transition(
            origin_binding,
            "transition_target_missing",
        )
    target = switch_board.option_target(target_result.option)
    return active_bench_transition_facts(
        switch_board,
        origin_binding=origin_binding,
        target_decision_option_index=target_result.index,
        target=target,
        projected_active_status=ActiveSpecialConditionFacts(
            asleep=False,
            paralyzed=False,
            confused=False,
            burned=False,
            poisoned=False,
        ),
        status_exact=True,
    )


def _retreat_discarded_energy_facts(
    board: BoardView,
    result: Optional[SimulationResult],
) -> Optional[AttachedEnergyPublicFacts]:
    if result is None or not _result_option_is_current(board, result):
        return None
    if (
        getattr(getattr(board, "select", None), "context", None)
        not in {
            SelectContext.DISCARD_ENERGY,
            SelectContext.DISCARD_ENERGY_CARD,
        }
        or getattr(result.option, "type", None)
        not in {OptionType.ENERGY, OptionType.ENERGY_CARD}
    ):
        return None
    active = getattr(board, "active", None)
    if active is None or board.option_target(result.option) is not active:
        return None
    active_facts, reason = _pokemon_public_snapshot_facts_with_reason(
        board,
        active,
    )
    if active_facts is None or reason is not None:
        return None
    energy_cards = tuple(getattr(active, "energyCards", None) or ())
    option_serial = getattr(result.option, "serial", None)
    energy_index = getattr(result.option, "energyIndex", None)
    selected = None
    if type(energy_index) is int and 0 <= energy_index < len(energy_cards):
        selected = energy_cards[energy_index]
        if (
            type(option_serial) is int
            and getattr(selected, "serial", None) != option_serial
        ):
            return None
    elif type(option_serial) is int:
        matches = tuple(
            card
            for card in energy_cards
            if getattr(card, "serial", None) == option_serial
        )
        if len(matches) != 1:
            return None
        selected = matches[0]
    if selected is None:
        return None
    selected_id = getattr(selected, "id", None)
    selected_serial = getattr(selected, "serial", None)
    if type(selected_id) is not int or type(selected_serial) is not int:
        return None
    option_card_id = getattr(result.option, "cardId", None)
    if option_card_id is not None and option_card_id != selected_id:
        return None
    matches = tuple(
        facts
        for facts in active_facts.attached_energy
        if facts.card_id == selected_id and facts.serial == selected_serial
    )
    return matches[0] if len(matches) == 1 else None


def retreat_transition_origin_binding_facts(
    origin_board: BoardView,
    origin_result: Optional[SimulationResult],
    discard_steps: Sequence[Tuple[BoardView, SimulationResult]],
    switch_board: BoardView,
) -> ActiveBenchTransitionOriginBindingFacts:
    origin_index = getattr(origin_result, "index", None)
    unsupported = lambda: _unsupported_effect_transition_origin_binding(
        "retreat_energy_discard_unresolved",
        origin=ActiveBenchTransitionOrigin.RETREAT,
        origin_decision_option_index=origin_index,
    )
    if (
        origin_result is None
        or not _result_option_is_current(origin_board, origin_result)
        or getattr(origin_result.option, "type", None) != OptionType.RETREAT
        or getattr(getattr(origin_board, "select", None), "context", None)
        != SelectContext.MAIN
        or not bool(getattr(origin_result.outcome, "supported", False))
        or bool(getattr(getattr(origin_board, "state", None), "retreated", False))
    ):
        return unsupported()
    active = getattr(origin_board, "active", None)
    active_data = (
        origin_board.data(origin_board.pid(active))
        if active is not None
        else None
    )
    raw_cost = getattr(active_data, "retreatCost", None)
    if (
        active is None
        or type(raw_cost) is not int
        or raw_cost < 0
        or OpponentPublicThreatEvaluator(
            origin_board,
        )._public_retreat_effect_unsupported_reason(active) is not None
    ):
        return unsupported()
    cost = ImmediateOutcomeEvaluator(origin_board)._effective_retreat_cost(
        active,
    )
    steps = tuple(discard_steps or ())
    if len(steps) != cost:
        return unsupported()
    origin_key = _effect_sequence_state_key(origin_board)
    expected_key = (
        None
        if origin_key is None
        else (
            origin_key[0],
            origin_key[1] + 1,
            origin_key[2],
            origin_key[3],
        )
    )
    origin_our = _public_transition_side_signature(
        origin_board,
        opponent=False,
    )
    origin_opponent = _public_transition_side_signature(
        origin_board,
        opponent=True,
    )
    if (
        expected_key is None
        or origin_our is None
        or origin_opponent is None
        or getattr(origin_board, "my_index", None) != origin_key[2]
    ):
        return unsupported()
    remaining_energy = list(origin_our[0].attached_energy)
    selected_serials = set()
    for step_index, step in enumerate(steps):
        if not isinstance(step, tuple) or len(step) != 2:
            return unsupported()
        discard_board, discard_result = step
        expected_active = replace(
            origin_our[0],
            attached_energy=tuple(remaining_energy),
        )
        if (
            _effect_sequence_state_key(discard_board) != expected_key
            or _public_transition_side_signature(
                discard_board,
                opponent=False,
            )
            != (expected_active, origin_our[1], origin_our[2])
            or _public_transition_side_signature(
                discard_board,
                opponent=True,
            )
            != origin_opponent
            or getattr(
                getattr(discard_board, "select", None),
                "remainEnergyCost",
                None,
            )
            != cost - step_index
        ):
            return unsupported()
        selected = _retreat_discarded_energy_facts(
            discard_board,
            discard_result,
        )
        if selected is None or selected.serial in selected_serials:
            return unsupported()
        selected_serials.add(selected.serial)
        remaining_energy = [
            facts
            for facts in remaining_energy
            if facts.serial != selected.serial
        ]

    final_active = replace(
        origin_our[0],
        attached_energy=tuple(remaining_energy),
    )
    if (
        _effect_sequence_state_key(switch_board) != expected_key
        or getattr(getattr(switch_board, "select", None), "context", None)
        != SelectContext.SWITCH
        or getattr(
            getattr(getattr(switch_board, "select", None), "effect", None),
            "id",
            None,
        )
        is not None
        or not bool(getattr(getattr(switch_board, "state", None), "retreated", False))
        or _public_transition_side_signature(
            switch_board,
            opponent=False,
        )
        != (final_active, origin_our[1], origin_our[2])
        or _public_transition_side_signature(
            switch_board,
            opponent=True,
        )
        != origin_opponent
    ):
        return unsupported()
    acting_player_index = getattr(origin_board, "my_index", None)
    if (
        acting_player_index not in {0, 1}
        or getattr(switch_board, "my_index", None) != acting_player_index
    ):
        return unsupported()
    return ActiveBenchTransitionOriginBindingFacts(
        supported=True,
        origin=ActiveBenchTransitionOrigin.RETREAT,
        acting_player_index=acting_player_index,
        affected_player_index=acting_player_index,
        origin_decision_option_index=origin_result.index,
        origin_option_type=OptionType.RETREAT,
        origin_option_card_id=None,
        expected_switch_effect_id=None,
        binding_exact=True,
        unsupported_reason=None,
    )


def retreat_transition_facts(
    origin_board: BoardView,
    origin_result: Optional[SimulationResult],
    discard_steps: Sequence[Tuple[BoardView, SimulationResult]],
    switch_board: BoardView,
    target_result: Optional[SimulationResult],
) -> ActiveBenchTransitionFacts:
    binding = retreat_transition_origin_binding_facts(
        origin_board,
        origin_result,
        discard_steps,
        switch_board,
    )
    if not binding.supported:
        return _unsupported_active_bench_transition(
            binding,
            binding.unsupported_reason or "retreat_energy_discard_unresolved",
        )
    if target_result is None or not _result_option_is_current(
        switch_board,
        target_result,
    ):
        return _unsupported_active_bench_transition(
            binding,
            "transition_target_missing",
        )
    return active_bench_transition_facts(
        switch_board,
        origin_binding=binding,
        target_decision_option_index=target_result.index,
        target=switch_board.option_target(target_result.option),
        projected_active_status=ActiveSpecialConditionFacts(
            asleep=False,
            paralyzed=False,
            confused=False,
            burned=False,
            poisoned=False,
        ),
        status_exact=True,
    )


class ImmediateOutcomeEvaluator:
    def __init__(self, board: BoardView):
        self.b = board
        self._surfing_beach_fact_cache: Dict[
            Tuple[int, bool],
            Tuple[SwitchTargetAttackFacts, ...],
        ] = {}
        self._current_active_attack_candidate_cache: Optional[
            AttackCandidateCollection
        ] = None
        self._switch_target_attack_candidate_cache: Dict[
            int, AttackCandidateCollection
        ] = {}

    def is_surfing_beach_ability(self, option: Any) -> bool:
        if option.type != OptionType.ABILITY or option.area != AreaType.STADIUM:
            return False
        if not any(candidate is option for _, candidate in self.b.iter_options()):
            return False
        index = getattr(option, "index", None)
        stadium = getattr(getattr(self.b, "state", None), "stadium", None) or ()
        if index is None or not 0 <= int(index) < len(stadium):
            return False
        return card_id(stadium[int(index)]) == SURFING_BEACH

    def is_surfing_beach_play_ability_available(self, option: Any) -> bool:
        if option.type != OptionType.PLAY or self.b.option_card(option) != SURFING_BEACH:
            return False
        state = getattr(self.b, "state", None)
        if getattr(state, "stadiumPlayed", False):
            return False
        stadium = getattr(state, "stadium", None) or ()
        if stadium and card_id(stadium[0]) == SURFING_BEACH:
            return False
        return any(candidate is option for _, candidate in self.b.iter_options())

    def surfing_beach_candidate_facts(
        self,
        option: Any,
        after_stadium_play: bool = False,
    ) -> Tuple[SwitchTargetAttackFacts, ...]:
        cache_key = (id(option), after_stadium_play)
        cached = self._surfing_beach_fact_cache.get(cache_key)
        if cached is not None:
            return cached
        available = (
            self.is_surfing_beach_play_ability_available(option)
            if after_stadium_play
            else self.is_surfing_beach_ability(option)
        )
        if not available or self.b.active is None:
            return ()

        facts: List[SwitchTargetAttackFacts] = []
        for bench_index, target in enumerate(self.b.bench):
            if not self._can_surfing_beach_switch(
                self.b.active,
                target,
            ):
                continue
            collection = self.switch_target_attack_candidates(target)
            survival = self._survival_retreat_reason(self.b.active)
            if collection.candidates:
                for candidate in collection.candidates:
                    facts.append(
                        SwitchTargetAttackFacts(
                            target_id=self.b.pid(target),
                            target_serial=getattr(
                                target,
                                "serial",
                                None,
                            ),
                            bench_index=bench_index,
                            attack_candidate=candidate,
                            no_legal_attack_confirmed=(
                                collection.no_legal_attack_confirmed
                            ),
                            unsupported_reasons=(
                                collection.unsupported_reasons
                            ),
                            survival=survival,
                        )
                    )
            else:
                facts.append(
                    SwitchTargetAttackFacts(
                        target_id=self.b.pid(target),
                        target_serial=getattr(target, "serial", None),
                        bench_index=bench_index,
                        attack_candidate=None,
                        no_legal_attack_confirmed=(
                            collection.no_legal_attack_confirmed
                        ),
                        unsupported_reasons=(
                            collection.unsupported_reasons
                        ),
                        survival=survival,
                    )
                )
        result = tuple(facts)
        self._surfing_beach_fact_cache[cache_key] = result
        return result

    def surfing_beach_candidate_outcomes(
        self,
        option: Any,
        after_stadium_play: bool = False,
    ) -> Tuple[ImmediateOutcome, ...]:
        outcomes: List[ImmediateOutcome] = []
        for facts in self.surfing_beach_candidate_facts(
            option,
            after_stadium_play=after_stadium_play,
        ):
            candidate = facts.attack_candidate
            if candidate is None:
                outcomes.append(
                    ImmediateOutcome(
                        supported=facts.survival,
                        target_id=facts.target_id,
                        target_serial=facts.target_serial,
                        reasons=(
                            "surfing_beach_candidate_facts",
                            *facts.unsupported_reasons,
                        ),
                    )
                )
                continue
            candidate_outcome = candidate.outcome
            blocked_only = bool(
                candidate_outcome.supported
                and candidate_outcome.blocked
            )
            outcomes.append(
                replace(
                    candidate_outcome,
                    supported=(
                        candidate_outcome.supported
                        and not candidate_outcome.blocked
                    ),
                    target_id=facts.target_id,
                    target_serial=facts.target_serial,
                    reachable_attack_id=candidate.attack_id,
                    reachable_damage=candidate_outcome.damage,
                    reachable_knockout=candidate_outcome.knockout,
                    reachable_prizes_taken=(
                        candidate_outcome.prizes_taken
                    ),
                    reachable_wins_game=(
                        candidate_outcome.wins_game
                    ),
                    reachable_can_continue_attack=(
                        candidate.can_continue_attack is True
                    ),
                    reasons=candidate_outcome.reasons + (
                        ("switch_target_only_blocked_attacks",)
                        if blocked_only
                        else ()
                    ),
                )
            )
        return tuple(outcomes)

    def evaluate_surfing_beach_ability(
        self,
        option: Any,
        after_stadium_play: bool = False,
    ) -> ImmediateOutcome:
        available = (
            self.is_surfing_beach_play_ability_available(option)
            if after_stadium_play
            else self.is_surfing_beach_ability(option)
        )
        if not available:
            return ImmediateOutcome(
                supported=False,
                reasons=("unsupported_surfing_beach_ability",),
            )
        candidates = self.surfing_beach_candidate_facts(
            option,
            after_stadium_play=after_stadium_play,
        )
        if not candidates:
            return ImmediateOutcome(
                supported=False,
                reasons=("surfing_beach_ability_no_target",),
            )
        return ImmediateOutcome(
            supported=True,
            reasons=("surfing_beach_ability_candidates_available",),
        )

    def evaluate_attack(self, option: Any) -> ImmediateOutcome:
        attack = self.b.attack(option.attackId)
        attacker = self.b.active
        target = self.b.opp_active
        reasons: List[str] = []
        if attack is None or attacker is None or target is None:
            return ImmediateOutcome(supported=False, reasons=("missing_attack_state",))

        target_id = self.b.pid(target)
        target_serial = getattr(target, "serial", None)
        bypasses_wall = self._bypasses_ex_wall(attack)
        if bypasses_wall and target_id in EX_ATTACK_WALLS:
            reasons.append("bypasses_ex_wall")

        suguri_applies = self._suguri_damage_boost_applies(
            attacker,
            target,
            attack,
            self._blocked_by_ex_wall(attacker, target, attack),
        )
        damage, blocked, prevention_reason = self.b.resolved_attack_damage(
            attacker,
            attack,
            target,
            additional_damage=30 if suguri_applies else 0,
        )
        if prevention_reason is not None:
            reasons.append(prevention_reason)
        if suguri_applies:
            reasons.append("suguri_damage_boost")
        if prevention_reason == UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON:
            return ImmediateOutcome(
                supported=False, damage=damage, target_id=target_id,
                target_serial=target_serial, reasons=tuple(reasons),
            )
        knockout = damage >= hp_left(target)
        prizes_taken = self.b.prize_value(target) if knockout else 0
        wins_game = prizes_taken >= self.b.my_prizes_left() if knockout else False
        if knockout:
            reasons.append("knockout")
        if wins_game:
            reasons.append("wins_game")

        # The first stage handles only a single active-target KO.
        # Unsupported here: bench/multiple KOs, damage counter KOs, prize modifiers,
        # and attack effects that KO a separate target.
        return ImmediateOutcome(
            blocked=blocked,
            damage=damage,
            knockout=knockout,
            prizes_taken=prizes_taken,
            wins_game=wins_game,
            bypasses_wall=bypasses_wall and target_id in EX_ATTACK_WALLS,
            target_id=target_id,
            target_serial=target_serial,
            reasons=tuple(reasons),
        )
    def evaluate_basic_pokemon_play(
        self,
        option: Any,
    ) -> ImmediateOutcome:
        if option.type != OptionType.PLAY:
            return ImmediateOutcome(
                supported=False,
                reasons=("basic_pokemon_play_required",),
            )

        played_card_id = self.b.option_card(option)
        if (
            played_card_id is None
            or not self.b.is_basic_pokemon(played_card_id)
        ):
            return ImmediateOutcome(
                supported=False,
                reasons=("basic_pokemon_card_required",),
            )

        if self.b.bench_space <= 0:
            return ImmediateOutcome(
                supported=False,
                target_id=played_card_id,
                reasons=("basic_pokemon_play_no_bench_space",),
            )

        adds_board_out_buffer = len(self.b.bench) == 0

        reasons = ["basic_pokemon_play"]
        if adds_board_out_buffer:
            reasons.append(
                "basic_pokemon_play_adds_board_out_buffer"
            )

        return ImmediateOutcome(
            supported=True,
            adds_board_out_buffer=adds_board_out_buffer,
            target_id=played_card_id,
            reasons=tuple(reasons),
    )

    def evaluate_attach(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.ATTACH:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attach_option",))
        card_id = self.b.option_card(option)
        target = self.b.option_target(option)
        if card_id is None or target is None:
            return ImmediateOutcome(supported=False, reasons=("missing_attach_state",))

        card_data = self.b.data(card_id)
        card_type = getattr(card_data, "cardType", None)
        if card_type in {CardType.BASIC_ENERGY, CardType.SPECIAL_ENERGY}:
            return self.evaluate_energy_attach(option)
        if card_type == CardType.TOOL:
            return self.evaluate_tool_attach(option)
        return ImmediateOutcome(
            supported=False,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=("unsupported_attach_card_type",),
        )

    def evaluate_energy_attach(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.ATTACH:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attach_option",))
        card_id = self.b.option_card(option)
        target = self.b.option_target(option)
        if card_id is None or target is None:
            return ImmediateOutcome(supported=False, reasons=("missing_attach_state",))

        extra_tokens = energy_tokens_for_attach(card_id, target)
        if extra_tokens is None:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attach_energy",))

        data = self.b.data(self.b.pid(target))
        if data is None:
            return ImmediateOutcome(supported=False, reasons=("missing_attach_state",))

        before_tokens = tuple(self.b.energy_tokens(target))
        after_tokens = before_tokens + extra_tokens
        after_energy_ids = tuple(self.b.energies(target)) + (int(card_id),)
        before_ids = self._energy_payable_attack_ids(data.attacks, before_tokens)
        after_ids = self._energy_payable_attack_ids(data.attacks, after_tokens)
        enabled_ids = tuple(attack_id for attack_id in after_ids if attack_id not in before_ids)

        reasons: List[str] = []
        if enabled_ids:
            reasons.append("enables_attack")
        else:
            reasons.append("no_new_attack")
        if NEBULA_BEAM in enabled_ids:
            reasons.append("enables_nebula_beam")
        reachable_outcomes: List[ImmediateOutcome] = []
        if target is self.b.active:
            direct_outcome = self._best_attach_reachable_attack_outcome(target, enabled_ids, after_tokens)
            if direct_outcome is not None:
                reachable_outcomes.append(direct_outcome)
        access_outcome = self._best_attach_access_attack_outcome(target, enabled_ids, after_tokens, after_energy_ids)
        if access_outcome is not None:
            reachable_outcomes.append(access_outcome)
        boss_outcome = self._best_attach_boss_attack_outcome(target, enabled_ids, after_tokens)
        if boss_outcome is not None:
            reachable_outcomes.append(boss_outcome)
        reachable_outcome = self._best_reachable_attack_outcome(reachable_outcomes) if reachable_outcomes else None
        immediate_attack_ids = self._unblocked_attack_ids(target, enabled_ids) if target is self.b.active else ()
        if card_id == IGNITION_ENERGY and target is self.b.active and enabled_ids and immediate_attack_ids:
            reasons.append("ignition_immediate_attack")
        if reachable_outcome is not None and reachable_outcome.knockout:
            reasons.append("attach_reaches_knockout")
        if reachable_outcome is not None and reachable_outcome.wins_game:
            reasons.append("attach_reaches_win")
        if reachable_outcome is not None:
            for reason in reachable_outcome.reasons:
                if reason in {
                    "attach_access_via_retreat",
                    "attach_access_via_surfing_beach",
                    "attach_access_via_boss",
                } and reason not in reasons:
                    reasons.append(reason)

        return ImmediateOutcome(
            enables_attack=bool(enabled_ids),
            enabled_attack_ids=enabled_ids,
            reachable_attack_id=reachable_outcome.reachable_attack_id if reachable_outcome is not None else None,
            reachable_damage=reachable_outcome.damage if reachable_outcome is not None else 0,
            reachable_knockout=bool(reachable_outcome and reachable_outcome.knockout),
            reachable_prizes_taken=reachable_outcome.prizes_taken if reachable_outcome is not None else 0,
            reachable_wins_game=bool(reachable_outcome and reachable_outcome.wins_game),
            reachable_can_continue_attack=bool(reachable_outcome and reachable_outcome.reachable_can_continue_attack),
            retreat_energy_cost=reachable_outcome.retreat_energy_cost if reachable_outcome is not None else 0,
            important_energy_loss=reachable_outcome.important_energy_loss if reachable_outcome is not None else 0,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def evaluate_tool_attach(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.ATTACH:
            return ImmediateOutcome(supported=False, reasons=("unsupported_tool_attach_option",))
        card_id = self.b.option_card(option)
        target = self.b.option_target(option)
        if card_id is None or target is None:
            return ImmediateOutcome(supported=False, reasons=("missing_attach_state",))

        target_id = self.b.pid(target)
        target_serial = getattr(target, "serial", None)
        if not any(candidate is target for candidate in self.b.all_my_pokemon):
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=("invalid_tool_attach_target",),
            )
        if getattr(target, "tools", []):
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=("target_already_has_tool",),
            )

        tool_data = self.b.data(card_id)
        if getattr(tool_data, "cardType", None) != CardType.TOOL:
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=("unsupported_tool_attach_card_type",),
            )
        hp_bonus = public_hp_bonus(tool_data)
        effect_kinds = classify_public_effect(tool_data)
        if hp_bonus is None or hp_bonus <= 0 or effect_kinds != (PublicEffectKind.HP_AFFECTING,):
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=("unsupported_tool_attach_effect",),
            )

        incoming_damage = (
            self.b.confirmed_opp_active_damage_for_survival_tool()
            if target is self.b.active
            else 0
        )
        current_hp = hp_left(target)
        next_knockout_without_tool = (
            incoming_damage is not None
            and incoming_damage > 0
            and incoming_damage >= current_hp
        )
        next_knockout_with_tool = (
            incoming_damage is not None
            and incoming_damage > 0
            and incoming_damage >= current_hp + hp_bonus
        )
        next_knockout_avoided = next_knockout_without_tool and not next_knockout_with_tool
        reasons = ["tool_attach", "static_hp_boost"]
        if incoming_damage is None:
            reasons.append("incoming_damage_unconfirmed")
        elif incoming_damage <= 0:
            reasons.append("no_known_incoming_damage")
        elif not next_knockout_without_tool:
            reasons.append("survives_without_tool")
        elif next_knockout_avoided:
            reasons.append("next_knockout_avoided")
        else:
            reasons.append("knockout_not_avoided")

        role = self.b.role_facts(target)
        preserves_primary = next_knockout_avoided and (
            self.b.prize_value(target) > 1
            or role.attack_ready
            or role.energy_count > 0
        )
        return ImmediateOutcome(
            next_knockout_avoided=next_knockout_avoided,
            avoids_prize_loss=next_knockout_avoided,
            prizes_preserved=self.b.prize_value(target) if next_knockout_avoided else 0,
            avoids_board_out=next_knockout_avoided and target is self.b.active and not self.b.bench,
            preserves_primary_pokemon=preserves_primary,
            target_id=target_id,
            target_serial=target_serial,
            reasons=tuple(reasons),
        )

    def _best_attach_reachable_attack_outcome(
        self,
        attacker: Pokemon,
        attack_ids: Sequence[int],
        after_tokens: Sequence[Any],
    ) -> Optional[ImmediateOutcome]:
        if not self.active_can_declare_attack_this_turn():
            return None
        outcomes = [self._attack_outcome_with_tokens(attacker, attack_id, after_tokens, "attach_reachable_attack") for attack_id in attack_ids]
        effective_outcomes = [outcome for outcome in outcomes if outcome.supported and not outcome.blocked]
        if not effective_outcomes:
            return None
        outcome = self._best_reachable_attack_outcome(effective_outcomes)
        attack = self.b.attack(outcome.reachable_attack_id)
        return replace(
            outcome,
            reachable_can_continue_attack=bool(attack and can_continue_attack_after_use_with_tokens(attack, after_tokens)),
        )

    def _best_attach_access_attack_outcome(
        self,
        attach_target: Pokemon,
        attack_ids: Sequence[int],
        after_tokens: Sequence[Any],
        after_energy_ids: Sequence[int],
    ) -> Optional[ImmediateOutcome]:
        if not self._can_declare_attack_after_same_turn_access():
            return None
        access = self._best_same_turn_access(attach_target, bool(attack_ids), after_tokens, after_energy_ids)
        if access is None:
            return None
        outcomes = []
        attackers = (attach_target,) if attach_target in self.b.bench else tuple(self.b.bench)
        for attacker in attackers:
            tokens = after_tokens if attacker is attach_target else self.b.energy_tokens(attacker)
            data = self.b.data(self.b.pid(attacker))
            if data is None:
                continue
            for attack_id in data.attacks:
                outcome = self._attack_outcome_with_tokens(attacker, attack_id, tokens, "attach_access_reachable_attack")
                if outcome.supported and not outcome.blocked:
                    outcomes.append(outcome)
        if not outcomes:
            return None
        best = self._best_reachable_attack_outcome(outcomes)
        return replace(
            best,
            retreat_energy_cost=access.retreat_energy_cost,
            important_energy_loss=access.important_energy_loss,
            reasons=best.reasons + access.reasons,
        )

    def _best_same_turn_access(
        self,
        attach_target: Pokemon,
        attach_enabled_attack: bool,
        after_tokens: Sequence[Any],
        after_energy_ids: Sequence[int],
    ) -> Optional[SameTurnAccess]:
        candidates: List[SameTurnAccess] = []
        if attach_target in self.b.bench and attach_enabled_attack and self._has_surfing_beach_access_option(attach_target):
            candidates.append(SameTurnAccess(("attach_access_via_surfing_beach",), 0, 0))
        retreat_access = self._retreat_access_after_attach(attach_target, after_tokens, after_energy_ids, attach_enabled_attack)
        if retreat_access is not None:
            candidates.append(retreat_access)
        if not candidates:
            return None
        return min(candidates, key=lambda access: (access.retreat_energy_cost, access.important_energy_loss))

    def _retreat_access_after_attach(
        self,
        attach_target: Pokemon,
        after_tokens: Sequence[Any],
        after_energy_ids: Sequence[int],
        attach_enabled_attack: bool,
    ) -> Optional[SameTurnAccess]:
        active = self.b.active
        if active is None:
            return None
        if self.active_status_blocks_attack():
            return None
        cost = self._effective_retreat_cost(active)
        before_tokens = tuple(self.b.energy_tokens(active))
        retreat_tokens = tuple(after_tokens) if attach_target is active else before_tokens
        before_can_retreat = len(before_tokens) >= cost
        after_can_retreat = len(retreat_tokens) >= cost
        if not after_can_retreat:
            return None
        retreat_option_visible = self._has_retreat_access_option()
        if attach_target is active and not before_can_retreat:
            pass
        elif retreat_option_visible and attach_target in self.b.bench and attach_enabled_attack:
            pass
        else:
            return None
        if cost == 0:
            important_loss = 0
        elif attach_target is active:
            important_loss = self._possible_important_energy_loss_from_ids(after_energy_ids, cost)
        else:
            important_loss = self._possible_important_energy_loss(active, cost)
        return SameTurnAccess(("attach_access_via_retreat",), cost, important_loss)

    def _possible_important_energy_loss_from_ids(self, energy_ids: Sequence[int], cost: int) -> int:
        important_cards = sum(1 for energy_id in energy_ids if energy_id in {BASIC_WATER_ENERGY, IGNITION_ENERGY})
        nonimportant_capacity = max(0, len(energy_ids) - important_cards)
        return min(important_cards, max(0, cost - nonimportant_capacity))

    def _best_attach_boss_attack_outcome(
        self,
        attach_target: Pokemon,
        attack_ids: Sequence[int],
        after_tokens: Sequence[Any],
    ) -> Optional[ImmediateOutcome]:
        if attach_target is not self.b.active or not attack_ids:
            return None
        if not self.active_can_declare_attack_this_turn():
            return None
        if self.b.state.supporterPlayed or BEFEHL_VON_BOSS not in self.b.hand_ids or not self.b.opp_bench:
            return None
        if not any(option.type == OptionType.PLAY and self.b.option_card(option) == BEFEHL_VON_BOSS for _, option in self.b.iter_options()):
            return None
        outcomes = []
        for target in self.b.opp_bench:
            for attack_id in attack_ids:
                outcome = self._attack_outcome_with_tokens_against(
                    attach_target,
                    attack_id,
                    after_tokens,
                    target,
                    "attach_boss_reachable_attack",
                )
                if outcome.supported and not outcome.blocked:
                    outcomes.append(outcome)
        if not outcomes:
            return None
        best = self._best_reachable_attack_outcome(outcomes)
        return replace(best, reasons=best.reasons + ("attach_access_via_boss",))

    def evaluate_energy_switch_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != ENERGY_SWITCH:
            return ImmediateOutcome(supported=False, reasons=("unsupported_energy_switch_option",))
        equivalent_attach = self.b.energy_switch_has_equivalent_normal_attach_result()
        if not self.active_can_declare_attack_this_turn():
            return ImmediateOutcome(
                supported=False,
                additional_card_consumed=True,
                equivalent_normal_attach_available=equivalent_attach,
                reasons=("energy_switch_attack_not_declarable",),
            )
        active = self.b.active
        if active is None:
            return ImmediateOutcome(supported=False, additional_card_consumed=True, equivalent_normal_attach_available=equivalent_attach, reasons=("missing_energy_switch_state",))
        data = self.b.data(self.b.pid(active))
        if data is None:
            return ImmediateOutcome(supported=False, additional_card_consumed=True, equivalent_normal_attach_available=equivalent_attach, reasons=("missing_energy_switch_state",))
        before_tokens = tuple(self.b.energy_tokens(active))
        before_ids = self._energy_payable_attack_ids(data.attacks, before_tokens)
        outcomes: List[ImmediateOutcome] = []
        for source in self.b.all_my_pokemon:
            if source is active:
                continue
            for energy_id in self.b.energies(source):
                moved_tokens = energy_tokens_for_attach(energy_id, active)
                if moved_tokens is None:
                    continue
                after_tokens = before_tokens + tuple(moved_tokens)
                after_ids = self._energy_payable_attack_ids(data.attacks, after_tokens)
                enabled_ids = tuple(attack_id for attack_id in after_ids if attack_id not in before_ids)
                for attack_id in enabled_ids:
                    outcome = self._attack_outcome_with_tokens(active, attack_id, after_tokens, "energy_switch_reachable_attack")
                    if outcome.supported and not outcome.blocked:
                        outcomes.append(outcome)
        if not outcomes:
            return ImmediateOutcome(
                supported=True,
                additional_card_consumed=True,
                equivalent_normal_attach_available=equivalent_attach,
                reasons=("energy_switch_no_reachable_attack",),
            )
        best = self._best_reachable_attack_outcome(outcomes)
        reasons = ["energy_switch"]
        if best.knockout:
            reasons.append("energy_switch_reaches_knockout")
        if best.wins_game:
            reasons.append("energy_switch_reaches_win")
        return ImmediateOutcome(
            enables_attack=True,
            enabled_attack_ids=(best.reachable_attack_id,) if best.reachable_attack_id is not None else (),
            reachable_attack_id=best.reachable_attack_id,
            reachable_damage=best.damage,
            reachable_knockout=best.knockout,
            reachable_prizes_taken=best.prizes_taken,
            reachable_wins_game=best.wins_game,
            additional_card_consumed=True,
            equivalent_normal_attach_available=equivalent_attach,
            target_id=self.b.pid(active),
            target_serial=getattr(active, "serial", None),
            reasons=tuple(reasons),
        )

    def _has_retreat_access_option(self) -> bool:
        return any(option.type == OptionType.RETREAT for _, option in self.b.iter_options())

    def _has_surfing_beach_access_option(self, target: Pokemon) -> bool:
        active = self.b.active
        if active is None or not self._can_surfing_beach_switch(active, target):
            return False
        for _, option in self.b.iter_options():
            if self.is_surfing_beach_ability(option):
                return True
            if self.is_surfing_beach_play_ability_available(option):
                return True
        return False

    def _can_declare_attack_after_same_turn_access(self) -> bool:
        state = getattr(self.b, "state", None)
        turn = getattr(state, "turn", None)
        first_player = getattr(state, "firstPlayer", None)
        your_index = getattr(state, "yourIndex", getattr(self.b, "my_index", None))
        if turn == 1 and first_player is not None and your_index is not None and int(first_player) == int(your_index):
            return False
        return True

    def _best_reachable_attack_outcome(self, outcomes: Sequence[ImmediateOutcome]) -> ImmediateOutcome:
        return max(
            outcomes,
            key=lambda outcome: (
                outcome.wins_game,
                outcome.knockout,
                outcome.prizes_taken,
                outcome.damage,
            ),
        )

    def _salvatore_evolve_option(self, evolution_id: int, target: Pokemon) -> Any:
        return SimpleNamespace(
            type=OptionType.EVOLVE,
            cardId=int(evolution_id),
            target=target,
            attackId=None,
            area=None,
            index=None,
            playerIndex=None,
            inPlayArea=AreaType.ACTIVE,
            inPlayIndex=0,
            toolIndex=None,
            energyIndex=None,
            serial=None,
            number=None,
        )

    def _salvatore_active_evolve_attack_facts(
        self,
        target: Optional[Pokemon] = None,
        require_unused_supporter: bool = True,
        evolution_id: Optional[int] = None,
    ) -> List[Tuple[Pokemon, int, ActiveEvolutionAttackFact]]:
        if require_unused_supporter and self.b.state.supporterPlayed:
            return []
        if not self.active_can_declare_attack_this_turn():
            return []
        candidates = [target] if target is not None else self.b.all_my_pokemon
        facts: List[Tuple[Pokemon, int, ActiveEvolutionAttackFact]] = []
        for pokemon in candidates:
            if pokemon is None or pokemon is not self.b.active:
                continue
            candidate_evolution_id = evolution_id or self.b.salvatore_deck_target_evolution(pokemon)
            if candidate_evolution_id is None:
                continue
            if not self.b.salvatore_can_evolve_from_deck_this_turn(pokemon, candidate_evolution_id):
                continue
            option = self._salvatore_evolve_option(candidate_evolution_id, pokemon)
            for fact in self.b.active_evolution_attack_facts(option):
                if fact.supported:
                    facts.append((pokemon, candidate_evolution_id, fact))
        return facts

    def _best_salvatore_active_evolve_attack_fact(
        self,
        target: Optional[Pokemon] = None,
        require_unused_supporter: bool = True,
        evolution_id: Optional[int] = None,
    ) -> Optional[Tuple[Pokemon, int, ActiveEvolutionAttackFact]]:
        facts = self._salvatore_active_evolve_attack_facts(target, require_unused_supporter, evolution_id)
        if not facts:
            return None
        return max(
            facts,
            key=lambda item: (
                not item[2].blocked,
                item[2].wins_game,
                item[2].knockout,
                item[2].prizes_taken,
                item[2].damage,
            ),
        )

    def _active_evolution_fact_to_reachable_outcome(self, target: Pokemon, fact: ActiveEvolutionAttackFact, reason: str) -> ImmediateOutcome:
        reasons = [reason]
        if fact.prevention_reason is not None:
            reasons.append(fact.prevention_reason)
        if fact.knockout:
            reasons.append("reachable_knockout")
        if fact.wins_game:
            reasons.append("reachable_win")
        return ImmediateOutcome(
            supported=fact.supported,
            blocked=fact.blocked,
            reachable_attack_id=fact.attack_id,
            reachable_damage=fact.damage,
            reachable_knockout=fact.knockout,
            reachable_prizes_taken=fact.prizes_taken,
            reachable_wins_game=fact.wins_game,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def evaluate_active_evolution(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.EVOLVE:
            return ImmediateOutcome(supported=False, reasons=("unsupported_active_evolution_option",))
        target = self.b.option_target(option)
        if target is None or target is not self.b.active:
            return ImmediateOutcome(supported=False, reasons=("active_evolution_not_active_target",))
        if not self.active_can_declare_attack_this_turn():
            return ImmediateOutcome(
                supported=False,
                target_id=self.b.pid(target),
                target_serial=getattr(target, "serial", None),
                reasons=("active_evolution_attack_not_declarable",),
            )
        facts = [fact for fact in self.b.active_evolution_attack_facts(option) if fact.supported]
        if not facts:
            return ImmediateOutcome(supported=False, target_id=self.b.pid(target), target_serial=getattr(target, "serial", None), reasons=("active_evolution_no_same_turn_attack_chain",))
        best = max(
            facts,
            key=lambda fact: (
                not fact.blocked,
                fact.wins_game,
                fact.knockout,
                fact.prizes_taken,
                fact.damage,
            ),
        )
        return self._active_evolution_fact_to_reachable_outcome(target, best, "active_evolution_reachable_attack")

    def _salvatore_fact_to_expected_outcome(
        self,
        target: Pokemon,
        fact: ActiveEvolutionAttackFact,
        reason: str,
        probability: float,
    ) -> ImmediateOutcome:
        reasons = [reason, "salvatore_evolution_deck_uncertain"]
        if fact.prevention_reason is not None:
            reasons.append(fact.prevention_reason)
        if fact.knockout:
            reasons.append("expected_reachable_knockout")
        if fact.wins_game:
            reasons.append("expected_reachable_win")
        return ImmediateOutcome(
            supported=fact.supported,
            blocked=fact.blocked,
            expected_reachable_attack_id=fact.attack_id,
            expected_reachable_damage=fact.damage * probability,
            expected_reachable_knockout=fact.knockout,
            expected_reachable_prizes_taken=fact.prizes_taken * probability,
            expected_reachable_wins_game=fact.wins_game,
            expected_hit_probability=probability,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def _best_salvatore_chain_outcome(self, outcomes: Sequence[ImmediateOutcome]) -> ImmediateOutcome:
        return max(
            outcomes,
            key=lambda outcome: (
                outcome.reachable_wins_game or outcome.expected_reachable_wins_game,
                outcome.reachable_knockout or outcome.expected_reachable_knockout,
                outcome.reachable_prizes_taken + outcome.expected_reachable_prizes_taken,
                outcome.reachable_damage + outcome.expected_reachable_damage,
            ),
        )

    def _best_salvatore_active_evolve_attack_outcome(
        self,
        target: Optional[Pokemon] = None,
        reason: str = "salvatore_active_evolve_attack",
        require_unused_supporter: bool = True,
        evolution_id: Optional[int] = None,
        confirmed_evolution_candidate: bool = False,
    ) -> Optional[ImmediateOutcome]:
        outcomes: List[ImmediateOutcome] = []
        for pokemon, candidate_evolution_id, fact in self._salvatore_active_evolve_attack_facts(
            target,
            require_unused_supporter,
            evolution_id,
        ):
            if fact.blocked:
                continue
            if confirmed_evolution_candidate or (self.b.deck_view and candidate_evolution_id in self.b.deck_ids):
                outcomes.append(self._active_evolution_fact_to_reachable_outcome(pokemon, fact, reason))
            else:
                probability = self.b.deck_presence_probability(candidate_evolution_id)
                if probability > 0:
                    outcomes.append(self._salvatore_fact_to_expected_outcome(pokemon, fact, reason, probability))
        return self._best_salvatore_chain_outcome(outcomes) if outcomes else None

    def evaluate_salvatore_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != SALVATORE:
            return ImmediateOutcome(supported=False, reasons=("unsupported_salvatore_play",))
        if self.b.state.supporterPlayed:
            return ImmediateOutcome(supported=True, reasons=("salvatore_supporter_already_used",))
        outcome = self._best_salvatore_active_evolve_attack_outcome(reason="salvatore_play_reachable_attack")
        development = self._best_salvatore_development_outcome()
        if outcome is None:
            if development is None:
                return ImmediateOutcome(supported=True, reasons=("salvatore_no_same_turn_attack_chain",))
            return replace(
                development,
                reasons=development.reasons + ("salvatore_no_same_turn_attack_chain",),
            )
        if development is None:
            return outcome
        direct_damage = self._best_unblocked_damage_from(self.b.active)
        reachable_damage = outcome.reachable_damage
        if reachable_damage <= 0 and outcome.expected_hit_probability > 0:
            reachable_damage = outcome.expected_reachable_damage / outcome.expected_hit_probability
        return replace(
            outcome,
            improves_damage=reachable_damage > direct_damage,
            equivalent_evolution_available=development.equivalent_evolution_available,
            completes_next_attacker=development.completes_next_attacker,
            develops_bench_next_attacker=development.develops_bench_next_attacker,
            evolution_hp_gain=development.evolution_hp_gain,
            completes_evolution_line=development.completes_evolution_line,
            completed_same_line_attackers=development.completed_same_line_attackers,
            same_turn_attack_connected=development.same_turn_attack_connected,
            same_turn_attack_option_count=development.same_turn_attack_option_count,
            post_evolution_ready_attack_count=development.post_evolution_ready_attack_count,
            development_value=development.development_value,
            development_probability=development.development_probability,
        )

    def _salvatore_completed_same_line_attackers(self, evolution_id: int) -> int:
        return sum(
            1
            for pokemon in self.b.all_my_pokemon
            if self.b.pid(pokemon) == evolution_id
            and self._best_unblocked_damage_from(pokemon) > 0
        )

    def _salvatore_development_fact(
        self,
        target: Pokemon,
    ) -> Optional[SalvatoreDevelopmentFacts]:
        evolution_id = self.b.salvatore_deck_target_evolution(target)
        if evolution_id is None:
            return None
        evolution_data = self.b.data(evolution_id)
        base_data = self.b.data(self.b.pid(target))
        if evolution_data is None or base_data is None:
            return None
        probability = self.b.deck_presence_probability(evolution_id)
        if probability <= 0:
            return None
        equivalent = any(
            option.type == OptionType.EVOLVE
            and self.b.option_card(option) == evolution_id
            and self.b.option_target(option) is target
            for _, option in self.b.iter_options()
        )
        tokens = tuple(self.b.energy_tokens_as(target, evolution_id))
        post_evolution_ready_attack_count = 0
        for attack_id in getattr(evolution_data, "attacks", ()):
            attack = self.b.attack(attack_id)
            if attack is None or not can_pay_attack_with_tokens(attack, tokens):
                continue
            if self.b.attack_blocked_for_card(
                evolution_id,
                self.b.opp_active,
                attack,
            ):
                continue
            post_evolution_ready_attack_count += 1
        same_turn_attack_option_count = (
            post_evolution_ready_attack_count
            if target is self.b.active
            and self.active_can_declare_attack_this_turn()
            else 0
        )
        same_turn_attack_connected = same_turn_attack_option_count > 0
        completed_same_line_attackers = (
            self._salvatore_completed_same_line_attackers(evolution_id)
        )
        hp_gain = max(
            0,
            safe_int(getattr(evolution_data, "hp", 0))
            - safe_int(getattr(base_data, "hp", 0)),
        )
        completes_evolution_line = self.b.card_evolves_from_card(
            evolution_id,
            self.b.pid(target),
        )
        develops_bench_next_attacker = (
            target is not self.b.active
            and completes_evolution_line
        )
        # HP gain is the single numeric development axis.  Line completion,
        # next-attacker status, same-line saturation and same-turn attack remain
        # separate facts so none of them re-adds attack damage.
        development_value = (
            max(1, hp_gain)
            * probability
            / (1 + completed_same_line_attackers)
            if completes_evolution_line
            else 0.0
        )
        return SalvatoreDevelopmentFacts(
            base_id=self.b.pid(target),
            base_serial=getattr(target, "serial", None),
            evolution_id=evolution_id,
            source_in_play=target in self.b.all_my_pokemon,
            evolution_searchable=True,
            hp_gain=hp_gain,
            completes_evolution_line=completes_evolution_line,
            develops_bench_next_attacker=develops_bench_next_attacker,
            completed_same_line_attackers=completed_same_line_attackers,
            equivalent_normal_evolution=equivalent,
            same_turn_attack_connected=same_turn_attack_connected,
            same_turn_attack_option_count=same_turn_attack_option_count,
            post_evolution_ready_attack_count=post_evolution_ready_attack_count,
            development_probability=probability,
            development_value=development_value,
        )

    def _salvatore_development_facts(self) -> Tuple[SalvatoreDevelopmentFacts, ...]:
        return tuple(
            fact
            for target in self.b.all_my_pokemon
            for fact in (self._salvatore_development_fact(target),)
            if fact is not None
        )

    def _salvatore_development_outcome(
        self,
        fact: SalvatoreDevelopmentFacts,
    ) -> ImmediateOutcome:
        target = next(
            (
                pokemon
                for pokemon in self.b.all_my_pokemon
                if getattr(pokemon, "serial", None) == fact.base_serial
            ),
            None,
        )
        opp_damage = self.b.opp_max_damage()
        evolution_data = self.b.data(fact.evolution_id)
        evolution_hp = safe_int(getattr(evolution_data, "hp", 0))
        avoids_board_out = (
            target is self.b.active
            and len(self.b.all_my_pokemon) == 1
            and opp_damage > 0
            and hp_left(target) <= opp_damage
            and evolution_hp - damage_on(target) > opp_damage
        )
        return ImmediateOutcome(
            supported=True,
            avoids_board_out=avoids_board_out,
            equivalent_evolution_available=fact.equivalent_normal_evolution,
            completes_next_attacker=fact.post_evolution_ready_attack_count > 0,
            develops_bench_next_attacker=fact.develops_bench_next_attacker,
            evolution_hp_gain=fact.hp_gain,
            completes_evolution_line=fact.completes_evolution_line,
            completed_same_line_attackers=fact.completed_same_line_attackers,
            same_turn_attack_connected=fact.same_turn_attack_connected,
            same_turn_attack_option_count=fact.same_turn_attack_option_count,
            post_evolution_ready_attack_count=fact.post_evolution_ready_attack_count,
            development_value=fact.development_value,
            development_probability=fact.development_probability,
            target_id=fact.base_id,
            target_serial=fact.base_serial,
            recommended_target_id=fact.base_id,
            recommended_target_serial=fact.base_serial,
            reasons=("salvatore_development_fact",),
        )

    def _best_salvatore_development_outcome(self) -> Optional[ImmediateOutcome]:
        facts = self._salvatore_development_facts()
        if not facts:
            return None
        best = max(
            facts,
            key=lambda fact: (
                fact.same_turn_attack_connected,
                fact.post_evolution_ready_attack_count,
                fact.develops_bench_next_attacker,
                fact.completed_same_line_attackers == 0,
                not fact.equivalent_normal_evolution,
                fact.development_value,
            ),
        )
        return self._salvatore_development_outcome(best)

    def _wally_target_outcome(self, target: Optional[Pokemon]) -> ImmediateOutcome:
        if target is None or target not in self.b.all_my_pokemon:
            return ImmediateOutcome(supported=False, reasons=("wally_missing_target",))
        if self.b.pid(target) not in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX}:
            return ImmediateOutcome(supported=False, reasons=("wally_invalid_target",))
        healed_damage = damage_on(target)
        if healed_damage <= 0:
            return ImmediateOutcome(supported=False, target_id=self.b.pid(target), target_serial=getattr(target, "serial", None), reasons=("wally_no_damage",))
        energy_count = self.b.energy_count(target)
        opp_damage = self.b.opp_max_damage()
        avoids_next_knockout = (
            target is self.b.active
            and opp_damage > 0
            and hp_left(target) <= opp_damage
            and safe_int(getattr(target, "maxHp", 0)) > opp_damage
        )
        avoids_board_out = avoids_next_knockout and len(self.b.all_my_pokemon) == 1
        reasons = ["wally_heals_damage"]
        if energy_count > 0:
            reasons.append("wally_recovers_energy")
        if avoids_next_knockout:
            reasons.extend(("wally_avoids_next_knockout", "wally_avoids_prize_loss"))
        if avoids_board_out:
            reasons.append("wally_avoids_board_out")
        return ImmediateOutcome(
            supported=True,
            healed_damage=healed_damage,
            recovered_energy_count=energy_count,
            board_energy_removed=energy_count,
            next_knockout_avoided=avoids_next_knockout,
            avoids_prize_loss=avoids_next_knockout,
            prizes_preserved=self.b.prize_value(target) if avoids_next_knockout else 0,
            avoids_board_out=avoids_board_out,
            preserves_primary_pokemon=target is self.b.active,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def evaluate_wally_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != WALLY_COMPASSION:
            return ImmediateOutcome(supported=False, reasons=("unsupported_wally_play",))
        if self.b.state.supporterPlayed:
            return ImmediateOutcome(supported=False, reasons=("wally_supporter_already_used",))
        outcomes = [
            self._wally_target_outcome(target)
            for target in self.b.all_my_pokemon
        ]
        outcomes = [outcome for outcome in outcomes if outcome.supported]
        if not outcomes:
            return ImmediateOutcome(supported=False, reasons=("wally_no_effective_target",))
        best = max(outcomes, key=wally_effect_fact_key)
        return replace(
            best,
            recommended_target_id=best.target_id,
            recommended_target_serial=best.target_serial,
            reasons=("wally_play",) + best.reasons,
        )

    def evaluate_wally_target(self, target: Optional[Pokemon]) -> ImmediateOutcome:
        outcome = self._wally_target_outcome(target)
        if not outcome.supported:
            return outcome
        return replace(outcome, reasons=("wally_target",) + outcome.reasons)

    def evaluate_salvatore_target(self, target: Optional[Pokemon]) -> ImmediateOutcome:
        if target is None:
            return ImmediateOutcome(supported=False, reasons=("missing_salvatore_target",))
        development_fact = self._salvatore_development_fact(target)
        if development_fact is None:
            return ImmediateOutcome(
                supported=False,
                reasons=("salvatore_target_has_no_current_evolution",),
            )
        outcome = self._best_salvatore_active_evolve_attack_outcome(
            target,
            "salvatore_target_reachable_attack",
            require_unused_supporter=False,
        )
        if outcome is None:
            development = self._salvatore_development_outcome(development_fact)
            return replace(
                development,
                reasons=development.reasons
                + ("salvatore_target_no_same_turn_attack_chain",),
            )
        development = self._salvatore_development_outcome(development_fact)
        return replace(
            outcome,
            equivalent_evolution_available=development.equivalent_evolution_available,
            completes_next_attacker=development.completes_next_attacker,
            develops_bench_next_attacker=development.develops_bench_next_attacker,
            evolution_hp_gain=development.evolution_hp_gain,
            completes_evolution_line=development.completes_evolution_line,
            completed_same_line_attackers=development.completed_same_line_attackers,
            same_turn_attack_connected=True,
            same_turn_attack_option_count=development.same_turn_attack_option_count,
            post_evolution_ready_attack_count=development.post_evolution_ready_attack_count,
            development_value=development.development_value,
            development_probability=development.development_probability,
        )

    def evaluate_salvatore_evolution_candidate(self, option: Any) -> ImmediateOutcome:
        evolution_id = self.b.option_card(option)
        if evolution_id not in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX}:
            return ImmediateOutcome(supported=False, reasons=("unsupported_salvatore_evolution_candidate",))
        outcome = self._best_salvatore_active_evolve_attack_outcome(
            reason="salvatore_evolution_candidate_reachable_attack",
            require_unused_supporter=False,
            evolution_id=evolution_id,
            confirmed_evolution_candidate=True,
        )
        if outcome is None:
            return ImmediateOutcome(supported=True, target_id=evolution_id, reasons=("salvatore_evolution_candidate_no_same_turn_attack_chain",))
        return outcome

    def evaluate_pokegear_candidate(self, option: Any) -> ImmediateOutcome:
        cid = self.b.option_card(option)
        if cid != SALVATORE:
            return ImmediateOutcome(supported=False, reasons=("pokegear_candidate_no_same_turn_chain",))
        if self.b.state.supporterPlayed:
            return ImmediateOutcome(supported=True, reasons=("pokegear_salvatore_candidate_supporter_already_used",))
        outcome = self._best_salvatore_active_evolve_attack_outcome(
            reason="pokegear_salvatore_candidate_reachable_attack",
        )
        if outcome is None:
            return ImmediateOutcome(supported=True, reasons=("pokegear_salvatore_candidate_no_same_turn_attack_chain",))
        return outcome

    def evaluate_poke_pad_candidate(self, option: Any) -> ImmediateOutcome:
        cid = self.b.option_card(option)
        facts = self.b.poke_pad_target_facts(cid, visible_search_candidate=True)
        if facts is None:
            return ImmediateOutcome(supported=False, reasons=("invalid_poke_pad_candidate",))
        return ImmediateOutcome(
            supported=True,
            target_id=cid,
            reasons=("poke_pad_candidate_public_facts",),
        )

    def retained_non_ko_attack_candidates(
        self,
    ) -> Tuple[AttackOutcomeCandidate, ...]:
        candidates: List[AttackOutcomeCandidate] = []
        for option_index, option in self.b.iter_options():
            if (
                option.type != OptionType.ATTACK
                and option.attackId is None
            ):
                continue
            outcome = self.evaluate_attack(option)
            if (
                not outcome.supported
                or outcome.blocked
                or outcome.knockout
                or outcome.wins_game
            ):
                continue
            attack = self.b.attack(option.attackId)
            if attack is None or self.b.active is None:
                continue
            candidates.append(
                AttackOutcomeCandidate(
                    attack_id=int(option.attackId),
                    attack_index=len(candidates),
                    option_index=option_index,
                    outcome=outcome,
                    can_continue_attack=(
                        can_continue_attack_after_use_with_tokens(
                            attack,
                            self.b.energy_tokens(self.b.active),
                        )
                    ),
                )
            )
        return tuple(candidates)

    def evaluate_poke_pad_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != POKE_PAD:
            return ImmediateOutcome(supported=False, reasons=("unsupported_poke_pad_play",))
        candidates = self.b.poke_pad_target_facts_in_deck()
        if not candidates:
            return ImmediateOutcome(supported=True, reasons=("poke_pad_no_searchable_candidate",))
        return ImmediateOutcome(
            supported=True,
            reasons=("poke_pad_searchable_candidates_available",),
        )

    def evaluate_pokegear_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != POKEGEAR:
            return ImmediateOutcome(supported=False, reasons=("unsupported_pokegear_play",))
        if self.b.state.supporterPlayed or not self.b.remaining_possible(SALVATORE):
            return ImmediateOutcome(supported=True, reasons=("pokegear_no_same_turn_salvatore_chain",))
        chain = self._best_salvatore_active_evolve_attack_fact(require_unused_supporter=True)
        probability = self.b.pokegear_hit_probability(SALVATORE)
        if chain is not None:
            _target, evolution_id, _fact = chain
            if _fact.blocked:
                return ImmediateOutcome(supported=True, expected_hit_probability=probability, reasons=("pokegear_no_same_turn_salvatore_chain",))
            probability = self.b.pokegear_chain_hit_probability(SALVATORE, evolution_id)
        if chain is None or probability <= 0:
            return ImmediateOutcome(supported=True, expected_hit_probability=probability, reasons=("pokegear_no_same_turn_salvatore_chain",))
        target, _evolution_id, fact = chain
        return ImmediateOutcome(
            supported=True,
            expected_reachable_attack_id=fact.attack_id,
            expected_reachable_damage=fact.damage * probability,
            expected_reachable_knockout=fact.knockout,
            expected_reachable_prizes_taken=fact.prizes_taken * probability,
            expected_reachable_wins_game=fact.wins_game,
            expected_hit_probability=probability,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=("pokegear_expected_salvatore_chain",),
        )

    def active_status_blocks_attack(self) -> bool:
        return active_status_blocks_attack_for_board(self.b)

    def active_can_declare_attack_this_turn(self) -> bool:
        return active_can_declare_attack_this_turn_for_board(self.b)

    def _current_turn_supporter_id(self) -> Optional[int]:
        if not getattr(self.b.state, "supporterPlayed", False):
            return None
        return getattr(
            self.b,
            "used_supporter_id_this_turn",
            None,
        )

    def _suguri_target_is_eligible(self, target: Optional[Pokemon]) -> bool:
        target_data = self.b.data(self.b.pid(target))
        return bool(
            target is not None
            and target_data is not None
            and (target_data.ex or target_data.megaEx)
        )

    def _suguri_damage_boost_applies(
        self,
        attacker: Optional[Pokemon],
        target: Optional[Pokemon],
        attack: Optional[Any],
        blocked: bool,
    ) -> bool:
        return bool(
            attacker is self.b.active
            and attack is not None
            and not blocked
            and self._current_turn_supporter_id() == SUGURI
            and self._suguri_target_is_eligible(target)
            and self.active_can_declare_attack_this_turn()
            and self.b.can_pay_attack(attacker, attack)
            and self.b.attack_damage(attacker, attack, target) > 0
        )

    def evaluate_suguri_damage_boost(self) -> ImmediateOutcome:
        attacker = self.b.active
        target = self.b.opp_active
        attacker_data = self.b.data(self.b.pid(attacker))
        if (
            attacker is None
            or target is None
            or attacker_data is None
            or not self._suguri_target_is_eligible(target)
            or not self.active_can_declare_attack_this_turn()
        ):
            return ImmediateOutcome(
                supported=False,
                reasons=("suguri_damage_boost_no_legal_attack",),
            )

        outcomes: List[ImmediateOutcome] = []
        unsupported_reasons: List[str] = []
        for attack_id in attacker_data.attacks:
            attack = self.b.attack(attack_id)
            if attack is None:
                unsupported_reasons.append("suguri_attack_data_missing")
                continue
            if not self.b.can_pay_attack(attacker, attack):
                continue
            if self._blocked_by_ex_wall(attacker, target, attack):
                continue
            base_damage = self.b.attack_damage(attacker, attack, target)
            if base_damage <= 0:
                continue
            boosted_damage, blocked, prevention_reason = (
                self.b.resolved_attack_damage(
                    attacker,
                    attack,
                    target,
                    additional_damage=30,
                )
            )
            if prevention_reason == UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON:
                unsupported_reasons.append(prevention_reason)
                continue
            if blocked:
                continue
            knockout = boosted_damage >= hp_left(target)
            prizes_taken = (
                self.b.prize_value(target)
                if knockout
                else 0
            )
            wins_game = bool(
                knockout
                and prizes_taken >= self.b.my_prizes_left()
            )
            outcomes.append(
                ImmediateOutcome(
                    reachable_attack_id=int(attack.attackId),
                    reachable_damage=boosted_damage,
                    reachable_knockout=knockout,
                    reachable_prizes_taken=prizes_taken,
                    reachable_wins_game=wins_game,
                    target_id=self.b.pid(target),
                    target_serial=getattr(target, "serial", None),
                    reasons=("suguri_damage_boost",),
                )
            )
        if not outcomes:
            if unsupported_reasons:
                return ImmediateOutcome(
                    supported=False,
                    reasons=(
                        "suguri_damage_boost_unsupported",
                        *tuple(dict.fromkeys(unsupported_reasons)),
                    ),
                )
            return ImmediateOutcome(
                supported=False,
                reasons=("suguri_damage_boost_no_legal_attack",),
            )
        return max(
            outcomes,
            key=lambda outcome: (
                outcome.reachable_wins_game,
                outcome.reachable_knockout,
                outcome.reachable_prizes_taken,
                outcome.reachable_damage,
            ),
        )

    def _attack_outcome_with_tokens(
        self,
        attacker: Pokemon,
        attack_id: int,
        tokens: Sequence[Any],
        reason: str,
    ) -> ImmediateOutcome:
        return self._attack_outcome_with_tokens_against(attacker, attack_id, tokens, self.b.opp_active, reason)

    def _attack_outcome_with_tokens_against(
        self,
        attacker: Pokemon,
        attack_id: int,
        tokens: Sequence[Any],
        target: Optional[Pokemon],
        reason: str,
    ) -> ImmediateOutcome:
        attack = self.b.attack(attack_id)
        if attack is None or target is None:
            return ImmediateOutcome(supported=False, reachable_attack_id=int(attack_id), reasons=("missing_reachable_attack_state",))
        if not can_pay_attack_with_tokens(attack, tokens):
            return ImmediateOutcome(supported=False, reachable_attack_id=int(attack_id), reasons=("reachable_attack_not_payable",))
        damage, blocked, prevention_reason = self.b.resolved_attack_damage(
            attacker,
            attack,
            target,
        )
        if prevention_reason == UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON:
            return ImmediateOutcome(
                supported=False, damage=damage, reachable_attack_id=int(attack_id),
                target_id=self.b.pid(target),
                target_serial=getattr(target, "serial", None),
                reasons=(reason, prevention_reason),
            )
        knockout = damage >= hp_left(target)
        prizes_taken = self.b.prize_value(target) if knockout else 0
        wins_game = prizes_taken >= self.b.my_prizes_left() if knockout else False
        reasons = [reason]
        if prevention_reason is not None:
            reasons.append(prevention_reason)
        if knockout:
            reasons.append("reachable_knockout")
        if wins_game:
            reasons.append("reachable_win")
        return ImmediateOutcome(
            blocked=blocked,
            damage=damage,
            knockout=knockout,
            prizes_taken=prizes_taken,
            wins_game=wins_game,
            reachable_attack_id=int(attack_id),
            reasons=tuple(reasons),
        )

    def evaluate_boss_target(self, target: Optional[Pokemon]) -> ImmediateOutcome:
        attacker = self.b.active
        if attacker is None or target is None or target not in self.b.opp_bench:
            return ImmediateOutcome(supported=False, reasons=("missing_boss_state",))
        data = self.b.data(self.b.pid(attacker))
        if data is None:
            return ImmediateOutcome(supported=False, reasons=("missing_boss_state",))
        if not self.active_can_declare_attack_this_turn():
            return self._boss_no_effective_attack(target)

        attack_ids = self._energy_payable_attack_ids(data.attacks, self.b.energy_tokens(attacker))
        outcomes = [self._boss_attack_outcome(attacker, target, attack_id) for attack_id in attack_ids]
        effective_outcomes = [outcome for outcome in outcomes if outcome.supported and not outcome.blocked]
        if not effective_outcomes:
            return self._boss_no_effective_attack(target)

        best = max(
            effective_outcomes,
            key=lambda outcome: (
                outcome.wins_game,
                outcome.knockout,
                outcome.prizes_taken,
                not outcome.blocked,
                outcome.damage,
            ),
        )

        target_id = self.b.pid(target)
        avoids_wall = (
            self.b.opp_active is not None
            and self.b.pid(self.b.opp_active) in EX_ATTACK_WALLS
            and target_id not in EX_ATTACK_WALLS
        )
        # breaks_engine means this Boss target is an important engine piece from
        # MATCHUP_PLANS or existing engine sets, not that it has already been KO'd.
        breaks_engine = target_id in self.b.plan_boss_targets() or target_id in (LUCARIO_ENGINE | CRUSTLE_LINE | DREEPY_LINE)
        reasons = ["boss_target"]
        if best.wins_game:
            reasons.append("boss_wins_game")
        if best.knockout:
            reasons.append("boss_knockout")
        if best.prizes_taken:
            reasons.append("boss_takes_prizes")
        if avoids_wall:
            reasons.append("boss_avoids_wall")
        if breaks_engine:
            reasons.append("boss_breaks_engine")
        if best.damage > 0 and not best.knockout:
            reasons.append("boss_damage_only")

        return ImmediateOutcome(
            damage=best.damage,
            knockout=best.knockout,
            prizes_taken=best.prizes_taken,
            wins_game=best.wins_game,
            bypasses_wall=best.bypasses_wall,
            avoids_wall=avoids_wall,
            breaks_engine=breaks_engine,
            target_id=target_id,
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def evaluate_boss_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != BEFEHL_VON_BOSS:
            return ImmediateOutcome(supported=False, reasons=("unsupported_boss_play",))
        if not any(candidate is option for _, candidate in self.b.iter_options()):
            return ImmediateOutcome(supported=True, reasons=("boss_play_option_not_legal",))
        if self.b.state.supporterPlayed:
            return ImmediateOutcome(supported=True, reasons=("boss_play_supporter_already_used",))
        if self.b.active is None or not self.b.opp_bench:
            return ImmediateOutcome(supported=True, reasons=("boss_play_missing_state",))
        if not self.active_can_declare_attack_this_turn():
            return ImmediateOutcome(supported=False, reasons=("boss_play_attack_not_declarable",))

        candidates = []
        for target in self.b.opp_bench:
            outcome = self.evaluate_boss_target(target)
            if outcome.supported and not outcome.blocked and (outcome.wins_game or (outcome.knockout and outcome.prizes_taken > 0)):
                candidates.append(outcome)
        if not candidates:
            return ImmediateOutcome(supported=True, reasons=("boss_play_no_reachable_prize_attack",))

        best = max(
            candidates,
            key=lambda outcome: (
                outcome.wins_game,
                outcome.knockout,
                outcome.prizes_taken,
                outcome.damage,
            ),
        )
        reasons = ["boss_play_reachable_attack"]
        if best.wins_game:
            reasons.append("boss_play_reachable_win")
        if best.knockout:
            reasons.append("boss_play_reachable_knockout")
        if best.prizes_taken:
            reasons.append("boss_play_takes_prizes")
        return ImmediateOutcome(
            supported=True,
            reachable_damage=best.damage,
            reachable_knockout=best.knockout,
            reachable_prizes_taken=best.prizes_taken,
            reachable_wins_game=best.wins_game,
            target_id=best.target_id,
            target_serial=best.target_serial,
            reasons=tuple(reasons),
        )

    def _energy_payable_attack_ids(self, attack_ids: Sequence[int], tokens: Sequence[Any]) -> Tuple[int, ...]:
        payable: List[int] = []
        for attack_id in attack_ids:
            attack = self.b.attack(attack_id)
            if can_pay_attack_with_tokens(attack, tokens):
                payable.append(int(attack_id))
        return tuple(payable)

    def _unblocked_attack_ids(self, attacker: Pokemon, attack_ids: Sequence[int]) -> Tuple[int, ...]:
        if self.b.opp_active is None:
            return ()
        unblocked: List[int] = []
        for attack_id in attack_ids:
            attack = self.b.attack(attack_id)
            if (
                attack is not None
                and not self.b.attack_blocked_for_card(
                    self.b.pid(attacker),
                    self.b.opp_active,
                    attack,
                )
            ):
                unblocked.append(int(attack_id))
        return tuple(unblocked)

    def has_energy_payable_unblocked_active_attack(self) -> bool:
        attacker = self.b.active
        data = self.b.data(self.b.pid(attacker))
        if attacker is None or data is None:
            return False
        for attack_id in data.attacks:
            if self.active_attack_is_payable_unblocked(attack_id):
                return True
        return False

    def active_attack_is_payable_unblocked(self, attack_id: int) -> bool:
        if not self.active_can_declare_attack_this_turn():
            return False
        attacker = self.b.active
        target = self.b.opp_active
        attack = self.b.attack(attack_id)
        if attacker is None or target is None or attack is None:
            return False
        return (
            self.b.can_pay_attack(attacker, attack)
            and not self.b.attack_blocked_for_card(
                self.b.pid(attacker),
                target,
                attack,
            )
        )

    def _boss_attack_outcome(self, attacker: Pokemon, target: Pokemon, attack_id: int) -> ImmediateOutcome:
        attack = self.b.attack(attack_id)
        if attack is None:
            return ImmediateOutcome(supported=False, reasons=("boss_no_effective_attack",))
        damage, blocked, prevention_reason = self.b.resolved_attack_damage(
            attacker,
            attack,
            target,
        )
        if prevention_reason == UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON:
            return ImmediateOutcome(
                supported=False, damage=damage, target_id=self.b.pid(target),
                target_serial=getattr(target, "serial", None),
                reasons=(prevention_reason,),
            )
        knockout = damage >= hp_left(target)
        prizes_taken = self.b.prize_value(target) if knockout else 0
        wins_game = prizes_taken >= self.b.my_prizes_left() if knockout else False
        return ImmediateOutcome(
            blocked=blocked,
            damage=damage,
            knockout=knockout,
            prizes_taken=prizes_taken,
            wins_game=wins_game,
            bypasses_wall=self._bypasses_ex_wall(attack) and self.b.pid(target) in EX_ATTACK_WALLS,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=(prevention_reason,) if prevention_reason is not None else (),
        )

    def _boss_no_effective_attack(self, target: Pokemon) -> ImmediateOutcome:
        return ImmediateOutcome(
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=("boss_target", "boss_no_effective_attack"),
        )

    def evaluate_tool_scrapper_play(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.PLAY or self.b.option_card(option) != TOOL_SCRAPPER:
            return ImmediateOutcome(supported=False, reasons=("tool_scrapper_no_target",))
        outcomes = [
            self.evaluate_tool_scrapper_target(pokemon, index)
            for pokemon in self.b.all_opp_pokemon
            for index, _ in enumerate(pokemon.tools)
        ]
        supported = [outcome for outcome in outcomes if outcome.supported]
        if supported:
            return max(supported, key=self._tool_scrapper_priority)
        unmodeled = next(
            (
                outcome
                for outcome in outcomes
                if "tool_removal_effect_unmodeled" in outcome.reasons
            ),
            None,
        )
        if unmodeled is not None:
            return unmodeled
        return ImmediateOutcome(supported=False, reasons=("tool_scrapper_no_target",))

    def evaluate_tool_scrapper_target(
        self,
        target: Optional[Pokemon],
        tool_index: Optional[int] = None,
    ) -> ImmediateOutcome:
        if target is None or target not in self.b.all_opp_pokemon:
            return ImmediateOutcome(supported=False, reasons=("tool_scrapper_no_target",))
        tool = self._selected_tool(target, tool_index)
        if tool is None:
            return ImmediateOutcome(supported=False, target_id=self.b.pid(target), target_serial=getattr(target, "serial", None), reasons=("tool_scrapper_no_target",))

        tool_id = int(tool.id)
        tool_data = self.b.data(tool_id)
        effect_kinds = classify_public_effect(tool_data)
        hp_bonus = public_hp_bonus(tool_data)
        unmodeled_kinds = {
            PublicEffectKind.DAMAGE_AFFECTING,
            PublicEffectKind.AFTER_DAMAGE_TRIGGERED_EFFECT,
            PublicEffectKind.WEAKNESS_RESISTANCE_AFFECTING,
            PublicEffectKind.RETREAT_COST_AFFECTING,
            PublicEffectKind.RETREAT_OR_SWITCH_TRIGGERED_EFFECT,
            PublicEffectKind.OTHER_RELEVANT_EFFECT,
            PublicEffectKind.UNKNOWN,
        }
        if (
            any(kind in unmodeled_kinds for kind in effect_kinds)
            or (
                PublicEffectKind.HP_AFFECTING in effect_kinds
                and hp_bonus is None
            )
        ):
            return ImmediateOutcome(
                supported=False,
                removes_tool=True,
                target_id=self.b.pid(target),
                target_serial=getattr(target, "serial", None),
                reasons=(
                    "tool_scrapper_target",
                    "removes_tool",
                    "tool_removal_effect_unmodeled",
                ),
            )

        before_hp = hp_left(target)
        after_hp = max(0, before_hp - hp_bonus) if hp_bonus is not None else before_hp
        before_damage = self._best_unblocked_damage_to(target)
        attack_ko_before = before_damage >= before_hp
        attack_ko_after = before_damage >= after_hp
        removal_knockout = hp_bonus is not None and after_hp <= 0
        enables_knockout = (not removal_knockout) and (not attack_ko_before) and attack_ko_after
        prizes_taken = self.b.prize_value(target) if removal_knockout else 0
        wins_game = prizes_taken >= self.b.my_prizes_left() if removal_knockout else False

        reasons = ["tool_scrapper_target", "removes_tool"]
        if hp_bonus is not None:
            reasons.append("removes_hp_boost_tool")
            reasons.append(f"removed_hp_bonus_{hp_bonus}")
            if is_hero_cape_action(tool_id):
                reasons.append("removes_hero_cape")
        if enables_knockout:
            reasons.append("tool_scrapper_enables_ko")
        if removal_knockout:
            reasons.append("tool_removal_causes_knockout")
        if wins_game:
            reasons.append("wins_game")
        if (
            not enables_knockout
            and PublicEffectKind.NO_RELEVANT_EFFECT in effect_kinds
        ):
            reasons.append("tool_scrapper_no_immediate_gain")

        return ImmediateOutcome(
            damage=0,
            knockout=removal_knockout,
            prizes_taken=prizes_taken,
            wins_game=wins_game,
            removes_tool=True,
            enables_knockout=enables_knockout,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def _selected_tool(self, target: Pokemon, tool_index: Optional[int]) -> Optional[Any]:
        tools = target.tools
        if not tools:
            return None
        if tool_index is not None:
            return tools[tool_index] if 0 <= tool_index < len(tools) else None
        if len(tools) == 1:
            return tools[0]
        return None

    def _best_unblocked_damage_to(self, target: Pokemon) -> int:
        attacker = self.b.active
        if attacker is None:
            return 0
        data = self.b.data(self.b.pid(attacker))
        if data is None:
            return 0
        best = 0
        for attack_id in self._energy_payable_attack_ids(data.attacks, self.b.energy_tokens(attacker)):
            attack = self.b.attack(attack_id)
            if attack is None:
                continue
            damage, blocked, _ = self.b.resolved_attack_damage(
                attacker,
                attack,
                target,
            )
            if not blocked:
                best = max(best, damage)
        return best

    def _tool_scrapper_priority(self, outcome: ImmediateOutcome) -> Tuple[Any, ...]:
        return (
            outcome.wins_game,
            outcome.knockout,
            outcome.prizes_taken,
            outcome.enables_knockout,
            "removes_hp_boost_tool" in outcome.reasons,
            "removes_key_tool" in outcome.reasons,
            outcome.removes_tool,
        )

    def evaluate_retreat(self, option: Any) -> ImmediateOutcome:
        if option.type != OptionType.RETREAT:
            return ImmediateOutcome(supported=False, reasons=("unsupported_retreat_option",))
        active = self.b.active
        if active is None:
            return ImmediateOutcome(supported=False, reasons=("retreat_no_active",))
        target = self.b.option_target(option)
        if target is not None:
            return self.evaluate_switch_target(target, "retreat")

        cost = self._effective_retreat_cost(active)
        important_loss = self._possible_important_energy_loss(active, cost)
        active_damage = self._best_unblocked_damage_from(active)
        reasons = ["retreat", "retreat_cost"]
        if important_loss > 0:
            reasons.append("important_energy_loss")
        if active_damage > 0:
            reasons.append("retreat_from_ready_attacker")
        if self._survival_retreat_reason(active):
            reasons.append("survival_retreat")
        if not self.b.bench:
            reasons.append("retreat_no_target")
        best_target = self._best_retreat_candidate_summary()
        if best_target is not None:
            # recommended_target_* identify the best visible follow-up candidate only;
            # the RETREAT option has not switched the board yet.
            for reason in best_target.reasons:
                if reason in {
                    "retreat_enables_attack",
                    "switch_enables_knockout",
                    "switch_enables_win",
                    "role_handoff",
                    "retreat_improves_damage",
                } and reason not in reasons:
                    reasons.append(reason)
            if "zero_energy_mega_wall" in best_target.reasons and all(
                "zero_energy_mega_wall" in self.evaluate_switch_target(pokemon, "retreat").reasons
                for pokemon in self.b.bench
            ):
                reasons.append("zero_energy_mega_wall")
        if self.b.pid(active) == CINDERACE and self.b.cinderace_can_accelerate() and self.b.has_bench_energy_receiver():
            reasons.append("retreat_from_ready_attacker")

        return ImmediateOutcome(
            enables_attack=bool(best_target and best_target.enables_attack),
            enables_knockout=bool(best_target and best_target.enables_knockout),
            reachable_attack_id=best_target.reachable_attack_id if best_target is not None else None,
            reachable_damage=best_target.reachable_damage if best_target is not None else 0,
            reachable_knockout=bool(best_target and best_target.reachable_knockout),
            reachable_prizes_taken=best_target.reachable_prizes_taken if best_target is not None else 0,
            reachable_wins_game=bool(best_target and best_target.reachable_wins_game),
            retreat_energy_cost=cost,
            important_energy_loss=important_loss,
            improves_damage=bool(best_target and best_target.improves_damage),
            recommended_target_id=best_target.target_id if best_target is not None else None,
            recommended_target_serial=best_target.target_serial if best_target is not None else None,
            reasons=tuple(reasons),
        )

    def evaluate_switch_target(
        self,
        target: Optional[Pokemon],
        source: str,
    ) -> ImmediateOutcome:
        if source not in {"retreat", "surfing_beach", "suguri"}:
            return ImmediateOutcome(
                supported=False,
                reasons=("unsupported_switch_source",),
            )
        active = self.b.active
        if (
            active is None
            or target is None
            or target not in self.b.bench
        ):
            return ImmediateOutcome(
                supported=False,
                reasons=("retreat_no_target",),
            )
        target_id = self.b.pid(target)
        target_serial = getattr(target, "serial", None)
        if (
            source == "surfing_beach"
            and not self._can_surfing_beach_switch(active, target)
        ):
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=(
                    "surfing_beach_switch",
                    "unsupported_switch_target",
                ),
            )
        if source == "surfing_beach":
            return ImmediateOutcome(
                supported=False,
                target_id=target_id,
                target_serial=target_serial,
                reasons=(
                    "surfing_beach_switch",
                    "surfing_beach_switch_requires_policy_resolution",
                ),
            )

        current_collection = self.current_active_attack_candidates()
        current_supported = tuple(
            candidate.outcome
            for candidate in current_collection.candidates
            if candidate.outcome.supported
            and not candidate.outcome.blocked
        )
        current_outcome = (
            self._best_reachable_attack_outcome(current_supported)
            if current_supported
            else None
        )
        current_unknown = bool(
            not current_supported
            and current_collection.unsupported_reasons
        )

        survival = self._survival_retreat_reason(active)
        target_attack_outcome: Optional[ImmediateOutcome] = None
        unavailable_attack_reasons: Tuple[str, ...] = ()
        if (
            source != "retreat"
            or not self.active_status_blocks_attack()
        ):
            evaluated = self._best_switch_target_attack_outcome(target)
            if evaluated.supported:
                target_attack_outcome = evaluated
            elif source == "surfing_beach" and not survival:
                return ImmediateOutcome(
                    supported=False,
                    blocked=evaluated.blocked,
                    damage=evaluated.damage,
                    reachable_attack_id=evaluated.reachable_attack_id,
                    reachable_damage=evaluated.damage,
                    target_id=target_id,
                    target_serial=target_serial,
                    reasons=(
                        "surfing_beach_switch",
                    ) + evaluated.reasons,
                )
            else:
                unavailable_attack_reasons = evaluated.reasons

        cost = (
            0
            if source in {"surfing_beach", "suguri"}
            else self._effective_retreat_cost(active)
        )
        important_loss = (
            0
            if source in {"surfing_beach", "suguri"}
            else self._possible_important_energy_loss(active, cost)
        )
        target_damage = (
            target_attack_outcome.damage
            if target_attack_outcome is not None
            else 0
        )
        comparison_supported = not current_unknown
        enables_attack = bool(
            comparison_supported
            and current_collection.no_legal_attack_confirmed
            and target_attack_outcome is not None
        )
        improves_damage = bool(
            comparison_supported
            and current_outcome is not None
            and target_attack_outcome is not None
            and target_attack_outcome.damage > current_outcome.damage
        )
        enables_knockout = bool(
            comparison_supported
            and target_attack_outcome is not None
            and target_attack_outcome.knockout
            and not (
                current_outcome is not None
                and current_outcome.knockout
            )
        )
        enables_win = bool(
            comparison_supported
            and target_attack_outcome is not None
            and target_attack_outcome.wins_game
            and not (
                current_outcome is not None
                and current_outcome.wins_game
            )
        )
        role_handoff = self._role_handoff(
            active,
            target,
            target_damage,
        )

        reasons = ["switch_target"]
        if source == "surfing_beach":
            reasons.append("surfing_beach_switch")
        elif source == "suguri":
            reasons.append("suguri_switch")
        else:
            reasons.extend(("retreat", "retreat_cost"))
        reasons.extend(unavailable_attack_reasons)
        if current_unknown:
            reasons.extend(
                (
                    "current_active_attack_unsupported",
                    *current_collection.unsupported_reasons,
                )
            )
        if important_loss > 0:
            reasons.append("important_energy_loss")
        if enables_attack:
            reasons.append("retreat_enables_attack")
        if enables_knockout:
            reasons.append("switch_enables_knockout")
        if enables_win:
            reasons.append("switch_enables_win")
        if role_handoff:
            reasons.append("role_handoff")
        if improves_damage:
            reasons.append("retreat_improves_damage")
        elif comparison_supported:
            reasons.append("retreat_no_damage_improvement")
        if survival:
            reasons.append("survival_retreat")
        if (
            self._zero_energy_mega_wall(target, target_damage)
            and not survival
            and not enables_knockout
        ):
            reasons.append("zero_energy_mega_wall")
        if (
            self.b.pid(active) == CINDERACE
            and self.b.cinderace_can_accelerate()
            and self.b.has_bench_energy_receiver()
        ):
            reasons.append("retreat_from_ready_attacker")

        return ImmediateOutcome(
            supported=bool(
                target_attack_outcome is not None
                or survival
                or role_handoff
            ),
            damage=0,
            knockout=False,
            prizes_taken=0,
            wins_game=False,
            enables_attack=enables_attack,
            enables_knockout=enables_knockout,
            reachable_attack_id=(
                target_attack_outcome.reachable_attack_id
                if target_attack_outcome is not None
                else None
            ),
            reachable_damage=target_damage,
            reachable_knockout=bool(
                target_attack_outcome
                and target_attack_outcome.knockout
            ),
            reachable_prizes_taken=(
                target_attack_outcome.prizes_taken
                if target_attack_outcome is not None
                else 0
            ),
            reachable_wins_game=bool(
                target_attack_outcome
                and target_attack_outcome.wins_game
            ),
            reachable_can_continue_attack=(
                target_attack_outcome is not None
            ),
            retreat_energy_cost=cost,
            important_energy_loss=important_loss,
            improves_damage=improves_damage,
            target_id=target_id,
            target_serial=target_serial,
            reasons=tuple(dict.fromkeys(reasons)),
        )

    def evaluate_retreat_energy_selection(self, option: Any) -> ImmediateOutcome:
        target = self.b.option_target(option) or self.b.active
        if target is None:
            return ImmediateOutcome(supported=False, reasons=("retreat_energy_no_target",))
        energy_id = self._selected_energy_id(target, option)
        if energy_id is None:
            return ImmediateOutcome(supported=False, reasons=("retreat_energy_no_target",))
        important_loss = 1 if self._is_important_energy_card(target, energy_id) else 0
        reasons = ["retreat", "retreat_cost"]
        if important_loss:
            reasons.append("important_energy_loss")
        return ImmediateOutcome(
            important_energy_loss=important_loss,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def evaluate_attack_effect_target(self, option: Any) -> ImmediateOutcome:
        if self.b.select.context != SelectContext.DAMAGE:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attack_effect",))
        if self._recent_my_attack_id() != JETTING_BLOW:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attack_effect",))
        target = self.b.option_target(option)
        if target is None or target not in self.b.opp_bench:
            return ImmediateOutcome(supported=False, reasons=("unsupported_attack_effect",))

        damage = 50
        knockout = damage >= hp_left(target)
        prizes_taken = self.b.prize_value(target) if knockout else 0
        reasons = ["attack_effect_target", "jetting_blow_secondary_damage"]
        if knockout:
            reasons.append("knockout")
        if self.b.pid(target) in self.b.plan_pressure_targets() or self.b.pid(target) in self.b.plan_boss_targets():
            reasons.append("effect_hits_engine")

        return ImmediateOutcome(
            damage=damage,
            knockout=knockout,
            prizes_taken=prizes_taken,
            wins_game=False,
            target_id=self.b.pid(target),
            target_serial=getattr(target, "serial", None),
            reasons=tuple(reasons),
        )

    def _effective_retreat_cost(self, pokemon: Optional[Pokemon]) -> int:
        data = self.b.data(self.b.pid(pokemon))
        if data is None:
            return 0
        return max(0, safe_int(getattr(data, "retreatCost", 0)))

    def _possible_important_energy_loss(self, pokemon: Pokemon, cost: int) -> int:
        if cost <= 0:
            return 0
        important_cards = sum(1 for card in pokemon.energyCards if self._is_important_energy_card(pokemon, int(card.id)))
        nonimportant_capacity = sum(1 for card in pokemon.energyCards if not self._is_important_energy_card(pokemon, int(card.id)))
        return min(important_cards, max(0, cost - nonimportant_capacity))

    def _best_retreat_candidate_summary(self) -> Optional[ImmediateOutcome]:
        candidates = [self.evaluate_switch_target(pokemon, "retreat") for pokemon in self.b.bench]
        candidates = [candidate for candidate in candidates if candidate.supported]
        if not candidates:
            return None
        return max(candidates, key=self._retreat_candidate_key)

    def _retreat_candidate_key(self, outcome: ImmediateOutcome) -> Tuple[Any, ...]:
        return (
            "switch_enables_win" in outcome.reasons,
            outcome.enables_knockout,
            outcome.enables_attack,
            "role_handoff" in outcome.reasons,
            outcome.improves_damage,
            "zero_energy_mega_wall" not in outcome.reasons,
            -outcome.important_energy_loss,
        )

    def attack_candidate_collection(
        self,
        pokemon: Optional[Pokemon],
        *,
        after_switch: bool,
        reason: str,
    ) -> AttackCandidateCollection:
        if pokemon is None or self.b.opp_active is None:
            return AttackCandidateCollection(
                candidates=(),
                no_legal_attack_confirmed=False,
                unsupported_reasons=("missing_attack_candidate_state",),
            )
        if after_switch:
            can_declare = self._can_declare_attack_after_same_turn_access()
        else:
            can_declare = (
                pokemon is self.b.active
                and self.active_can_declare_attack_this_turn()
            )
        if not can_declare:
            return AttackCandidateCollection(
                candidates=(),
                no_legal_attack_confirmed=True,
                unsupported_reasons=(),
            )

        data = self.b.data(self.b.pid(pokemon))
        if data is None:
            return AttackCandidateCollection(
                candidates=(),
                no_legal_attack_confirmed=False,
                unsupported_reasons=("attack_candidate_card_data_missing",),
            )
        attack_ids = tuple(getattr(data, "attacks", ()) or ())
        if not attack_ids:
            return AttackCandidateCollection(
                candidates=(),
                no_legal_attack_confirmed=True,
                unsupported_reasons=(),
            )

        tokens = tuple(self.b.energy_tokens(pokemon))
        candidates: List[AttackOutcomeCandidate] = []
        unsupported_reasons: List[str] = []
        payable_found = False
        for attack_index, attack_id in enumerate(attack_ids):
            attack = self.b.attack(attack_id)
            if attack is None:
                unsupported_reasons.append("attack_candidate_data_missing")
                candidates.append(
                    AttackOutcomeCandidate(
                        attack_id=int(attack_id),
                        attack_index=attack_index,
                        option_index=None,
                        outcome=ImmediateOutcome(
                            supported=False,
                            reachable_attack_id=int(attack_id),
                            reasons=(
                                reason,
                                "attack_candidate_data_missing",
                            ),
                        ),
                        can_continue_attack=None,
                    )
                )
                continue
            if not can_pay_attack_with_tokens(attack, tokens):
                continue
            payable_found = True
            outcome = self._attack_outcome_with_tokens_against(
                pokemon,
                int(attack_id),
                tokens,
                self.b.opp_active,
                reason,
            )
            if not outcome.supported:
                unsupported_reasons.extend(outcome.reasons)
            candidates.append(
                AttackOutcomeCandidate(
                    attack_id=int(attack_id),
                    attack_index=attack_index,
                    option_index=None,
                    outcome=outcome,
                    can_continue_attack=(
                        can_continue_attack_after_use_with_tokens(
                            attack,
                            tokens,
                        )
                    ),
                )
            )

        return AttackCandidateCollection(
            candidates=tuple(candidates),
            no_legal_attack_confirmed=(
                not payable_found and not unsupported_reasons
            ),
            unsupported_reasons=tuple(
                dict.fromkeys(unsupported_reasons)
            ),
        )

    def current_active_attack_candidates(
        self,
    ) -> AttackCandidateCollection:
        if self._current_active_attack_candidate_cache is None:
            self._current_active_attack_candidate_cache = (
                self.attack_candidate_collection(
                    self.b.active,
                    after_switch=False,
                    reason="current_active_attack",
                )
            )
        return self._current_active_attack_candidate_cache

    def switch_target_attack_candidates(
        self,
        target: Optional[Pokemon],
    ) -> AttackCandidateCollection:
        if target is None:
            return self.attack_candidate_collection(
                target,
                after_switch=True,
                reason="switch_reachable_attack",
            )
        key = id(target)
        cached = self._switch_target_attack_candidate_cache.get(key)
        if cached is None:
            cached = self.attack_candidate_collection(
                target,
                after_switch=True,
                reason="switch_reachable_attack",
            )
            self._switch_target_attack_candidate_cache[key] = cached
        return cached

    def _best_switch_target_attack_outcome(
        self,
        target: Pokemon,
    ) -> ImmediateOutcome:
        collection = self.switch_target_attack_candidates(target)
        supported = tuple(
            candidate.outcome
            for candidate in collection.candidates
            if candidate.outcome.supported
            and not candidate.outcome.blocked
        )
        if supported:
            return self._best_reachable_attack_outcome(supported)
        if collection.candidates:
            first = collection.candidates[0].outcome
            blocked_only = all(
                candidate.outcome.blocked
                for candidate in collection.candidates
                if candidate.outcome.supported
            ) and any(
                candidate.outcome.supported
                for candidate in collection.candidates
            )
            return replace(
                first,
                supported=False,
                blocked=blocked_only or first.blocked,
                reasons=first.reasons + (
                    ("switch_target_only_blocked_attacks",)
                    if blocked_only
                    else ("switch_target_attack_outcome_unsupported",)
                ),
            )
        if collection.no_legal_attack_confirmed:
            return ImmediateOutcome(
                supported=False,
                reasons=("switch_target_no_payable_attack",),
            )
        return ImmediateOutcome(
            supported=False,
            reasons=collection.unsupported_reasons
            or ("switch_target_attack_state_unsupported",),
        )

    def _is_important_energy_card(self, pokemon: Pokemon, card_id: int) -> bool:
        if card_id in {BASIC_WATER_ENERGY, IGNITION_ENERGY}:
            return True
        if card_id != BASIC_DARK_ENERGY:
            return False
        data = self.b.data(self.b.pid(pokemon))
        if data is None:
            return False
        for attack_id in data.attacks:
            attack = self.b.attack(attack_id)
            if attack is not None and EnergyType.DARKNESS in getattr(attack, "energies", []):
                return True
        return False

    def _selected_energy_id(self, target: Pokemon, option: Any) -> Optional[int]:
        serial = getattr(option, "serial", None)
        if serial is not None:
            for card in target.energyCards:
                if getattr(card, "serial", None) == serial:
                    return int(card.id)
        energy_index = getattr(option, "energyIndex", None)
        if energy_index is not None and 0 <= energy_index < len(target.energyCards):
            return int(target.energyCards[energy_index].id)
        card_id = self.b.option_card(option)
        return None if card_id is None else int(card_id)

    def _best_unblocked_damage_from(self, attacker: Optional[Pokemon]) -> int:
        data = self.b.data(self.b.pid(attacker))
        if data is None:
            return 0
        best = 0
        for attack_id in data.attacks:
            attack = self.b.attack(attack_id)
            if attack is None or not self.b.can_pay_attack(attacker, attack):
                continue
            if self.b.opp_active is None:
                continue
            damage, blocked, _ = self.b.resolved_attack_damage(
                attacker,
                attack,
                self.b.opp_active,
            )
            if blocked:
                continue
            best = max(best, damage)
        return best

    def _can_surfing_beach_switch(self, active: Pokemon, target: Pokemon) -> bool:
        return self.b.pid(active) in WATER_POKEMON and self.b.pid(target) in WATER_POKEMON

    def _survival_retreat_reason(self, active: Pokemon) -> bool:
        return self.b.active_in_danger() or self.b.public_lethal_next_turn()

    def _role_handoff(self, active: Pokemon, target: Pokemon, target_damage: int) -> bool:
        return (
            self.b.pid(active) in {CINDERACE, YVELTAL, SHAYMIN}
            and self.b.pid(target) in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX}
            and target_damage > 0
        )

    def _zero_energy_mega_wall(self, target: Pokemon, target_damage: int) -> bool:
        return self.b.pid(target) in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX} and self.b.energy_count(target) == 0 and target_damage == 0

    def _recent_my_attack_id(self) -> Optional[int]:
        logs = getattr(getattr(self.b, "obs", None), "logs", None)
        if logs is None:
            logs = getattr(self.b, "logs", [])
        for log in reversed(logs or []):
            if getattr(log, "type", None) == LogType.ATTACK and getattr(log, "playerIndex", None) == self.b.my_index:
                return getattr(log, "attackId", None)
        return None

    def _bypasses_ex_wall(self, attack: Any) -> bool:
        return self.b.attack_bypasses_ex_wall(attack)

    def _blocked_by_ex_wall(self, attacker: Pokemon, target: Pokemon, attack: Any) -> bool:
        return self.b.attack_blocked_by_ex_wall_for_card(self.b.pid(attacker), target, attack)


# ============================================================
# Candidate public projection
# ============================================================
class CandidateProjectionEvaluator:
    @classmethod
    def project(cls, board: BoardView, result: SimulationResult) -> CandidateProjection:
        option = result.option
        option_type = getattr(option, "type", None)
        if option_type == OptionType.ATTACK:
            return cls._project_attack(board, result)
        if option_type == OptionType.RETREAT:
            return cls._project_retreat(board, result)
        if option_type == OptionType.END:
            return cls._project_end(board, result)
        return cls._unsupported(result, "unsupported_action_type")

    @classmethod
    def project_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> CandidateProjectionFacts:
        option = result.option
        option_type = getattr(option, "type", None)
        if option_type == OptionType.ATTACK:
            return cls._project_attack_facts(board, result)
        if option_type == OptionType.RETREAT:
            return cls._project_switch_facts(board, result, "retreat")
        if (
            getattr(getattr(board, "select", None), "context", None)
            == SelectContext.SWITCH
            and board.option_target(option) is not None
        ):
            return cls._project_switch_facts(board, result, "switch")
        if option_type == OptionType.EVOLVE:
            return cls._project_active_evolution_facts(board, result)
        if option_type == OptionType.ATTACH:
            return cls._project_attach_facts(board, result)
        if option_type == OptionType.END:
            return cls._project_unchanged_facts(board, result)
        return cls._unsupported_facts(board, result, "unsupported_action_type")

    @classmethod
    def direct_attack_p6_input_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        projection: CandidateProjectionFacts,
    ) -> P6AttackDecisionInputFacts:
        option_type = getattr(result.option, "type", None)
        if (
            option_type != OptionType.ATTACK
            or getattr(result.option, "attackId", None) is None
        ):
            return cls._unsupported_attack_decision_input(
                "direct_attack_required",
            )
        if not result.outcome.supported:
            return cls._unsupported_attack_decision_input(
                "attack_immediate_outcome_unsupported",
                projection.attack_id,
                result.index,
                immediate_prizes_taken=result.outcome.prizes_taken,
                candidate_wins_game=bool(result.outcome.wins_game),
                projected_bench_unchanged=True,
            )
        if not projection.supported:
            return cls._unsupported_attack_decision_input(
                projection.unsupported_reason
                or "candidate_projection_unsupported",
                projection.attack_id,
                result.index,
                immediate_prizes_taken=result.outcome.prizes_taken,
                candidate_wins_game=bool(result.outcome.wins_game),
                projected_bench_unchanged=True,
            )
        if (
            projection.option_type != OptionType.ATTACK
            or projection.attack_id is None
        ):
            return cls._unsupported_attack_decision_input(
                "attack_projection_mismatch",
                projection.attack_id,
                result.index,
                immediate_prizes_taken=result.outcome.prizes_taken,
                candidate_wins_game=bool(result.outcome.wins_game),
                projected_bench_unchanged=True,
            )

        our_active = projected_active_public_facts(
            board,
            getattr(board, "active", None),
            status_owner=getattr(board, "me", None),
            projected_card_id=projection.projected_active_card_id,
            projected_serial=projection.projected_active_serial,
            projected_hp=projection.projected_active_hp,
            projected_max_hp=projection.projected_active_max_hp,
            projected_energy_tokens=(
                projection.projected_active_energy_tokens
                if projection.projected_active_energy_tokens is not None
                else None
            ),
            projected_tool_ids=projection.projected_active_tool_ids,
        )
        opponent_active = None
        if not projection.opponent_active_ko and not projection.terminal_win:
            opponent_active = projected_active_public_facts(
                board,
                getattr(board, "opp_active", None),
                status_owner=getattr(board, "opp", None),
                projected_hp=projection.projected_opponent_active_hp,
            )
        return P6AttackDecisionInputFacts(
            supported=True,
            decision_option_index=result.index,
            attack_id=projection.attack_id,
            combat_result_exact=True,
            confirmed_damage=result.outcome.damage,
            opponent_active_ko=projection.opponent_active_ko,
            immediate_prizes_taken=result.outcome.prizes_taken,
            candidate_wins_game=bool(result.outcome.wins_game),
            our_active=our_active,
            opponent_active_after_attack=opponent_active,
            projected_bench_unchanged=True,
            unsupported_reason=None,
        )

    @classmethod
    def _wally_owned_prepared_decision(
        cls, board: BoardView, origin_result: SimulationResult,
        decision: P6AttackDecisionInputFacts,
    ) -> P6AttackDecisionInputFacts:
        if not decision.supported:
            return replace(
                decision,
                decision_option_index=origin_result.index,
            )
        our_bench, our_reason = cls._public_bench_snapshot_facts(board, opponent=False)
        opponent_bench, opponent_reason = cls._public_bench_snapshot_facts(board, opponent=True)
        if our_reason is not None or opponent_reason is not None:
            return cls._unsupported_attack_decision_input(
                our_reason or opponent_reason or "prepared_attack_board_unrepresentable",
                decision.attack_id,
                origin_result.index,
                decision.immediate_prizes_taken,
                decision.candidate_wins_game,
                decision.projected_bench_unchanged,
            )
        return replace(
            decision,
            decision_option_index=origin_result.index,
            prepared_our_bench=our_bench,
            prepared_opponent_bench=opponent_bench,
            prepared_board_exact=True,
        )

    @classmethod
    def wally_recovery_direct_attack_p6_input_facts(
        cls, origin_board: BoardView, origin_result: Optional[SimulationResult],
        target_board: BoardView, target_result: Optional[SimulationResult],
        post_board: BoardView, attack_result: Optional[SimulationResult],
    ) -> P6AttackDecisionInputFacts:
        _before, reason = _wally_recovery_board_facts(
            origin_board, origin_result, target_board, target_result, post_board,
        )
        if reason is not None:
            return cls._unsupported_attack_decision_input(reason)
        if not _result_option_is_current(post_board, attack_result):
            return cls._unsupported_attack_decision_input(
                "wally_direct_attack_option_not_current",
            )
        direct = cls.direct_attack_p6_input_facts(
            post_board, attack_result, cls.project_facts(post_board, attack_result),
        )
        return cls._wally_owned_prepared_decision(post_board, origin_result, direct)

    @classmethod
    def wally_recovery_active_basic_attach_p6_input_facts(
        cls, origin_board: BoardView, origin_result: Optional[SimulationResult],
        target_board: BoardView, target_result: Optional[SimulationResult],
        post_board: BoardView, attach_board: BoardView,
        attach_result: Optional[SimulationResult],
    ) -> P6AttackDecisionInputFacts:
        before, reason = _wally_recovery_board_facts(
            origin_board, origin_result, target_board, target_result, post_board,
        )
        if reason is not None:
            return cls._unsupported_attack_decision_input(reason)
        if not _wally_public_boards_equal(post_board, attach_board):
            return cls._unsupported_attack_decision_input(
                "wally_attach_board_mismatch",
            )
        if not _result_option_is_current(attach_board, attach_result):
            return cls._unsupported_attack_decision_input(
                "wally_attach_option_not_current",
            )
        selected_copy = _wally_hand_option_copy(
            attach_board, attach_result.option, require_hand_area=True,
        )
        if selected_copy is None:
            return cls._unsupported_attack_decision_input(
                "wally_attach_energy_copy_unresolved",
            )
        recovered_copies = tuple(
            (facts.card_id, facts.serial) for facts in before.attached_energy
        )
        preexisting_copies = _wally_public_card_copies(getattr(target_board, "hand", ()))
        if (
            preexisting_copies is None
            or (
                selected_copy not in recovered_copies
                and selected_copy not in preexisting_copies
            )
        ):
            return cls._unsupported_attack_decision_input(
                "wally_attach_energy_copy_not_owned",
            )
        decision = cls.active_basic_energy_attach_p6_input_facts(
            attach_board, attach_result,
        )
        return cls._wally_owned_prepared_decision(
            attach_board, origin_result, decision,
        )

    @staticmethod
    def _public_bench_snapshot_facts(
        board: BoardView,
        *,
        opponent: bool,
    ) -> Tuple[
        Optional[Tuple[PokemonPublicSnapshotFacts, ...]],
        Optional[str],
    ]:
        bench = tuple(
            (
                getattr(board, "opp_bench", ())
                if opponent
                else getattr(board, "bench", ())
            )
            or ()
        )
        facts_list = []
        for pokemon in bench:
            facts, reason = _pokemon_public_snapshot_facts_with_reason(
                board,
                pokemon,
            )
            if facts is None:
                return None, reason or "prepared_attack_board_unrepresentable"
            facts_list.append(facts)
        return tuple(facts_list), None

    @classmethod
    def _prepared_transition_board_facts(
        cls,
        switch_board: BoardView,
        post_transition_board: BoardView,
        transition: ActiveBenchTransitionFacts,
    ) -> Tuple[
        Optional[Tuple[PokemonPublicSnapshotFacts, ...]],
        Optional[Tuple[PokemonPublicSnapshotFacts, ...]],
        Optional[str],
    ]:
        if (
            not transition.supported
            or not transition.transition_exact
            or not transition.status_exact
        ):
            return None, None, (
                transition.unsupported_reason
                or "effect_transition_required"
            )
        switch_key = _effect_sequence_state_key(switch_board)
        post_key = _effect_sequence_state_key(post_transition_board)
        if (
            switch_key is None
            or post_key is None
            or post_key != switch_key
            or getattr(switch_board, "my_index", None)
            != getattr(post_transition_board, "my_index", None)
        ):
            return None, None, "prepared_transition_sequence_mismatch"

        pre_our = _public_transition_side_signature(
            switch_board,
            opponent=False,
        )
        pre_opponent = _public_transition_side_signature(
            switch_board,
            opponent=True,
        )
        post_our = _public_transition_side_signature(
            post_transition_board,
            opponent=False,
        )
        post_opponent = _public_transition_side_signature(
            post_transition_board,
            opponent=True,
        )
        if any(
            signature is None
            for signature in (
                pre_our,
                pre_opponent,
                post_our,
                post_opponent,
            )
        ):
            return None, None, "prepared_attack_board_unrepresentable"

        affected_is_ours = (
            transition.origin_binding.affected_player_index
            == getattr(switch_board, "my_index", None)
        )
        if affected_is_ours:
            if (
                pre_our[0] != transition.old_active
                or pre_our[2] != transition.old_active_status_before
                or post_our
                != (
                    transition.new_active,
                    transition.projected_bench,
                    transition.new_active_status_after,
                )
                or post_opponent != pre_opponent
            ):
                return None, None, "prepared_transition_projection_mismatch"
        else:
            if (
                transition.origin_binding.affected_player_index
                != getattr(switch_board, "opp_index", None)
                or pre_opponent[0] != transition.old_active
                or pre_opponent[2] != transition.old_active_status_before
                or post_opponent
                != (
                    transition.new_active,
                    transition.projected_bench,
                    transition.new_active_status_after,
                )
                or post_our != pre_our
            ):
                return None, None, "prepared_transition_projection_mismatch"
        return post_our[1], post_opponent[1], None

    @classmethod
    def active_bench_transition_attack_p6_input_facts(
        cls,
        switch_board: BoardView,
        post_transition_board: BoardView,
        transition: ActiveBenchTransitionFacts,
        attack_result: Optional[SimulationResult],
    ) -> P6AttackDecisionInputFacts:
        our_bench, opponent_bench, board_reason = (
            cls._prepared_transition_board_facts(
                switch_board,
                post_transition_board,
                transition,
            )
        )
        if board_reason is not None:
            return cls._unsupported_attack_decision_input(board_reason)
        if attack_result is None:
            return cls._unsupported_attack_decision_input(
                "prepared_attack_result_required",
            )
        if not _result_option_is_current(
            post_transition_board,
            attack_result,
        ):
            return cls._unsupported_attack_decision_input(
                "prepared_attack_option_not_current",
            )
        if (
            transition.origin_binding.origin
            == ActiveBenchTransitionOrigin.SUGURI
            and "suguri_damage_boost"
            in tuple(getattr(attack_result.outcome, "reasons", ()) or ())
        ):
            return cls._unsupported_attack_decision_input(
                "suguri_switch_attack_branch_mismatch",
                getattr(attack_result.option, "attackId", None),
                attack_result.index,
            )

        projection = cls.project_facts(
            post_transition_board,
            attack_result,
        )
        decision = cls.direct_attack_p6_input_facts(
            post_transition_board,
            attack_result,
            projection,
        )
        if not decision.supported:
            return decision
        return replace(
            decision,
            prepared_our_bench=our_bench,
            prepared_opponent_bench=opponent_bench,
            prepared_board_exact=True,
        )

    @classmethod
    def active_evolution_attack_p6_input_facts(
        cls,
        board: BoardView,
        evolution_result: Optional[SimulationResult],
        attack_fact: Optional[ActiveEvolutionAttackFact],
    ) -> P6AttackDecisionInputFacts:
        if evolution_result is None:
            return cls._unsupported_attack_decision_input(
                "active_evolution_result_required",
            )
        option = evolution_result.option
        if getattr(option, "type", None) != OptionType.EVOLVE:
            return cls._unsupported_attack_decision_input(
                "active_evolution_required",
            )

        active = getattr(board, "active", None)
        opponent_active = getattr(board, "opp_active", None)
        if active is None:
            return cls._unsupported_attack_decision_input(
                "missing_current_active",
            )
        if board.option_target(option) is not active:
            return cls._unsupported_attack_decision_input(
                "current_active_evolution_target_required",
            )
        evolution_id = board.option_card(option)
        if (
            evolution_id is None
            or not board.evolves_from(evolution_id, active)
        ):
            return cls._unsupported_attack_decision_input(
                "invalid_active_evolution",
            )
        current_options = tuple(
            (index, current_option)
            for index, current_option in board.iter_options()
            if current_option is option
        )
        if (
            len(current_options) != 1
            or current_options[0][0] != evolution_result.index
        ):
            return cls._unsupported_attack_decision_input(
                "active_evolution_option_not_current",
            )
        if opponent_active is None:
            return cls._unsupported_attack_decision_input(
                "missing_current_opponent_active",
            )
        if any(
            bool(getattr(getattr(board, "me", None), status, False))
            for status in (
                "asleep",
                "confused",
                "paralyzed",
                "burned",
                "poisoned",
            )
        ):
            return cls._unsupported_attack_decision_input(
                "active_evolution_special_condition_unmodeled",
            )
        if attack_fact is None:
            return cls._unsupported_attack_decision_input(
                "active_evolution_attack_fact_required",
            )

        reachable_facts = tuple(
            board.active_evolution_attack_facts(option)
        )
        if not reachable_facts:
            return cls._unsupported_attack_decision_input(
                "active_evolution_no_same_turn_attack_chain",
            )
        if not evolution_result.outcome.supported:
            return cls._unsupported_attack_decision_input(
                "active_evolution_immediate_outcome_unsupported",
            )
        if sum(fact == attack_fact for fact in reachable_facts) != 1:
            return cls._unsupported_attack_decision_input(
                "active_evolution_attack_fact_mismatch",
                getattr(attack_fact, "attack_id", None),
            )

        projection = cls.project_facts(board, evolution_result)
        if not projection.supported:
            return cls._unsupported_attack_decision_input(
                projection.unsupported_reason
                or "active_evolution_projection_unsupported",
                attack_fact.attack_id,
            )
        if (
            type(projection.projected_active_card_id) is not int
            or projection.projected_active_card_id != int(evolution_id)
            or projection.projected_active_serial
            != getattr(active, "serial", None)
            or type(projection.projected_active_hp) is not int
            or type(projection.projected_active_max_hp) is not int
            or (
                projection.projected_active_max_hp
                - projection.projected_active_hp
                != damage_on(active)
            )
        ):
            return cls._unsupported_attack_decision_input(
                "active_evolution_damage_counters_unrepresentable",
                attack_fact.attack_id,
            )
        if projection.projected_active_energy_tokens is None:
            return cls._unsupported_attack_decision_input(
                "projected_active_energy_mapping_unsupported",
                attack_fact.attack_id,
            )
        try:
            our_active = projected_active_public_facts(
                board,
                active,
                status_owner=getattr(board, "me", None),
                projected_card_id=projection.projected_active_card_id,
                projected_serial=projection.projected_active_serial,
                projected_hp=projection.projected_active_hp,
                projected_max_hp=projection.projected_active_max_hp,
                projected_energy_tokens=(
                    projection.projected_active_energy_tokens
                ),
                projected_tool_ids=projection.projected_active_tool_ids,
            )
        except (TypeError, ValueError, OverflowError):
            return cls._unsupported_attack_decision_input(
                "active_evolution_snapshot_unrepresentable",
                attack_fact.attack_id,
            )
        if (
            our_active is None
            or our_active.damage_counters != damage_on(active)
            or our_active.energy_card_ids
            != tuple(int(card_id) for card_id in board.energies(active))
            or our_active.energy_tokens
            != tuple(projection.projected_active_energy_tokens)
            or our_active.tool_ids != cls._tool_ids(active)
            or any(
                (
                    our_active.asleep,
                    our_active.confused,
                    our_active.paralyzed,
                    our_active.burned,
                    our_active.poisoned,
                )
            )
        ):
            return cls._unsupported_attack_decision_input(
                "active_evolution_snapshot_unrepresentable",
                attack_fact.attack_id,
            )

        attack_id = getattr(attack_fact, "attack_id", None)
        evolution_data = board.data(evolution_id)
        if (
            type(attack_id) is not int
            or evolution_data is None
            or attack_id
            not in tuple(getattr(evolution_data, "attacks", ()) or ())
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_unknown",
                attack_id,
            )
        attack = board.attack(attack_id)
        if attack is None:
            return cls._unsupported_attack_decision_input(
                "missing_reachable_attack_definition",
                attack_id,
            )
        if not can_pay_attack_with_tokens(
            attack,
            projection.projected_active_energy_tokens,
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_attack_energy_unpayable",
                attack_id,
            )

        limitations = list(cls._attack_projection_limitations(attack))
        attack_text = _normalized_attack_text(attack)
        variable_damage_markers = (
            "for each",
            "times the amount",
            "number of",
            "more damage for each",
            "damage for each",
        )
        if (
            attack_id != RESENTFUL_REFRAIN
            and (
                any(
                    marker in attack_text
                    for marker in variable_damage_markers
                )
                or (
                    safe_int(getattr(attack, "damage", 0)) == 0
                    and "damage" in attack_text
                )
            )
        ):
            limitations.append("dynamic_attack_damage_unmodeled")
        if (
            ImmediateOutcomeEvaluator(board)._current_turn_supporter_id()
            == SUGURI
        ):
            limitations.append("suguri_damage_boost_unmodeled")

        public_effect_reason = OpponentPublicThreatEvaluator(
            board
        )._public_damage_effect_unsupported_reason(
            active,
            opponent_active,
        )
        if public_effect_reason is not None:
            limitations.append(public_effect_reason)
        for public_card in (
            tuple(
                getattr(getattr(board, "state", None), "stadium", None)
                or ()
            )
            + tuple(getattr(active, "tools", None) or ())
            + tuple(getattr(opponent_active, "tools", None) or ())
        ):
            if (
                PublicEffectKind.AFTER_DAMAGE_TRIGGERED_EFFECT
                in classify_public_effect(board.data(card_id(public_card)))
            ):
                limitations.append(
                    "public_after_damage_effect_unmodeled"
                )
        ignores_weakness_resistance = (
            "isn't affected by weakness or resistance" in attack_text
            or "is not affected by weakness or resistance" in attack_text
        )
        if not ignores_weakness_resistance:
            modifier_match = public_attack_matches_weakness_or_resistance(
                board,
                active,
                opponent_active,
                attack,
                attacker_card_id=int(evolution_id),
            )
            if modifier_match is not False:
                limitations.append(
                    "weakness_resistance_damage_unmodeled"
                )
        if cls._has_unmodeled_between_turn_damage(board):
            limitations.append("between_turn_effect_unmodeled")
        limitations = list(cls._unique(limitations))
        if limitations:
            return cls._unsupported_attack_decision_input(
                limitations[0],
                attack_id,
            )

        (
            expected_damage,
            expected_blocked,
            expected_prevention_reason,
        ) = board.resolved_attack_damage_for_card(
            int(evolution_id),
            attack,
            opponent_active,
        )
        expected_knockout = expected_damage >= hp_left(opponent_active)
        expected_prizes_taken = (
            board.prize_value(opponent_active)
            if expected_knockout
            else 0
        )
        expected_wins_game = bool(
            expected_knockout
            and expected_prizes_taken >= board.my_prizes_left()
        )
        expected_bench_damage = (
            0
            if expected_blocked
            else attack_bench_damage_amount(attack)
        )
        expected_bypasses_wall = bool(
            board.attack_bypasses_ex_wall(attack)
            and board.pid(opponent_active) in EX_ATTACK_WALLS
        )
        if (
            type(attack_fact.supported) is not bool
            or not attack_fact.supported
            or type(attack_fact.damage) is not int
            or type(attack_fact.blocked) is not bool
            or type(attack_fact.knockout) is not bool
            or type(attack_fact.prizes_taken) is not int
            or type(attack_fact.wins_game) is not bool
            or type(attack_fact.bench_damage) is not int
            or type(attack_fact.bypasses_wall) is not bool
            or (
                attack_fact.prevention_reason is not None
                and not isinstance(attack_fact.prevention_reason, str)
            )
            or attack_fact.blocked != expected_blocked
            or attack_fact.damage != expected_damage
            or attack_fact.knockout != expected_knockout
            or attack_fact.prizes_taken != expected_prizes_taken
            or attack_fact.wins_game != expected_wins_game
            or attack_fact.bench_damage != expected_bench_damage
            or attack_fact.bypasses_wall != expected_bypasses_wall
            or attack_fact.prevention_reason != expected_prevention_reason
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_combat_facts_inconsistent",
                attack_id,
            )

        opponent_active_after_attack = None
        if not expected_knockout and not expected_wins_game:
            try:
                opponent_active_after_attack = projected_active_public_facts(
                    board,
                    opponent_active,
                    status_owner=getattr(board, "opp", None),
                    projected_hp=max(
                        0,
                        hp_left(opponent_active) - expected_damage,
                    ),
                )
            except (TypeError, ValueError, OverflowError):
                return cls._unsupported_attack_decision_input(
                    "opponent_active_snapshot_unrepresentable",
                    attack_id,
                )
            if opponent_active_after_attack is None:
                return cls._unsupported_attack_decision_input(
                    "opponent_active_snapshot_unrepresentable",
                    attack_id,
                )

        return P6AttackDecisionInputFacts(
            supported=True,
            decision_option_index=None,
            attack_id=attack_id,
            combat_result_exact=True,
            confirmed_damage=expected_damage,
            opponent_active_ko=expected_knockout,
            immediate_prizes_taken=expected_prizes_taken,
            candidate_wins_game=expected_wins_game,
            our_active=our_active,
            opponent_active_after_attack=opponent_active_after_attack,
            projected_bench_unchanged=True,
            unsupported_reason=None,
        )

    @classmethod
    def static_hp_tool_attach_p6_input_facts(
        cls,
        board: BoardView,
        attach_result: Optional[SimulationResult],
        attack_result: Optional[SimulationResult],
    ) -> P6AttackDecisionInputFacts:
        if attach_result is None:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_attach_result_required",
            )
        attach_option = attach_result.option
        if getattr(attach_option, "type", None) != OptionType.ATTACH:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_attach_required",
            )

        active = getattr(board, "active", None)
        if active is None:
            return cls._unsupported_attack_decision_input(
                "missing_current_active",
            )
        if board.option_target(attach_option) is not active:
            return cls._unsupported_attack_decision_input(
                "current_active_attach_target_required",
            )

        attached_card_id = board.option_card(attach_option)
        attached_card_data = (
            board.data(attached_card_id)
            if attached_card_id is not None
            else None
        )
        if (
            attached_card_id is None
            or getattr(attached_card_data, "cardType", None)
            != CardType.TOOL
        ):
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_required",
            )

        hp_bonus = public_hp_bonus(attached_card_data)
        if hp_bonus is None:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_bonus_required",
            )
        if type(hp_bonus) is not int:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_bonus_not_fixed_integer",
            )
        if hp_bonus <= 0:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_bonus_not_positive",
            )
        if classify_public_effect(attached_card_data) != (
            PublicEffectKind.HP_AFFECTING,
        ):
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_effect_unmodeled",
            )
        if not attach_result.outcome.supported:
            return cls._unsupported_attack_decision_input(
                "attach_immediate_outcome_unsupported",
            )
        if attack_result is None:
            return cls._unsupported_attack_decision_input(
                "direct_attack_result_required",
            )

        attack_projection = cls.project_facts(board, attack_result)
        attack_decision = cls.direct_attack_p6_input_facts(
            board,
            attack_result,
            attack_projection,
        )
        if not attack_decision.supported:
            return (
                replace(
                    attack_decision,
                    decision_option_index=attach_result.index,
                )
                if attack_decision.attack_id is not None
                else attack_decision
            )
        if attack_decision.our_active is None:
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_snapshot_unrepresentable",
                attack_decision.attack_id,
                attach_result.index,
                attack_decision.immediate_prizes_taken,
                attack_decision.candidate_wins_game,
                attack_decision.projected_bench_unchanged,
            )

        try:
            projected_active = replace(
                attack_decision.our_active,
                hp=attack_decision.our_active.hp + hp_bonus,
                max_hp=attack_decision.our_active.max_hp + hp_bonus,
                tool_ids=(
                    attack_decision.our_active.tool_ids
                    + (int(attached_card_id),)
                ),
            )
        except (TypeError, ValueError, OverflowError):
            return cls._unsupported_attack_decision_input(
                "static_hp_tool_snapshot_unrepresentable",
                attack_decision.attack_id,
                attach_result.index,
                attack_decision.immediate_prizes_taken,
                attack_decision.candidate_wins_game,
                attack_decision.projected_bench_unchanged,
            )
        return replace(
            attack_decision,
            decision_option_index=attach_result.index,
            our_active=projected_active,
        )

    @classmethod
    def active_basic_energy_attach_p6_input_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> P6AttackDecisionInputFacts:
        option = result.option
        if getattr(option, "type", None) != OptionType.ATTACH:
            return cls._unsupported_attack_decision_input(
                "active_basic_energy_attach_required",
            )

        active = getattr(board, "active", None)
        opponent_active = getattr(board, "opp_active", None)
        if active is None:
            return cls._unsupported_attack_decision_input(
                "missing_current_active",
            )
        if board.option_target(option) is not active:
            return cls._unsupported_attack_decision_input(
                "current_active_attach_target_required",
            )

        attached_card_id = board.option_card(option)
        attached_card_data = (
            board.data(attached_card_id)
            if attached_card_id is not None
            else None
        )
        if (
            attached_card_id is None
            or getattr(attached_card_data, "cardType", None)
            != CardType.BASIC_ENERGY
        ):
            return cls._unsupported_attack_decision_input(
                "basic_energy_attach_required",
            )

        outcome = result.outcome
        if not outcome.supported:
            return cls._unsupported_attack_decision_input(
                "attach_immediate_outcome_unsupported",
            )
        if opponent_active is None:
            return cls._unsupported_attack_decision_input(
                "missing_current_opponent_active",
            )

        attack_id = getattr(outcome, "reachable_attack_id", None)
        if attack_id is None:
            return cls._unsupported_attack_decision_input(
                "reachable_attack_required",
            )
        try:
            attack_id = int(attack_id)
        except (TypeError, ValueError):
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_unknown",
            )
        intermediate_reasons = {
            "attach_access_via_retreat",
            "attach_access_via_boss",
            "attach_access_via_surfing_beach",
        }
        intermediate_reason = next(
            (
                reason
                for reason in tuple(getattr(outcome, "reasons", ()) or ())
                if reason in intermediate_reasons
            ),
            None,
        )
        if intermediate_reason is not None:
            return cls._unsupported_attack_decision_input(
                intermediate_reason,
                attack_id,
            )
        if not outcome.enables_attack:
            return cls._unsupported_attack_decision_input(
                "attach_does_not_enable_attack",
                attack_id,
            )
        try:
            enabled_attack_ids = tuple(
                int(enabled_attack_id)
                for enabled_attack_id in outcome.enabled_attack_ids
            )
        except (TypeError, ValueError):
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_unknown",
                attack_id,
            )
        if len(enabled_attack_ids) != 1:
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_not_unique",
                attack_id,
            )
        if enabled_attack_ids[0] != attack_id:
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_mismatch",
                attack_id,
            )

        active_data = board.data(board.pid(active))
        if (
            active_data is None
            or attack_id not in tuple(getattr(active_data, "attacks", ()) or ())
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_attack_identity_unknown",
                attack_id,
            )
        attack = board.attack(attack_id)
        if attack is None:
            return cls._unsupported_attack_decision_input(
                "missing_reachable_attack_definition",
                attack_id,
            )
        attack_text = _normalized_attack_text(attack)
        variable_damage_markers = (
            "for each",
            "times the amount",
            "number of",
            "more damage for each",
            "damage for each",
        )
        if (
            attack_id != RESENTFUL_REFRAIN
            and (
                any(
                    marker in attack_text
                    for marker in variable_damage_markers
                )
                or (
                    safe_int(getattr(attack, "damage", 0)) == 0
                    and "damage" in attack_text
                )
            )
        ):
            return cls._unsupported_attack_decision_input(
                "dynamic_attack_damage_unmodeled",
                attack_id,
            )
        if (
            ImmediateOutcomeEvaluator(board)._current_turn_supporter_id()
            == SUGURI
        ):
            return cls._unsupported_attack_decision_input(
                "suguri_damage_boost_unmodeled",
                attack_id,
            )

        limitations = list(cls._attack_projection_limitations(attack))
        limitations.extend(
            cls._public_damage_projection_limitations(
                board,
                active,
                opponent_active,
                attack,
            )
        )
        if cls._has_unmodeled_between_turn_damage(board):
            limitations.append("between_turn_effect_unmodeled")
        limitations = list(cls._unique(limitations))
        if limitations:
            return cls._unsupported_attack_decision_input(
                limitations[0],
                attack_id,
            )

        reachable_damage = getattr(outcome, "reachable_damage", None)
        reachable_knockout = getattr(outcome, "reachable_knockout", None)
        reachable_prizes_taken = getattr(
            outcome,
            "reachable_prizes_taken",
            None,
        )
        reachable_wins_game = getattr(outcome, "reachable_wins_game", None)
        if (
            type(reachable_damage) is not int
            or reachable_damage < 0
            or type(reachable_knockout) is not bool
            or type(reachable_prizes_taken) is not int
            or reachable_prizes_taken < 0
            or type(reachable_wins_game) is not bool
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_combat_exactness_unconfirmed",
                attack_id,
            )
        expected_damage, _, _ = board.resolved_attack_damage(
            active,
            attack,
            opponent_active,
        )
        if reachable_damage != expected_damage:
            return cls._unsupported_attack_decision_input(
                "reachable_combat_facts_inconsistent",
                attack_id,
                immediate_prizes_taken=reachable_prizes_taken,
                candidate_wins_game=reachable_wins_game,
                projected_bench_unchanged=True,
            )

        expected_knockout = reachable_damage >= hp_left(opponent_active)
        expected_prizes_taken = (
            board.prize_value(opponent_active)
            if expected_knockout
            else 0
        )
        expected_wins_game = bool(
            expected_knockout
            and expected_prizes_taken >= board.my_prizes_left()
        )
        if (
            reachable_knockout != expected_knockout
            or reachable_prizes_taken != expected_prizes_taken
            or reachable_wins_game != expected_wins_game
        ):
            return cls._unsupported_attack_decision_input(
                "reachable_combat_facts_inconsistent",
                attack_id,
                immediate_prizes_taken=reachable_prizes_taken,
                candidate_wins_game=reachable_wins_game,
                projected_bench_unchanged=True,
            )

        attached_tokens = energy_tokens_for_attach(
            int(attached_card_id),
            active,
        )
        if attached_tokens is None:
            return cls._unsupported_attack_decision_input(
                "unsupported_attach_energy",
                attack_id,
            )
        projected_energy_card_ids = (
            tuple(int(card_id) for card_id in board.energies(active))
            + (int(attached_card_id),)
        )
        projected_energy_tokens = (
            tuple(board.energy_tokens(active))
            + tuple(attached_tokens)
        )
        try:
            our_active = projected_active_public_facts(
                board,
                active,
                status_owner=getattr(board, "me", None),
                projected_energy_card_ids=projected_energy_card_ids,
                projected_energy_tokens=projected_energy_tokens,
            )
        except (TypeError, ValueError) as error:
            return cls._unsupported_attack_decision_input(
                str(error) or "projected_active_energy_mapping_unsupported",
                attack_id,
            )

        opponent_active_after_attack = None
        if not reachable_knockout and not reachable_wins_game:
            try:
                opponent_active_after_attack = projected_active_public_facts(
                    board,
                    opponent_active,
                    status_owner=getattr(board, "opp", None),
                    projected_hp=max(
                        0,
                        hp_left(opponent_active) - reachable_damage,
                    ),
                )
            except (TypeError, ValueError) as error:
                return cls._unsupported_attack_decision_input(
                    str(error)
                    or "projected_active_energy_mapping_unsupported",
                    attack_id,
                )
        return P6AttackDecisionInputFacts(
            supported=True,
            decision_option_index=None,
            attack_id=attack_id,
            combat_result_exact=True,
            confirmed_damage=reachable_damage,
            opponent_active_ko=reachable_knockout,
            immediate_prizes_taken=reachable_prizes_taken,
            candidate_wins_game=reachable_wins_game,
            our_active=our_active,
            opponent_active_after_attack=opponent_active_after_attack,
            projected_bench_unchanged=True,
            unsupported_reason=None,
        )

    @staticmethod
    def _unsupported_attack_decision_input(
        reason: str,
        attack_id: Optional[int] = None,
        decision_option_index: Optional[int] = None,
        immediate_prizes_taken: Optional[int] = None,
        candidate_wins_game: Optional[bool] = None,
        projected_bench_unchanged: bool = False,
    ) -> P6AttackDecisionInputFacts:
        return P6AttackDecisionInputFacts(
            supported=False,
            decision_option_index=decision_option_index,
            attack_id=attack_id,
            combat_result_exact=False,
            confirmed_damage=None,
            opponent_active_ko=None,
            immediate_prizes_taken=immediate_prizes_taken,
            candidate_wins_game=candidate_wins_game,
            our_active=None,
            opponent_active_after_attack=None,
            projected_bench_unchanged=projected_bench_unchanged,
            unsupported_reason=reason,
        )

    @classmethod
    def prize_exchange_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        projection: Optional[CandidateProjectionFacts] = None,
        threat: Optional[OpponentPublicThreatFacts] = None,
    ) -> PrizeExchangeFacts:
        outcome = result.outcome
        projection = projection or cls.project_facts(board, result)
        threat = threat or (
            OpponentPublicThreatEvaluator.evaluate_projected_facts(
                board,
                projection,
            )
            if projection.supported
            else None
        )
        return cls._prize_exchange_from_combat_facts(
            board,
            candidate_supported=bool(outcome.supported),
            immediate_prizes_taken=max(0, safe_int(outcome.prizes_taken)),
            candidate_wins_game=bool(outcome.wins_game),
            projection_supported=projection.supported,
            projection_unsupported_reason=projection.unsupported_reason,
            threat=threat,
        )

    @classmethod
    def _prize_exchange_from_combat_facts(
        cls,
        board: BoardView,
        *,
        candidate_supported: bool,
        immediate_prizes_taken: int,
        candidate_wins_game: bool,
        projection_supported: bool,
        projection_unsupported_reason: Optional[str],
        threat: Optional[OpponentPublicThreatFacts],
    ) -> PrizeExchangeFacts:
        immediate_prizes_taken = max(
            0,
            safe_int(immediate_prizes_taken),
        )
        my_prizes_left_after_candidate = max(
            0,
            board.my_prizes_left() - immediate_prizes_taken,
        )
        if not candidate_supported:
            return PrizeExchangeFacts(
                supported=False,
                immediate_prizes_taken=immediate_prizes_taken,
                my_prizes_left_after_candidate=my_prizes_left_after_candidate,
                confirmed_reply_supported=False,
                confirmed_reply_prizes_lost=0,
                opponent_prizes_left_after_reply=None,
                net_prize_exchange=None,
                candidate_wins_game=bool(candidate_wins_game),
                confirmed_reply_wins_game=None,
                unsupported_reason="candidate_immediate_outcome_unsupported",
            )

        if not projection_supported:
            return cls._reply_unsupported_prize_exchange_values(
                candidate_wins_game,
                immediate_prizes_taken,
                my_prizes_left_after_candidate,
                projection_unsupported_reason
                or "candidate_projection_unsupported",
            )

        if threat is None or not threat.supported:
            return cls._reply_unsupported_prize_exchange_values(
                candidate_wins_game,
                immediate_prizes_taken,
                my_prizes_left_after_candidate,
                (
                    None if threat is None else threat.unsupported_reason
                ) or "opponent_public_threat_unsupported",
            )

        opponent_prizes = getattr(
            getattr(board, "opp", None),
            "prize",
            None,
        )
        if opponent_prizes is None:
            return cls._reply_unsupported_prize_exchange_values(
                candidate_wins_game,
                immediate_prizes_taken,
                my_prizes_left_after_candidate,
                "missing_opponent_prize_state",
            )

        confirmed_reply_prizes_lost = (
            max(0, safe_int(threat.prizes_lost))
            if threat.can_ko_projected_active
            else 0
        )
        opponent_prizes_left_after_reply = max(
            0,
            len(opponent_prizes) - confirmed_reply_prizes_lost,
        )
        return PrizeExchangeFacts(
            supported=True,
            immediate_prizes_taken=immediate_prizes_taken,
            my_prizes_left_after_candidate=my_prizes_left_after_candidate,
            confirmed_reply_supported=True,
            confirmed_reply_prizes_lost=confirmed_reply_prizes_lost,
            opponent_prizes_left_after_reply=(
                opponent_prizes_left_after_reply
            ),
            net_prize_exchange=(
                immediate_prizes_taken
                - confirmed_reply_prizes_lost
            ),
            candidate_wins_game=bool(candidate_wins_game),
            confirmed_reply_wins_game=bool(
                threat.can_ko_projected_active
                and opponent_prizes_left_after_reply == 0
            ),
            unsupported_reason=None,
        )

    @staticmethod
    def _reply_unsupported_prize_exchange(
        outcome: ImmediateOutcome,
        immediate_prizes_taken: int,
        my_prizes_left_after_candidate: int,
        reason: str,
    ) -> PrizeExchangeFacts:
        return CandidateProjectionEvaluator._reply_unsupported_prize_exchange_values(
            bool(outcome.wins_game),
            immediate_prizes_taken,
            my_prizes_left_after_candidate,
            reason,
        )

    @staticmethod
    def _reply_unsupported_prize_exchange_values(
        candidate_wins_game: bool,
        immediate_prizes_taken: int,
        my_prizes_left_after_candidate: int,
        reason: str,
    ) -> PrizeExchangeFacts:
        return PrizeExchangeFacts(
            supported=True,
            immediate_prizes_taken=immediate_prizes_taken,
            my_prizes_left_after_candidate=my_prizes_left_after_candidate,
            confirmed_reply_supported=False,
            confirmed_reply_prizes_lost=0,
            opponent_prizes_left_after_reply=None,
            net_prize_exchange=None,
            candidate_wins_game=bool(candidate_wins_game),
            confirmed_reply_wins_game=None,
            unsupported_reason=reason,
        )

    @classmethod
    def board_out_facts(
        cls,
        board: BoardView,
        projection: CandidateProjectionFacts,
        threat: Optional[OpponentPublicThreatFacts] = None,
    ) -> BoardOutFacts:
        threat = threat or (
            OpponentPublicThreatEvaluator.evaluate_projected_facts(
                board,
                projection,
            )
            if projection.supported
            else None
        )
        return cls._board_out_from_projected_active(
            board,
            projection_supported=projection.supported,
            projected_active_card_id=projection.projected_active_card_id,
            projected_active_hp=projection.projected_active_hp,
            projection_unsupported_reason=projection.unsupported_reason,
            threat=threat,
        )

    @classmethod
    def _board_out_from_projected_active(
        cls,
        board: BoardView,
        *,
        projection_supported: bool,
        projected_active_card_id: Optional[int],
        projected_active_hp: Optional[int],
        projection_unsupported_reason: Optional[str],
        threat: Optional[OpponentPublicThreatFacts],
    ) -> BoardOutFacts:
        if (
            not projection_supported
            or projected_active_card_id is None
            or projected_active_hp is None
        ):
            return BoardOutFacts(
                supported=False,
                projected_bench_count=None,
                board_out_if_projected_active_ko=None,
                confirmed_reply_supported=False,
                confirmed_reply_ko=None,
                confirmed_reply_causes_board_out=None,
                unsupported_reason=(
                    projection_unsupported_reason
                    or "candidate_projection_unsupported"
                ),
            )

        projected_bench_count = len(getattr(board, "bench", ()) or ())
        board_out_if_projected_active_ko = projected_bench_count == 0
        if threat is None or not threat.supported:
            return BoardOutFacts(
                supported=True,
                projected_bench_count=projected_bench_count,
                board_out_if_projected_active_ko=(
                    board_out_if_projected_active_ko
                ),
                confirmed_reply_supported=False,
                confirmed_reply_ko=None,
                confirmed_reply_causes_board_out=None,
                unsupported_reason=(
                    (None if threat is None else threat.unsupported_reason)
                    or "opponent_public_threat_unsupported"
                ),
            )

        confirmed_reply_ko = bool(threat.can_ko_projected_active)
        return BoardOutFacts(
            supported=True,
            projected_bench_count=projected_bench_count,
            board_out_if_projected_active_ko=(
                board_out_if_projected_active_ko
            ),
            confirmed_reply_supported=True,
            confirmed_reply_ko=confirmed_reply_ko,
            confirmed_reply_causes_board_out=bool(
                confirmed_reply_ko
                and board_out_if_projected_active_ko
            ),
            unsupported_reason=None,
        )

    @classmethod
    def next_attacker_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        projection: CandidateProjectionFacts,
        threat: Optional[OpponentPublicThreatFacts] = None,
    ) -> NextAttackerFacts:
        if (
            not projection.supported
            or projection.projected_opponent_active_hp is None
            or projection.opponent_active_ko
            or board.opp_active is None
        ):
            return cls._unsupported_next_attacker_facts(
                projection.unsupported_reason
                or (
                    "opponent_promotion_required"
                    if projection.opponent_active_ko
                    else "candidate_projection_unsupported"
                )
            )

        projected_bench, bench_reason = cls._projected_bench_for_next_attacker(
            board,
            result,
            projection,
        )
        if projected_bench is None:
            return cls._unsupported_next_attacker_facts(bench_reason)

        threat = threat or OpponentPublicThreatEvaluator.evaluate_projected_facts(
            board,
            projection,
        )
        return cls._next_attacker_for_projected_bench(
            board,
            projected_bench=projected_bench,
            projected_opponent_active_hp=(
                projection.projected_opponent_active_hp
            ),
            threat=threat,
        )

    @classmethod
    def _next_attacker_for_projected_bench(
        cls,
        board: BoardView,
        *,
        projected_bench: Tuple[Pokemon, ...],
        projected_opponent_active_hp: int,
        threat: OpponentPublicThreatFacts,
    ) -> NextAttackerFacts:
        projected_bench_count = len(projected_bench)
        serials = tuple(
            getattr(pokemon, "serial", None)
            for pokemon in projected_bench
        )
        if any(type(serial) is not int for serial in serials):
            return cls._unsupported_next_attacker_facts(
                "missing_projected_bench_serial",
                projected_bench_count,
            )
        if len(set(serials)) != len(serials):
            return cls._unsupported_next_attacker_facts(
                "duplicate_projected_bench_serial",
                projected_bench_count,
            )

        confirmed_by_serial: Dict[
            int,
            Tuple[Pokemon, Tuple[Tuple[int, int, bool], ...]],
        ] = {}
        unknown_attack_ids_by_serial: Dict[int, Tuple[int, ...]] = {}
        damage_probe = OpponentPublicThreatEvaluator(board)
        attack_evaluator = ImmediateOutcomeEvaluator(board)
        target = board.opp_active
        target_hp = max(0, safe_int(projected_opponent_active_hp))
        uncertain_damage_markers = (
            "for each",
            "more damage",
            "less damage",
            "times the number",
            "equal to",
            "instead of",
            "flip a coin",
            "flip coins",
            "if heads",
            "if tails",
            "at random",
            "random",
        )

        for pokemon in projected_bench:
            serial = safe_int(getattr(pokemon, "serial", None))
            pokemon_id = board.pid(pokemon)
            pokemon_data = board.data(pokemon_id)
            if pokemon_data is None:
                return cls._unsupported_next_attacker_facts(
                    "missing_projected_bench_card_data",
                    projected_bench_count,
                )
            missing_public_tokens = object()
            public_tokens = getattr(
                pokemon,
                "energies",
                missing_public_tokens,
            )
            if public_tokens is missing_public_tokens:
                tokens = cls._exact_energy_tokens_as(
                    board,
                    pokemon,
                    pokemon_id,
                )
            elif (
                not isinstance(public_tokens, Sequence)
                or isinstance(public_tokens, (str, bytes))
            ):
                tokens = None
            else:
                normalized_tokens: List[Any] = []
                for token in tuple(public_tokens):
                    if type(token) is bool:
                        normalized_tokens = []
                        tokens = None
                        break
                    if isinstance(token, EnergyType):
                        normalized_tokens.append(token)
                        continue
                    if type(token) is int:
                        try:
                            normalized_tokens.append(EnergyType(token))
                        except ValueError:
                            normalized_tokens = []
                            tokens = None
                            break
                        continue
                    if isinstance(token, str):
                        token_name = token.strip().upper()
                        if token_name.startswith("ENERGYTYPE."):
                            token_name = token_name.split(".", 1)[1]
                        try:
                            normalized_tokens.append(EnergyType[token_name])
                        except KeyError:
                            normalized_tokens = []
                            tokens = None
                            break
                        continue
                    normalized_tokens = []
                    tokens = None
                    break
                else:
                    tokens = tuple(normalized_tokens)
            confirmed_attacks: List[Tuple[int, int, bool]] = []
            unknown_attack_ids: List[int] = []
            for attack_id in dict.fromkeys(
                getattr(pokemon_data, "attacks", ()) or ()
            ):
                resolved_attack_id = safe_int(attack_id)
                attack = board.attack(attack_id)
                if attack is None or tokens is None:
                    unknown_attack_ids.append(resolved_attack_id)
                    continue
                if not can_pay_attack_with_tokens(attack, tokens):
                    continue
                attack_text = _normalized_attack_text(attack)
                if any(
                    marker in attack_text
                    for marker in uncertain_damage_markers
                ):
                    unknown_attack_ids.append(resolved_attack_id)
                    continue
                _, damage_reason = damage_probe._certain_damage(
                    pokemon,
                    attack,
                )
                if damage_reason is not None:
                    unknown_attack_ids.append(resolved_attack_id)
                    continue
                limitations = cls._unique(
                    cls._attack_projection_limitations(attack)
                    + cls._public_damage_projection_limitations(
                        board,
                        pokemon,
                        target,
                        attack,
                    )
                )
                if limitations:
                    unknown_attack_ids.append(resolved_attack_id)
                    continue
                outcome = attack_evaluator._attack_outcome_with_tokens_against(
                    pokemon,
                    resolved_attack_id,
                    tokens,
                    target,
                    "next_attacker_public_fact",
                )
                if not outcome.supported:
                    unknown_attack_ids.append(resolved_attack_id)
                    continue
                damage = max(0, safe_int(outcome.damage))
                confirmed_attacks.append((
                    resolved_attack_id,
                    damage,
                    bool(damage > 0 and damage >= target_hp),
                ))

            if confirmed_attacks:
                confirmed_by_serial[serial] = (
                    pokemon,
                    tuple(confirmed_attacks),
                )
            if unknown_attack_ids:
                unknown_attack_ids_by_serial[serial] = tuple(
                    sorted(set(unknown_attack_ids))
                )

        attack_candidates = [
            (
                knockout,
                damage,
                serial,
                attack_id,
                pokemon,
                attacks,
            )
            for serial, (pokemon, attacks) in confirmed_by_serial.items()
            for attack_id, damage, knockout in attacks
        ]
        unknown_attack_ids = tuple(sorted({
            attack_id
            for attack_ids in unknown_attack_ids_by_serial.values()
            for attack_id in attack_ids
        }))
        unknown_only_serials = (
            set(unknown_attack_ids_by_serial) - set(confirmed_by_serial)
        )
        unknown_outcome_exists = bool(unknown_attack_ids)

        if attack_candidates:
            best = min(
                attack_candidates,
                key=lambda item: (
                    not item[0],
                    -item[1],
                    item[2],
                    item[3],
                ),
            )
            (
                confirmed_best_ko,
                best_damage,
                best_serial,
                best_attack_id,
                best_pokemon,
                best_attacks,
            ) = best
            usable_attack_ids = tuple(sorted({
                attack_id for attack_id, _, _ in best_attacks
            }))
            best_card_id = board.pid(best_pokemon)
        else:
            confirmed_best_ko = False
            best_damage = None if unknown_outcome_exists else 0
            best_serial = None
            best_card_id = None
            best_attack_id = None
            usable_attack_ids = ()

        if confirmed_by_serial:
            ready_exists: Optional[bool] = True
        elif unknown_only_serials:
            ready_exists = None
        else:
            ready_exists = False
        ready_count = (
            None
            if unknown_only_serials
            else len(confirmed_by_serial)
        )
        can_ko: Optional[bool]
        if confirmed_best_ko:
            can_ko = True
        elif unknown_outcome_exists:
            can_ko = None
        else:
            can_ko = False

        confirmed_reply_supported = bool(threat.supported)
        confirmed_reply_ko = (
            bool(threat.can_ko_projected_active)
            if threat.supported
            else None
        )
        confirmed_reply_has_ready = (
            None
            if not threat.supported
            else ready_exists
            if confirmed_reply_ko
            else False
        )
        return NextAttackerFacts(
            supported=True,
            projected_bench_count=projected_bench_count,
            ready_next_attacker_exists=ready_exists,
            ready_next_attacker_count=ready_count,
            best_confirmed_damage=best_damage,
            can_ko_projected_opponent_active=can_ko,
            best_next_attacker_card_id=best_card_id,
            best_next_attacker_serial=best_serial,
            best_attack_id=best_attack_id,
            usable_attack_ids=usable_attack_ids,
            confirmed_reply_supported=confirmed_reply_supported,
            confirmed_reply_ko=confirmed_reply_ko,
            confirmed_reply_has_ready_next_attacker=(
                confirmed_reply_has_ready
            ),
            unsupported_reason=(
                None
                if threat.supported
                else threat.unsupported_reason
                or "opponent_public_threat_unsupported"
            ),
            confirmed_ready_next_attacker_count=len(confirmed_by_serial),
            unknown_ready_next_attacker_count=len(unknown_only_serials),
            unknown_usable_attack_ids=unknown_attack_ids,
        )

    @classmethod
    def attack_decision_outcome_facts(
        cls,
        board: BoardView,
        decision: P6AttackDecisionInputFacts,
    ) -> DirectDecisionOutcomeFacts:
        return cls._attack_decision_p6_facts(
            board,
            decision,
        )[-1]

    @classmethod
    def _attack_decision_p6_facts(
        cls,
        board: BoardView,
        decision: P6AttackDecisionInputFacts,
    ) -> Tuple[
        OpponentPublicThreatFacts,
        PrizeExchangeFacts,
        BoardOutFacts,
        NextAttackerFacts,
        DirectDecisionOutcomeFacts,
    ]:
        if decision.supported and decision.prepared_board_exact:
            current_our_bench, our_reason = (
                cls._public_bench_snapshot_facts(
                    board,
                    opponent=False,
                )
            )
            current_opponent_bench, opponent_reason = (
                cls._public_bench_snapshot_facts(
                    board,
                    opponent=True,
                )
            )
            if (
                our_reason is not None
                or opponent_reason is not None
                or current_our_bench != decision.prepared_our_bench
                or current_opponent_bench
                != decision.prepared_opponent_bench
            ):
                decision = cls._unsupported_attack_decision_input(
                    "prepared_attack_board_mismatch",
                    decision.attack_id,
                    decision.decision_option_index,
                    decision.immediate_prizes_taken,
                    decision.candidate_wins_game,
                    decision.projected_bench_unchanged,
                )
        if decision.supported:
            return cls._supported_attack_decision_p6_facts(board, decision)

        reason = (
            decision.unsupported_reason
            or "candidate_projection_unsupported"
        )
        threat = OpponentPublicThreatFacts(
            supported=False,
            best_confirmed_damage=0,
            can_ko_projected_active=False,
            prizes_lost=0,
            usable_attack_ids=(),
            unsupported_reason="candidate_projection_unsupported",
        )
        candidate_outcome_supported = (
            reason != "attack_immediate_outcome_unsupported"
            and reason != "direct_attack_required"
        )
        prize_exchange = cls._prize_exchange_from_combat_facts(
            board,
            candidate_supported=candidate_outcome_supported,
            immediate_prizes_taken=(
                decision.immediate_prizes_taken
                if decision.immediate_prizes_taken is not None
                else 0
            ),
            candidate_wins_game=bool(decision.candidate_wins_game),
            projection_supported=False,
            projection_unsupported_reason=reason,
            threat=threat,
        )
        board_out = cls._board_out_from_projected_active(
            board,
            projection_supported=False,
            projected_active_card_id=None,
            projected_active_hp=None,
            projection_unsupported_reason=reason,
            threat=threat,
        )
        next_attacker = cls._unsupported_next_attacker_facts(reason)
        direct_outcome = cls._unsupported_direct_decision_outcome(
            reason,
            decision.attack_id,
        )
        return (
            threat,
            prize_exchange,
            board_out,
            next_attacker,
            direct_outcome,
        )

    @classmethod
    def _supported_attack_decision_p6_facts(
        cls,
        board: BoardView,
        decision: P6AttackDecisionInputFacts,
    ) -> Tuple[
        OpponentPublicThreatFacts,
        PrizeExchangeFacts,
        BoardOutFacts,
        NextAttackerFacts,
        DirectDecisionOutcomeFacts,
    ]:
        if (
            not decision.supported
            or decision.our_active is None
            or decision.attack_id is None
            or decision.confirmed_damage is None
            or decision.opponent_active_ko is None
            or decision.immediate_prizes_taken is None
            or decision.candidate_wins_game is None
            or not decision.combat_result_exact
            or not decision.projected_bench_unchanged
        ):
            raise ValueError("unsupported_attack_decision_p6_input")

        threat = OpponentPublicThreatEvaluator.evaluate_public_active_facts(
            board,
            decision.our_active,
            decision.opponent_active_after_attack,
            terminal_win=decision.candidate_wins_game,
            opponent_active_ko=decision.opponent_active_ko,
        )
        prize_exchange = cls._prize_exchange_from_combat_facts(
            board,
            candidate_supported=True,
            immediate_prizes_taken=decision.immediate_prizes_taken,
            candidate_wins_game=decision.candidate_wins_game,
            projection_supported=True,
            projection_unsupported_reason=None,
            threat=threat,
        )
        board_out = cls._board_out_from_projected_active(
            board,
            projection_supported=True,
            projected_active_card_id=decision.our_active.card_id,
            projected_active_hp=decision.our_active.hp,
            projection_unsupported_reason=None,
            threat=threat,
        )
        if (
            decision.opponent_active_ko
            or decision.opponent_active_after_attack is None
            or board.opp_active is None
        ):
            next_attacker = cls._unsupported_next_attacker_facts(
                "opponent_promotion_required"
                if decision.opponent_active_ko
                else "candidate_projection_unsupported"
            )
        else:
            next_attacker = cls._next_attacker_for_projected_bench(
                board,
                projected_bench=tuple(getattr(board, "bench", ()) or ()),
                projected_opponent_active_hp=(
                    decision.opponent_active_after_attack.hp
                ),
                threat=threat,
            )
        direct_outcome = cls._direct_decision_outcome_from_combat_facts(
            attack_id=decision.attack_id,
            confirmed_damage=decision.confirmed_damage,
            opponent_active_ko=decision.opponent_active_ko,
            candidate_wins_game=decision.candidate_wins_game,
            threat=threat,
            prize_exchange=prize_exchange,
            board_out=board_out,
            next_attacker=next_attacker,
        )
        return (
            threat,
            prize_exchange,
            board_out,
            next_attacker,
            direct_outcome,
        )

    @classmethod
    def direct_decision_outcome_facts(
        cls,
        result: SimulationResult,
        projection: CandidateProjectionFacts,
        threat: OpponentPublicThreatFacts,
        prize_exchange: PrizeExchangeFacts,
        board_out: BoardOutFacts,
        next_attacker: NextAttackerFacts,
    ) -> DirectDecisionOutcomeFacts:
        option_type = getattr(result.option, "type", None)
        if (
            option_type != OptionType.ATTACK
            or getattr(result.option, "attackId", None) is None
        ):
            return cls._unsupported_direct_decision_outcome(
                "direct_attack_required",
            )
        if not result.outcome.supported:
            return cls._unsupported_direct_decision_outcome(
                "attack_immediate_outcome_unsupported",
                projection.attack_id,
            )
        if not projection.supported:
            return cls._unsupported_direct_decision_outcome(
                projection.unsupported_reason
                or "candidate_projection_unsupported",
                projection.attack_id,
            )
        if (
            projection.option_type != OptionType.ATTACK
            or projection.attack_id is None
        ):
            return cls._unsupported_direct_decision_outcome(
                "attack_projection_mismatch",
                projection.attack_id,
            )
        if not prize_exchange.supported:
            return cls._unsupported_direct_decision_outcome(
                prize_exchange.unsupported_reason
                or "prize_exchange_unsupported",
                projection.attack_id,
            )

        return cls._direct_decision_outcome_from_combat_facts(
            attack_id=projection.attack_id,
            confirmed_damage=result.outcome.damage,
            opponent_active_ko=projection.opponent_active_ko,
            candidate_wins_game=bool(result.outcome.wins_game),
            threat=threat,
            prize_exchange=prize_exchange,
            board_out=board_out,
            next_attacker=next_attacker,
        )

    @classmethod
    def _direct_decision_outcome_from_combat_facts(
        cls,
        *,
        attack_id: int,
        confirmed_damage: int,
        opponent_active_ko: bool,
        candidate_wins_game: bool,
        threat: OpponentPublicThreatFacts,
        prize_exchange: PrizeExchangeFacts,
        board_out: BoardOutFacts,
        next_attacker: NextAttackerFacts,
    ) -> DirectDecisionOutcomeFacts:
        next_attacker_can_ko = (
            next_attacker.can_ko_projected_opponent_active
            if next_attacker.supported
            else None
        )
        next_attacker_confirmed_damage = (
            next_attacker.best_confirmed_damage
            if next_attacker.supported
            else None
        )
        reply_information_supported = bool(
            threat.supported
            and prize_exchange.confirmed_reply_supported
            and board_out.confirmed_reply_supported
        )
        if not reply_information_supported:
            return DirectDecisionOutcomeFacts(
                supported=True,
                attack_id=attack_id,
                confirmed_damage=confirmed_damage,
                opponent_active_ko=opponent_active_ko,
                immediate_prizes_taken=(
                    prize_exchange.immediate_prizes_taken
                ),
                candidate_wins_game=candidate_wins_game,
                reply_information_supported=False,
                confirmed_reply_damage=None,
                confirmed_reply_ko=None,
                confirmed_reply_prizes_lost=None,
                confirmed_loss_by_prize=None,
                confirmed_loss_by_board_out=None,
                confirmed_loss=None,
                net_prize_exchange=prize_exchange.net_prize_exchange,
                my_prizes_left_after_candidate=(
                    prize_exchange.my_prizes_left_after_candidate
                ),
                opponent_prizes_left_after_reply=(
                    prize_exchange.opponent_prizes_left_after_reply
                ),
                projected_active_survives_confirmed_reply=None,
                has_ready_next_attacker_after_reply=None,
                next_attacker_can_ko=next_attacker_can_ko,
                next_attacker_confirmed_damage=(
                    next_attacker_confirmed_damage
                ),
                unsupported_reason=(
                    threat.unsupported_reason
                    or prize_exchange.unsupported_reason
                    or board_out.unsupported_reason
                    or next_attacker.unsupported_reason
                    or "reply_information_unsupported"
                ),
            )

        confirmed_loss_by_prize = (
            prize_exchange.confirmed_reply_wins_game
        )
        confirmed_loss_by_board_out = (
            board_out.confirmed_reply_causes_board_out
        )
        return DirectDecisionOutcomeFacts(
            supported=True,
            attack_id=attack_id,
            confirmed_damage=confirmed_damage,
            opponent_active_ko=opponent_active_ko,
            immediate_prizes_taken=(
                prize_exchange.immediate_prizes_taken
            ),
            candidate_wins_game=candidate_wins_game,
            reply_information_supported=True,
            confirmed_reply_damage=threat.best_confirmed_damage,
            confirmed_reply_ko=threat.can_ko_projected_active,
            confirmed_reply_prizes_lost=(
                prize_exchange.confirmed_reply_prizes_lost
            ),
            confirmed_loss_by_prize=confirmed_loss_by_prize,
            confirmed_loss_by_board_out=confirmed_loss_by_board_out,
            confirmed_loss=bool(
                confirmed_loss_by_prize
                or confirmed_loss_by_board_out
            ),
            net_prize_exchange=prize_exchange.net_prize_exchange,
            my_prizes_left_after_candidate=(
                prize_exchange.my_prizes_left_after_candidate
            ),
            opponent_prizes_left_after_reply=(
                prize_exchange.opponent_prizes_left_after_reply
            ),
            projected_active_survives_confirmed_reply=not bool(
                threat.can_ko_projected_active
            ),
            has_ready_next_attacker_after_reply=(
                next_attacker.confirmed_reply_has_ready_next_attacker
            ),
            next_attacker_can_ko=next_attacker_can_ko,
            next_attacker_confirmed_damage=(
                next_attacker_confirmed_damage
            ),
            unsupported_reason=None,
        )

    @staticmethod
    def _unsupported_direct_decision_outcome(
        reason: str,
        attack_id: Optional[int] = None,
    ) -> DirectDecisionOutcomeFacts:
        return DirectDecisionOutcomeFacts(
            supported=False,
            attack_id=attack_id,
            confirmed_damage=None,
            opponent_active_ko=None,
            immediate_prizes_taken=None,
            candidate_wins_game=None,
            reply_information_supported=False,
            confirmed_reply_damage=None,
            confirmed_reply_ko=None,
            confirmed_reply_prizes_lost=None,
            confirmed_loss_by_prize=None,
            confirmed_loss_by_board_out=None,
            confirmed_loss=None,
            net_prize_exchange=None,
            my_prizes_left_after_candidate=None,
            opponent_prizes_left_after_reply=None,
            projected_active_survives_confirmed_reply=None,
            has_ready_next_attacker_after_reply=None,
            next_attacker_can_ko=None,
            next_attacker_confirmed_damage=None,
            unsupported_reason=reason,
        )

    @classmethod
    def _projected_bench_for_next_attacker(
        cls,
        board: BoardView,
        result: SimulationResult,
        projection: CandidateProjectionFacts,
    ) -> Tuple[Optional[Tuple[Pokemon, ...]], Optional[str]]:
        option_type = getattr(result.option, "type", None)
        current_bench = tuple(getattr(board, "bench", ()) or ())
        is_switch = (
            option_type == OptionType.RETREAT
            or (
                getattr(getattr(board, "select", None), "context", None)
                == SelectContext.SWITCH
                and board.option_target(result.option) is not None
            )
        )
        if is_switch:
            if (
                option_type == OptionType.RETREAT
                and safe_int(result.outcome.retreat_energy_cost) > 0
            ):
                return None, "retreat_energy_discard_unresolved"
            target_serial = projection.projected_active_serial
            active = getattr(board, "active", None)
            active_serial = getattr(active, "serial", None)
            if target_serial is None or active is None or active_serial is None:
                return None, "missing_switch_projection_state"
            target_matches = tuple(
                pokemon
                for pokemon in current_bench
                if getattr(pokemon, "serial", None) == target_serial
            )
            if len(target_matches) != 1:
                return None, "ambiguous_switch_projection_target"
            return (
                tuple(
                    pokemon
                    for pokemon in current_bench
                    if getattr(pokemon, "serial", None) != target_serial
                )
                + (active,)
            ), None

        if option_type not in {
            OptionType.END,
            OptionType.ATTACK,
            OptionType.EVOLVE,
            OptionType.ATTACH,
        }:
            return None, "unsupported_next_attacker_action_type"
        return current_bench, None

    @staticmethod
    def _unsupported_next_attacker_facts(
        reason: Optional[str],
        projected_bench_count: Optional[int] = None,
    ) -> NextAttackerFacts:
        return NextAttackerFacts(
            supported=False,
            projected_bench_count=projected_bench_count,
            ready_next_attacker_exists=None,
            ready_next_attacker_count=None,
            best_confirmed_damage=None,
            can_ko_projected_opponent_active=None,
            best_next_attacker_card_id=None,
            best_next_attacker_serial=None,
            best_attack_id=None,
            usable_attack_ids=(),
            confirmed_reply_supported=False,
            confirmed_reply_ko=None,
            confirmed_reply_has_ready_next_attacker=None,
            unsupported_reason=reason or "next_attacker_unsupported",
            confirmed_ready_next_attacker_count=None,
            unknown_ready_next_attacker_count=None,
            unknown_usable_attack_ids=(),
        )

    @classmethod
    def _project_attack_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> CandidateProjectionFacts:
        projection = cls.project(board, result)
        active = getattr(board, "active", None)
        opponent = getattr(board, "opp_active", None)
        if active is None or opponent is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_attack_state",
            )
        if (
            projection.confidence != CandidateProjectionConfidence.EXACT
            or not projection.combat_result_exact
        ):
            return cls._unsupported_facts(
                board,
                result,
                projection.unsupported_reason or "attack_projection_not_exact",
            )
        return cls._supported_facts(
            board,
            result,
            active=active,
            active_card_id=board.pid(active),
            active_hp=hp_left(active),
            active_max_hp=max_hp(active),
            energy_tokens=cls._exact_energy_tokens_as(
                board,
                active,
                board.pid(active),
            ),
            tool_ids=cls._tool_ids(active),
            opponent_hp=max(
                0,
                hp_left(opponent) - max(0, safe_int(result.outcome.damage)),
            ),
            terminal_win=bool(result.outcome.wins_game),
            opponent_active_ko=bool(result.outcome.knockout),
        )

    @classmethod
    def _project_switch_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        source: str,
    ) -> CandidateProjectionFacts:
        active = getattr(board, "active", None)
        target = board.option_target(result.option)
        if active is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_current_active",
            )
        if target is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_explicit_switch_target",
            )
        if target not in getattr(board, "bench", ()):
            return cls._unsupported_facts(
                board,
                result,
                "invalid_switch_target",
            )
        if not result.outcome.supported:
            return cls._unsupported_facts(
                board,
                result,
                f"{source}_immediate_outcome_unsupported",
            )
        transition_reason = OpponentPublicThreatEvaluator(
            board
        )._public_retreat_effect_unsupported_reason(active, target)
        if transition_reason is not None:
            return cls._unsupported_facts(
                board,
                result,
                transition_reason,
            )
        return cls._supported_facts(
            board,
            result,
            active=target,
            active_card_id=board.pid(target),
            active_hp=hp_left(target),
            active_max_hp=max_hp(target),
            energy_tokens=cls._exact_energy_tokens_as(
                board,
                target,
                board.pid(target),
            ),
            tool_ids=cls._tool_ids(target),
            opponent_hp=cls._current_opponent_hp(board),
            terminal_win=False,
            opponent_active_ko=False,
        )

    @classmethod
    def _project_active_evolution_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> CandidateProjectionFacts:
        target = board.option_target(result.option)
        evolution_id = board.option_card(result.option)
        if target is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_evolution_target",
            )
        if target is not getattr(board, "active", None):
            return cls._unsupported_facts(
                board,
                result,
                "evolution_target_not_active",
            )
        if (
            evolution_id is None
            or not board.evolves_from(evolution_id, target)
        ):
            return cls._unsupported_facts(
                board,
                result,
                "invalid_active_evolution",
            )
        evolution_data = board.data(evolution_id)
        if evolution_data is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_evolution_card_data",
            )
        if (
            tuple(getattr(evolution_data, "skills", ()) or ())
            and not has_impervious_shell(evolution_data)
        ):
            return cls._unsupported_facts(
                board,
                result,
                "evolution_skill_effect_unmodeled",
            )

        tool_bonus = 0
        for tool_id in cls._tool_ids(target):
            tool_data = board.data(tool_id)
            kinds = classify_public_effect(tool_data)
            hp_bonus = public_hp_bonus(tool_data)
            if kinds == (PublicEffectKind.HP_AFFECTING,) and hp_bonus is not None:
                tool_bonus += hp_bonus
                continue
            if kinds == (PublicEffectKind.NO_RELEVANT_EFFECT,):
                continue
            return cls._unsupported_facts(
                board,
                result,
                "evolution_tool_effect_unmodeled",
            )

        evolved_max_hp = (
            safe_int(getattr(evolution_data, "hp", None), default=-1)
            + tool_bonus
        )
        if evolved_max_hp <= 0:
            return cls._unsupported_facts(
                board,
                result,
                "missing_evolution_hp",
            )
        damage_counters = damage_on(target)
        return cls._supported_facts(
            board,
            result,
            active=target,
            active_card_id=int(evolution_id),
            active_hp=max(0, evolved_max_hp - damage_counters),
            active_max_hp=evolved_max_hp,
            energy_tokens=cls._exact_energy_tokens_as(
                board,
                target,
                int(evolution_id),
            ),
            tool_ids=cls._tool_ids(target),
            opponent_hp=cls._current_opponent_hp(board),
            terminal_win=False,
            opponent_active_ko=False,
        )

    @classmethod
    def _project_attach_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> CandidateProjectionFacts:
        active = getattr(board, "active", None)
        target = board.option_target(result.option)
        attached_card_id = board.option_card(result.option)
        if active is None or target is None or attached_card_id is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_attach_state",
            )
        if target is not active:
            return cls._unsupported_facts(
                board,
                result,
                "attach_target_not_active",
            )
        if not result.outcome.supported:
            return cls._unsupported_facts(
                board,
                result,
                "attach_immediate_outcome_unsupported",
            )
        attached_data = board.data(attached_card_id)
        attached_type = getattr(attached_data, "cardType", None)
        current_tokens = cls._exact_energy_tokens_as(
            board,
            active,
            board.pid(active),
        )
        if attached_type == CardType.BASIC_ENERGY:
            extra_tokens = energy_tokens_for_attach(
                int(attached_card_id),
                active,
            )
            if current_tokens is None or extra_tokens is None:
                return cls._unsupported_facts(
                    board,
                    result,
                    "unsupported_attach_energy",
                )
            return cls._supported_facts(
                board,
                result,
                active=active,
                active_card_id=board.pid(active),
                active_hp=hp_left(active),
                active_max_hp=max_hp(active),
                energy_tokens=current_tokens + tuple(extra_tokens),
                tool_ids=cls._tool_ids(active),
                opponent_hp=cls._current_opponent_hp(board),
                terminal_win=False,
                opponent_active_ko=False,
            )
        if attached_type == CardType.TOOL:
            hp_bonus = public_hp_bonus(attached_data)
            if (
                hp_bonus is None
                or hp_bonus <= 0
                or classify_public_effect(attached_data)
                != (PublicEffectKind.HP_AFFECTING,)
            ):
                return cls._unsupported_facts(
                    board,
                    result,
                    "unsupported_tool_attach_effect",
                )
            return cls._supported_facts(
                board,
                result,
                active=active,
                active_card_id=board.pid(active),
                active_hp=hp_left(active) + hp_bonus,
                active_max_hp=max_hp(active) + hp_bonus,
                energy_tokens=current_tokens,
                tool_ids=cls._tool_ids(active) + (int(attached_card_id),),
                opponent_hp=cls._current_opponent_hp(board),
                terminal_win=False,
                opponent_active_ko=False,
            )
        return cls._unsupported_facts(
            board,
            result,
            "unsupported_attach_card_type",
        )

    @classmethod
    def _project_unchanged_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
    ) -> CandidateProjectionFacts:
        active = getattr(board, "active", None)
        projection = cls.project(board, result)
        if active is None:
            return cls._unsupported_facts(
                board,
                result,
                "missing_current_active",
            )
        if projection.confidence != CandidateProjectionConfidence.EXACT:
            return cls._unsupported_facts(
                board,
                result,
                projection.unsupported_reason or "unchanged_projection_not_exact",
            )
        return cls._supported_facts(
            board,
            result,
            active=active,
            active_card_id=board.pid(active),
            active_hp=hp_left(active),
            active_max_hp=max_hp(active),
            energy_tokens=cls._exact_energy_tokens_as(
                board,
                active,
                board.pid(active),
            ),
            tool_ids=cls._tool_ids(active),
            opponent_hp=cls._current_opponent_hp(board),
            terminal_win=False,
            opponent_active_ko=False,
        )

    @classmethod
    def _supported_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        *,
        active: Pokemon,
        active_card_id: int,
        active_hp: int,
        active_max_hp: int,
        energy_tokens: Optional[Tuple[Any, ...]],
        tool_ids: Tuple[int, ...],
        opponent_hp: Optional[int],
        terminal_win: bool,
        opponent_active_ko: bool,
    ) -> CandidateProjectionFacts:
        current = getattr(board, "active", None)
        return CandidateProjectionFacts(
            supported=True,
            option_type=getattr(result.option, "type", None),
            card_id=board.option_card(result.option),
            attack_id=getattr(result.option, "attackId", None),
            projected_active_card_id=int(active_card_id),
            projected_active_serial=getattr(active, "serial", None),
            projected_active_hp=max(0, int(active_hp)),
            projected_active_max_hp=max(0, int(active_max_hp)),
            projected_active_energy_tokens=energy_tokens,
            projected_active_tool_ids=tool_ids,
            projected_active_changed=bool(
                current is None
                or getattr(current, "serial", None)
                != getattr(active, "serial", None)
                or board.pid(current) != int(active_card_id)
            ),
            projected_opponent_active_hp=opponent_hp,
            terminal_win=terminal_win,
            opponent_active_ko=opponent_active_ko,
            unsupported_reason=None,
        )

    @classmethod
    def _unsupported_facts(
        cls,
        board: BoardView,
        result: SimulationResult,
        reason: str,
    ) -> CandidateProjectionFacts:
        return CandidateProjectionFacts(
            supported=False,
            option_type=getattr(result.option, "type", None),
            card_id=board.option_card(result.option),
            attack_id=getattr(result.option, "attackId", None),
            projected_active_card_id=None,
            projected_active_serial=None,
            projected_active_hp=None,
            projected_active_max_hp=None,
            projected_active_energy_tokens=None,
            projected_active_tool_ids=(),
            projected_active_changed=False,
            projected_opponent_active_hp=None,
            terminal_win=False,
            opponent_active_ko=False,
            unsupported_reason=reason,
        )

    @staticmethod
    def _tool_ids(pokemon: Pokemon) -> Tuple[int, ...]:
        return tuple(
            int(public_card.id)
            for public_card in tuple(
                getattr(pokemon, "tools", None) or ()
            )
        )

    @staticmethod
    def _current_opponent_hp(board: BoardView) -> Optional[int]:
        opponent = getattr(board, "opp_active", None)
        return None if opponent is None else hp_left(opponent)

    @staticmethod
    def _exact_energy_tokens_as(
        board: BoardView,
        pokemon: Pokemon,
        pokemon_card_id: int,
    ) -> Optional[Tuple[Any, ...]]:
        pokemon_data = board.data(pokemon_card_id)
        tokens: List[Any] = []
        for energy_id in tuple(board.energies(pokemon)):
            energy_tokens = attached_energy_tokens_for_card(
                board.data(energy_id),
                pokemon_data,
            )
            if energy_tokens is None:
                return None
            tokens.extend(energy_tokens)
        return tuple(tokens)

    @classmethod
    def _project_attack(cls, board: BoardView, result: SimulationResult) -> CandidateProjection:
        active = getattr(board, "active", None)
        outcome = result.outcome
        if active is None:
            return cls._unsupported(result, "missing_current_active")
        attack = board.attack(getattr(result.option, "attackId", None))
        if attack is None:
            return cls._unsupported(result, "missing_attack_definition")

        limitations = list(cls._attack_projection_limitations(attack))
        target = getattr(board, "opp_active", None)
        if target is not None:
            limitations.extend(
                cls._public_damage_projection_limitations(
                    board,
                    active,
                    target,
                    attack,
                )
            )
        if not outcome.supported:
            limitations.insert(0, "attack_immediate_outcome_unsupported")
        if cls._has_unmodeled_between_turn_damage(board):
            limitations.append("between_turn_effect_unmodeled")
        limitations = list(cls._unique(limitations))
        confidence = (
            CandidateProjectionConfidence.UNSUPPORTED
            if not outcome.supported
            else CandidateProjectionConfidence.PARTIAL
            if limitations
            else CandidateProjectionConfidence.EXACT
        )
        combat_result_exact = bool(
            outcome.supported
            and not cls._combat_result_limitations(limitations)
        )
        readiness_unknown = any(
            reason in limitations
            for reason in {
                "self_damage_attack_unmodeled",
                "attack_switch_effect_unmodeled",
                "attack_active_leaves_play_unmodeled",
                "energy_discard_projection_unmodeled",
            }
        )
        next_ready = cls._pokemon_energy_ready(board, active) and not readiness_unknown
        reasons = cls._unique(
            ("attack_projection",)
            + tuple(outcome.reasons)
            + tuple(limitations)
        )
        return CandidateProjection(
            option_index=result.index,
            option_type=result.option.type,
            confidence=confidence,
            combat_result_exact=combat_result_exact,
            terminal_win=bool(outcome.wins_game),
            damage_to_opponent=max(0, safe_int(outcome.damage)),
            opponent_active_ko=bool(outcome.knockout),
            prizes_taken=max(0, safe_int(outcome.prizes_taken)),
            projected_active_serial=getattr(active, "serial", None),
            projected_active_card_id=board.pid(active),
            projected_active_hp=hp_left(active),
            projected_active_prize_value=board.prize_value(active),
            projected_active_can_attack=False,
            next_attacker_ready=next_ready,
            ends_turn=True,
            unsupported_reason=limitations[0] if limitations else None,
            reasons=reasons,
        )

    @classmethod
    def _project_retreat(cls, board: BoardView, result: SimulationResult) -> CandidateProjection:
        if getattr(board, "active", None) is None:
            return cls._unsupported(result, "missing_current_active")
        outcome = result.outcome
        target_serial = (
            outcome.target_serial
            if outcome.target_serial is not None
            else outcome.recommended_target_serial
        )
        target_id = (
            outcome.target_id
            if outcome.target_id is not None
            else outcome.recommended_target_id
        )
        if target_serial is None:
            return cls._unsupported(result, "missing_retreat_target")
        matches = [
            target
            for target in getattr(board, "bench", ())
            if getattr(target, "serial", None) == target_serial
        ]
        if len(matches) != 1:
            reason = "ambiguous_retreat_target" if len(matches) > 1 else "missing_retreat_target"
            return cls._unsupported(result, reason)
        target = matches[0]
        if target_id is not None and board.pid(target) != target_id:
            return cls._unsupported(result, "retreat_target_mismatch")
        if not outcome.supported:
            return cls._unsupported(result, "retreat_immediate_outcome_unsupported")

        retreat_limitation = OpponentPublicThreatEvaluator(
            board
        )._public_retreat_effect_unsupported_reason(board.active, target)
        ready = (
            retreat_limitation is None
            and cls._pokemon_energy_ready(board, target)
            and active_can_declare_attack_this_turn_for_board(board)
        )
        reasons = cls._unique(
            ("retreat_projection",)
            + tuple(outcome.reasons)
            + ((retreat_limitation,) if retreat_limitation is not None else ())
        )
        return CandidateProjection(
            option_index=result.index,
            option_type=result.option.type,
            confidence=(
                CandidateProjectionConfidence.PARTIAL
                if retreat_limitation is not None
                else CandidateProjectionConfidence.EXACT
            ),
            combat_result_exact=retreat_limitation is None,
            terminal_win=False,
            damage_to_opponent=0,
            opponent_active_ko=False,
            prizes_taken=0,
            projected_active_serial=getattr(target, "serial", None),
            projected_active_card_id=board.pid(target),
            projected_active_hp=hp_left(target),
            projected_active_prize_value=board.prize_value(target),
            projected_active_can_attack=ready,
            next_attacker_ready=ready,
            ends_turn=False,
            unsupported_reason=retreat_limitation,
            reasons=reasons,
        )

    @classmethod
    def _project_end(cls, board: BoardView, result: SimulationResult) -> CandidateProjection:
        active = getattr(board, "active", None)
        if active is None:
            return cls._unsupported(result, "missing_current_active")
        limitations = cls._end_projection_limitations(board)
        return CandidateProjection(
            option_index=result.index,
            option_type=result.option.type,
            confidence=(
                CandidateProjectionConfidence.PARTIAL
                if limitations
                else CandidateProjectionConfidence.EXACT
            ),
            combat_result_exact=True,
            terminal_win=False,
            damage_to_opponent=0,
            opponent_active_ko=False,
            prizes_taken=0,
            projected_active_serial=getattr(active, "serial", None),
            projected_active_card_id=board.pid(active),
            projected_active_hp=hp_left(active),
            projected_active_prize_value=board.prize_value(active),
            projected_active_can_attack=False,
            next_attacker_ready=(
                cls._pokemon_energy_ready(board, active)
                and not limitations
            ),
            ends_turn=True,
            unsupported_reason=limitations[0] if limitations else None,
            reasons=("end_current_public_board",) + limitations,
        )

    @classmethod
    def _unsupported(cls, result: SimulationResult, reason: str) -> CandidateProjection:
        return CandidateProjection(
            option_index=result.index,
            option_type=getattr(result.option, "type", None),
            confidence=CandidateProjectionConfidence.UNSUPPORTED,
            combat_result_exact=False,
            terminal_win=False,
            damage_to_opponent=0,
            opponent_active_ko=False,
            prizes_taken=0,
            projected_active_serial=None,
            projected_active_card_id=None,
            projected_active_hp=None,
            projected_active_prize_value=None,
            projected_active_can_attack=False,
            next_attacker_ready=False,
            ends_turn=False,
            unsupported_reason=reason,
            reasons=(reason,),
        )

    @staticmethod
    def _pokemon_energy_ready(board: BoardView, pokemon: Pokemon) -> bool:
        data = board.data(board.pid(pokemon))
        if data is None:
            return False
        return any(
            attack is not None and board.can_pay_attack(pokemon, attack)
            for attack in (board.attack(attack_id) for attack_id in getattr(data, "attacks", ()))
        )

    @classmethod
    def _attack_projection_limitations(cls, attack: Any) -> Tuple[str, ...]:
        text = _normalized_attack_text(attack)
        reasons: List[str] = []
        if attack_ignores_defending_pokemon_damage_effects(attack) is None:
            reasons.append(UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON)
        if attack_can_damage_opponent_bench(attack):
            reasons.append("multi_ko_unmodeled")
        if "damage counter" in text:
            reasons.append("damage_counter_effect_unmodeled")
        if (
            "damage to itself" in text
            or "damage to this pokemon" in text
            or ("put" in text and "damage counter" in text and "this pokemon" in text)
        ):
            reasons.append("self_damage_attack_unmodeled")
        if "heal" in text and "this pokemon" in text:
            reasons.append("self_heal_attack_unmodeled")
        if "switch this pokemon with" in text or "switch out this pokemon" in text:
            reasons.append("attack_switch_effect_unmodeled")
        if (
            "return this pokemon" in text
            or "shuffle this pokemon" in text
            or "put this pokemon and all attached cards" in text
        ):
            reasons.append("attack_active_leaves_play_unmodeled")
        if (
            ("discard" in text or "move" in text)
            and "energy" in text
            and ("this pokemon" in text or "attached to this pokemon" in text)
        ):
            reasons.append("energy_discard_projection_unmodeled")
        if (
            ("attach" in text or "move" in text)
            and "energy" in text
            and ("your benched pokemon" in text or "to your pokemon" in text)
        ):
            reasons.append("attack_board_effect_unmodeled")
        if "tool" in text or "stadium" in text:
            reasons.append("tool_stadium_effect_unmodeled")
        if any(
            marker in text
            for marker in (
                "is now asleep",
                "is now burned",
                "is now confused",
                "is now paralyzed",
                "is now poisoned",
            )
        ):
            reasons.append("opponent_status_effect_unmodeled")
        if "during your opponent's next turn" in text:
            reasons.append("delayed_attack_effect_unmodeled")
        return cls._unique(reasons)

    @staticmethod
    def _combat_result_limitations(limitations: Sequence[str]) -> Tuple[str, ...]:
        combat_reasons = {
            "attack_immediate_outcome_unsupported",
            UNKNOWN_DAMAGE_EFFECT_IGNORE_REASON,
            "multi_ko_unmodeled",
            "damage_counter_effect_unmodeled",
            "tool_stadium_effect_unmodeled",
            "weakness_resistance_damage_unmodeled",
            "public_damage_effect_unclassified",
            "public_stadium_damage_modifier_unmodeled",
            "public_stadium_damage_effect_unknown",
            "public_stadium_weakness_resistance_unmodeled",
            "public_tool_damage_modifier_unmodeled",
            "public_tool_damage_effect_unknown",
            "public_tool_weakness_resistance_unmodeled",
            "public_after_damage_effect_unmodeled",
        }
        return tuple(reason for reason in limitations if reason in combat_reasons)

    @classmethod
    def _public_damage_projection_limitations(
        cls,
        board: BoardView,
        attacker: Pokemon,
        target: Pokemon,
        attack: Any,
    ) -> Tuple[str, ...]:
        reasons: List[str] = []
        public_effect_reason = OpponentPublicThreatEvaluator(
            board
        )._public_damage_effect_unsupported_reason(attacker, target)
        if public_effect_reason is not None:
            if public_effect_reason in {
                "public_stadium_damage_effect_unknown",
                "public_tool_damage_effect_unknown",
            }:
                reasons.append("public_damage_effect_unclassified")
            reasons.append(public_effect_reason)

        for public_card in (
            tuple(getattr(getattr(board, "state", None), "stadium", None) or ())
            + tuple(getattr(attacker, "tools", None) or ())
            + tuple(getattr(target, "tools", None) or ())
        ):
            if PublicEffectKind.AFTER_DAMAGE_TRIGGERED_EFFECT in classify_public_effect(
                board.data(card_id(public_card))
            ):
                reasons.append("public_after_damage_effect_unmodeled")

        text = _normalized_attack_text(attack)
        ignores_weakness_resistance = (
            "isn't affected by weakness or resistance" in text
            or "is not affected by weakness or resistance" in text
        )
        if not ignores_weakness_resistance:
            modifier_match = public_attack_matches_weakness_or_resistance(
                board,
                attacker,
                target,
                attack,
            )
            if modifier_match is not False:
                reasons.append("weakness_resistance_damage_unmodeled")
        return cls._unique(reasons)

    @classmethod
    def _end_projection_limitations(cls, board: BoardView) -> Tuple[str, ...]:
        player = getattr(board, "me", None)
        reasons: List[str] = []
        if getattr(player, "asleep", False):
            reasons.append("asleep_next_attack_uncertain")
        if getattr(player, "confused", False):
            reasons.append("confused_attack_outcome_uncertain")
        if getattr(player, "paralyzed", False):
            reasons.append("paralyzed_next_attack_uncertain")
        if cls._has_unmodeled_between_turn_damage(board):
            reasons.append("between_turn_effect_unmodeled")
        return cls._unique(reasons)

    @staticmethod
    def _has_unmodeled_between_turn_damage(board: BoardView) -> bool:
        player = getattr(board, "me", None)
        return bool(
            getattr(player, "burned", False)
            or getattr(player, "poisoned", False)
        )

    @staticmethod
    def _unique(reasons: Iterable[str]) -> Tuple[str, ...]:
        return tuple(dict.fromkeys(reasons))


def phase3_prepared_attack_binding_facts(
    adapter: str,
    origin_board: BoardView,
    origin_result: Optional[SimulationResult],
    decision_board: BoardView,
    decision: P6AttackDecisionInputFacts,
) -> Phase3PreparedAttackBindingFacts:
    if not adapter:
        raise ValueError("phase3_adapter_required")
    if not _result_option_is_current(origin_board, origin_result):
        return Phase3PreparedAttackBindingFacts(
            adapter=adapter,
            origin_option_index=None,
            supported=False,
            candidate=None,
            unsupported_reason="phase3_origin_option_not_current",
        )

    origin_option_index = origin_result.index
    decision_option_index = decision.decision_option_index
    if (
        decision_option_index is not None
        and decision_option_index != origin_option_index
    ):
        return Phase3PreparedAttackBindingFacts(
            adapter=adapter,
            origin_option_index=origin_option_index,
            supported=False,
            candidate=None,
            unsupported_reason="phase3_origin_option_index_mismatch",
        )
    outcome = CandidateProjectionEvaluator.attack_decision_outcome_facts(
        decision_board,
        decision,
    )
    return Phase3PreparedAttackBindingFacts(
        adapter=adapter,
        origin_option_index=origin_option_index,
        supported=outcome.supported,
        candidate=DirectAttackShadowCandidate(
            option_index=origin_option_index,
            attack_id=decision.attack_id,
            facts=outcome,
        ),
        unsupported_reason=(
            None
            if outcome.supported
            else (
                outcome.unsupported_reason
                or decision.unsupported_reason
                or "phase3_prepared_adapter_unsupported"
            )
        ),
    )


def phase3_direct_attack_shadow_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    prepared_bindings: Sequence[Phase3PreparedAttackBindingFacts],
) -> Phase3DirectAttackShadowFacts:
    current = current_direct_attack_candidate_facts(board, results)
    blocked_reasons = list(current.blocked_reasons)
    bindings_list: List[Phase3PreparedAttackBindingFacts] = []
    prepared_duplicate_deduplications = 0
    for binding in prepared_bindings:
        if binding in bindings_list:
            prepared_duplicate_deduplications += 1
            continue
        bindings_list.append(binding)
        if binding.candidate is None:
            blocked_reasons.append(
                f"{binding.adapter}:{binding.unsupported_reason}"
            )
    bindings = tuple(bindings_list)
    candidate_bindings = tuple(
        binding for binding in bindings if binding.candidate is not None
    )
    bindings_by_origin: Dict[int, List[Phase3PreparedAttackBindingFacts]] = {}
    for binding in candidate_bindings:
        bindings_by_origin.setdefault(binding.origin_option_index, []).append(
            binding
        )
    origin_conflicts = tuple(sorted(
        origin_option_index
        for origin_option_index, origin_bindings
        in bindings_by_origin.items()
        if len({binding.adapter for binding in origin_bindings}) > 1
    ))
    multiple_prepared_attack_origins = tuple(sorted(
        origin_option_index
        for origin_option_index, origin_bindings
        in bindings_by_origin.items()
        if len({
            (binding.candidate.attack_id, binding.candidate.facts)
            for binding in origin_bindings
        }) > 1
    ))
    prepared_candidates = tuple(
        binding.candidate for binding in candidate_bindings
    )
    comparisons = tuple(
        Phase3CurrentPreparedComparisonFacts(
            current_candidate=current_candidate,
            prepared_binding=prepared_binding,
            result=compare_direct_attack_candidates(
                current_candidate,
                prepared_binding.candidate,
            ),
        )
        for current_candidate in current.candidates
        for prepared_binding in candidate_bindings
    )
    return Phase3DirectAttackShadowFacts(
        current_candidates=current.candidates,
        prepared_bindings=bindings,
        prepared_candidates=prepared_candidates,
        prepared_duplicate_deduplications=prepared_duplicate_deduplications,
        multiple_prepared_attack_origins=multiple_prepared_attack_origins,
        origin_conflicts=origin_conflicts,
        blocked_reasons=tuple(blocked_reasons),
        comparisons=comparisons,
    )


def current_direct_attack_candidate_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
) -> CurrentDirectAttackCandidateFacts:
    candidates: List[DirectAttackShadowCandidate] = []
    blocked_reasons: List[str] = []
    for result in results:
        option = getattr(result, "option", None)
        if (
            getattr(option, "type", None) != OptionType.ATTACK
            or getattr(option, "attackId", None) is None
        ):
            continue
        if not _result_option_is_current(board, result):
            blocked_reasons.append("current_attack_option_not_current")
            continue
        projection = CandidateProjectionEvaluator.project_facts(board, result)
        decision = CandidateProjectionEvaluator.direct_attack_p6_input_facts(
            board,
            result,
            projection,
        )
        if decision.decision_option_index != result.index:
            blocked_reasons.append("current_attack_option_index_mismatch")
            continue
        outcome = CandidateProjectionEvaluator.attack_decision_outcome_facts(
            board,
            decision,
        )
        candidates.append(DirectAttackShadowCandidate(
            option_index=result.index,
            attack_id=decision.attack_id,
            facts=outcome,
        ))
    return CurrentDirectAttackCandidateFacts(
        candidates=tuple(candidates),
        blocked_reasons=tuple(blocked_reasons),
    )
def phase5_same_observation_prepared_bindings(
    board: BoardView,
    results: Sequence[SimulationResult],
) -> Tuple[Phase3PreparedAttackBindingFacts, ...]:
    """Collect only same-observation prepared bindings from existing adapters."""
    results_tuple = tuple(results)
    current_attack_results = tuple(
        result
        for result in results_tuple
        if (
            getattr(getattr(result, "option", None), "type", None)
            == OptionType.ATTACK
            and getattr(getattr(result, "option", None), "attackId", None)
            is not None
        )
    )
    bindings: List[Phase3PreparedAttackBindingFacts] = []
    for result in results_tuple:
        option = getattr(result, "option", None)
        option_type = getattr(option, "type", None)
        if option_type == OptionType.ATTACH:
            attached_card_id = board.option_card(option)
            attached_card_data = (
                board.data(attached_card_id)
                if attached_card_id is not None
                else None
            )
            attached_card_type = getattr(attached_card_data, "cardType", None)
            if attached_card_type == CardType.BASIC_ENERGY:
                decision = (
                    CandidateProjectionEvaluator
                    .active_basic_energy_attach_p6_input_facts(
                        board,
                        result,
                    )
                )
                bindings.append(phase3_prepared_attack_binding_facts(
                    "active_basic_energy_attach",
                    board,
                    result,
                    board,
                    decision,
                ))
            elif attached_card_type == CardType.TOOL:
                for attack_result in current_attack_results:
                    decision = (
                        CandidateProjectionEvaluator
                        .static_hp_tool_attach_p6_input_facts(
                            board,
                            result,
                            attack_result,
                        )
                    )
                    bindings.append(phase3_prepared_attack_binding_facts(
                        "static_hp_tool_attach",
                        board,
                        result,
                        board,
                        decision,
                    ))
        elif option_type == OptionType.EVOLVE:
            attack_facts = tuple(
                board.active_evolution_attack_facts(option)
            )
            if not attack_facts:
                attack_facts = (None,)
            for attack_fact in attack_facts:
                decision = (
                    CandidateProjectionEvaluator
                    .active_evolution_attack_p6_input_facts(
                        board,
                        result,
                        attack_fact,
                    )
                )
                bindings.append(phase3_prepared_attack_binding_facts(
                    "active_evolution_attack",
                    board,
                    result,
                    board,
                    decision,
                ))
    return tuple(bindings)



def same_observation_prepared_attack_bindings(
    board: BoardView,
    results: Sequence[SimulationResult],
) -> Tuple[Phase3PreparedAttackBindingFacts, ...]:
    """Reuse the existing safe adapter collector without ranking."""
    return phase5_same_observation_prepared_bindings(board, results)


_ACTION_LINE_PREPARATION_TYPES = frozenset({
    OptionType.ATTACH,
    OptionType.EVOLVE,
    OptionType.PLAY,
    OptionType.ABILITY,
    OptionType.RETREAT,
})


def _action_line_origin_metadata(
    board: BoardView,
    result: SimulationResult,
) -> Tuple[Any, Optional[int], Optional[int], Optional[int]]:
    option = getattr(result, "option", None)
    option_type = getattr(option, "type", None)
    try:
        option_card_id = board.option_card(option)
    except (AttributeError, TypeError, ValueError, IndexError):
        option_card_id = getattr(option, "cardId", None)
        if type(option_card_id) is not int:
            option_card_id = getattr(option, "card_id", None)
    target = None
    try:
        target = board.option_target(option)
    except (AttributeError, TypeError, ValueError, IndexError):
        target = getattr(option, "target", None)
    target_card_id: Optional[int] = None
    if target is not None:
        try:
            target_card_id = board.pid(target)
        except (AttributeError, TypeError, ValueError, IndexError):
            raw_target_id = getattr(target, "id", None)
            if type(raw_target_id) is int:
                target_card_id = raw_target_id
    target_serial = getattr(target, "serial", None)
    return option_type, option_card_id, target_card_id, target_serial


def _action_line_same_origin_selection(
    candidates: Sequence[DirectAttackShadowCandidate],
) -> Tuple[
    ActionLineBestAttackState,
    Optional[DirectAttackShadowCandidate],
    Tuple[DirectAttackShadowCandidate, ...],
    Tuple[ActionLineAttackComparisonFacts, ...],
    int,
    str,
]:
    exact_groups: Dict[
        Tuple[Any, ...],
        List[DirectAttackShadowCandidate],
    ] = {}
    for candidate in candidates:
        exact_groups.setdefault(
            (candidate.attack_id, candidate.facts),
            [],
        ).append(candidate)
    representatives = tuple(group[0] for group in exact_groups.values())
    duplicate_count = len(tuple(candidates)) - len(representatives)
    if not representatives:
        return (
            ActionLineBestAttackState.UNSUPPORTED,
            None,
            (),
            (),
            duplicate_count,
            "action_line_no_reachable_attack",
        )
    if len(representatives) == 1:
        candidate = representatives[0]
        if (
            classify_direct_attack_candidate(candidate.facts)
            == DirectAttackCandidateState.OVERALL_UNSUPPORTED
        ):
            return (
                ActionLineBestAttackState.UNSUPPORTED,
                None,
                representatives,
                (),
                duplicate_count,
                candidate.facts.unsupported_reason
                or "action_line_attack_outcome_unsupported",
            )
        return (
            ActionLineBestAttackState.SELECTED,
            candidate,
            representatives,
            (),
            duplicate_count,
            "single_same_origin_attack",
        )

    reindexed = tuple(
        replace(candidate, option_index=index)
        for index, candidate in enumerate(representatives)
    )
    raw_comparisons = tuple(
        compare_direct_attack_candidates(left, right)
        for left, right in combinations(reindexed, 2)
    )
    comparisons = tuple(
        ActionLineAttackComparisonFacts(
            left_candidate_ordinal=comparison.left_option_index,
            right_candidate_ordinal=comparison.right_option_index,
            left_attack_id=representatives[
                comparison.left_option_index
            ].attack_id,
            right_attack_id=representatives[
                comparison.right_option_index
            ].attack_id,
            relation=comparison.relation,
            reason=comparison.reason,
            left_state=comparison.left_state,
            right_state=comparison.right_state,
        )
        for comparison in raw_comparisons
    )
    winner = unique_direct_attack_shadow_winner(
        reindexed,
        raw_comparisons,
    )
    if winner is not None:
        selected = representatives[winner.option_index]
        return (
            ActionLineBestAttackState.SELECTED,
            selected,
            representatives,
            comparisons,
            duplicate_count,
            "unique_same_origin_best_attack",
        )
    if raw_comparisons and all(
        comparison.relation == DirectAttackComparison.EQUIVALENT
        for comparison in raw_comparisons
    ):
        return (
            ActionLineBestAttackState.TIE,
            None,
            representatives,
            comparisons,
            duplicate_count,
            "same_origin_attack_tie",
        )
    return (
        ActionLineBestAttackState.INCOMPARABLE,
        None,
        representatives,
        comparisons,
        duplicate_count,
        "same_origin_attack_incomparable",
    )


def action_line_outcome_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    prepared_bindings: Optional[
        Sequence[Phase3PreparedAttackBindingFacts]
    ] = None,
) -> Tuple[ActionLineOutcomeFacts, ...]:
    """Build facts only; never compare or rank different Action origins."""
    results_tuple = tuple(results)
    bindings = tuple(
        same_observation_prepared_attack_bindings(board, results_tuple)
        if prepared_bindings is None
        else prepared_bindings
    )
    bindings_by_origin: Dict[
        int,
        List[Phase3PreparedAttackBindingFacts],
    ] = {}
    for binding in bindings:
        if type(binding.origin_option_index) is int:
            bindings_by_origin.setdefault(
                binding.origin_option_index,
                [],
            ).append(binding)

    lines: List[ActionLineOutcomeFacts] = []
    for result in results_tuple:
        option_type = getattr(getattr(result, "option", None), "type", None)
        if option_type not in _ACTION_LINE_PREPARATION_TYPES:
            continue
        origin_bindings = tuple(bindings_by_origin.get(result.index, ()))
        (
            origin_option_type,
            origin_option_card_id,
            origin_target_card_id,
            origin_target_serial,
        ) = _action_line_origin_metadata(board, result)
        if not origin_bindings:
            lines.append(ActionLineOutcomeFacts(
                origin_option_index=result.index,
                origin_option_type=origin_option_type,
                origin_option_card_id=origin_option_card_id,
                origin_target_card_id=origin_target_card_id,
                origin_target_serial=origin_target_serial,
                adapter_names=(),
                prepared_bindings=(),
                attack_candidates=(),
                comparisons=(),
                best_attack=None,
                best_attack_id=None,
                outcome_facts=None,
                phase3_state=None,
                virtual_state_exact=False,
                supported=False,
                selection_state=ActionLineBestAttackState.UNSUPPORTED,
                unsupported_reason="action_line_safe_adapter_unavailable",
                reasons=("action_line_safe_adapter_unavailable",),
            ))
            continue

        adapter_names = tuple(dict.fromkeys(
            binding.adapter for binding in origin_bindings
        ))
        if len(adapter_names) != 1:
            lines.append(ActionLineOutcomeFacts(
                origin_option_index=result.index,
                origin_option_type=origin_option_type,
                origin_option_card_id=origin_option_card_id,
                origin_target_card_id=origin_target_card_id,
                origin_target_serial=origin_target_serial,
                adapter_names=adapter_names,
                prepared_bindings=origin_bindings,
                attack_candidates=tuple(
                    binding.candidate
                    for binding in origin_bindings
                    if binding.candidate is not None
                ),
                comparisons=(),
                best_attack=None,
                best_attack_id=None,
                outcome_facts=None,
                phase3_state=None,
                virtual_state_exact=False,
                supported=False,
                selection_state=ActionLineBestAttackState.UNSUPPORTED,
                unsupported_reason="action_line_origin_adapter_conflict",
                reasons=("action_line_origin_adapter_conflict",),
            ))
            continue

        raw_candidates = tuple(
            binding.candidate
            for binding in origin_bindings
            if binding.candidate is not None
        )
        (
            selection_state,
            best_attack,
            candidates,
            comparisons,
            duplicate_count,
            selection_reason,
        ) = _action_line_same_origin_selection(raw_candidates)
        supported = selection_state != ActionLineBestAttackState.UNSUPPORTED
        phase3_state = (
            classify_direct_attack_candidate(best_attack.facts)
            if best_attack is not None
            else None
        )
        lines.append(ActionLineOutcomeFacts(
            origin_option_index=result.index,
            origin_option_type=origin_option_type,
            origin_option_card_id=origin_option_card_id,
            origin_target_card_id=origin_target_card_id,
            origin_target_serial=origin_target_serial,
            adapter_names=adapter_names,
            prepared_bindings=origin_bindings,
            attack_candidates=candidates,
            comparisons=comparisons,
            best_attack=best_attack,
            best_attack_id=(
                best_attack.attack_id if best_attack is not None else None
            ),
            outcome_facts=(
                best_attack.facts if best_attack is not None else None
            ),
            phase3_state=phase3_state,
            virtual_state_exact=bool(
                candidates
                and all(
                    binding.supported
                    for binding in origin_bindings
                    if binding.candidate in candidates
                )
            ),
            supported=supported,
            selection_state=selection_state,
            duplicate_candidate_count=duplicate_count,
            unsupported_reason=(None if supported else selection_reason),
            reasons=(selection_reason,),
        ))
    return tuple(lines)


def _current_action_line_origin() -> ActionLineOriginFacts:
    return ActionLineOriginFacts(
        kind=ActionLineOriginKind.CURRENT_BOARD,
        option_index=None,
    )


def _prepared_action_line_origin(
    line: ActionLineOutcomeFacts,
) -> ActionLineOriginFacts:
    return ActionLineOriginFacts(
        kind=ActionLineOriginKind.PREPARED_ACTION,
        option_index=line.origin_option_index,
        option_type=line.origin_option_type,
        option_card_id=line.origin_option_card_id,
        target_card_id=line.origin_target_card_id,
        target_serial=line.origin_target_serial,
        adapter_names=line.adapter_names,
    )


def current_action_line_outcome_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    current_facts: Optional[CurrentDirectAttackCandidateFacts] = None,
) -> CurrentActionLineOutcomeFacts:
    """Build the current-board ATTACK Line without ranking options."""
    current = (
        current_direct_attack_candidate_facts(board, results)
        if current_facts is None
        else current_facts
    )
    (
        selection_state,
        best_attack,
        candidates,
        comparisons,
        duplicate_count,
        selection_reason,
    ) = _action_line_same_origin_selection(current.candidates)
    supported = selection_state != ActionLineBestAttackState.UNSUPPORTED
    return CurrentActionLineOutcomeFacts(
        origin=_current_action_line_origin(),
        attack_candidates=candidates,
        comparisons=comparisons,
        best_attack=best_attack,
        best_attack_id=(
            best_attack.attack_id if best_attack is not None else None
        ),
        outcome_facts=(
            best_attack.facts if best_attack is not None else None
        ),
        phase3_state=(
            classify_direct_attack_candidate(best_attack.facts)
            if best_attack is not None
            else None
        ),
        state_exact=bool(candidates) and not current.blocked_reasons,
        supported=supported,
        selection_state=selection_state,
        duplicate_candidate_count=duplicate_count,
        unsupported_reason=(None if supported else selection_reason),
        blocked_reasons=current.blocked_reasons,
        reasons=(selection_reason,) + current.blocked_reasons,
    )



def _active_position_current_result_for_candidate(
    board: BoardView,
    results: Sequence[SimulationResult],
    candidate: DirectAttackShadowCandidate,
) -> Tuple[Optional[SimulationResult], Optional[str]]:
    matches = tuple(
        result
        for result in results
        if result.index == candidate.option_index
        and getattr(result.option, "type", None) == OptionType.ATTACK
        and getattr(result.option, "attackId", None) == candidate.attack_id
        and _result_option_is_current(board, result)
    )
    if len(matches) != 1:
        return None, "active_position_current_attack_identity_unresolved"
    return matches[0], None


def _active_position_attack_decision_input_facts(
    board: BoardView,
    result: SimulationResult,
    *,
    allow_counterline_recovery: bool = False,
) -> Tuple[
    P6AttackDecisionInputFacts,
    CandidateProjectionFacts,
    Optional[bool],
    Optional[str],
]:
    projection = CandidateProjectionEvaluator.project_facts(board, result)
    decision = CandidateProjectionEvaluator.direct_attack_p6_input_facts(
        board,
        result,
        projection,
    )
    if decision.supported:
        return decision, projection, projection.projected_active_changed, None
    if (
        not allow_counterline_recovery
        or decision.unsupported_reason != "public_damage_effect_unclassified"
        or projection.unsupported_reason != "public_damage_effect_unclassified"
    ):
        return decision, projection, None, decision.unsupported_reason

    active = getattr(board, "active", None)
    opponent = getattr(board, "opp_active", None)
    active_tools = tuple(getattr(active, "tools", ()) or ()) if active is not None else ()
    tool_ids = tuple(int(getattr(tool, "id", -1)) for tool in active_tools)
    tool_serials = tuple(getattr(tool, "serial", None) for tool in active_tools)
    active_energy = tuple(getattr(active, "energyCards", ()) or ()) if active is not None else ()
    energy_serials = tuple(getattr(card, "serial", None) for card in active_energy)
    if (
        active is None
        or opponent is None
        or type(getattr(active, "serial", None)) is not int
        or type(getattr(opponent, "serial", None)) is not int
        or DELUXE_BOMB not in tool_ids
        or any(type(serial) is not int for serial in tool_serials)
        or len(set(tool_serials)) != len(tool_serials)
        or any(type(serial) is not int for serial in energy_serials)
        or len(set(energy_serials)) != len(energy_serials)
        or not result.outcome.supported
        or projection.option_type != OptionType.ATTACK
        or projection.attack_id != getattr(result.option, "attackId", None)
    ):
        return decision, projection, None, decision.unsupported_reason

    projection = replace(
        projection,
        projected_active_card_id=board.pid(active),
        projected_active_serial=getattr(active, "serial", None),
        projected_active_hp=hp_left(active),
        projected_active_max_hp=max_hp(active),
        projected_active_energy_tokens=tuple(board.energy_tokens(active)),
        projected_active_tool_ids=tool_ids,
        projected_active_changed=False,
        projected_opponent_active_hp=max(
            0,
            hp_left(opponent) - max(0, safe_int(result.outcome.damage)),
        ),
        terminal_win=bool(result.outcome.wins_game),
        opponent_active_ko=bool(result.outcome.knockout),
    )
    our_active = projected_active_public_facts(
        board,
        active,
        status_owner=getattr(board, "me", None),
        projected_card_id=projection.projected_active_card_id,
        projected_serial=projection.projected_active_serial,
        projected_hp=projection.projected_active_hp,
        projected_max_hp=projection.projected_active_max_hp,
        projected_energy_tokens=projection.projected_active_energy_tokens,
        projected_tool_ids=projection.projected_active_tool_ids,
    )
    opponent_after = None
    if not projection.opponent_active_ko and not projection.terminal_win:
        opponent_after = projected_active_public_facts(
            board,
            opponent,
            status_owner=getattr(board, "opp", None),
            projected_hp=projection.projected_opponent_active_hp,
        )
    recovered = P6AttackDecisionInputFacts(
        supported=True,
        decision_option_index=result.index,
        attack_id=projection.attack_id,
        combat_result_exact=True,
        confirmed_damage=max(0, safe_int(result.outcome.damage)),
        opponent_active_ko=bool(result.outcome.knockout),
        immediate_prizes_taken=max(0, safe_int(result.outcome.prizes_taken)),
        candidate_wins_game=bool(result.outcome.wins_game),
        our_active=our_active,
        opponent_active_after_attack=opponent_after,
        projected_bench_unchanged=True,
        unsupported_reason=None,
    )
    return (
        recovered,
        projection,
        projection.projected_active_changed,
        "active_position_reply_reaction_projection_recovered",
    )






def _active_position_counterline_kind(
    attack_fact: Stage2b4CounterlineAttackFacts,
) -> Stage2b4CounterlineRouteKind:
    bruxish = attack_fact.bruxish_trigger_confirmed
    bomb = attack_fact.deluxe_bomb_trigger_confirmed
    if bruxish is False and bomb is False:
        return Stage2b4CounterlineRouteKind.NONE
    if bruxish is False and bomb is True:
        return Stage2b4CounterlineRouteKind.DELUXE_BOMB_ONLY
    if bruxish is True and bomb is False:
        return Stage2b4CounterlineRouteKind.BRUXISH_ONLY
    if (
        bruxish is True
        and bomb is True
        and attack_fact.combined_damage_counters == 15
        and attack_fact.combined_damage_amount == 150
    ):
        return Stage2b4CounterlineRouteKind.DELUXE_BOMB_AND_BRUXISH
    return Stage2b4CounterlineRouteKind.UNRESOLVED


def _active_position_counterline_incoming_damage(
    integrated: Stage2b4IntegratedCounterlineFacts,
    attack_fact: Stage2b4CounterlineAttackFacts,
) -> Optional[int]:
    values: List[int] = []
    key = (
        attack_fact.attack_id,
        attack_fact.opponent_active_id,
        attack_fact.opponent_active_serial,
    )
    for fact in integrated.bruxish_facts.attack_facts:
        if (fact.attack_id, fact.opponent_active_id, fact.opponent_active_serial) == key:
            if fact.confirmed_incoming_damage is not None:
                values.append(int(fact.confirmed_incoming_damage))
    for fact in integrated.deluxe_bomb_facts.attack_facts:
        if (fact.attack_id, fact.opponent_active_id, fact.opponent_active_serial) == key:
            if fact.confirmed_incoming_damage is not None:
                values.append(int(fact.confirmed_incoming_damage))
    if not values:
        return None
    return values[0] if len(set(values)) == 1 else None


def _active_position_drednaw_followup_error(
    board: BoardView,
    attack_fact: Stage2b4CounterlineAttackFacts,
) -> Optional[str]:
    if attack_fact.drednaw_followup_supported is not True:
        return None
    if (
        type(attack_fact.drednaw_serial) is not int
        or attack_fact.drednaw_hard_crunch_damage is None
    ):
        return "active_position_drednaw_followup_identity_unresolved"
    matches = tuple(
        pokemon
        for pokemon in tuple(getattr(board, "bench", ()) or ())
        if getattr(pokemon, "serial", None) == attack_fact.drednaw_serial
        and board.pid(pokemon) == DREDNAW
    )
    if len(matches) != 1:
        return "active_position_drednaw_followup_identity_unresolved"
    return None


def _active_position_current_attack_line_base(
    *,
    origin: ActionLineOriginFacts,
    candidate: DirectAttackShadowCandidate,
    decision: Optional[P6AttackDecisionInputFacts],
    current_active_card_id: Optional[int],
    current_active_serial: Optional[int],
    projected_active_card_id: Optional[int],
    projected_active_serial: Optional[int],
    projected_opponent_active_card_id: Optional[int],
    projected_opponent_active_serial: Optional[int],
    projected_opponent_active_hp: Optional[int],
    current_active_preserved: Optional[bool],
    terminal_win: Optional[bool],
    opponent_active_ko: Optional[bool],
    reply_required: Optional[bool],
    counterline_kind: Stage2b4CounterlineRouteKind,
    supported: bool,
    exact: bool,
    reason: Optional[str],
    counterline_recovery_applied: bool = False,
    integrated: Optional[Stage2b4IntegratedCounterlineFacts] = None,
    attack_fact: Optional[Stage2b4CounterlineAttackFacts] = None,
    incoming_damage: Optional[int] = None,
) -> ActivePositionCurrentAttackLineFacts:
    return ActivePositionCurrentAttackLineFacts(
        origin=origin,
        current_active_card_id=current_active_card_id,
        current_active_serial=current_active_serial,
        attack_option_index=candidate.option_index,
        attack_id=candidate.attack_id,
        attack_candidate=candidate,
        p6_input_facts=decision,
        generic_outcome_facts=candidate.facts,
        counterline_recovery_applied=counterline_recovery_applied,
        projected_active_card_id=projected_active_card_id,
        projected_active_serial=projected_active_serial,
        projected_opponent_active_card_id=projected_opponent_active_card_id,
        projected_opponent_active_serial=projected_opponent_active_serial,
        projected_opponent_active_hp=projected_opponent_active_hp,
        current_active_preserved=current_active_preserved,
        terminal_win=terminal_win,
        opponent_active_ko=opponent_active_ko,
        reply_required=reply_required,
        counterline_kind=counterline_kind,
        incoming_damage=incoming_damage,
        integrated_counterline_facts=integrated,
        counterline_attack_facts=attack_fact,
        supported=supported,
        exact=exact,
        unsupported_reason=reason,
        reasons=("active_position_current_attack_line",)
        + ((reason,) if reason else ()),
    )


def _active_position_current_attack_lines(
    board: BoardView,
    result: SimulationResult,
    candidate: DirectAttackShadowCandidate,
    *,
    allow_counterline_recovery: bool = False,
) -> Tuple[ActivePositionCurrentAttackLineFacts, ...]:
    origin = _current_action_line_origin()
    active = getattr(board, "active", None)
    active_card_id = None if active is None else board.pid(active)
    active_serial = None if active is None else getattr(active, "serial", None)
    decision, projection_facts, projected_active_changed, decision_note = (
        _active_position_attack_decision_input_facts(
            board,
            result,
            allow_counterline_recovery=allow_counterline_recovery,
        )
    )
    recovery_applied = (
        decision_note == "active_position_reply_reaction_projection_recovered"
    )
    if recovery_applied and projection_facts.supported:
        raise ValueError("active_position_recovery_changed_generic_projection_support")
    projected_active_card_id = (
        None if decision.our_active is None else decision.our_active.card_id
    )
    projected_active_serial = (
        None if decision.our_active is None else decision.our_active.serial
    )
    projected_opp_card_id = (
        None
        if decision.opponent_active_after_attack is None
        else decision.opponent_active_after_attack.card_id
    )
    projected_opp_serial = (
        None
        if decision.opponent_active_after_attack is None
        else decision.opponent_active_after_attack.serial
    )
    projected_opp_hp = (
        None
        if decision.opponent_active_after_attack is None
        else decision.opponent_active_after_attack.hp
    )
    preserved = (
        None
        if active_card_id is None
        or type(active_serial) is not int
        or projected_active_card_id is None
        or projected_active_serial is None
        else active_card_id == projected_active_card_id
        and active_serial == projected_active_serial
        and projected_active_changed is False
    )
    if not decision.supported:
        limitation = decision.unsupported_reason
        reason = (
            "active_position_current_attack_does_not_preserve_active"
            if limitation in {
                "attack_switch_effect_unmodeled",
                "attack_active_leaves_play_unmodeled",
            }
            else limitation or "active_position_projected_active_identity_unresolved"
        )
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=preserved,
                terminal_win=decision.candidate_wins_game,
                opponent_active_ko=decision.opponent_active_ko,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason=reason,
            ),
        )
    if (
        active_card_id is None
        or type(active_serial) is not int
        or projected_active_card_id is None
        or type(projected_active_serial) is not int
    ):
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=None,
                terminal_win=decision.candidate_wins_game,
                opponent_active_ko=decision.opponent_active_ko,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason="active_position_projected_active_identity_unresolved",
            ),
        )
    if preserved is not True:
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=preserved,
                terminal_win=decision.candidate_wins_game,
                opponent_active_ko=decision.opponent_active_ko,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason="active_position_current_attack_does_not_preserve_active",
            ),
        )
    if decision.candidate_wins_game is True:
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=None,
                projected_opponent_active_serial=None,
                projected_opponent_active_hp=None,
                current_active_preserved=True,
                terminal_win=True,
                opponent_active_ko=decision.opponent_active_ko,
                reply_required=False,
                counterline_kind=Stage2b4CounterlineRouteKind.NONE,
                supported=True,
                exact=True,
                reason=None,
            ),
        )
    if decision.opponent_active_ko is True:
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=None,
                projected_opponent_active_serial=None,
                projected_opponent_active_hp=0,
                current_active_preserved=True,
                terminal_win=False,
                opponent_active_ko=True,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason="active_position_opponent_promotion_required",
            ),
        )
    opponent = getattr(board, "opp_active", None)
    opponent_damage_amount = (
        0
        if opponent is None or decision.opponent_active_after_attack is None
        else max(0, hp_left(opponent) - decision.opponent_active_after_attack.hp)
    )
    projected_board, board_reason = _stage2b4_project_board(
        board,
        opponent_damage_amount=opponent_damage_amount,
    )
    if projected_board is None:
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=True,
                terminal_win=False,
                opponent_active_ko=False,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason=board_reason,
            ),
        )
    projected_our = projected_active_public_facts(
        projected_board,
        getattr(projected_board, "active", None),
        status_owner=getattr(projected_board, "me", None),
    )
    projected_opponent = projected_active_public_facts(
        projected_board,
        getattr(projected_board, "opp_active", None),
        status_owner=getattr(projected_board, "opp", None),
    )
    if (
        projected_our != decision.our_active
        or projected_opponent != decision.opponent_active_after_attack
    ):
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=True,
                terminal_win=False,
                opponent_active_ko=False,
                reply_required=None,
                counterline_kind=Stage2b4CounterlineRouteKind.UNRESOLVED,
                supported=False,
                exact=False,
                reason="active_position_shared_projection_mismatch",
            ),
        )
    integrated = stage2b4_integrated_counterline_facts(
        projected_board,
        route_enumeration_complete=True,
    )
    public_reply_facts = tuple(
        OpponentPublicThreatEvaluator(
            projected_board,
            projected_our_active=decision.our_active,
        )._attack_facts_from_public_active(
            decision.opponent_active_after_attack,
            ThreatEvidenceKind.CERTAIN,
            True,
        )
    )
    integrated_by_key = {
        (fact.attack_id, fact.opponent_active_id, fact.opponent_active_serial): fact
        for fact in integrated.attack_facts
    }
    usable = tuple(
        fact for fact in public_reply_facts if fact.can_attack_with_current_energy
    )
    uncertain = tuple(
        fact
        for fact in public_reply_facts
        if not fact.can_attack_with_current_energy and fact.unsupported_reason
    )
    if not usable and not uncertain:
        return (
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=True,
                terminal_win=False,
                opponent_active_ko=False,
                reply_required=False,
                counterline_kind=Stage2b4CounterlineRouteKind.NONE,
                supported=True,
                exact=True,
                reason=None,
                integrated=integrated,
            ),
        )
    lines: List[ActivePositionCurrentAttackLineFacts] = []
    active_has_bomb = DELUXE_BOMB in tuple(
        int(getattr(tool, "id", -1))
        for tool in tuple(getattr(projected_board.active, "tools", ()) or ())
    )
    active_is_bruxish = projected_active_card_id == BRUXISH
    for public_fact in usable + uncertain:
        key = (
            public_fact.attack_id,
            public_fact.attacker_card_id,
            public_fact.attacker_serial,
        )
        attack_fact = integrated_by_key.get(key)
        if attack_fact is None and not active_has_bomb and not active_is_bruxish:
            incoming_damage = public_fact.estimated_damage
            holder_ko = (
                None
                if incoming_damage is None or decision.our_active is None
                else int(incoming_damage) >= int(decision.our_active.hp)
            )
            attack_fact = Stage2b4CounterlineAttackFacts(
                supported=public_fact.unsupported_reason is None,
                can_attack_with_current_energy=public_fact.can_attack_with_current_energy,
                attack_id=public_fact.attack_id,
                opponent_active_id=public_fact.attacker_card_id,
                opponent_active_serial=public_fact.attacker_serial,
                holder_id=projected_active_card_id,
                holder_serial=projected_active_serial,
                holder_is_bruxish=False,
                bruxish_trigger_confirmed=False,
                deluxe_bomb_trigger_confirmed=False,
                bruxish_damage_counters=0,
                deluxe_bomb_damage_counters=0,
                combined_damage_counters=0,
                combined_damage_amount=0,
                attacker_damage_before=(
                    None if projected_board.opp_active is None
                    else damage_on(projected_board.opp_active)
                ),
                attacker_damage_after=(
                    None if projected_board.opp_active is None
                    else damage_on(projected_board.opp_active)
                ),
                holder_knocked_out=holder_ko,
                attacker_knocked_out=False if incoming_damage is not None else None,
                attacker_remains_active=True if incoming_damage is not None else None,
                hard_crunch_bonus_after_counterline=False if incoming_damage is not None else None,
                drednaw_followup_supported=False if incoming_damage is not None else None,
                drednaw_serial=None,
                drednaw_hard_crunch_payable=None,
                drednaw_hard_crunch_damage=None,
                simultaneous_knockout=False if holder_ko is not None else None,
                unsupported_reason=public_fact.unsupported_reason,
                reasons=("active_position_no_counterline_reply",)
                + ((public_fact.unsupported_reason,) if public_fact.unsupported_reason else ()),
            )
        kind = (
            Stage2b4CounterlineRouteKind.UNRESOLVED
            if attack_fact is None
            else _active_position_counterline_kind(attack_fact)
        )
        identity_ok = bool(
            attack_fact is not None
            and attack_fact.holder_id == projected_active_card_id
            and attack_fact.holder_serial == projected_active_serial
            and attack_fact.opponent_active_id == projected_opp_card_id
            and attack_fact.opponent_active_serial == projected_opp_serial
        )
        incoming_damage = (
            public_fact.estimated_damage
            if attack_fact is None
            else _active_position_counterline_incoming_damage(integrated, attack_fact)
            if active_has_bomb or active_is_bruxish
            else public_fact.estimated_damage
        )
        drednaw_reason = (
            None
            if attack_fact is None
            else _active_position_drednaw_followup_error(projected_board, attack_fact)
        )
        public_reason = public_fact.unsupported_reason
        if (
            public_reason in {
                "public_tool_damage_effect_unknown",
                "public_damage_effect_unclassified",
            }
            and attack_fact is not None
            and incoming_damage is not None
        ):
            public_reason = None
        reason = None
        if public_reason is not None:
            reason = public_reason
        elif attack_fact is None:
            reason = "active_position_counterline_trigger_unresolved"
        elif not identity_ok:
            reason = "active_position_counterline_identity_mismatch"
        elif incoming_damage is None:
            reason = attack_fact.unsupported_reason or "active_position_opponent_reply_damage_unresolved"
        elif kind == Stage2b4CounterlineRouteKind.UNRESOLVED:
            reason = attack_fact.unsupported_reason or "active_position_counterline_trigger_unresolved"
        elif (
            not attack_fact.supported
            and attack_fact.unsupported_reason
            not in _STAGE2B4_COUNTERLINE_FOLLOWUP_LIMITATION_REASONS
        ):
            reason = attack_fact.unsupported_reason or "active_position_counterline_reply_unsupported"
        elif drednaw_reason is not None:
            reason = drednaw_reason
        supported = reason is None
        lines.append(
            _active_position_current_attack_line_base(
                origin=origin,
                candidate=candidate,
                decision=decision,
                counterline_recovery_applied=recovery_applied,
                current_active_card_id=active_card_id,
                current_active_serial=active_serial,
                projected_active_card_id=projected_active_card_id,
                projected_active_serial=projected_active_serial,
                projected_opponent_active_card_id=projected_opp_card_id,
                projected_opponent_active_serial=projected_opp_serial,
                projected_opponent_active_hp=projected_opp_hp,
                current_active_preserved=True,
                terminal_win=False,
                opponent_active_ko=False,
                reply_required=True,
                counterline_kind=(kind if supported else Stage2b4CounterlineRouteKind.UNRESOLVED),
                supported=supported,
                exact=supported,
                reason=reason,
                integrated=integrated,
                attack_fact=attack_fact,
                incoming_damage=incoming_damage,
            )
        )
    return tuple(lines)


def active_position_current_line_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    current_line: Optional[CurrentActionLineOutcomeFacts] = None,
) -> ActivePositionCurrentLineCollectionFacts:
    """Construct fact-only Current Active stay Lines without ranking actions."""
    current = (
        current_action_line_outcome_facts(board, results)
        if current_line is None
        else current_line
    )
    active = getattr(board, "active", None)
    active_card_id = None if active is None else board.pid(active)
    active_serial = None if active is None else getattr(active, "serial", None)
    if current.selection_state == ActionLineBestAttackState.INCOMPARABLE:
        reason = current.unsupported_reason or "active_position_current_attack_incomparable"
        return ActivePositionCurrentLineCollectionFacts(
            current_action_line=current,
            current_active_card_id=active_card_id,
            current_active_serial=active_serial,
            selection_state=current.selection_state,
            candidate_lines=(),
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("active_position_current_line_collection", reason),
        )
    recoverable_single = bool(
        current.selection_state == ActionLineBestAttackState.UNSUPPORTED
        and current.unsupported_reason == "public_damage_effect_unclassified"
        and len(current.attack_candidates) == 1
        and not current.attack_candidates[0].facts.supported
        and current.attack_candidates[0].facts.unsupported_reason
        == "public_damage_effect_unclassified"
    )
    if current.selection_state == ActionLineBestAttackState.UNSUPPORTED and not recoverable_single:
        reason = (
            "active_position_current_attack_required"
            if not current.attack_candidates
            else current.unsupported_reason or "active_position_current_attack_required"
        )
        return ActivePositionCurrentLineCollectionFacts(
            current_action_line=current,
            current_active_card_id=active_card_id,
            current_active_serial=active_serial,
            selection_state=current.selection_state,
            candidate_lines=(),
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("active_position_current_line_collection", reason),
        )
    candidates = (
        current.attack_candidates
        if recoverable_single
        else _action_line_comparison_candidates(
            current.selection_state,
            current.best_attack,
            current.attack_candidates,
        )
    )
    if not candidates:
        reason = "active_position_current_attack_required"
        return ActivePositionCurrentLineCollectionFacts(
            current_action_line=current,
            current_active_card_id=active_card_id,
            current_active_serial=active_serial,
            selection_state=current.selection_state,
            candidate_lines=(),
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("active_position_current_line_collection", reason),
        )
    lines: List[ActivePositionCurrentAttackLineFacts] = []
    identity_reasons: List[str] = []
    for candidate in candidates:
        result, reason = _active_position_current_result_for_candidate(
            board, results, candidate
        )
        if result is None:
            identity_reasons.append(reason or "active_position_current_attack_identity_unresolved")
            continue
        lines.extend(
            _active_position_current_attack_lines(
                board,
                result,
                candidate,
                allow_counterline_recovery=recoverable_single,
            )
        )
    if identity_reasons or not lines:
        reason = identity_reasons[0] if identity_reasons else "active_position_current_attack_required"
        return ActivePositionCurrentLineCollectionFacts(
            current_action_line=current,
            current_active_card_id=active_card_id,
            current_active_serial=active_serial,
            selection_state=current.selection_state,
            candidate_lines=tuple(lines),
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("active_position_current_line_collection",) + tuple(identity_reasons),
        )
    supported = all(line.supported for line in lines)
    exact = (
        supported
        and (current.state_exact or recoverable_single)
        and all(line.exact for line in lines)
    )
    reason = next(
        (line.unsupported_reason for line in lines if line.unsupported_reason),
        None,
    )
    return ActivePositionCurrentLineCollectionFacts(
        current_action_line=current,
        current_active_card_id=active_card_id,
        current_active_serial=active_serial,
        selection_state=current.selection_state,
        candidate_lines=tuple(lines),
        supported=supported,
        exact=exact,
        unsupported_reason=reason,
        reasons=("active_position_current_line_collection",)
        + ((reason,) if reason else ()),
    )



def deluxe_bomb_resource_preservation_facts(
    current_position: ActivePositionCurrentLineCollectionFacts,
    bomb_line: Stage2b4CounterlineActionLineFacts,
    sibling_routes: Sequence[Stage2b4CounterlineActionLineFacts],
) -> DeluxeBombResourcePreservationFacts:
    """Prove only that a new Deluxe Bomb is redundant for the same confirmed counter-KO."""
    bomb_steps = tuple(
        step for step in bomb_line.action_steps if step.option_card_id == DELUXE_BOMB
    )
    reason: Optional[str] = None
    if not bomb_line.supported:
        reason = bomb_line.unsupported_reason or "deluxe_bomb_preservation_bomb_line_unsupported"
    elif not bomb_line.exact:
        reason = "deluxe_bomb_preservation_bomb_line_not_exact"
    elif bomb_steps and any(
        not step.identity_exact or not step.legality_exact for step in bomb_steps
    ):
        reason = "deluxe_bomb_preservation_bomb_commitment_not_exact"
    elif bomb_steps and any(
        not step.current_observation_option and not step.projected_followup_action
        for step in bomb_steps
    ):
        reason = "deluxe_bomb_preservation_bomb_commitment_origin_unresolved"

    if reason is not None:
        return DeluxeBombResourcePreservationFacts(
            bomb_line=bomb_line,
            matching_current_lines=(),
            matching_non_bomb_routes=(),
            new_bomb_commitment=None,
            preservation_required=None,
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("deluxe_bomb_resource_preservation", reason),
        )

    new_bomb_commitment = bool(bomb_steps)
    if not new_bomb_commitment:
        return DeluxeBombResourcePreservationFacts(
            bomb_line=bomb_line,
            matching_current_lines=(),
            matching_non_bomb_routes=(),
            new_bomb_commitment=False,
            preservation_required=None,
            supported=True,
            exact=True,
            unsupported_reason=None,
            reasons=(
                "deluxe_bomb_resource_preservation",
                "no_new_deluxe_bomb_commitment",
            ),
        )

    bomb_attack_matches = tuple(
        fact
        for fact in tuple(getattr(bomb_line.integrated_facts, "attack_facts", ()) or ())
        if fact.attack_id == bomb_line.opponent_attack_id
        and fact.opponent_active_id == bomb_line.opponent_attacker_card_id
        and fact.opponent_active_serial == bomb_line.opponent_attacker_serial
        and fact.holder_id == bomb_line.holder_card_id
        and fact.holder_serial == bomb_line.holder_serial
    )
    if len(bomb_attack_matches) != 1:
        reason = "deluxe_bomb_preservation_bomb_attack_identity_unresolved"
        return DeluxeBombResourcePreservationFacts(
            bomb_line=bomb_line,
            matching_current_lines=(),
            matching_non_bomb_routes=(),
            new_bomb_commitment=True,
            preservation_required=None,
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("deluxe_bomb_resource_preservation", reason),
        )
    bomb_attack = bomb_attack_matches[0]
    if bomb_attack.deluxe_bomb_trigger_confirmed is not True:
        return DeluxeBombResourcePreservationFacts(
            bomb_line=bomb_line,
            matching_current_lines=(),
            matching_non_bomb_routes=(),
            new_bomb_commitment=True,
            preservation_required=None,
            supported=True,
            exact=True,
            unsupported_reason=None,
            reasons=(
                "deluxe_bomb_resource_preservation",
                "deluxe_bomb_trigger_not_confirmed",
            ),
        )
    if bomb_attack.attacker_knocked_out is not True:
        return DeluxeBombResourcePreservationFacts(
            bomb_line=bomb_line,
            matching_current_lines=(),
            matching_non_bomb_routes=(),
            new_bomb_commitment=True,
            preservation_required=None,
            supported=True,
            exact=True,
            unsupported_reason=None,
            reasons=(
                "deluxe_bomb_resource_preservation",
                "confirmed_attacker_ko_not_established",
            ),
        )

    matching_current_lines = []
    if current_position.supported and current_position.exact:
        for line in current_position.candidate_lines:
            reference = line.counterline_attack_facts
            if not line.supported or not line.exact or reference is None:
                continue
            if (
                reference.holder_id != bomb_attack.holder_id
                or reference.holder_serial != bomb_attack.holder_serial
                or reference.opponent_active_id != bomb_attack.opponent_active_id
                or reference.opponent_active_serial != bomb_attack.opponent_active_serial
                or reference.attack_id != bomb_attack.attack_id
                or reference.attacker_knocked_out is not True
                or reference.holder_knocked_out != bomb_attack.holder_knocked_out
                or reference.simultaneous_knockout != bomb_attack.simultaneous_knockout
                or reference.drednaw_followup_supported != bomb_attack.drednaw_followup_supported
                or reference.drednaw_serial != bomb_attack.drednaw_serial
                or reference.drednaw_hard_crunch_damage != bomb_attack.drednaw_hard_crunch_damage
            ):
                continue
            matching_current_lines.append(line)

    matching_non_bomb_routes = []
    for route in sibling_routes:
        if route is bomb_line or not route.supported or not route.exact:
            continue
        route_bomb_steps = tuple(
            step for step in route.action_steps if step.option_card_id == DELUXE_BOMB
        )
        if route_bomb_steps:
            continue
        route_attack_matches = tuple(
            fact
            for fact in tuple(getattr(route.integrated_facts, "attack_facts", ()) or ())
            if fact.attack_id == route.opponent_attack_id
            and fact.opponent_active_id == route.opponent_attacker_card_id
            and fact.opponent_active_serial == route.opponent_attacker_serial
            and fact.holder_id == route.holder_card_id
            and fact.holder_serial == route.holder_serial
        )
        if len(route_attack_matches) != 1:
            continue
        reference = route_attack_matches[0]
        if (
            reference.holder_id != bomb_attack.holder_id
            or reference.holder_serial != bomb_attack.holder_serial
            or reference.opponent_active_id != bomb_attack.opponent_active_id
            or reference.opponent_active_serial != bomb_attack.opponent_active_serial
            or reference.attack_id != bomb_attack.attack_id
            or reference.attacker_knocked_out is not True
            or reference.holder_knocked_out != bomb_attack.holder_knocked_out
            or reference.simultaneous_knockout != bomb_attack.simultaneous_knockout
            or reference.drednaw_followup_supported != bomb_attack.drednaw_followup_supported
            or reference.drednaw_serial != bomb_attack.drednaw_serial
            or reference.drednaw_hard_crunch_damage != bomb_attack.drednaw_hard_crunch_damage
        ):
            continue
        matching_non_bomb_routes.append(route)

    preservation_required = True if matching_current_lines or matching_non_bomb_routes else None
    return DeluxeBombResourcePreservationFacts(
        bomb_line=bomb_line,
        matching_current_lines=tuple(matching_current_lines),
        matching_non_bomb_routes=tuple(matching_non_bomb_routes),
        new_bomb_commitment=True,
        preservation_required=preservation_required,
        supported=True,
        exact=True,
        unsupported_reason=None,
        reasons=(
            "deluxe_bomb_resource_preservation",
            "exact_new_deluxe_bomb_commitment",
        )
        + (
            ("confirmed_counter_ko_without_new_bomb",)
            if preservation_required is True
            else ("matching_exact_non_bomb_reference_not_proven",)
        ),
    )


def active_position_transition_commitment_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    transition: ActiveBenchTransitionFacts,
    current_position: Optional[ActivePositionCurrentLineCollectionFacts] = None,
) -> ActivePositionTransitionCommitmentFacts:
    """Relate an exact Current Stay baseline to one exact self-transition."""
    current = (
        active_position_current_line_facts(board, results)
        if current_position is None
        else current_position
    )
    binding = transition.origin_binding
    old_active = transition.old_active
    new_active = transition.new_active
    reason: Optional[str] = None

    if current.selection_state == ActionLineBestAttackState.INCOMPARABLE:
        reason = "active_position_commitment_current_position_incomparable"
    elif not current.supported:
        reason = (
            current.unsupported_reason
            or "active_position_commitment_current_position_unsupported"
        )
    elif not current.exact:
        reason = "active_position_commitment_current_position_not_exact"
    elif not current.candidate_lines:
        reason = "active_position_commitment_current_stay_candidate_missing"
    elif any(not line.supported for line in current.candidate_lines):
        reason = "active_position_commitment_current_stay_candidate_unsupported"
    elif any(not line.exact for line in current.candidate_lines):
        reason = "active_position_commitment_current_stay_candidate_not_exact"
    elif not transition.supported:
        reason = (
            transition.unsupported_reason
            or "active_position_commitment_transition_unsupported"
        )
    elif not transition.transition_exact:
        reason = "active_position_commitment_transition_not_exact"
    elif not transition.status_exact:
        reason = "active_position_commitment_transition_status_not_exact"
    elif not binding.supported or not binding.binding_exact or binding.origin is None:
        reason = "active_position_commitment_transition_origin_unresolved"
    elif binding.origin == ActiveBenchTransitionOrigin.BOSS_FORCED_SWITCH:
        reason = "active_position_commitment_forced_transition_not_applicable"
    elif binding.origin not in {
        ActiveBenchTransitionOrigin.RETREAT,
        ActiveBenchTransitionOrigin.SURFING_BEACH,
        ActiveBenchTransitionOrigin.SUGURI,
    }:
        reason = "active_position_commitment_transition_origin_not_applicable"
    elif (
        old_active is None
        or type(current.current_active_card_id) is not int
        or type(current.current_active_serial) is not int
        or type(old_active.card_id) is not int
        or type(old_active.serial) is not int
    ):
        reason = "active_position_commitment_current_active_identity_unresolved"
    elif (
        current.current_active_card_id != old_active.card_id
        or current.current_active_serial != old_active.serial
    ):
        reason = "active_position_commitment_current_active_mismatch"
    elif (
        new_active is None
        or type(new_active.card_id) is not int
        or type(new_active.serial) is not int
        or type(transition.target_card_id) is not int
        or type(transition.target_serial) is not int
    ):
        reason = "active_position_commitment_transition_target_identity_unresolved"
    elif (
        transition.target_card_id != new_active.card_id
        or transition.target_serial != new_active.serial
    ):
        reason = "active_position_commitment_transition_target_identity_mismatch"
    elif old_active.serial == new_active.serial:
        reason = "active_position_commitment_same_active_pseudo_transition"

    if reason is not None:
        return ActivePositionTransitionCommitmentFacts(
            current_position=current,
            transition=transition,
            strict_superiority_required=None,
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("active_position_transition_commitment", reason),
        )

    return ActivePositionTransitionCommitmentFacts(
        current_position=current,
        transition=transition,
        strict_superiority_required=True,
        supported=True,
        exact=True,
        unsupported_reason=None,
        reasons=(
            "active_position_transition_commitment",
            "exact_current_stay_baseline",
            "exact_self_initiated_active_transition",
            "strict_superiority_proof_required",
        ),
    )


def drednaw_defensive_action_line_facts(
    strategy: DrednawHighPowerStrategyFacts,
    current_position: ActivePositionCurrentLineCollectionFacts,
    transitions: Sequence[ActiveBenchTransitionFacts],
) -> Tuple[DrednawDefensiveActionLineFacts, ...]:
    """Adapt existing Drednaw defensive facts into disconnected ActionLine candidates."""
    transition_facts = tuple(transitions)
    combat_lines = tuple(strategy.combat_lines)
    serial_counts: Dict[int, int] = {}
    for combat_line in combat_lines:
        serial = combat_line.drednaw_serial
        if type(serial) is int:
            serial_counts[serial] = serial_counts.get(serial, 0) + 1

    output: List[DrednawDefensiveActionLineFacts] = []
    for combat_line in combat_lines:
        readiness = combat_line.readiness
        serial = combat_line.drednaw_serial
        if type(serial) is not int:
            continue
        attacks = tuple(combat_line.attack_facts)
        if not attacks:
            continue

        paths: List[Tuple[ActionLineOriginFacts, Optional[ActiveBenchTransitionFacts], Optional[str]]] = []
        if readiness.active:
            origin = ActionLineOriginFacts(
                kind=ActionLineOriginKind.CURRENT_BOARD,
                option_index=None,
                target_card_id=DREDNAW,
                target_serial=serial,
                adapter_names=("drednaw_defensive_action_line",),
            )
            path_reason = None
            if (
                current_position.current_active_card_id != DREDNAW
                or current_position.current_active_serial != serial
            ):
                path_reason = "drednaw_defensive_current_active_identity_mismatch"
            paths.append((origin, None, path_reason))
        elif readiness.bench:
            matching_transitions = tuple(
                transition
                for transition in transition_facts
                if transition.target_serial == serial
                or (transition.new_active is not None and transition.new_active.serial == serial)
            )
            if not matching_transitions:
                origin = ActionLineOriginFacts(
                    kind=ActionLineOriginKind.PREPARED_ACTION,
                    option_index=None,
                    target_card_id=DREDNAW,
                    target_serial=serial,
                    adapter_names=("drednaw_defensive_action_line",),
                )
                paths.append((origin, None, "drednaw_defensive_exact_transition_missing"))
            for transition in matching_transitions:
                binding = transition.origin_binding
                origin = ActionLineOriginFacts(
                    kind=ActionLineOriginKind.PREPARED_ACTION,
                    option_index=binding.origin_decision_option_index,
                    option_type=binding.origin_option_type,
                    option_card_id=binding.origin_option_card_id,
                    target_card_id=DREDNAW,
                    target_serial=serial,
                    adapter_names=("drednaw_defensive_action_line",),
                )
                path_reason: Optional[str] = None
                if not transition.supported:
                    path_reason = transition.unsupported_reason or "drednaw_defensive_transition_unsupported"
                elif not transition.transition_exact:
                    path_reason = "drednaw_defensive_transition_not_exact"
                elif not transition.status_exact:
                    path_reason = "drednaw_defensive_transition_status_not_exact"
                elif (
                    not binding.supported
                    or not binding.binding_exact
                    or binding.origin not in {
                        ActiveBenchTransitionOrigin.RETREAT,
                        ActiveBenchTransitionOrigin.SURFING_BEACH,
                        ActiveBenchTransitionOrigin.SUGURI,
                    }
                ):
                    path_reason = "drednaw_defensive_transition_origin_not_applicable"
                elif (
                    transition.new_active is None
                    or transition.target_card_id != DREDNAW
                    or transition.new_active.card_id != DREDNAW
                    or transition.target_serial != serial
                    or transition.new_active.serial != serial
                ):
                    path_reason = "drednaw_defensive_transition_target_identity_mismatch"
                elif (
                    transition.old_active is None
                    or transition.old_active.card_id != current_position.current_active_card_id
                    or transition.old_active.serial != current_position.current_active_serial
                ):
                    path_reason = "drednaw_defensive_transition_old_active_identity_mismatch"
                paths.append((origin, transition, path_reason))
        else:
            origin = ActionLineOriginFacts(
                kind=ActionLineOriginKind.CURRENT_BOARD,
                option_index=None,
                target_card_id=DREDNAW,
                target_serial=serial,
                adapter_names=("drednaw_defensive_action_line",),
            )
            paths.append((origin, None, "drednaw_defensive_position_identity_unresolved"))

        for origin, transition, path_reason in paths:
            for attack in attacks:
                reason = (
                    "drednaw_defensive_duplicate_serial_ambiguity"
                    if serial_counts.get(serial, 0) != 1
                    else path_reason
                )
                if reason is None and (
                    type(strategy.opponent_active_id) is not int
                    or type(strategy.opponent_active_serial) is not int
                ):
                    reason = "drednaw_defensive_opponent_identity_unresolved"
                elif reason is None and readiness.unsupported_reason is not None:
                    reason = readiness.unsupported_reason
                elif reason is None and readiness.drednaw_serial != serial:
                    reason = "drednaw_defensive_readiness_identity_mismatch"
                elif reason is None and readiness.hard_crunch_payable is not True:
                    reason = (
                        "drednaw_defensive_hard_crunch_payability_unknown"
                        if readiness.hard_crunch_payable is None
                        else "drednaw_defensive_hard_crunch_not_payable"
                    )
                elif reason is None and type(readiness.hard_crunch_damage_now) is not int:
                    reason = "drednaw_defensive_hard_crunch_damage_unresolved"
                elif reason is None and attack.target_drednaw_serial != serial:
                    reason = "drednaw_defensive_attack_target_identity_mismatch"
                elif reason is None and type(attack.attack_id) is not int:
                    reason = "drednaw_defensive_opponent_attack_identity_unresolved"
                elif reason is None and attack.unsupported_reason is not None:
                    reason = attack.unsupported_reason
                elif reason is None and type(attack.confirmed_incoming_damage) is not int:
                    reason = "drednaw_defensive_incoming_damage_unresolved"
                elif reason is None and attack.can_attack_with_current_energy is not True:
                    reason = "drednaw_defensive_opponent_attack_not_currently_usable"
                elif reason is None and attack.high_power_attack_confirmed is not True:
                    reason = (
                        "drednaw_defensive_high_power_attack_unknown"
                        if attack.high_power_attack_confirmed is None
                        else "drednaw_defensive_high_power_attack_not_confirmed"
                    )
                elif reason is None and attack.damage_effect_ignore is True:
                    reason = "drednaw_defensive_impervious_shell_bypassed"
                elif reason is None and attack.impervious_shell_effective is not True:
                    reason = (
                        "drednaw_defensive_impervious_shell_unknown"
                        if attack.impervious_shell_effective is None
                        else "drednaw_defensive_impervious_shell_not_effective"
                    )

                output.append(
                    DrednawDefensiveActionLineFacts(
                        strategy=strategy,
                        origin=origin,
                        combat_line=combat_line,
                        transition=transition,
                        drednaw_serial=serial,
                        opponent_attack=attack,
                        supported=reason is None,
                        exact=reason is None,
                        unsupported_reason=reason,
                        reasons=(
                            "drednaw_defensive_action_line",
                            "existing_drednaw_combat_fact_reused",
                            "current_active_drednaw" if transition is None and readiness.active
                            else "exact_self_initiated_drednaw_transition",
                        ) + (() if reason is None else (reason,)),
                    )
                )
    return tuple(output)



def phase3_strategic_action_line_comparison_matrix_facts(
    current_position: ActivePositionCurrentLineCollectionFacts,
    counterline_collections: Sequence[Stage2b4CounterlineActionLineCollectionFacts],
    drednaw_lines: Sequence[DrednawDefensiveActionLineFacts],
    bomb_preservations: Sequence[DeluxeBombResourcePreservationFacts] = (),
    stage2c_lines: Sequence["Stage2cStrategicActionLineFacts"] = (),
) -> Tuple[Phase3StrategicActionLineComparisonFacts, ...]:
    """Build the disconnected strategic relation matrix; never select a winner."""
    current_lines = tuple(current_position.candidate_lines)
    counterlines = tuple(
        route
        for collection in tuple(counterline_collections)
        for route in tuple(collection.routes)
    )
    defensive_lines = tuple(drednaw_lines)
    strategic_stage2c_lines = tuple(stage2c_lines)
    preservations = tuple(bomb_preservations)

    def line_origin(line: Any) -> ActionLineOriginFacts:
        if isinstance(line, ActivePositionCurrentAttackLineFacts):
            return line.origin
        if isinstance(line, DrednawDefensiveActionLineFacts):
            return line.origin
        if isinstance(line, Stage2cStrategicActionLineFacts):
            return ActionLineOriginFacts(
                kind=ActionLineOriginKind.PREPARED_ACTION,
                option_index=line.origin_option_index,
                option_type=line.origin_option_type,
                option_card_id=line.origin_option_card_id,
                target_card_id=line.origin_target_card_id,
                target_serial=line.origin_target_serial,
                adapter_names=("stage2c_strategic_action_line",),
            )
        return ActionLineOriginFacts(
            kind=ActionLineOriginKind.PREPARED_ACTION,
            option_index=line.origin_option_index,
            option_type=line.origin_option_type,
            option_card_id=line.origin_option_card_id,
            target_card_id=line.origin_target_card_id,
            target_serial=line.origin_target_serial,
            adapter_names=("stage2b4_counterline_action_line",),
        )

    def opponent_identity(line: Any) -> Tuple[Optional[int], Optional[int], Optional[int]]:
        if isinstance(line, ActivePositionCurrentAttackLineFacts):
            reply = line.counterline_attack_facts
            if reply is None:
                return None, None, None
            return reply.opponent_active_id, reply.opponent_active_serial, reply.attack_id
        if isinstance(line, Stage2b4CounterlineActionLineFacts):
            return (
                line.opponent_attacker_card_id,
                line.opponent_attacker_serial,
                line.opponent_attack_id,
            )
        if isinstance(line, DrednawDefensiveActionLineFacts):
            return (
                line.strategy.opponent_active_id,
                line.strategy.opponent_active_serial,
                line.opponent_attack.attack_id,
            )
        identities = []
        for current_line in line.current_attack_lines:
            identity = opponent_identity(current_line)
            if any(type(value) is not int for value in identity):
                return None, None, None
            if identity not in identities:
                identities.append(identity)
        return identities[0] if len(identities) == 1 else (None, None, None)

    def stage2c_current_identity(
        line: ActivePositionCurrentAttackLineFacts,
    ) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
        return (
            line.current_active_card_id,
            line.current_active_serial,
            line.attack_option_index,
            line.attack_id,
        )

    def stage2c_matching_current_line(
        stage2c: Stage2cStrategicActionLineFacts,
        current: ActivePositionCurrentAttackLineFacts,
    ) -> Tuple[Optional[ActivePositionCurrentAttackLineFacts], Optional[str]]:
        target = stage2c_current_identity(current)
        if any(type(value) is not int for value in target):
            return None, "stage2c_current_attack_identity_unresolved"
        matches = tuple(
            candidate
            for candidate in stage2c.current_attack_lines
            if candidate.supported
            and candidate.exact
            and stage2c_current_identity(candidate) == target
        )
        if len(matches) == 0:
            return None, "stage2c_matching_current_line_missing"
        if len(matches) != 1:
            return None, "stage2c_matching_current_line_ambiguous"
        current_scenario = opponent_identity(current)
        matching_scenario = opponent_identity(matches[0])
        if any(
            type(value) is not int
            for value in current_scenario + matching_scenario
        ):
            return None, "stage2c_matching_current_opponent_scenario_unresolved"
        if current_scenario != matching_scenario:
            return None, "stage2c_matching_current_opponent_scenario_mismatch"
        return matches[0], None

    def stage2c_lines_for_scenario(
        stage2c: Stage2cStrategicActionLineFacts,
        scenario: Tuple[Optional[int], Optional[int], Optional[int]],
    ) -> Tuple[Tuple[ActivePositionCurrentAttackLineFacts, ...], Optional[str]]:
        if any(type(value) is not int for value in scenario):
            return (), "stage2c_opponent_scenario_unresolved"
        matches = []
        for current_line in stage2c.current_attack_lines:
            if not current_line.supported or not current_line.exact:
                return (), "stage2c_current_line_unsupported_or_inexact"
            identity = opponent_identity(current_line)
            if any(type(value) is not int for value in identity):
                return (), "stage2c_opponent_scenario_unresolved"
            if identity == scenario:
                matches.append(current_line)
        if len(matches) == 0:
            return (), "stage2c_opponent_scenario_mismatch"
        if len(matches) != 1:
            return tuple(matches), "stage2c_opponent_scenario_ambiguous"
        return tuple(matches), None

    def pair_opponent_identity(
        left: Any,
        right: Any,
    ) -> Tuple[Tuple[Optional[int], Optional[int], Optional[int]], Optional[str]]:
        left_stage2c = isinstance(left, Stage2cStrategicActionLineFacts)
        right_stage2c = isinstance(right, Stage2cStrategicActionLineFacts)
        if not left_stage2c and not right_stage2c:
            left_identity = opponent_identity(left)
            right_identity = opponent_identity(right)
            if any(type(value) is not int for value in left_identity + right_identity):
                return (None, None, None), "strategic_opponent_attack_identity_unresolved"
            if left_identity != right_identity:
                return (None, None, None), "strategic_opponent_attack_identity_mismatch"
            return left_identity, None

        if left_stage2c and right_stage2c:
            left_scenarios = []
            right_scenarios = []
            for stage2c, output in ((left, left_scenarios), (right, right_scenarios)):
                for current_line in stage2c.current_attack_lines:
                    if not current_line.supported or not current_line.exact:
                        return (None, None, None), "stage2c_current_line_unsupported_or_inexact"
                    identity = opponent_identity(current_line)
                    if any(type(value) is not int for value in identity):
                        return (None, None, None), "stage2c_opponent_scenario_unresolved"
                    if identity not in output:
                        output.append(identity)
            shared = tuple(identity for identity in left_scenarios if identity in right_scenarios)
            if len(shared) == 0:
                return (None, None, None), "stage2c_shared_opponent_scenario_missing"
            if len(shared) != 1:
                return (None, None, None), "stage2c_shared_opponent_scenario_ambiguous"
            return shared[0], None

        stage2c = left if left_stage2c else right
        other = right if left_stage2c else left
        if isinstance(other, ActivePositionCurrentAttackLineFacts):
            _, reason = stage2c_matching_current_line(stage2c, other)
            if reason is not None:
                return (None, None, None), reason
            return opponent_identity(other), None

        other_identity = opponent_identity(other)
        _, reason = stage2c_lines_for_scenario(stage2c, other_identity)
        if reason is not None:
            return (None, None, None), reason
        return other_identity, None

    def fail_closed(
        left: Any,
        right: Any,
        reason: str,
        comparison_reason: DirectAttackComparisonReason = DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
    ) -> Phase3StrategicActionLineComparisonFacts:
        shared, _ = pair_opponent_identity(left, right)
        return Phase3StrategicActionLineComparisonFacts(
            left_origin=line_origin(left),
            right_origin=line_origin(right),
            left_line=left,
            right_line=right,
            opponent_attacker_card_id=shared[0],
            opponent_attacker_serial=shared[1],
            opponent_attack_id=shared[2],
            relation=DirectAttackComparison.INCOMPARABLE,
            reason=comparison_reason,
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=("phase3_strategic_action_line_comparison", reason),
        )

    def exact_result(
        left: Any,
        right: Any,
        relation: DirectAttackComparison,
        reason: DirectAttackComparisonReason,
        *extra_reasons: str,
    ) -> Phase3StrategicActionLineComparisonFacts:
        shared, _ = pair_opponent_identity(left, right)
        return Phase3StrategicActionLineComparisonFacts(
            left_origin=line_origin(left),
            right_origin=line_origin(right),
            left_line=left,
            right_line=right,
            opponent_attacker_card_id=shared[0],
            opponent_attacker_serial=shared[1],
            opponent_attack_id=shared[2],
            relation=relation,
            reason=reason,
            supported=True,
            exact=True,
            unsupported_reason=None,
            reasons=("phase3_strategic_action_line_comparison",) + tuple(extra_reasons),
        )

    def is_line_exact(line: Any) -> bool:
        if isinstance(line, ActivePositionCurrentAttackLineFacts):
            return (
                current_position.supported
                and current_position.exact
                and current_position.selection_state
                not in {ActionLineBestAttackState.UNSUPPORTED, ActionLineBestAttackState.INCOMPARABLE}
                and line.supported
                and line.exact
            )
        return bool(line.supported and line.exact)

    def current_terminal_win(line: ActivePositionCurrentAttackLineFacts) -> bool:
        return line.terminal_win is True

    def current_confirmed_reply_loss(line: ActivePositionCurrentAttackLineFacts) -> bool:
        outcome = line.generic_outcome_facts
        reply = line.counterline_attack_facts
        return bool(
            outcome is not None
            and getattr(outcome, "supported", False) is True
            and outcome.confirmed_loss is True
            and outcome.confirmed_reply_ko is True
            and reply is not None
            and reply.supported
            and reply.holder_knocked_out is True
            and type(reply.opponent_active_id) is int
            and type(reply.opponent_active_serial) is int
            and type(reply.attack_id) is int
        )

    def preservation_direction(left: Any, right: Any) -> int:
        for preservation in preservations:
            if (
                not preservation.supported
                or not preservation.exact
                or preservation.preservation_required is not True
            ):
                continue
            references = tuple(preservation.matching_current_lines) + tuple(
                preservation.matching_non_bomb_routes
            )
            if preservation.bomb_line == left and any(reference == right for reference in references):
                return -1
            if preservation.bomb_line == right and any(reference == left for reference in references):
                return 1
        return 0

    def counter_resource_signature(line: Stage2b4CounterlineActionLineFacts) -> Tuple[Any, ...]:
        return (
            line.action_kind,
            line.route_kind,
            line.route_origin,
            line.origin_option_type,
            line.origin_option_card_id,
            line.origin_target_card_id,
            line.origin_target_serial,
            line.action_count,
            line.remaining_actions,
            tuple(
                (
                    step.option_type,
                    step.option_card_id,
                    step.option_effect_id,
                    step.target_card_id,
                    step.target_serial,
                    step.route_origin,
                    step.current_observation_option,
                    step.projected_followup_action,
                    step.identity_exact,
                    step.legality_exact,
                )
                for step in line.action_steps
            ),
        )

    def compare_counterlines(
        left: Stage2b4CounterlineActionLineFacts,
        right: Stage2b4CounterlineActionLineFacts,
    ) -> Phase3StrategicActionLineComparisonFacts:
        if any(
            type(value) is not int
            for value in (
                left.holder_card_id,
                left.holder_serial,
                right.holder_card_id,
                right.holder_serial,
            )
        ):
            return fail_closed(left, right, "strategic_counterline_holder_identity_unresolved")
        if (
            left.holder_card_id != right.holder_card_id
            or left.holder_serial != right.holder_serial
        ):
            return fail_closed(left, right, "strategic_counterline_holder_identity_mismatch")
        primary_values = (
            left.attacker_knocked_out,
            right.attacker_knocked_out,
            left.holder_knocked_out,
            right.holder_knocked_out,
            left.holder_survives,
            right.holder_survives,
            left.simultaneous_knockout,
            right.simultaneous_knockout,
        )
        if any(type(value) is not bool for value in primary_values):
            return fail_closed(left, right, "strategic_counterline_primary_outcome_inexact")
        if (
            left.holder_knocked_out == left.holder_survives
            or right.holder_knocked_out == right.holder_survives
        ):
            return fail_closed(left, right, "strategic_counterline_holder_state_inconsistent")

        directions: List[int] = []
        if left.attacker_knocked_out != right.attacker_knocked_out:
            directions.append(1 if left.attacker_knocked_out else -1)
        if left.holder_survives != right.holder_survives:
            directions.append(1 if left.holder_survives else -1)

        primary_equal = (
            left.attacker_knocked_out == right.attacker_knocked_out
            and left.holder_survives == right.holder_survives
        )
        if primary_equal and left.simultaneous_knockout != right.simultaneous_knockout:
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "counterline_simultaneous_ko_state_differs",
            )

        if primary_equal:
            left_follow = left.drednaw_followup_supported
            right_follow = right.drednaw_followup_supported
            if type(left_follow) is not bool or type(right_follow) is not bool:
                return fail_closed(left, right, "strategic_counterline_followup_inexact")
            if left_follow != right_follow:
                directions.append(1 if left_follow else -1)
            elif left_follow:
                if (
                    type(left.drednaw_serial) is not int
                    or type(right.drednaw_serial) is not int
                    or type(left.drednaw_hard_crunch_damage) is not int
                    or type(right.drednaw_hard_crunch_damage) is not int
                ):
                    return fail_closed(left, right, "strategic_counterline_followup_identity_inexact")
                if left.drednaw_serial != right.drednaw_serial:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        "different_drednaw_followup_identity",
                    )
                if left.drednaw_hard_crunch_damage != right.drednaw_hard_crunch_damage:
                    directions.append(
                        1 if left.drednaw_hard_crunch_damage > right.drednaw_hard_crunch_damage else -1
                    )
        preservation = preservation_direction(left, right)
        if primary_equal and not directions and preservation:
            return exact_result(
                left,
                right,
                DirectAttackComparison.LEFT_BETTER if preservation > 0 else DirectAttackComparison.RIGHT_BETTER,
                DirectAttackComparisonReason.SAFE_DOMINANCE,
                "deluxe_bomb_resource_preservation",
                "redundant_new_bomb_commitment",
            )

        if primary_equal:
            if type(left.counter_damage_amount) is not int or type(right.counter_damage_amount) is not int:
                return fail_closed(left, right, "strategic_counterline_damage_inexact")
            if left.counter_damage_amount != right.counter_damage_amount:
                directions.append(1 if left.counter_damage_amount > right.counter_damage_amount else -1)

        distinct = set(directions)
        if distinct == {1, -1}:
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                "counterline_conflicting_advantages",
            )
        if distinct == {1}:
            if preservation < 0:
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.INCOMPARABLE,
                    DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                    "counterline_combat_vs_bomb_resource_tradeoff",
                )
            return exact_result(
                left, right, DirectAttackComparison.LEFT_BETTER,
                DirectAttackComparisonReason.SAFE_DOMINANCE,
                "counterline_safe_dominance",
            )
        if distinct == {-1}:
            if preservation > 0:
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.INCOMPARABLE,
                    DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                    "counterline_combat_vs_bomb_resource_tradeoff",
                )
            return exact_result(
                left, right, DirectAttackComparison.RIGHT_BETTER,
                DirectAttackComparisonReason.SAFE_DOMINANCE,
                "counterline_safe_dominance",
            )

        if counter_resource_signature(left) != counter_resource_signature(right):
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "counterline_resource_identity_differs",
            )
        return exact_result(
            left,
            right,
            DirectAttackComparison.EQUIVALENT,
            DirectAttackComparisonReason.SAME_CANONICAL_OUTCOME,
            "counterline_exact_outcome_equivalent",
        )

    def drednaw_cost_class(line: DrednawDefensiveActionLineFacts) -> Any:
        if line.transition is None:
            return "CURRENT_ACTIVE"
        binding = line.transition.origin_binding
        if (
            not binding.supported
            or not binding.binding_exact
            or binding.origin not in {
                ActiveBenchTransitionOrigin.RETREAT,
                ActiveBenchTransitionOrigin.SURFING_BEACH,
                ActiveBenchTransitionOrigin.SUGURI,
            }
        ):
            return None
        return binding.origin

    def compare_drednaw(
        left: DrednawDefensiveActionLineFacts,
        right: DrednawDefensiveActionLineFacts,
    ) -> Phase3StrategicActionLineComparisonFacts:
        left_class = drednaw_cost_class(left)
        right_class = drednaw_cost_class(right)
        if left_class is None or right_class is None:
            return fail_closed(left, right, "strategic_drednaw_transition_cost_class_inexact")
        if left_class != right_class:
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                "drednaw_transition_cost_class_tradeoff",
            )
        left_damage = left.combat_line.readiness.hard_crunch_damage_now
        right_damage = right.combat_line.readiness.hard_crunch_damage_now
        if type(left_damage) is not int or type(right_damage) is not int:
            return fail_closed(left, right, "strategic_drednaw_hard_crunch_damage_inexact")
        if left_damage > right_damage:
            return exact_result(
                left, right, DirectAttackComparison.LEFT_BETTER,
                DirectAttackComparisonReason.SAFE_DOMINANCE,
                "drednaw_same_cost_class_higher_hard_crunch",
            )
        if right_damage > left_damage:
            return exact_result(
                left, right, DirectAttackComparison.RIGHT_BETTER,
                DirectAttackComparisonReason.SAFE_DOMINANCE,
                "drednaw_same_cost_class_higher_hard_crunch",
            )
        if left.drednaw_serial != right.drednaw_serial:
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "drednaw_identity_difference_unmodeled",
            )
        return exact_result(
            left,
            right,
            DirectAttackComparison.EQUIVALENT,
            DirectAttackComparisonReason.SAME_CANONICAL_OUTCOME,
            "drednaw_same_cost_class_same_hard_crunch",
        )

    def compare_current_stage2c(
        left: Any,
        right: Any,
        current: ActivePositionCurrentAttackLineFacts,
        stage2c: Stage2cStrategicActionLineFacts,
        *,
        left_current: bool,
    ) -> Phase3StrategicActionLineComparisonFacts:
        matching_current, matching_reason = stage2c_matching_current_line(stage2c, current)
        if matching_reason is not None or matching_current is None:
            return fail_closed(
                left,
                right,
                matching_reason or "stage2c_matching_current_line_unresolved",
            )

        if stage2c.action_line_kind == Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY:
            continuation_identity_preserved = bool(
                type(current.attack_option_index) is int
                and type(current.attack_id) is int
                and (current.attack_option_index, current.attack_id)
                in tuple(zip(
                    stage2c.continuation_attack_option_indices,
                    stage2c.continuation_attack_ids,
                ))
            )
            safe_dominance = bool(
                type(stage2c.origin_option_index) is int
                and stage2c.origin_option_type == OptionType.PLAY
                and type(stage2c.origin_option_card_id) is int
                and stage2c.continuation_confirmed is True
                and stage2c.attack_preserved_after_origin is True
                and stage2c.current_attack_is_nonwinning_ko is True
                and stage2c.current_direct_win_exists is False
                and stage2c.bench_count_before == 0
                and type(stage2c.bench_space_before) is int
                and stage2c.bench_space_before > 0
                and stage2c.bench_slot_consumed is True
                and current.terminal_win is False
                and current.opponent_active_ko is True
                and matching_current.terminal_win is False
                and matching_current.opponent_active_ko is True
                and continuation_identity_preserved
            )
            if safe_dominance:
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.RIGHT_BETTER
                    if left_current
                    else DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparisonReason.SAFE_DOMINANCE,
                    "stage2c_safe_pre_ko_preserved_ko_with_board_out_buffer",
                )
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "stage2c_safe_pre_ko_safe_dominance_not_proven",
            )

        if stage2c.action_line_kind == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT:
            continuation_identity_preserved = bool(
                type(current.attack_option_index) is int
                and type(current.attack_id) is int
                and (current.attack_option_index, current.attack_id)
                in tuple(zip(
                    stage2c.continuation_attack_option_indices,
                    stage2c.continuation_attack_ids,
                ))
            )
            chewtle_role = bool(
                stage2c.origin_option_card_id == CHEWTLE
                and stage2c.same_card_in_play_count == 0
                and stage2c.duplicate_deployment is False
                and type(stage2c.accessible_drednaw_line_count) is int
                and stage2c.accessible_drednaw_line_count > 0
                and (
                    stage2c.chewtle_drednaw_in_hand is True
                    or stage2c.drednaw_remaining_possible is True
                )
            )
            bruxish_role = bool(
                stage2c.origin_option_card_id == BRUXISH
                and stage2c.bruxish_already_in_play is False
                and stage2c.bruxish_counterattack_contract_supported is True
                and stage2c.bruxish_counterline_role_live is True
            )
            last_slot_ambiguous = bool(
                stage2c.bench_space_before == 1
                and stage2c.other_legal_basic_option_indices
            )
            current_scenario = opponent_identity(current)
            blocking_evolution = any(
                evolution is not stage2c
                and evolution.action_line_kind
                == Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION
                and evolution.supported
                and evolution.exact
                and evolution.evolution_relation_exact is True
                and pair_opponent_identity(current, evolution)[1] is None
                and opponent_identity(evolution) == current_scenario
                for evolution in strategic_stage2c_lines
            )
            hand_dominance = bool(
                type(stage2c.origin_option_index) is int
                and stage2c.origin_option_type == OptionType.PLAY
                and type(stage2c.origin_option_card_id) is int
                and stage2c.continuation_confirmed is True
                and stage2c.attack_preserved_after_origin is True
                and stage2c.current_direct_win_exists is False
                and stage2c.current_direct_knockout_exists is False
                and stage2c.current_non_ko_attack_exists is True
                and type(stage2c.bench_space_before) is int
                and stage2c.bench_space_before > 0
                and stage2c.bench_slot_consumed is True
                and current.terminal_win is False
                and current.opponent_active_ko is False
                and matching_current.terminal_win is False
                and matching_current.opponent_active_ko is False
                and continuation_identity_preserved
                and (chewtle_role or bruxish_role)
                and not last_slot_ambiguous
                and not blocking_evolution
                and stage2c.blocking_high_value_evolution_exists is False
            )
            if hand_dominance:
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.RIGHT_BETTER
                    if left_current
                    else DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparisonReason.SAFE_DOMINANCE,
                    "stage2c_hand_basic_preserved_nonko_with_exact_development_role",
                )
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "stage2c_hand_basic_safe_dominance_not_proven",
            )

        if stage2c.action_line_kind == Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION:
            continuation_identity_preserved = bool(
                type(current.attack_option_index) is int
                and type(current.attack_id) is int
                and (current.attack_option_index, current.attack_id)
                in tuple(zip(
                    stage2c.continuation_attack_option_indices,
                    stage2c.continuation_attack_ids,
                ))
            )
            evolution_dominance = bool(
                type(stage2c.origin_option_index) is int
                and stage2c.origin_option_type == OptionType.EVOLVE
                and type(stage2c.origin_option_card_id) is int
                and type(stage2c.origin_target_card_id) is int
                and type(stage2c.origin_target_serial) is int
                and stage2c.evolution_relation_exact is True
                and stage2c.continuation_confirmed is True
                and stage2c.attack_preserved_after_origin is True
                and stage2c.current_direct_win_exists is False
                and stage2c.current_direct_knockout_exists is False
                and stage2c.current_non_ko_attack_exists is True
                and current.terminal_win is False
                and current.opponent_active_ko is False
                and matching_current.terminal_win is False
                and matching_current.opponent_active_ko is False
                and continuation_identity_preserved
            )
            if evolution_dominance:
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.RIGHT_BETTER
                    if left_current
                    else DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparisonReason.SAFE_DOMINANCE,
                    "stage2c_evolution_preserved_nonko_with_exact_line_progression",
                )
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "stage2c_evolution_safe_dominance_not_proven",
            )

        return exact_result(
            left,
            right,
            DirectAttackComparison.INCOMPARABLE,
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
            "stage2c_unknown_action_line_kind",
        )

    def compare_pair(left: Any, right: Any) -> Phase3StrategicActionLineComparisonFacts:
        if not is_line_exact(left):
            return fail_closed(
                left,
                right,
                getattr(left, "unsupported_reason", None) or "left_strategic_line_unsupported_or_inexact",
                DirectAttackComparisonReason.OVERALL_UNSUPPORTED,
            )
        if not is_line_exact(right):
            return fail_closed(
                left,
                right,
                getattr(right, "unsupported_reason", None) or "right_strategic_line_unsupported_or_inexact",
                DirectAttackComparisonReason.OVERALL_UNSUPPORTED,
            )

        left_current = isinstance(left, ActivePositionCurrentAttackLineFacts)
        right_current = isinstance(right, ActivePositionCurrentAttackLineFacts)
        if left_current and current_terminal_win(left):
            return exact_result(
                left, right, DirectAttackComparison.LEFT_BETTER,
                DirectAttackComparisonReason.LEFT_IMMEDIATE_WIN,
                "current_terminal_win",
            )
        if right_current and current_terminal_win(right):
            return exact_result(
                left, right, DirectAttackComparison.RIGHT_BETTER,
                DirectAttackComparisonReason.RIGHT_IMMEDIATE_WIN,
                "current_terminal_win",
            )

        shared_identity, identity_reason = pair_opponent_identity(left, right)
        if identity_reason is not None:
            return fail_closed(left, right, identity_reason)
        if any(type(value) is not int for value in shared_identity):
            return fail_closed(left, right, "strategic_opponent_attack_identity_unresolved")

        if left_current or right_current:
            current = left if left_current else right
            strategic = right if left_current else left
            confirmed_reply_loss = current_confirmed_reply_loss(current)
            if confirmed_reply_loss:
                avoids = False
                if isinstance(strategic, Stage2b4CounterlineActionLineFacts):
                    avoids = strategic.holder_survives is True
                elif isinstance(strategic, DrednawDefensiveActionLineFacts):
                    avoids = True
                if avoids:
                    if left_current:
                        return exact_result(
                            left,
                            right,
                            DirectAttackComparison.RIGHT_BETTER,
                            DirectAttackComparisonReason.RIGHT_AVOIDS_CONFIRMED_LOSS,
                            "exact_confirmed_loss_avoidance",
                        )
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparisonReason.LEFT_AVOIDS_CONFIRMED_LOSS,
                        "exact_confirmed_loss_avoidance",
                    )
                if (
                    isinstance(strategic, Stage2cStrategicActionLineFacts)
                    and strategic.action_line_kind
                    == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT
                    and strategic.origin_option_card_id == BRUXISH
                ):
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        "stage2c_bruxish_confirmed_reply_loss_not_proven_avoided",
                    )
            if not confirmed_reply_loss:
                preservation = preservation_direction(left, right)
                if preservation:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.LEFT_BETTER
                        if preservation > 0
                        else DirectAttackComparison.RIGHT_BETTER,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "deluxe_bomb_resource_preservation",
                        "redundant_new_bomb_commitment",
                    )
            if isinstance(strategic, Stage2cStrategicActionLineFacts):
                return compare_current_stage2c(
                    left,
                    right,
                    current,
                    strategic,
                    left_current=left_current,
                )
            if isinstance(strategic, Stage2b4CounterlineActionLineFacts):
                current_reply = current.counterline_attack_facts
                if current_reply is None:
                    return fail_closed(
                        left, right, "current_counterline_composite_missing"
                    )

                current_primary = (
                    current_reply.attacker_knocked_out,
                    current_reply.holder_knocked_out,
                    current_reply.simultaneous_knockout,
                )
                strategic_primary = (
                    strategic.attacker_knocked_out,
                    strategic.holder_knocked_out,
                    strategic.simultaneous_knockout,
                )
                if any(
                    type(value) is not bool
                    for value in current_primary + strategic_primary
                ) or type(strategic.holder_survives) is not bool:
                    return fail_closed(
                        left, right, "current_counterline_primary_outcome_inexact"
                    )
                if strategic.holder_knocked_out == strategic.holder_survives:
                    return fail_closed(
                        left, right, "current_counterline_holder_state_inconsistent"
                    )

                current_survives = not current_reply.holder_knocked_out
                current_better = []
                strategic_better = []
                if current_reply.attacker_knocked_out != strategic.attacker_knocked_out:
                    if current_reply.attacker_knocked_out:
                        current_better.append("attacker_knockout")
                    else:
                        strategic_better.append("attacker_knockout")
                if current_survives != strategic.holder_survives:
                    if current_survives:
                        current_better.append("holder_survival")
                    else:
                        strategic_better.append("holder_survival")

                primary_differs = bool(current_better or strategic_better)
                if primary_differs and (
                    strategic.action_count < 1
                    or len(strategic.action_steps) != strategic.action_count
                    or any(
                        not step.identity_exact or not step.legality_exact
                        for step in strategic.action_steps
                    )
                ):
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        "current_counterline_action_identity_missing_for_primary_change",
                    )

                if current_better and strategic_better:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                        "current_counterline_primary_conflict",
                    )

                strategic_has_new_bomb = any(
                    step.option_card_id == DELUXE_BOMB
                    for step in strategic.action_steps
                )
                self_transition_origins = {
                    ActiveBenchTransitionOrigin.RETREAT,
                    ActiveBenchTransitionOrigin.SURFING_BEACH,
                    ActiveBenchTransitionOrigin.SUGURI,
                }
                strategic_transition = (
                    strategic.route_origin
                    if strategic.route_origin in self_transition_origins
                    else next(
                        (
                            step.route_origin
                            for step in strategic.action_steps
                            if step.route_origin in self_transition_origins
                        ),
                        None,
                    )
                )
                strategic_has_transition_commitment = strategic_transition is not None
                strategic_has_supporter_commitment = (
                    strategic_transition == ActiveBenchTransitionOrigin.SUGURI
                    or any(step.option_card_id == SUGURI for step in strategic.action_steps)
                )
                strategic_has_resource_commitment = (
                    strategic_has_new_bomb
                    or strategic_has_transition_commitment
                    or strategic_has_supporter_commitment
                )

                if current_better:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.LEFT_BETTER
                        if left_current
                        else DirectAttackComparison.RIGHT_BETTER,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "current_counterline_primary_safe_dominance",
                        *(f"current_primary_{item}" for item in current_better),
                    )
                if strategic_better:
                    if strategic_has_new_bomb:
                        return exact_result(
                            left,
                            right,
                            DirectAttackComparison.INCOMPARABLE,
                            DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                            "current_counterline_primary_vs_bomb_resource_tradeoff",
                        )
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.RIGHT_BETTER
                        if left_current
                        else DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "current_counterline_primary_safe_dominance",
                        *(f"strategic_primary_{item}" for item in strategic_better),
                    )

                if (
                    current_reply.simultaneous_knockout
                    != strategic.simultaneous_knockout
                ):
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        "current_counterline_simultaneous_ko_state_differs",
                    )

                current_follow = current_reply.drednaw_followup_supported
                strategic_follow = strategic.drednaw_followup_supported
                if type(current_follow) is not bool or type(strategic_follow) is not bool:
                    return fail_closed(
                        left, right, "current_counterline_drednaw_followup_inexact"
                    )
                if current_follow != strategic_follow:
                    if strategic_has_resource_commitment and strategic_follow:
                        return exact_result(
                            left,
                            right,
                            DirectAttackComparison.INCOMPARABLE,
                            DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                            "current_counterline_continuation_resource_tradeoff",
                        )
                    relation = (
                        DirectAttackComparison.RIGHT_BETTER
                        if strategic_follow == left_current
                        else DirectAttackComparison.LEFT_BETTER
                    )
                    return exact_result(
                        left,
                        right,
                        relation,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "current_counterline_drednaw_followup_safe_dominance",
                    )

                if current_follow:
                    current_drednaw = (
                        current_reply.drednaw_serial,
                        current_reply.drednaw_hard_crunch_damage,
                    )
                    strategic_drednaw = (
                        strategic.drednaw_serial,
                        strategic.drednaw_hard_crunch_damage,
                    )
                    if any(
                        type(value) is not int
                        for value in current_drednaw + strategic_drednaw
                    ):
                        return fail_closed(
                            left, right, "current_counterline_drednaw_identity_or_damage_inexact"
                        )
                    if current_reply.drednaw_serial != strategic.drednaw_serial:
                        return exact_result(
                            left,
                            right,
                            DirectAttackComparison.INCOMPARABLE,
                            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                            "current_counterline_drednaw_identity_mismatch",
                        )
                    if (
                        current_reply.drednaw_hard_crunch_damage
                        != strategic.drednaw_hard_crunch_damage
                    ):
                        if (
                            strategic_has_resource_commitment
                            and strategic.drednaw_hard_crunch_damage
                            > current_reply.drednaw_hard_crunch_damage
                        ):
                            return exact_result(
                                left,
                                right,
                                DirectAttackComparison.INCOMPARABLE,
                                DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                                "current_counterline_continuation_resource_tradeoff",
                            )
                        strategic_damage_better = (
                            strategic.drednaw_hard_crunch_damage
                            > current_reply.drednaw_hard_crunch_damage
                        )
                        return exact_result(
                            left,
                            right,
                            (
                                (
                                    DirectAttackComparison.RIGHT_BETTER
                                    if left_current
                                    else DirectAttackComparison.LEFT_BETTER
                                )
                                if strategic_damage_better
                                else (
                                    DirectAttackComparison.LEFT_BETTER
                                    if left_current
                                    else DirectAttackComparison.RIGHT_BETTER
                                )
                            ),
                            DirectAttackComparisonReason.SAFE_DOMINANCE,
                            "current_counterline_same_drednaw_continuation_damage",
                        )

                current_holder = (current_reply.holder_id, current_reply.holder_serial)
                strategic_holder = (strategic.holder_card_id, strategic.holder_serial)
                current_counter_damage = current_reply.combined_damage_amount
                strategic_counter_damage = strategic.counter_damage_amount
                if any(
                    type(value) is not int
                    for value in current_holder + strategic_holder
                ):
                    return fail_closed(
                        left, right, "current_counterline_holder_identity_unresolved"
                    )
                if current_holder != strategic_holder:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        "current_counterline_holder_identity_differs",
                    )
                if (
                    type(current_counter_damage) is not int
                    or type(strategic_counter_damage) is not int
                ):
                    return fail_closed(
                        left, right, "current_counterline_counter_damage_inexact"
                    )

                if strategic_has_resource_commitment:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.INCOMPARABLE,
                        DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                        (
                            "current_counterline_bomb_resource_tradeoff"
                            if strategic_has_new_bomb
                            else "current_counterline_transition_commitment_tradeoff"
                        ),
                    )
                if current_counter_damage > strategic_counter_damage:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.LEFT_BETTER
                        if left_current
                        else DirectAttackComparison.RIGHT_BETTER,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "current_counterline_same_horizon_counter_damage",
                    )
                if strategic_counter_damage > current_counter_damage:
                    return exact_result(
                        left,
                        right,
                        DirectAttackComparison.RIGHT_BETTER
                        if left_current
                        else DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparisonReason.SAFE_DOMINANCE,
                        "current_counterline_same_horizon_counter_damage",
                    )
                return exact_result(
                    left,
                    right,
                    DirectAttackComparison.EQUIVALENT,
                    DirectAttackComparisonReason.SAME_CANONICAL_OUTCOME,
                    "current_counterline_exact_composite_equivalent",
                )

            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
                "current_strategic_horizon_tradeoff",
            )

        if (
            isinstance(left, Stage2b4CounterlineActionLineFacts)
            and isinstance(right, Stage2b4CounterlineActionLineFacts)
        ):
            return compare_counterlines(left, right)
        if (
            isinstance(left, DrednawDefensiveActionLineFacts)
            and isinstance(right, DrednawDefensiveActionLineFacts)
        ):
            return compare_drednaw(left, right)
        left_stage2c = isinstance(left, Stage2cStrategicActionLineFacts)
        right_stage2c = isinstance(right, Stage2cStrategicActionLineFacts)
        if left_stage2c and right_stage2c:
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                "stage2c_vs_stage2c_strategic_tradeoff",
            )
        if left_stage2c or right_stage2c:
            other = right if left_stage2c else left
            return exact_result(
                left,
                right,
                DirectAttackComparison.INCOMPARABLE,
                DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
                (
                    "stage2c_vs_counterline_strategic_tradeoff"
                    if isinstance(other, Stage2b4CounterlineActionLineFacts)
                    else "stage2c_vs_drednaw_strategic_tradeoff"
                ),
            )
        return exact_result(
            left,
            right,
            DirectAttackComparison.INCOMPARABLE,
            DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
            "counterline_vs_drednaw_tradeoff",
        )

    output: List[Phase3StrategicActionLineComparisonFacts] = []
    for current in current_lines:
        for counterline in counterlines:
            output.append(compare_pair(current, counterline))
        for drednaw in defensive_lines:
            output.append(compare_pair(current, drednaw))
        for stage2c in strategic_stage2c_lines:
            output.append(compare_pair(current, stage2c))
    for left, right in combinations(counterlines, 2):
        output.append(compare_pair(left, right))
    for counterline in counterlines:
        for drednaw in defensive_lines:
            output.append(compare_pair(counterline, drednaw))
        for stage2c in strategic_stage2c_lines:
            output.append(compare_pair(counterline, stage2c))
    for left, right in combinations(defensive_lines, 2):
        output.append(compare_pair(left, right))
    for drednaw in defensive_lines:
        for stage2c in strategic_stage2c_lines:
            output.append(compare_pair(drednaw, stage2c))
    for left, right in combinations(strategic_stage2c_lines, 2):
        output.append(compare_pair(left, right))
    return tuple(output)


def _action_line_comparison_candidates(
    selection_state: ActionLineBestAttackState,
    best_attack: Optional[DirectAttackShadowCandidate],
    candidates: Sequence[DirectAttackShadowCandidate],
) -> Tuple[DirectAttackShadowCandidate, ...]:
    if selection_state == ActionLineBestAttackState.SELECTED:
        return (best_attack,) if best_attack is not None else ()
    if selection_state == ActionLineBestAttackState.TIE:
        return tuple(candidates)
    return ()


def _cross_origin_action_line_comparison(
    *,
    left_origin: ActionLineOriginFacts,
    right_origin: ActionLineOriginFacts,
    left_selection_state: ActionLineBestAttackState,
    right_selection_state: ActionLineBestAttackState,
    left_best_attack: Optional[DirectAttackShadowCandidate],
    right_best_attack: Optional[DirectAttackShadowCandidate],
    left_candidates: Sequence[DirectAttackShadowCandidate],
    right_candidates: Sequence[DirectAttackShadowCandidate],
    left_supported: bool,
    right_supported: bool,
    left_exact: bool,
    right_exact: bool,
    left_unsupported_reason: Optional[str],
    right_unsupported_reason: Optional[str],
) -> CrossOriginActionLineComparisonFacts:
    def blocked(
        reason: str,
        comparison_reason: DirectAttackComparisonReason,
    ) -> CrossOriginActionLineComparisonFacts:
        return CrossOriginActionLineComparisonFacts(
            left_origin=left_origin,
            right_origin=right_origin,
            left_selection_state=left_selection_state,
            right_selection_state=right_selection_state,
            left_attack_candidates=(),
            right_attack_candidates=(),
            candidate_comparisons=(),
            relation=DirectAttackComparison.INCOMPARABLE,
            reason=comparison_reason,
            pairwise_reasons=(),
            supported=False,
            exact=False,
            unsupported_reason=reason,
        )

    if not left_supported:
        return blocked(
            left_unsupported_reason or "left_action_line_unsupported",
            DirectAttackComparisonReason.OVERALL_UNSUPPORTED,
        )
    if not right_supported:
        return blocked(
            right_unsupported_reason or "right_action_line_unsupported",
            DirectAttackComparisonReason.OVERALL_UNSUPPORTED,
        )
    if left_selection_state == ActionLineBestAttackState.INCOMPARABLE:
        return blocked(
            "left_action_line_best_incomparable",
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
        )
    if right_selection_state == ActionLineBestAttackState.INCOMPARABLE:
        return blocked(
            "right_action_line_best_incomparable",
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
        )
    if not left_exact:
        return blocked(
            "left_action_line_candidate_set_not_exact",
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
        )
    if not right_exact:
        return blocked(
            "right_action_line_candidate_set_not_exact",
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
        )

    left_set = _action_line_comparison_candidates(
        left_selection_state,
        left_best_attack,
        left_candidates,
    )
    right_set = _action_line_comparison_candidates(
        right_selection_state,
        right_best_attack,
        right_candidates,
    )
    if not left_set or not right_set:
        return blocked(
            "cross_origin_action_line_candidate_set_missing",
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION,
        )

    candidate_comparisons = tuple(
        CrossOriginActionLineCandidateComparisonFacts(
            left_candidate=left_candidate,
            right_candidate=right_candidate,
            result=compare_direct_attack_candidates(
                left_candidate,
                right_candidate,
            ),
        )
        for left_candidate in left_set
        for right_candidate in right_set
    )
    relations = {
        item.result.relation for item in candidate_comparisons
    }
    pairwise_reasons = tuple(
        item.result.reason for item in candidate_comparisons
    )
    if len(relations) != 1:
        return CrossOriginActionLineComparisonFacts(
            left_origin=left_origin,
            right_origin=right_origin,
            left_selection_state=left_selection_state,
            right_selection_state=right_selection_state,
            left_attack_candidates=left_set,
            right_attack_candidates=right_set,
            candidate_comparisons=candidate_comparisons,
            relation=DirectAttackComparison.INCOMPARABLE,
            reason=DirectAttackComparisonReason.CONFLICTING_ADVANTAGES,
            pairwise_reasons=pairwise_reasons,
            supported=True,
            exact=False,
            unsupported_reason=None,
        )

    relation = next(iter(relations))
    distinct_reasons = tuple(dict.fromkeys(pairwise_reasons))
    if len(distinct_reasons) == 1:
        aggregate_reason = distinct_reasons[0]
    elif relation in {
        DirectAttackComparison.LEFT_BETTER,
        DirectAttackComparison.RIGHT_BETTER,
    }:
        aggregate_reason = DirectAttackComparisonReason.SAFE_DOMINANCE
    elif relation == DirectAttackComparison.EQUIVALENT:
        aggregate_reason = (
            DirectAttackComparisonReason.SAME_CANONICAL_OUTCOME
        )
    else:
        aggregate_reason = (
            DirectAttackComparisonReason.INSUFFICIENT_INFORMATION
        )
    return CrossOriginActionLineComparisonFacts(
        left_origin=left_origin,
        right_origin=right_origin,
        left_selection_state=left_selection_state,
        right_selection_state=right_selection_state,
        left_attack_candidates=left_set,
        right_attack_candidates=right_set,
        candidate_comparisons=candidate_comparisons,
        relation=relation,
        reason=aggregate_reason,
        pairwise_reasons=pairwise_reasons,
        supported=True,
        exact=True,
        unsupported_reason=None,
    )


def phase3_action_line_comparison_foundation_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    prepared_bindings: Optional[
        Sequence[Phase3PreparedAttackBindingFacts]
    ] = None,
    current_line: Optional[CurrentActionLineOutcomeFacts] = None,
    prepared_lines: Optional[Sequence[ActionLineOutcomeFacts]] = None,
) -> Phase3ActionLineComparisonFoundationFacts:
    """Build a relation matrix only; never select a cross-origin winner."""
    results_tuple = tuple(results)
    current = (
        current_action_line_outcome_facts(board, results_tuple)
        if current_line is None
        else current_line
    )
    prepared = tuple(
        action_line_outcome_facts(
            board,
            results_tuple,
            prepared_bindings,
        )
        if prepared_lines is None
        else prepared_lines
    )

    def compare_current_prepared(
        line: ActionLineOutcomeFacts,
    ) -> CrossOriginActionLineComparisonFacts:
        return _cross_origin_action_line_comparison(
            left_origin=current.origin,
            right_origin=_prepared_action_line_origin(line),
            left_selection_state=current.selection_state,
            right_selection_state=line.selection_state,
            left_best_attack=current.best_attack,
            right_best_attack=line.best_attack,
            left_candidates=current.attack_candidates,
            right_candidates=line.attack_candidates,
            left_supported=current.supported,
            right_supported=line.supported,
            left_exact=current.state_exact,
            right_exact=line.virtual_state_exact,
            left_unsupported_reason=current.unsupported_reason,
            right_unsupported_reason=line.unsupported_reason,
        )

    def compare_prepared(
        left: ActionLineOutcomeFacts,
        right: ActionLineOutcomeFacts,
    ) -> CrossOriginActionLineComparisonFacts:
        return _cross_origin_action_line_comparison(
            left_origin=_prepared_action_line_origin(left),
            right_origin=_prepared_action_line_origin(right),
            left_selection_state=left.selection_state,
            right_selection_state=right.selection_state,
            left_best_attack=left.best_attack,
            right_best_attack=right.best_attack,
            left_candidates=left.attack_candidates,
            right_candidates=right.attack_candidates,
            left_supported=left.supported,
            right_supported=right.supported,
            left_exact=left.virtual_state_exact,
            right_exact=right.virtual_state_exact,
            left_unsupported_reason=left.unsupported_reason,
            right_unsupported_reason=right.unsupported_reason,
        )

    comparisons = tuple(
        compare_current_prepared(line) for line in prepared
    ) + tuple(
        compare_prepared(left, right)
        for left, right in combinations(prepared, 2)
    )
    return Phase3ActionLineComparisonFoundationFacts(
        current_line=current,
        prepared_lines=prepared,
        comparisons=comparisons,
    )



def _phase5_prepared_outcome_key(
    candidate: DirectAttackShadowCandidate,
) -> Tuple[Any, ...]:
    return (candidate.attack_id, candidate.facts)


def _phase5_select_prepared_candidate(
    candidates: Sequence[DirectAttackShadowCandidate],
) -> Tuple[Optional[DirectAttackShadowCandidate], str]:
    """Select with the existing comparator; never invent a new score."""
    exact_groups: Dict[Tuple[Any, ...], List[DirectAttackShadowCandidate]] = {}
    for candidate in candidates:
        exact_groups.setdefault(
            _phase5_prepared_outcome_key(candidate),
            [],
        ).append(candidate)
    representatives = tuple(group[0] for group in exact_groups.values())
    if not representatives:
        return None, "no_eligible_prepared_candidate"
    if len(representatives) == 1:
        return representatives[0], "single_prepared_outcome"

    reindexed = tuple(
        replace(candidate, option_index=index)
        for index, candidate in enumerate(representatives)
    )
    comparisons = tuple(
        compare_direct_attack_candidates(left, right)
        for left, right in combinations(reindexed, 2)
    )
    if comparisons and all(
        comparison.relation == DirectAttackComparison.EQUIVALENT
        for comparison in comparisons
    ):
        return representatives[0], "prepared_outcomes_equivalent"
    winner = unique_direct_attack_shadow_winner(
        reindexed,
        comparisons,
    )
    if winner is None:
        return None, "prepared_winner_unresolved"
    return representatives[winner.option_index], "unique_prepared_winner"


def phase5_confirmed_live_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    prepared_bindings: Optional[
        Sequence[Phase3PreparedAttackBindingFacts]
    ] = None,
) -> Phase5ConfirmedLiveFacts:
    bindings = tuple(
        phase5_same_observation_prepared_bindings(board, results)
        if prepared_bindings is None
        else prepared_bindings
    )
    phase3_facts = phase3_direct_attack_shadow_facts(
        board,
        results,
        bindings,
    )
    current_candidates = phase3_facts.current_candidates
    current_identity_reasons = tuple(
        reason
        for reason in phase3_facts.blocked_reasons
        if reason in {
            "current_attack_option_not_current",
            "current_attack_option_index_mismatch",
        }
    )

    def no_op(reason: str) -> Phase5ConfirmedLiveFacts:
        return Phase5ConfirmedLiveFacts(
            supported=False,
            current_candidates=current_candidates,
            prepared_bindings=bindings,
            phase3_facts=phase3_facts,
            eligible_origins=(),
            selected_origin_indices=(),
            selected_candidate=None,
            live_applied=False,
            no_op_reason=reason,
            reasons=(reason,),
        )

    if not current_candidates:
        return no_op("current_direct_attack_required")
    if current_identity_reasons:
        return no_op("current_direct_attack_identity_blocked")
    current_states = tuple(
        classify_direct_attack_candidate(candidate.facts)
        for candidate in current_candidates
    )
    if any(
        state != DirectAttackCandidateState.FULLY_KNOWN
        for state in current_states
    ):
        return no_op("current_direct_attack_not_fully_known")
    if any(
        candidate.facts.candidate_wins_game is True
        for candidate in current_candidates
    ):
        return no_op("current_direct_win_preserved")
    if any(
        candidate.facts.opponent_active_ko is True
        for candidate in current_candidates
    ):
        return no_op("current_direct_knockout_preserved")
    if any(
        (candidate.facts.immediate_prizes_taken or 0) > 0
        for candidate in current_candidates
    ):
        return no_op("current_direct_prize_gain_preserved")

    bindings_by_origin: Dict[int, List[Phase3PreparedAttackBindingFacts]] = {}
    for binding in phase3_facts.prepared_bindings:
        if type(binding.origin_option_index) is int:
            bindings_by_origin.setdefault(
                binding.origin_option_index,
                [],
            ).append(binding)

    origin_facts: List[Phase5ConfirmedPreparedOriginFacts] = []
    for origin_option_index in sorted(bindings_by_origin):
        origin_bindings = tuple(bindings_by_origin[origin_option_index])
        adapter_names = tuple(sorted({
            binding.adapter for binding in origin_bindings
        }))
        origin_comparisons = tuple(
            comparison
            for comparison in phase3_facts.comparisons
            if (
                comparison.prepared_binding.origin_option_index
                == origin_option_index
            )
        )
        reasons: List[str] = []
        prepared_candidates = tuple(
            binding.candidate
            for binding in origin_bindings
            if binding.candidate is not None
        )
        if origin_option_index in phase3_facts.origin_conflicts:
            origin_facts.append(Phase5ConfirmedPreparedOriginFacts(
                origin_option_index=origin_option_index,
                adapter_names=adapter_names,
                prepared_candidates=prepared_candidates,
                selected_candidate=None,
                current_comparisons=origin_comparisons,
                eligible=False,
                unsupported_reason="prepared_origin_adapter_conflict",
                reasons=("prepared_origin_adapter_conflict",),
            ))
            continue
        if (
            origin_option_index
            in phase3_facts.multiple_prepared_attack_origins
        ):
            origin_facts.append(Phase5ConfirmedPreparedOriginFacts(
                origin_option_index=origin_option_index,
                adapter_names=adapter_names,
                prepared_candidates=prepared_candidates,
                selected_candidate=None,
                current_comparisons=origin_comparisons,
                eligible=False,
                unsupported_reason="multiple_prepared_attacks_same_origin",
                reasons=("multiple_prepared_attacks_same_origin",),
            ))
            continue
        if len(adapter_names) != 1:
            origin_facts.append(Phase5ConfirmedPreparedOriginFacts(
                origin_option_index=origin_option_index,
                adapter_names=adapter_names,
                prepared_candidates=prepared_candidates,
                selected_candidate=None,
                current_comparisons=origin_comparisons,
                eligible=False,
                unsupported_reason="prepared_origin_adapter_conflict",
                reasons=("prepared_origin_adapter_conflict",),
            ))
            continue

        eligible_candidates: List[DirectAttackShadowCandidate] = []
        for binding in origin_bindings:
            candidate = binding.candidate
            if (
                not binding.supported
                or candidate is None
                or classify_direct_attack_candidate(candidate.facts)
                not in {
                    DirectAttackCandidateState.FULLY_KNOWN,
                    DirectAttackCandidateState.TERMINAL_WIN,
                }
            ):
                continue
            comparisons = tuple(
                comparison
                for comparison in origin_comparisons
                if comparison.prepared_binding == binding
            )
            if len(comparisons) != len(current_candidates):
                continue
            relations = tuple(
                comparison.result.relation
                for comparison in comparisons
            )
            if (
                all(
                    relation in {
                        DirectAttackComparison.RIGHT_BETTER,
                        DirectAttackComparison.EQUIVALENT,
                    }
                    for relation in relations
                )
                and DirectAttackComparison.RIGHT_BETTER in relations
            ):
                eligible_candidates.append(candidate)

        selected_candidate, selection_reason = (
            _phase5_select_prepared_candidate(eligible_candidates)
        )
        if selected_candidate is None:
            reasons.append(selection_reason)
        else:
            reasons.extend(("strict_safe_dominance", selection_reason))
        origin_facts.append(Phase5ConfirmedPreparedOriginFacts(
            origin_option_index=origin_option_index,
            adapter_names=adapter_names,
            prepared_candidates=prepared_candidates,
            selected_candidate=selected_candidate,
            current_comparisons=origin_comparisons,
            eligible=selected_candidate is not None,
            unsupported_reason=(
                None if selected_candidate is not None else selection_reason
            ),
            reasons=tuple(reasons),
        ))

    eligible_origins = tuple(
        facts for facts in origin_facts if facts.eligible
    )
    if not eligible_origins:
        return replace(
            no_op("no_confirmed_right_better_origin"),
            eligible_origins=tuple(origin_facts),
        )

    origins_by_outcome: Dict[
        Tuple[Any, ...],
        List[Phase5ConfirmedPreparedOriginFacts],
    ] = {}
    for origin in eligible_origins:
        origins_by_outcome.setdefault(
            _phase5_prepared_outcome_key(origin.selected_candidate),
            [],
        ).append(origin)
    outcome_representatives = tuple(
        origin_group[0].selected_candidate
        for origin_group in origins_by_outcome.values()
    )
    selected_candidate, global_reason = (
        _phase5_select_prepared_candidate(outcome_representatives)
    )
    if selected_candidate is None:
        return Phase5ConfirmedLiveFacts(
            supported=False,
            current_candidates=current_candidates,
            prepared_bindings=bindings,
            phase3_facts=phase3_facts,
            eligible_origins=tuple(origin_facts),
            selected_origin_indices=(),
            selected_candidate=None,
            live_applied=False,
            no_op_reason="global_prepared_winner_unresolved",
            reasons=(global_reason,),
        )
    selected_key = _phase5_prepared_outcome_key(selected_candidate)
    if global_reason == "prepared_outcomes_equivalent":
        selected_origin_indices = tuple(sorted(
            origin.origin_option_index
            for origin in eligible_origins
        ))
    else:
        selected_origin_indices = tuple(sorted(
            origin.origin_option_index
            for origin in origins_by_outcome[selected_key]
        ))
    return Phase5ConfirmedLiveFacts(
        supported=True,
        current_candidates=current_candidates,
        prepared_bindings=bindings,
        phase3_facts=phase3_facts,
        eligible_origins=tuple(origin_facts),
        selected_origin_indices=selected_origin_indices,
        selected_candidate=selected_candidate,
        live_applied=False,
        no_op_reason=None,
        reasons=("confirmed_phase3_right_better", global_reason),
    )


def apply_phase5_confirmed_live_results(
    board: BoardView,
    results: Sequence[SimulationResult],
) -> Tuple[Tuple[SimulationResult, ...], Phase5ConfirmedLiveFacts]:
    facts = phase5_confirmed_live_facts(board, results)
    if not facts.supported or facts.selected_candidate is None:
        return tuple(results), facts

    prepared = facts.selected_candidate.facts
    terminal_prepared = bool(
        prepared.candidate_wins_game is True
        or prepared.opponent_active_ko is True
        or (prepared.immediate_prizes_taken or 0) > 0
    )
    target_tier = (
        TIER_PRESERVE_WIN_OR_KO_PREP
        if terminal_prepared
        else TIER_HIGH_VALUE_PREP
    )
    target_immediate = (
        prepared.immediate_prizes_taken or 0
        if terminal_prepared
        else 0
    )
    target_pressure = prepared.confirmed_damage or 0
    selected_indices = set(facts.selected_origin_indices)
    changed = False
    updated: List[SimulationResult] = []
    for result in results:
        if result.index not in selected_indices:
            updated.append(result)
            continue
        current_score = result.action_score
        if current_score.tier > target_tier:
            updated.append(result)
            continue
        if (
            current_score.tier == target_tier
            and (current_score.immediate, current_score.pressure)
            >= (target_immediate, target_pressure)
        ):
            updated.append(result)
            continue
        updated.append(replace(
            result,
            action_score=replace(
                current_score,
                tier=target_tier,
                immediate=target_immediate,
                pressure=target_pressure,
            ),
        ))
        changed = True
    return tuple(updated), replace(facts, live_applied=changed)



def _stage2c_phase5_actionable_origin_index(
    board: BoardView,
    results: Sequence[SimulationResult],
    line: "Stage2cStrategicActionLineFacts",
) -> Tuple[Optional[int], Optional[str]]:
    """Bind one Stage2c strategic line to exactly one current SimulationResult."""
    index = line.origin_option_index
    if type(index) is not int:
        return None, "strategic_live_stage2c_origin_identity_unresolved"
    matches = tuple(
        result
        for result in results
        if type(result.index) is int and result.index == index
    )
    if len(matches) != 1:
        return None, "strategic_live_origin_not_current_result"
    option = matches[0].option
    if (
        line.origin_option_type is not None
        and getattr(option, "type", None) != line.origin_option_type
    ):
        return None, "strategic_live_stage2c_origin_identity_mismatch"
    if line.origin_option_card_id is not None:
        actual_card_id = board.option_card(option)
        if actual_card_id != line.origin_option_card_id:
            return None, "strategic_live_stage2c_origin_identity_mismatch"
    if (
        line.origin_target_card_id is not None
        or line.origin_target_serial is not None
    ):
        target = board.option_target(option)
        if target is None:
            return None, "strategic_live_stage2c_origin_identity_mismatch"
        if (
            line.origin_target_card_id is not None
            and board.pid(target) != line.origin_target_card_id
        ):
            return None, "strategic_live_stage2c_origin_identity_mismatch"
        if (
            line.origin_target_serial is not None
            and getattr(target, "serial", None) != line.origin_target_serial
        ):
            return None, "strategic_live_stage2c_origin_identity_mismatch"
    return index, None

def phase5_strategic_live_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    policy: Any,
    *,
    current_position: Optional[ActivePositionCurrentLineCollectionFacts] = None,
    counterline_collections: Optional[
        Sequence[Stage2b4CounterlineActionLineCollectionFacts]
    ] = None,
    drednaw_lines: Optional[Sequence[DrednawDefensiveActionLineFacts]] = None,
    bomb_preservations: Optional[
        Sequence[DeluxeBombResourcePreservationFacts]
    ] = None,
    comparisons: Optional[
        Sequence[Phase3StrategicActionLineComparisonFacts]
    ] = None,
    stage2c_lines: Optional[
        Sequence["Stage2cStrategicActionLineFacts"]
    ] = None,
) -> Phase5StrategicLiveFacts:
    """Connect only exact Strategic Phase3 dominance to current-action origins."""
    source_results = tuple(results)
    current = (
        active_position_current_line_facts(board, source_results)
        if current_position is None
        else current_position
    )
    counter_collections = tuple(
        stage2b4_counterline_action_line_collections(policy)
        if counterline_collections is None
        else counterline_collections
    )
    if drednaw_lines is None:
        strategy = drednaw_high_power_strategy_facts(board)
        defensive_lines = tuple(
            drednaw_defensive_action_line_facts(strategy, current, ())
        )
    else:
        defensive_lines = tuple(drednaw_lines)
    if bomb_preservations is None:
        preservation_facts: List[DeluxeBombResourcePreservationFacts] = []
        for collection in counter_collections:
            siblings = tuple(collection.routes)
            for route in siblings:
                if not any(
                    step.option_card_id == DELUXE_BOMB
                    for step in route.action_steps
                ):
                    continue
                preservation_facts.append(
                    deluxe_bomb_resource_preservation_facts(
                        current,
                        route,
                        siblings,
                    )
                )
        preservations = tuple(preservation_facts)
    else:
        preservations = tuple(bomb_preservations)

    if stage2c_lines is not None:
        strategic_stage2c_lines = tuple(stage2c_lines)
    elif comparisons is not None:
        extracted_stage2c_lines: List[Stage2cStrategicActionLineFacts] = []
        seen_stage2c_line_ids: set[int] = set()
        for comparison in comparisons:
            for candidate_line in (comparison.left_line, comparison.right_line):
                if not isinstance(candidate_line, Stage2cStrategicActionLineFacts):
                    continue
                candidate_identity = id(candidate_line)
                if candidate_identity in seen_stage2c_line_ids:
                    continue
                seen_stage2c_line_ids.add(candidate_identity)
                extracted_stage2c_lines.append(candidate_line)
        strategic_stage2c_lines = tuple(extracted_stage2c_lines)
    else:
        stage2c_collection = stage2c_strategic_action_line_collection_facts(
            policy,
            source_results,
            current_position=current,
            counterline_collections=counter_collections,
        )
        strategic_stage2c_lines = tuple(stage2c_collection.lines)

    matrix = tuple(
        phase3_strategic_action_line_comparison_matrix_facts(
            current,
            counter_collections,
            defensive_lines,
            preservations,
            strategic_stage2c_lines,
        )
        if comparisons is None
        else comparisons
    )

    def no_op(
        reason: str,
        *,
        eligible: Sequence[int] = (),
        blocked: Sequence[int] = (),
    ) -> Phase5StrategicLiveFacts:
        return Phase5StrategicLiveFacts(
            current_position=current,
            counterline_collections=counter_collections,
            drednaw_lines=defensive_lines,
            comparisons=matrix,
            eligible_origin_indices=tuple(eligible),
            selected_origin_indices=(),
            blocked_origin_indices=tuple(blocked),
            supported=False,
            live_applied=False,
            no_op_reason=reason,
            reasons=("phase5_strategic_live", reason),
        )

    if (
        not current.supported
        or not current.exact
        or not current.candidate_lines
    ):
        return no_op("strategic_live_current_position_not_exact")
    if any(
        not line.supported or not line.exact
        for line in current.candidate_lines
    ):
        return no_op("strategic_live_current_candidate_not_exact")
    if any(line.terminal_win is True for line in current.candidate_lines):
        return no_op("strategic_live_current_terminal_win_preserved")

    result_counts: Dict[int, int] = {}
    for result in source_results:
        if type(result.index) is int:
            result_counts[result.index] = result_counts.get(result.index, 0) + 1

    def scenario_identity(line: Any) -> Optional[Tuple[int, int, int]]:
        if isinstance(line, ActivePositionCurrentAttackLineFacts):
            reply = line.counterline_attack_facts
            values = (
                None if reply is None else reply.opponent_active_id,
                None if reply is None else reply.opponent_active_serial,
                None if reply is None else reply.attack_id,
            )
        elif isinstance(line, Stage2b4CounterlineActionLineFacts):
            values = (
                line.opponent_attacker_card_id,
                line.opponent_attacker_serial,
                line.opponent_attack_id,
            )
        elif isinstance(line, DrednawDefensiveActionLineFacts):
            values = (
                line.strategy.opponent_active_id,
                line.strategy.opponent_active_serial,
                line.opponent_attack.attack_id,
            )
        elif isinstance(line, Stage2cStrategicActionLineFacts):
            exact_current_lines = tuple(
                current_line
                for current_line in line.current_attack_lines
                if current_line.supported and current_line.exact
            )
            if not exact_current_lines:
                return None
            scenarios = tuple(
                scenario_identity(current_line)
                for current_line in exact_current_lines
            )
            if any(scenario is None for scenario in scenarios):
                return None
            unique_scenarios = tuple(dict.fromkeys(scenarios))
            if len(unique_scenarios) != 1:
                return None
            return unique_scenarios[0]
        else:
            return None
        if not all(type(value) is int for value in values):
            return None
        return values  # type: ignore[return-value]

    def stage2c_safe_rank_payload(
        line: Stage2cStrategicActionLineFacts,
    ) -> Optional[Tuple[int, int]]:
        if (
            not line.supported
            or not line.exact
            or line.action_line_kind
            != Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY
            or line.continuation_confirmed is not True
            or line.attack_preserved_after_origin is not True
            or line.current_attack_is_nonwinning_ko is not True
            or line.current_direct_win_exists is not False
            or not line.current_attack_lines
        ):
            return None
        payloads: List[Tuple[int, int]] = []
        for current_line in line.current_attack_lines:
            outcome = current_line.generic_outcome_facts
            if (
                not current_line.supported
                or not current_line.exact
                or current_line.terminal_win is not False
                or current_line.opponent_active_ko is not True
                or outcome is None
                or not outcome.supported
                or outcome.candidate_wins_game is not False
                or outcome.opponent_active_ko is not True
                or type(outcome.immediate_prizes_taken) is not int
                or type(outcome.confirmed_damage) is not int
            ):
                return None
            payloads.append(
                (
                    outcome.immediate_prizes_taken,
                    outcome.confirmed_damage,
                )
            )
        unique_payloads = tuple(dict.fromkeys(payloads))
        if len(unique_payloads) != 1:
            return None
        return unique_payloads[0]

    result_by_index = {
        result.index: result
        for result in source_results
        if type(result.index) is int and result_counts.get(result.index, 0) == 1
    }

    def actionable_origin_index(
        line: Any,
    ) -> Tuple[Optional[int], Optional[str]]:
        if isinstance(line, Stage2b4CounterlineActionLineFacts):
            index = line.origin_option_index
            if type(index) is not int:
                return None, "strategic_live_origin_identity_unresolved"
        elif isinstance(line, DrednawDefensiveActionLineFacts):
            if line.origin.kind == ActionLineOriginKind.CURRENT_BOARD:
                return None, "strategic_live_current_board_non_actionable"
            if line.origin.kind != ActionLineOriginKind.PREPARED_ACTION:
                return None, "strategic_live_origin_identity_unresolved"
            origin_index = line.origin.option_index
            transition_index: Optional[int] = None
            if line.transition is not None:
                binding = line.transition.origin_binding
                if not binding.supported or not binding.binding_exact:
                    return None, "strategic_live_drednaw_transition_origin_inexact"
                transition_index = binding.origin_decision_option_index
            known_indices = tuple(
                value
                for value in (origin_index, transition_index)
                if type(value) is int
            )
            if not known_indices:
                return None, "strategic_live_drednaw_origin_unresolved"
            if len(set(known_indices)) != 1:
                return None, "strategic_live_origin_identity_mismatch"
            index = known_indices[0]
        elif isinstance(line, Stage2cStrategicActionLineFacts):
            index, stage2c_origin_reason = _stage2c_phase5_actionable_origin_index(
                board,
                source_results,
                line,
            )
            if index is None:
                return None, stage2c_origin_reason
            if (
                line.action_line_kind
                == Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY
                and stage2c_safe_rank_payload(line) is None
            ):
                return None, "strategic_live_stage2c_rank_payload_unresolved"
        else:
            return None, "strategic_live_non_actionable_line"
        if result_counts.get(index, 0) != 1:
            return None, "strategic_live_origin_not_current_result"
        return index, None

    strategic_lines = tuple(
        route
        for collection in counter_collections
        for route in collection.routes
    ) + defensive_lines + strategic_stage2c_lines
    origin_lines: Dict[int, List[Any]] = {}
    blocked_indices: List[int] = []
    for line in strategic_lines:
        index, origin_reason = actionable_origin_index(line)
        if index is None:
            if (
                origin_reason == "strategic_live_origin_identity_mismatch"
                and isinstance(line, DrednawDefensiveActionLineFacts)
            ):
                for candidate in (
                    line.origin.option_index,
                    None
                    if line.transition is None
                    else line.transition.origin_binding.origin_decision_option_index,
                ):
                    if type(candidate) is int and candidate not in blocked_indices:
                        blocked_indices.append(candidate)
            elif isinstance(line, Stage2cStrategicActionLineFacts):
                candidate = line.origin_option_index
                if type(candidate) is int and candidate not in blocked_indices:
                    blocked_indices.append(candidate)
            continue
        origin_lines.setdefault(index, []).append(line)

    def comparison_for_pair(
        left_line: Any,
        right_line: Any,
    ) -> Tuple[Phase3StrategicActionLineComparisonFacts, ...]:
        return tuple(
            comparison
            for comparison in matrix
            if (
                comparison.left_line is left_line
                and comparison.right_line is right_line
            )
            or (
                comparison.left_line is right_line
                and comparison.right_line is left_line
            )
        )

    def relation_from_line(
        comparison: Phase3StrategicActionLineComparisonFacts,
        line: Any,
    ) -> Optional[DirectAttackComparison]:
        if not comparison.supported or not comparison.exact:
            return None
        if comparison.left_line is line:
            return comparison.relation
        if comparison.right_line is line:
            if comparison.relation == DirectAttackComparison.LEFT_BETTER:
                return DirectAttackComparison.RIGHT_BETTER
            if comparison.relation == DirectAttackComparison.RIGHT_BETTER:
                return DirectAttackComparison.LEFT_BETTER
            return comparison.relation
        return None

    current_scenarios = tuple(
        scenario_identity(line) for line in current.candidate_lines
    )
    if any(scenario is None for scenario in current_scenarios):
        return no_op(
            "strategic_live_current_scenario_identity_unresolved",
            blocked=blocked_indices,
        )

    current_drednaw_baselines = tuple(
        line
        for line in defensive_lines
        if (
            line.supported
            and line.exact
            and line.origin.kind == ActionLineOriginKind.CURRENT_BOARD
            and scenario_identity(line) is not None
        )
    )

    eligible_indices: List[int] = []
    for origin_index, lines_for_origin in origin_lines.items():
        exact_lines = tuple(
            line
            for line in lines_for_origin
            if line.supported and line.exact and scenario_identity(line) is not None
        )
        if not exact_lines:
            continue
        strict_better = False
        origin_safe = True
        for current_line in current.candidate_lines:
            scenario = scenario_identity(current_line)
            candidates = tuple(
                line for line in exact_lines if scenario_identity(line) == scenario
            )
            covered = False
            for strategic_line in candidates:
                for comparison in comparison_for_pair(current_line, strategic_line):
                    relation = relation_from_line(comparison, strategic_line)
                    if relation in {
                        DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparison.EQUIVALENT,
                    }:
                        covered = True
                        strict_better = strict_better or (
                            relation == DirectAttackComparison.LEFT_BETTER
                        )
                        break
                if covered:
                    break
            if not covered:
                origin_safe = False
                break
        if not origin_safe or not strict_better:
            continue

        baseline_safe = True
        for baseline in current_drednaw_baselines:
            scenario = scenario_identity(baseline)
            candidates = tuple(
                line for line in exact_lines if scenario_identity(line) == scenario
            )
            no_worse = False
            for strategic_line in candidates:
                if strategic_line is baseline:
                    no_worse = True
                    break
                for comparison in comparison_for_pair(baseline, strategic_line):
                    relation = relation_from_line(comparison, strategic_line)
                    if relation in {
                        DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparison.EQUIVALENT,
                    }:
                        no_worse = True
                        break
                if no_worse:
                    break
            if not no_worse:
                baseline_safe = False
                break
        if baseline_safe:
            eligible_indices.append(origin_index)

    eligible_tuple = tuple(eligible_indices)
    if not eligible_tuple:
        return no_op(
            "no_safe_strategic_origin",
            blocked=blocked_indices,
        )
    if len(eligible_tuple) == 1:
        return Phase5StrategicLiveFacts(
            current_position=current,
            counterline_collections=counter_collections,
            drednaw_lines=defensive_lines,
            comparisons=matrix,
            eligible_origin_indices=eligible_tuple,
            selected_origin_indices=eligible_tuple,
            blocked_origin_indices=tuple(blocked_indices),
            supported=True,
            live_applied=False,
            no_op_reason=None,
            reasons=(
                "phase5_strategic_live",
                "unique_safe_strategic_origin",
            ),
        )

    scenarios = tuple(dict.fromkeys(current_scenarios))

    def origin_pair_relation(left_index: int, right_index: int) -> str:
        left_lines = tuple(
            line
            for line in origin_lines[left_index]
            if line.supported and line.exact
        )
        right_lines = tuple(
            line
            for line in origin_lines[right_index]
            if line.supported and line.exact
        )
        any_strict_left = False
        any_strict_right = False
        all_left_no_worse = True
        all_right_no_worse = True
        for scenario in scenarios:
            scenario_comparisons: List[
                Tuple[Phase3StrategicActionLineComparisonFacts, Any, Any]
            ] = []
            for left_line in left_lines:
                if scenario_identity(left_line) != scenario:
                    continue
                for right_line in right_lines:
                    if scenario_identity(right_line) != scenario:
                        continue
                    for comparison in comparison_for_pair(left_line, right_line):
                        scenario_comparisons.append(
                            (comparison, left_line, right_line)
                        )
            if not scenario_comparisons:
                return "CONFLICT"
            for comparison, left_line, right_line in scenario_comparisons:
                left_relation = relation_from_line(comparison, left_line)
                right_relation = relation_from_line(comparison, right_line)
                if left_relation not in {
                    DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparison.EQUIVALENT,
                }:
                    all_left_no_worse = False
                if right_relation not in {
                    DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparison.EQUIVALENT,
                }:
                    all_right_no_worse = False
                any_strict_left = any_strict_left or (
                    left_relation == DirectAttackComparison.LEFT_BETTER
                )
                any_strict_right = any_strict_right or (
                    right_relation == DirectAttackComparison.LEFT_BETTER
                )
        if all_left_no_worse and any_strict_left:
            return "LEFT_BETTER"
        if all_right_no_worse and any_strict_right:
            return "RIGHT_BETTER"
        if all_left_no_worse and all_right_no_worse:
            return "EQUIVALENT"
        return "CONFLICT"

    pair_relations: Dict[Tuple[int, int], str] = {}
    for left_pos, left_index in enumerate(eligible_tuple):
        for right_index in eligible_tuple[left_pos + 1:]:
            pair_relations[(left_index, right_index)] = origin_pair_relation(
                left_index,
                right_index,
            )

    def relation_for_origin(left_index: int, right_index: int) -> str:
        if left_index == right_index:
            return "EQUIVALENT"
        if (left_index, right_index) in pair_relations:
            return pair_relations[(left_index, right_index)]
        relation = pair_relations.get((right_index, left_index), "CONFLICT")
        if relation == "LEFT_BETTER":
            return "RIGHT_BETTER"
        if relation == "RIGHT_BETTER":
            return "LEFT_BETTER"
        return relation

    winners = tuple(
        origin_index
        for origin_index in eligible_tuple
        if all(
            relation_for_origin(origin_index, other) in {
                "LEFT_BETTER",
                "EQUIVALENT",
            }
            for other in eligible_tuple
            if other != origin_index
        )
    )
    if not winners:
        safe_frontier_lines: Dict[
            int, Tuple[Stage2cStrategicActionLineFacts, ...]
        ] = {}
        safe_frontier_payloads: Dict[int, Tuple[int, int]] = {}
        safe_frontier_valid = True
        for origin_index in eligible_tuple:
            safe_lines = tuple(
                line
                for line in origin_lines[origin_index]
                if (
                    isinstance(line, Stage2cStrategicActionLineFacts)
                    and line.supported
                    and line.exact
                    and line.action_line_kind
                    == Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY
                    and _stage2c_phase5_actionable_origin_index(
                        board,
                        source_results,
                        line,
                    )[0]
                    == origin_index
                    and scenario_identity(line) is not None
                    and stage2c_safe_rank_payload(line) is not None
                )
            )
            if not safe_lines:
                safe_frontier_valid = False
                break

            strict_better = False
            for current_line in current.candidate_lines:
                scenario = scenario_identity(current_line)
                covered = False
                for safe_line in safe_lines:
                    if scenario_identity(safe_line) != scenario:
                        continue
                    for comparison in comparison_for_pair(current_line, safe_line):
                        relation = relation_from_line(comparison, safe_line)
                        if relation in {
                            DirectAttackComparison.LEFT_BETTER,
                            DirectAttackComparison.EQUIVALENT,
                        }:
                            covered = True
                            strict_better = strict_better or (
                                relation == DirectAttackComparison.LEFT_BETTER
                            )
                            break
                    if covered:
                        break
                if not covered:
                    safe_frontier_valid = False
                    break
            if not safe_frontier_valid or not strict_better:
                safe_frontier_valid = False
                break

            payloads = tuple(dict.fromkeys(
                stage2c_safe_rank_payload(line)
                for line in safe_lines
            ))
            if (
                len(payloads) != 1
                or payloads[0] is None
            ):
                safe_frontier_valid = False
                break
            safe_frontier_lines[origin_index] = safe_lines
            safe_frontier_payloads[origin_index] = payloads[0]

        if safe_frontier_valid:
            frontier_payloads = tuple(dict.fromkeys(
                safe_frontier_payloads[index]
                for index in eligible_tuple
            ))
            if len(frontier_payloads) != 1:
                safe_frontier_valid = False

        if safe_frontier_valid:
            for left_pos, left_index in enumerate(eligible_tuple):
                for right_index in eligible_tuple[left_pos + 1:]:
                    left_lines = safe_frontier_lines[left_index]
                    right_lines = safe_frontier_lines[right_index]
                    for scenario in scenarios:
                        sibling_relations: List[DirectAttackComparison] = []
                        for left_line in left_lines:
                            if scenario_identity(left_line) != scenario:
                                continue
                            for right_line in right_lines:
                                if scenario_identity(right_line) != scenario:
                                    continue
                                for comparison in comparison_for_pair(
                                    left_line,
                                    right_line,
                                ):
                                    left_relation = relation_from_line(
                                        comparison,
                                        left_line,
                                    )
                                    if left_relation is not None:
                                        sibling_relations.append(left_relation)
                        if (
                            not sibling_relations
                            or any(
                                relation not in {
                                    DirectAttackComparison.EQUIVALENT,
                                    DirectAttackComparison.INCOMPARABLE,
                                }
                                for relation in sibling_relations
                            )
                        ):
                            safe_frontier_valid = False
                            break
                    if not safe_frontier_valid:
                        break
                if not safe_frontier_valid:
                    break

        if safe_frontier_valid:
            return Phase5StrategicLiveFacts(
                current_position=current,
                counterline_collections=counter_collections,
                drednaw_lines=defensive_lines,
                comparisons=matrix,
                eligible_origin_indices=eligible_tuple,
                selected_origin_indices=eligible_tuple,
                blocked_origin_indices=tuple(blocked_indices),
                supported=True,
                live_applied=False,
                no_op_reason=None,
                reasons=(
                    "phase5_strategic_live",
                    "safe_pre_ko_multi_origin_frontier",
                ),
            )

        hand_frontier_lines: Dict[
            int, Tuple[Stage2cStrategicActionLineFacts, ...]
        ] = {}
        hand_frontier_valid = True
        for origin_index in eligible_tuple:
            hand_lines = tuple(
                line
                for line in origin_lines[origin_index]
                if (
                    isinstance(line, Stage2cStrategicActionLineFacts)
                    and line.supported
                    and line.exact
                    and line.action_line_kind
                    == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT
                    and _stage2c_phase5_actionable_origin_index(
                        board, source_results, line
                    )[0]
                    == origin_index
                    and scenario_identity(line) is not None
                    and type(line.bench_space_before) is int
                    and line.bench_space_before > 1
                )
            )
            if not hand_lines:
                hand_frontier_valid = False
                break

            strict_better = False
            for current_line in current.candidate_lines:
                scenario = scenario_identity(current_line)
                covered = False
                for hand_line in hand_lines:
                    if scenario_identity(hand_line) != scenario:
                        continue
                    for comparison in comparison_for_pair(current_line, hand_line):
                        relation = relation_from_line(comparison, hand_line)
                        if relation in {
                            DirectAttackComparison.LEFT_BETTER,
                            DirectAttackComparison.EQUIVALENT,
                        }:
                            covered = True
                            strict_better = strict_better or (
                                relation == DirectAttackComparison.LEFT_BETTER
                            )
                            break
                    if covered:
                        break
                if not covered:
                    hand_frontier_valid = False
                    break
            if not hand_frontier_valid or not strict_better:
                hand_frontier_valid = False
                break
            hand_frontier_lines[origin_index] = hand_lines

        if hand_frontier_valid:
            for left_pos, left_index in enumerate(eligible_tuple):
                for right_index in eligible_tuple[left_pos + 1:]:
                    left_lines = hand_frontier_lines[left_index]
                    right_lines = hand_frontier_lines[right_index]
                    for scenario in scenarios:
                        sibling_relations: List[DirectAttackComparison] = []
                        for left_line in left_lines:
                            if scenario_identity(left_line) != scenario:
                                continue
                            for right_line in right_lines:
                                if scenario_identity(right_line) != scenario:
                                    continue
                                for comparison in comparison_for_pair(
                                    left_line, right_line
                                ):
                                    left_relation = relation_from_line(
                                        comparison, left_line
                                    )
                                    if left_relation is not None:
                                        sibling_relations.append(left_relation)
                        if (
                            not sibling_relations
                            or any(
                                relation not in {
                                    DirectAttackComparison.EQUIVALENT,
                                    DirectAttackComparison.INCOMPARABLE,
                                }
                                for relation in sibling_relations
                            )
                        ):
                            hand_frontier_valid = False
                            break
                    if not hand_frontier_valid:
                        break
                if not hand_frontier_valid:
                    break

        if hand_frontier_valid:
            return Phase5StrategicLiveFacts(
                current_position=current,
                counterline_collections=counter_collections,
                drednaw_lines=defensive_lines,
                comparisons=matrix,
                eligible_origin_indices=eligible_tuple,
                selected_origin_indices=eligible_tuple,
                blocked_origin_indices=tuple(blocked_indices),
                supported=True,
                live_applied=False,
                no_op_reason=None,
                reasons=(
                    "phase5_strategic_live",
                    "stage2c_hand_basic_multi_origin_frontier",
                ),
            )

        evolution_frontier_lines: Dict[
            int, Tuple[Stage2cStrategicActionLineFacts, ...]
        ] = {}
        evolution_frontier_valid = True
        for origin_index in eligible_tuple:
            evolution_lines = tuple(
                line
                for line in origin_lines[origin_index]
                if (
                    isinstance(line, Stage2cStrategicActionLineFacts)
                    and line.supported
                    and line.exact
                    and line.action_line_kind
                    == Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION
                    and line.evolution_relation_exact is True
                    and line.continuation_confirmed is True
                    and line.attack_preserved_after_origin is True
                    and _stage2c_phase5_actionable_origin_index(
                        board, source_results, line
                    )[0]
                    == origin_index
                    and scenario_identity(line) is not None
                )
            )
            if not evolution_lines:
                evolution_frontier_valid = False
                break

            strict_better = False
            for current_line in current.candidate_lines:
                scenario = scenario_identity(current_line)
                covered = False
                for evolution_line in evolution_lines:
                    if scenario_identity(evolution_line) != scenario:
                        continue
                    for comparison in comparison_for_pair(
                        current_line, evolution_line
                    ):
                        relation = relation_from_line(comparison, evolution_line)
                        if relation in {
                            DirectAttackComparison.LEFT_BETTER,
                            DirectAttackComparison.EQUIVALENT,
                        }:
                            covered = True
                            strict_better = strict_better or (
                                relation == DirectAttackComparison.LEFT_BETTER
                            )
                            break
                    if covered:
                        break
                if not covered:
                    evolution_frontier_valid = False
                    break
            if not evolution_frontier_valid or not strict_better:
                evolution_frontier_valid = False
                break
            evolution_frontier_lines[origin_index] = evolution_lines

        if evolution_frontier_valid:
            for left_pos, left_index in enumerate(eligible_tuple):
                for right_index in eligible_tuple[left_pos + 1:]:
                    left_lines = evolution_frontier_lines[left_index]
                    right_lines = evolution_frontier_lines[right_index]
                    for scenario in scenarios:
                        sibling_relations: List[DirectAttackComparison] = []
                        for left_line in left_lines:
                            if scenario_identity(left_line) != scenario:
                                continue
                            for right_line in right_lines:
                                if scenario_identity(right_line) != scenario:
                                    continue
                                for comparison in comparison_for_pair(
                                    left_line, right_line
                                ):
                                    left_relation = relation_from_line(
                                        comparison, left_line
                                    )
                                    if left_relation is not None:
                                        sibling_relations.append(left_relation)
                        if (
                            not sibling_relations
                            or any(
                                relation not in {
                                    DirectAttackComparison.EQUIVALENT,
                                    DirectAttackComparison.INCOMPARABLE,
                                }
                                for relation in sibling_relations
                            )
                        ):
                            evolution_frontier_valid = False
                            break
                    if not evolution_frontier_valid:
                        break
                if not evolution_frontier_valid:
                    break

        if evolution_frontier_valid:
            return Phase5StrategicLiveFacts(
                current_position=current,
                counterline_collections=counter_collections,
                drednaw_lines=defensive_lines,
                comparisons=matrix,
                eligible_origin_indices=eligible_tuple,
                selected_origin_indices=eligible_tuple,
                blocked_origin_indices=tuple(blocked_indices),
                supported=True,
                live_applied=False,
                no_op_reason=None,
                reasons=(
                    "phase5_strategic_live",
                    "stage2c_evolution_multi_origin_frontier",
                ),
            )

        return no_op(
            "global_strategic_winner_unresolved",
            eligible=eligible_tuple,
            blocked=blocked_indices,
        )
    if any(
        relation_for_origin(left, right) != "EQUIVALENT"
        for pos, left in enumerate(winners)
        for right in winners[pos + 1:]
    ):
        return no_op(
            "global_strategic_winner_unresolved",
            eligible=eligible_tuple,
            blocked=blocked_indices,
        )
    return Phase5StrategicLiveFacts(
        current_position=current,
        counterline_collections=counter_collections,
        drednaw_lines=defensive_lines,
        comparisons=matrix,
        eligible_origin_indices=eligible_tuple,
        selected_origin_indices=winners,
        blocked_origin_indices=tuple(blocked_indices),
        supported=True,
        live_applied=False,
        no_op_reason=None,
        reasons=(
            "phase5_strategic_live",
            "safe_global_strategic_selection",
        ),
    )


def apply_phase5_strategic_live_results(
    board: BoardView,
    results: Sequence[SimulationResult],
    policy: Any,
) -> Tuple[Tuple[SimulationResult, ...], Phase5StrategicLiveFacts]:
    facts = phase5_strategic_live_facts(board, results, policy)
    if not facts.supported or not facts.selected_origin_indices:
        return tuple(results), facts
    selected_indices = set(facts.selected_origin_indices)

    def relation_from_line(
        comparison: Phase3StrategicActionLineComparisonFacts,
        line: Any,
    ) -> Optional[DirectAttackComparison]:
        if not comparison.supported or not comparison.exact:
            return None
        if comparison.left_line is line:
            return comparison.relation
        if comparison.right_line is line:
            if comparison.relation == DirectAttackComparison.LEFT_BETTER:
                return DirectAttackComparison.RIGHT_BETTER
            if comparison.relation == DirectAttackComparison.RIGHT_BETTER:
                return DirectAttackComparison.LEFT_BETTER
            return comparison.relation
        return None

    def comparisons_for_pair(
        left_line: Any,
        right_line: Any,
    ) -> Tuple[Phase3StrategicActionLineComparisonFacts, ...]:
        return tuple(
            comparison
            for comparison in facts.comparisons
            if (
                comparison.left_line is left_line
                and comparison.right_line is right_line
            )
            or (
                comparison.left_line is right_line
                and comparison.right_line is left_line
            )
        )

    def stage2c_rank_payload(
        line: Stage2cStrategicActionLineFacts,
    ) -> Optional[Tuple[int, int]]:
        if (
            not line.supported
            or not line.exact
            or line.action_line_kind
            != Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY
            or line.continuation_confirmed is not True
            or line.attack_preserved_after_origin is not True
            or line.current_attack_is_nonwinning_ko is not True
            or line.current_direct_win_exists is not False
            or not line.current_attack_lines
        ):
            return None
        payloads: List[Tuple[int, int]] = []
        for current_line in line.current_attack_lines:
            outcome = current_line.generic_outcome_facts
            if (
                not current_line.supported
                or not current_line.exact
                or current_line.terminal_win is not False
                or current_line.opponent_active_ko is not True
                or outcome is None
                or not outcome.supported
                or outcome.candidate_wins_game is not False
                or outcome.opponent_active_ko is not True
                or type(outcome.immediate_prizes_taken) is not int
                or type(outcome.confirmed_damage) is not int
            ):
                return None
            payloads.append(
                (
                    outcome.immediate_prizes_taken,
                    outcome.confirmed_damage,
                )
            )
        unique_payloads = tuple(dict.fromkeys(payloads))
        if len(unique_payloads) != 1:
            return None
        return unique_payloads[0]

    stage2c_lines: List[Stage2cStrategicActionLineFacts] = []
    seen_stage2c_line_ids: set[int] = set()
    for comparison in facts.comparisons:
        for candidate_line in (comparison.left_line, comparison.right_line):
            if not isinstance(candidate_line, Stage2cStrategicActionLineFacts):
                continue
            candidate_identity = id(candidate_line)
            if candidate_identity in seen_stage2c_line_ids:
                continue
            seen_stage2c_line_ids.add(candidate_identity)
            stage2c_lines.append(candidate_line)

    safe_payload_by_origin: Dict[int, Tuple[int, int]] = {}
    high_value_prep_authority_origins: set[int] = set()
    stronger_authority_origins: set[int] = set()

    def line_has_current_coverage(line: Any) -> bool:
        strict_better = False
        for current_line in facts.current_position.candidate_lines:
            covered = False
            for comparison in comparisons_for_pair(current_line, line):
                relation = relation_from_line(comparison, line)
                if relation in {
                    DirectAttackComparison.LEFT_BETTER,
                    DirectAttackComparison.EQUIVALENT,
                }:
                    covered = True
                    strict_better = strict_better or (
                        relation == DirectAttackComparison.LEFT_BETTER
                    )
                    break
            if not covered:
                return False
        return strict_better

    for origin_index in facts.selected_origin_indices:
        for stage2c_line in stage2c_lines:
            if stage2c_line.origin_option_index != origin_index:
                continue
            actionable_index, _ = _stage2c_phase5_actionable_origin_index(
                board, results, stage2c_line
            )
            if actionable_index != origin_index or not line_has_current_coverage(stage2c_line):
                continue
            if stage2c_line.action_line_kind in {
                Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT,
                Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION,
            }:
                high_value_prep_authority_origins.add(origin_index)
            else:
                stronger_authority_origins.add(origin_index)

        if any(
            route.origin_option_index == origin_index
            and route.supported
            and route.exact
            and line_has_current_coverage(route)
            for collection in facts.counterline_collections
            for route in collection.routes
        ) or any(
            (
                line.origin.option_index == origin_index
                or (
                    line.transition is not None
                    and line.transition.origin_binding.origin_decision_option_index
                    == origin_index
                )
            )
            and line.supported
            and line.exact
            and line_has_current_coverage(line)
            for line in facts.drednaw_lines
        ):
            stronger_authority_origins.add(origin_index)

    for origin_index in facts.selected_origin_indices:
        exact_payloads: List[Tuple[int, int]] = []
        for stage2c_line in stage2c_lines:
            if (
                stage2c_line.origin_option_index != origin_index
                or stage2c_line.action_line_kind
                != Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY
            ):
                continue
            actionable_index, _ = _stage2c_phase5_actionable_origin_index(
                board,
                results,
                stage2c_line,
            )
            if actionable_index != origin_index:
                continue
            strict_better = False
            covers_all_current = True
            for current_line in facts.current_position.candidate_lines:
                covered = False
                for comparison in comparisons_for_pair(current_line, stage2c_line):
                    relation = relation_from_line(comparison, stage2c_line)
                    if relation in {
                        DirectAttackComparison.LEFT_BETTER,
                        DirectAttackComparison.EQUIVALENT,
                    }:
                        covered = True
                        strict_better = strict_better or (
                            relation == DirectAttackComparison.LEFT_BETTER
                        )
                        break
                if not covered:
                    covers_all_current = False
                    break
            if not covers_all_current or not strict_better:
                continue
            payload = stage2c_rank_payload(stage2c_line)
            if payload is not None:
                exact_payloads.append(payload)
        unique_payloads = tuple(dict.fromkeys(exact_payloads))
        if len(unique_payloads) == 1:
            safe_payload_by_origin[origin_index] = unique_payloads[0]

    changed = False
    updated: List[SimulationResult] = []
    for result in results:
        if result.index not in selected_indices:
            updated.append(result)
            continue
        current_score = result.action_score
        high_value_prep_only = bool(
            result.index in high_value_prep_authority_origins
            and result.index not in stronger_authority_origins
        )
        target_tier = max(
            current_score.tier,
            TIER_HIGH_VALUE_PREP
            if high_value_prep_only
            else TIER_PRESERVE_WIN_OR_KO_PREP,
        )
        target_immediate = current_score.immediate
        target_pressure = current_score.pressure
        target_development = current_score.development
        safe_payload = safe_payload_by_origin.get(result.index)
        if safe_payload is not None:
            preserved_prizes, preserved_damage = safe_payload
            target_tier = max(target_tier, TIER_KO)
            target_immediate = max(target_immediate, preserved_prizes)
            target_pressure = max(target_pressure, preserved_damage)
            target_development = max(
                target_development,
                int(bool(result.outcome.adds_board_out_buffer)),
            )
        if (
            target_tier == current_score.tier
            and target_immediate == current_score.immediate
            and target_pressure == current_score.pressure
            and target_development == current_score.development
        ):
            updated.append(result)
            continue
        updated.append(
            replace(
                result,
                action_score=replace(
                    current_score,
                    tier=target_tier,
                    immediate=target_immediate,
                    pressure=target_pressure,
                    development=target_development,
                ),
            )
        )
        changed = True
    return tuple(updated), replace(facts, live_applied=changed)



def _phase4ex_normal_candidate_exactness_facts(
    board: BoardView,
    result: SimulationResult,
    families: Sequence[Phase4EXCandidateFamily],
) -> Phase4EXCandidateExactnessFacts:
    """Prove only the public Facts actually carried by one normal prep candidate."""
    outcome = getattr(result, "outcome", None)
    option = getattr(result, "option", None)
    family_set = set(families)
    option_identity_exact = bool(
        isinstance(outcome, ImmediateOutcome)
        and option is not None
        and _result_option_is_current(board, result)
    )
    legal = option_identity_exact
    supported = bool(
        isinstance(outcome, ImmediateOutcome)
        and outcome.supported is True
    )

    target_required = bool(
        Phase4EXCandidateFamily.HEALING_SURVIVAL in family_set
        or Phase4EXCandidateFamily.OPPONENT_DISRUPTION in family_set
    )
    target_identity_exact = True
    if isinstance(outcome, ImmediateOutcome):
        option_target = board.option_target(option) if option is not None else None
        option_target_id = (
            board.pid(option_target) if option_target is not None else None
        )
        option_target_serial = (
            getattr(option_target, "serial", None)
            if option_target is not None
            else None
        )
        target_id = (
            outcome.target_id
            if type(outcome.target_id) is int
            else option_target_id
        )
        target_serial = (
            outcome.target_serial
            if type(outcome.target_serial) is int
            else option_target_serial
        )
        any_target_identity = bool(
            outcome.target_id is not None
            or outcome.target_serial is not None
            or option_target is not None
        )
        if target_required or any_target_identity:
            if type(target_id) is not int or type(target_serial) is not int:
                target_identity_exact = False
            else:
                matches = tuple(
                    pokemon
                    for pokemon in tuple(getattr(board, "all_my_pokemon", ()) or ())
                    + tuple(getattr(board, "all_opp_pokemon", ()) or ())
                    if board.pid(pokemon) == target_id
                    and getattr(pokemon, "serial", None) == target_serial
                )
                target_identity_exact = len(matches) == 1
                if option_target is not None:
                    target_identity_exact = bool(
                        target_identity_exact
                        and option_target_id == target_id
                        and option_target_serial == target_serial
                    )
    elif target_required:
        target_identity_exact = False

    expected_or_probabilistic = False
    if isinstance(outcome, ImmediateOutcome):
        expected_or_probabilistic = bool(
            outcome.expected_reachable_attack_id is not None
            or outcome.expected_reachable_damage != 0
            or outcome.expected_reachable_knockout
            or outcome.expected_reachable_prizes_taken != 0
            or outcome.expected_reachable_wins_game
            or outcome.expected_hit_probability not in (0, 0.0, 1, 1.0)
            or outcome.development_probability not in (0, 0.0, 1, 1.0)
        )
    transition_provenance_required = bool(
        Phase4EXCandidateFamily.SELF_PREPARATION in family_set
        or Phase4EXCandidateFamily.BOARD_DEVELOPMENT in family_set
    )
    transition_exact = bool(
        isinstance(outcome, ImmediateOutcome)
        and not expected_or_probabilistic
        and not transition_provenance_required
    )
    hidden_dependent_component = False

    policy_facts_complete = isinstance(outcome, ImmediateOutcome)
    if isinstance(outcome, ImmediateOutcome):
        if Phase4EXCandidateFamily.SELF_PREPARATION in family_set:
            policy_facts_complete = bool(
                policy_facts_complete
                and type(outcome.enables_attack) is bool
                and isinstance(outcome.enabled_attack_ids, tuple)
                and type(outcome.avoids_wall) is bool
                and type(outcome.improves_damage) is bool
                and type(outcome.completes_next_attacker) is bool
            )
        if Phase4EXCandidateFamily.BOARD_DEVELOPMENT in family_set:
            policy_facts_complete = bool(
                policy_facts_complete
                and type(outcome.develops_bench_next_attacker) is bool
                and type(outcome.completes_evolution_line) is bool
                and type(outcome.completed_same_line_attackers) is int
                and type(outcome.post_evolution_ready_attack_count) is int
            )
        if Phase4EXCandidateFamily.HEALING_SURVIVAL in family_set:
            policy_facts_complete = bool(
                policy_facts_complete
                and target_identity_exact
                and type(outcome.healed_damage) is int
                and type(outcome.recovered_energy_count) is int
                and type(outcome.board_energy_removed) is int
                and type(outcome.next_knockout_avoided) is bool
                and type(outcome.avoids_prize_loss) is bool
                and type(outcome.prizes_preserved) is int
                and type(outcome.avoids_board_out) is bool
                and type(outcome.preserves_primary_pokemon) is bool
                and type(outcome.evolution_hp_gain) is int
            )
        if Phase4EXCandidateFamily.OPPONENT_DISRUPTION in family_set:
            policy_facts_complete = bool(
                policy_facts_complete
                and target_identity_exact
                and type(outcome.breaks_engine) is bool
                and type(outcome.removes_tool) is bool
            )

    uncertainty: List[str] = []
    if not legal:
        uncertainty.append("action_not_current")
    if not supported:
        uncertainty.append("immediate_outcome_unsupported")
    if not option_identity_exact:
        uncertainty.append("option_identity_inexact")
    if not target_identity_exact:
        uncertainty.append("target_identity_inexact")
    if not transition_exact:
        uncertainty.append(
            "typed_transition_provenance_unavailable"
            if transition_provenance_required and not expected_or_probabilistic
            else "probabilistic_or_expected_transition"
        )
    if not policy_facts_complete:
        uncertainty.append("policy_fact_set_incomplete")
    if hidden_dependent_component:
        uncertainty.append("hidden_dependent_component")

    exact_public_facts = bool(
        legal
        and supported
        and option_identity_exact
        and target_identity_exact
        and transition_exact
        and policy_facts_complete
        and not hidden_dependent_component
    )
    return Phase4EXCandidateExactnessFacts(
        legal=legal,
        supported=supported,
        option_identity_exact=option_identity_exact,
        target_identity_exact=target_identity_exact,
        transition_exact=transition_exact,
        policy_facts_complete=policy_facts_complete,
        hidden_dependent_component=hidden_dependent_component,
        exact_public_facts=exact_public_facts,
        uncertainty_reasons=tuple(uncertainty),
    )


def _phase4ex_stage2c_candidate_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    phase5: Phase5StrategicLiveFacts,
    line: "Stage2cStrategicActionLineFacts",
) -> Optional[Phase4EXCandidateFacts]:
    """Adapt only Phase5-selected Stage2c tier-40 strategic origins."""
    if line.action_line_kind == Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY:
        return None
    if line.action_line_kind not in {
        Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT,
        Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION,
    }:
        return None

    selected = line.origin_option_index in set(phase5.selected_origin_indices)
    actionable_index, binding_reason = _stage2c_phase5_actionable_origin_index(
        board,
        results,
        line,
    )
    legal = bool(
        actionable_index == line.origin_option_index
        and type(line.origin_option_index) is int
    )
    families = (
        Phase4EXCandidateFamily.EXACT_STRATEGIC_ACTION,
        Phase4EXCandidateFamily.SELF_PREPARATION,
        Phase4EXCandidateFamily.BOARD_DEVELOPMENT,
    )

    access_count: Optional[int] = None
    exact_development_line = False
    if line.action_line_kind == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT:
        if type(line.accessible_drednaw_line_count) is int:
            access_count = line.accessible_drednaw_line_count
        elif line.bruxish_counterattack_contract_supported is True:
            access_count = 1
        exact_development_line = bool(
            line.supported
            and line.exact
            and line.continuation_confirmed is True
            and line.attack_preserved_after_origin is True
            and type(access_count) is int
            and access_count > 0
        )
    else:
        access_count = 1 if line.evolution_relation_exact is True else None
        exact_development_line = bool(
            line.supported
            and line.exact
            and line.evolution_relation_exact is True
            and line.continuation_confirmed is True
            and line.attack_preserved_after_origin is True
        )

    supported = bool(line.supported)
    exact_public_facts = bool(
        legal
        and selected
        and supported
        and line.exact
        and exact_development_line
    )
    uncertainty: List[str] = []
    if not legal:
        uncertainty.append(binding_reason or "stage2c_origin_identity_inexact")
    if not selected:
        uncertainty.append("stage2c_origin_not_phase5_selected")
    if not supported:
        uncertainty.append(line.unsupported_reason or "stage2c_line_unsupported")
    if not line.exact:
        uncertainty.append("stage2c_line_inexact")
    if not exact_development_line:
        uncertainty.append("stage2c_development_or_continuation_unproved")

    return Phase4EXCandidateFacts(
        origin_option_index=line.origin_option_index,
        option_type=line.origin_option_type,
        option_card_id=line.origin_option_card_id,
        target_card_id=line.origin_target_card_id,
        target_serial=line.origin_target_serial,
        legal=legal,
        supported=supported,
        exact_public_facts=exact_public_facts,
        families=families,
        stage2c_kind=line.action_line_kind,
        phase5_selected=selected,
        continuation_confirmed=line.continuation_confirmed,
        attack_preserved_after_origin=line.attack_preserved_after_origin,
        exact_development_line=exact_development_line,
        development_line_access_count=access_count,
        avoids_board_out=False,
        avoids_prize_loss=False,
        prizes_preserved=0,
        preserves_primary_pokemon=False,
        healed_damage=0,
        recovered_energy_count=0,
        board_energy_removed=0,
        breaks_engine=False,
        removes_tool=False,
        uncertainty_reasons=tuple(uncertainty),
    )


def phase4ex_candidate_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
    phase5: Phase5StrategicLiveFacts,
) -> Tuple[Phase4EXCandidateFacts, ...]:
    """Build read-only Phase4EX candidate Facts without making a preference."""
    source_results = tuple(results)
    stage2c_lines: List[Stage2cStrategicActionLineFacts] = []
    seen_line_ids: set[int] = set()
    for comparison in phase5.comparisons:
        for candidate_line in (comparison.left_line, comparison.right_line):
            if not isinstance(candidate_line, Stage2cStrategicActionLineFacts):
                continue
            identity = id(candidate_line)
            if identity in seen_line_ids:
                continue
            seen_line_ids.add(identity)
            stage2c_lines.append(candidate_line)

    candidates: List[Phase4EXCandidateFacts] = []
    for line in stage2c_lines:
        candidate = _phase4ex_stage2c_candidate_facts(
            board,
            source_results,
            phase5,
            line,
        )
        if candidate is not None:
            candidates.append(candidate)

    strategic_indices = {candidate.origin_option_index for candidate in candidates}
    for result in source_results:
        option = getattr(result, "option", None)
        if (
            result.index in strategic_indices
            or option is None
            or getattr(option, "type", None) == OptionType.ATTACK
        ):
            continue
        outcome = getattr(result, "outcome", None)
        if not isinstance(outcome, ImmediateOutcome):
            continue
        families: List[Phase4EXCandidateFamily] = []
        if any((
            outcome.enables_attack,
            bool(outcome.enabled_attack_ids),
            outcome.avoids_wall,
            outcome.improves_damage,
            outcome.completes_next_attacker,
        )):
            families.append(Phase4EXCandidateFamily.SELF_PREPARATION)
        if any((
            outcome.develops_bench_next_attacker,
            outcome.completes_evolution_line,
            outcome.completed_same_line_attackers > 0,
            outcome.post_evolution_ready_attack_count > 0,
        )):
            families.append(Phase4EXCandidateFamily.BOARD_DEVELOPMENT)
        if any((
            outcome.healed_damage > 0,
            outcome.recovered_energy_count > 0,
            outcome.next_knockout_avoided,
            outcome.avoids_prize_loss,
            outcome.prizes_preserved > 0,
            outcome.avoids_board_out,
            outcome.preserves_primary_pokemon,
            outcome.evolution_hp_gain > 0,
        )):
            families.append(Phase4EXCandidateFamily.HEALING_SURVIVAL)
        if outcome.breaks_engine or outcome.removes_tool:
            families.append(Phase4EXCandidateFamily.OPPONENT_DISRUPTION)
        if not families:
            continue

        family_tuple = tuple(dict.fromkeys(families))
        exactness = _phase4ex_normal_candidate_exactness_facts(
            board,
            result,
            family_tuple,
        )
        option_target = board.option_target(option)
        target_card_id = (
            outcome.target_id
            if type(outcome.target_id) is int
            else board.pid(option_target)
            if option_target is not None
            else None
        )
        target_serial = (
            outcome.target_serial
            if type(outcome.target_serial) is int
            else getattr(option_target, "serial", None)
            if option_target is not None
            else None
        )
        candidates.append(Phase4EXCandidateFacts(
            origin_option_index=result.index,
            option_type=getattr(option, "type", None),
            option_card_id=board.option_card(option),
            target_card_id=target_card_id,
            target_serial=target_serial,
            legal=exactness.legal,
            supported=exactness.supported,
            exact_public_facts=exactness.exact_public_facts,
            families=family_tuple,
            stage2c_kind=None,
            phase5_selected=False,
            continuation_confirmed=None,
            attack_preserved_after_origin=None,
            exact_development_line=False,
            development_line_access_count=None,
            avoids_board_out=bool(outcome.avoids_board_out),
            avoids_prize_loss=bool(outcome.avoids_prize_loss),
            prizes_preserved=int(outcome.prizes_preserved),
            preserves_primary_pokemon=bool(outcome.preserves_primary_pokemon),
            healed_damage=int(outcome.healed_damage),
            recovered_energy_count=int(outcome.recovered_energy_count),
            board_energy_removed=int(outcome.board_energy_removed),
            breaks_engine=bool(outcome.breaks_engine),
            removes_tool=bool(outcome.removes_tool),
            uncertainty_reasons=exactness.uncertainty_reasons,
        ))

    return tuple(sorted(candidates, key=lambda candidate: candidate.origin_option_index))


def phase4ex_board_need_facts(
    board: BoardView,
    phase5: Phase5StrategicLiveFacts,
    threat: Optional["OpponentPublicThreat"] = None,
) -> Phase4EXBoardNeedFacts:
    """Adapt current public-board need Facts without ranking or preference."""
    public_threat = (
        OpponentPublicThreatEvaluator.evaluate(board)
        if threat is None
        else threat
    )
    current = phase5.current_position
    current_supported = current.supported is True
    current_exact = current.exact is True
    current_terminal_win = any(
        line.terminal_win is True for line in current.candidate_lines
    )
    current_attack_available = bool(current.candidate_lines)

    retreat_resolved = bool(
        public_threat.public_retreat.status != PublicRetreatStatus.UNSUPPORTED
        and public_threat.public_retreat.unsupported_reason is None
    )
    public_threat_complete = bool(
        not public_threat.unsupported_public_threats
        and retreat_resolved
    )
    threat_adapter = OpponentPublicThreatFacts(
        supported=public_threat_complete,
        best_confirmed_damage=int(public_threat.best_certain_damage),
        can_ko_projected_active=bool(public_threat.certain_active_can_ko),
        prizes_lost=int(public_threat.certain_active_prizes_if_ko),
        usable_attack_ids=tuple(sorted({
            fact.attack_id
            for fact in public_threat.certain_active_threats
            if fact.unsupported_reason is None
            and fact.can_attack_with_current_energy
        })),
        unsupported_reason=(
            None
            if public_threat_complete
            else "opponent_public_threat_partial"
            if public_threat.unsupported_public_threats
            else public_threat.public_retreat.unsupported_reason
            or "public_retreat_unresolved"
        ),
    )

    opponent_active = getattr(board, "opp_active", None)
    if opponent_active is None:
        next_attacker = CandidateProjectionEvaluator._unsupported_next_attacker_facts(
            "missing_current_opponent_active"
        )
    else:
        next_attacker = CandidateProjectionEvaluator._next_attacker_for_projected_bench(
            board,
            projected_bench=tuple(getattr(board, "bench", ()) or ()),
            projected_opponent_active_hp=hp_left(opponent_active),
            threat=threat_adapter,
        )
    ready_next_attacker_exists = (
        next_attacker.ready_next_attacker_exists
        if next_attacker.supported
        else None
    )
    next_attacker_deficit = (
        not ready_next_attacker_exists
        if type(ready_next_attacker_exists) is bool
        else None
    )

    supported_bench_threats = tuple(
        fact
        for fact in public_threat.publicly_reachable_bench_threats
        if fact.unsupported_reason is None
    )
    public_reachable_bench_can_ko = any(
        fact.can_ko_our_active for fact in supported_bench_threats
    )

    uncertainty: List[str] = []
    if not current_supported:
        uncertainty.append("current_position_unsupported")
    if not current_exact:
        uncertainty.append("current_position_inexact")
    if not next_attacker.supported:
        uncertainty.append(next_attacker.unsupported_reason or "next_attacker_unknown")
    if type(ready_next_attacker_exists) is not bool:
        uncertainty.append("next_attacker_unknown")
    if type(next_attacker_deficit) is not bool:
        uncertainty.append("next_attacker_deficit_unknown")
    if public_threat.unsupported_public_threats:
        uncertainty.append("opponent_public_threat_partial")
    if not retreat_resolved:
        uncertainty.append(
            public_threat.public_retreat.unsupported_reason
            or "public_retreat_unresolved"
        )

    supported = bool(current_supported)
    exact_public_facts = bool(
        supported
        and current_exact
        and next_attacker.supported
        and type(ready_next_attacker_exists) is bool
        and type(next_attacker_deficit) is bool
        and public_threat_complete
    )
    return Phase4EXBoardNeedFacts(
        supported=supported,
        exact_public_facts=exact_public_facts,
        current_terminal_win=current_terminal_win,
        current_attack_available=current_attack_available,
        bench_space=int(getattr(board, "bench_space", 0)),
        ready_next_attacker_exists=ready_next_attacker_exists,
        next_attacker_deficit=next_attacker_deficit,
        certain_active_can_ko=bool(public_threat.certain_active_can_ko),
        certain_active_best_damage=int(public_threat.best_certain_damage),
        public_reachable_bench_threat_count=len(supported_bench_threats),
        public_reachable_bench_can_ko=public_reachable_bench_can_ko,
        hidden_dependent_risk=bool(public_threat.has_hidden_dependent_risk),
        hidden_dependent_reasons=tuple(public_threat.hidden_dependent_reasons),
        uncertainty_reasons=tuple(dict.fromkeys(uncertainty)),
    )


def phase4ex_preference_facts(
    left: Phase4EXCandidateFacts,
    right: Phase4EXCandidateFacts,
    board_need: Phase4EXBoardNeedFacts,
    phase5: Phase5StrategicLiveFacts,
) -> Phase4EXPreferenceFacts:
    """Build one pairwise uncertain-policy relation without changing rank."""
    base_supported = bool(
        left.legal
        and right.legal
        and left.supported
        and right.supported
        and board_need.supported
    )
    base_exact = bool(
        base_supported
        and left.exact_public_facts
        and right.exact_public_facts
        and board_need.exact_public_facts
    )

    def abstain(
        reason: Phase4EXPreferenceReason,
        *uncertainty: str,
        supported: Optional[bool] = None,
        exact: Optional[bool] = None,
    ) -> Phase4EXPreferenceFacts:
        return Phase4EXPreferenceFacts(
            left_origin_option_index=left.origin_option_index,
            right_origin_option_index=right.origin_option_index,
            preference=Phase4EXPreference.ABSTAIN,
            reason=reason,
            supported=base_supported if supported is None else supported,
            exact_public_facts=base_exact if exact is None else exact,
            policy_applicable=False,
            uncertainty_reasons=tuple(uncertainty),
        )

    def decided(
        preference: Phase4EXPreference,
        reason: Phase4EXPreferenceReason,
    ) -> Phase4EXPreferenceFacts:
        return Phase4EXPreferenceFacts(
            left_origin_option_index=left.origin_option_index,
            right_origin_option_index=right.origin_option_index,
            preference=preference,
            reason=reason,
            supported=True,
            exact_public_facts=True,
            policy_applicable=True,
            uncertainty_reasons=(),
        )

    if left.origin_option_index == right.origin_option_index:
        return abstain(
            Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE,
            "same_origin_pair",
            supported=False,
            exact=False,
        )

    # Fail Closed before any policy-family branch.
    if not base_exact:
        uncertainty = tuple(dict.fromkeys(
            tuple(left.uncertainty_reasons)
            + tuple(right.uncertainty_reasons)
            + tuple(board_need.uncertainty_reasons)
            + (() if left.legal else ("left_illegal",))
            + (() if right.legal else ("right_illegal",))
            + (() if left.supported else ("left_unsupported",))
            + (() if right.supported else ("right_unsupported",))
            + (() if board_need.supported else ("board_need_unsupported",))
            + (() if left.exact_public_facts else ("left_inexact",))
            + (() if right.exact_public_facts else ("right_inexact",))
            + (() if board_need.exact_public_facts else ("board_need_inexact",))
        ))
        return abstain(
            Phase4EXPreferenceReason.INEXACT_PUBLIC_FACTS,
            *uncertainty,
            supported=base_supported,
            exact=False,
        )

    if board_need.current_terminal_win:
        return abstain(Phase4EXPreferenceReason.EXACT_AUTHORITY_SHIELD)

    # Protect any existing strict exact Phase3 authority for this origin pair.
    pair = frozenset((left.origin_option_index, right.origin_option_index))
    for comparison in phase5.comparisons:
        left_index = comparison.left_origin.option_index
        right_index = comparison.right_origin.option_index
        if (
            comparison.supported
            and comparison.exact
            and comparison.relation in {
                DirectAttackComparison.LEFT_BETTER,
                DirectAttackComparison.RIGHT_BETTER,
            }
            and type(left_index) is int
            and type(right_index) is int
            and frozenset((left_index, right_index)) == pair
        ):
            return abstain(Phase4EXPreferenceReason.EXACT_AUTHORITY_SHIELD)

    left_urgent = bool(left.avoids_prize_loss or left.avoids_board_out)
    right_urgent = bool(right.avoids_prize_loss or right.avoids_board_out)
    if left_urgent != right_urgent:
        return decided(
            Phase4EXPreference.PREFER_LEFT
            if left_urgent
            else Phase4EXPreference.PREFER_RIGHT,
            Phase4EXPreferenceReason.URGENT_LOSS_AVOIDANCE,
        )
    if left_urgent and right_urgent:
        return abstain(Phase4EXPreferenceReason.CONFLICTING_NONTERMINAL_PREP)

    if board_need.hidden_dependent_risk:
        return abstain(
            Phase4EXPreferenceReason.HIDDEN_DEPENDENT_UNCERTAINTY,
            *board_need.hidden_dependent_reasons,
        )
    if board_need.certain_active_can_ko or board_need.public_reachable_bench_can_ko:
        return abstain(Phase4EXPreferenceReason.OPPONENT_PUBLIC_THREAT)

    def exact_development_direction(candidate: Phase4EXCandidateFacts) -> bool:
        return bool(
            Phase4EXCandidateFamily.EXACT_STRATEGIC_ACTION in candidate.families
            and Phase4EXCandidateFamily.BOARD_DEVELOPMENT in candidate.families
            and candidate.phase5_selected
            and candidate.continuation_confirmed is True
            and candidate.attack_preserved_after_origin is True
            and candidate.exact_development_line
        )

    def nonurgent_preservation(candidate: Phase4EXCandidateFacts) -> bool:
        return bool(
            Phase4EXCandidateFamily.HEALING_SURVIVAL in candidate.families
            and not candidate.avoids_prize_loss
            and not candidate.avoids_board_out
            and candidate.preserves_primary_pokemon
            and (candidate.healed_damage > 0 or candidate.recovered_energy_count > 0)
        )

    left_development = exact_development_direction(left)
    right_development = exact_development_direction(right)
    left_preservation = nonurgent_preservation(left)
    right_preservation = nonurgent_preservation(right)

    if (left_development and right_preservation) or (right_development and left_preservation):
        if board_need.next_attacker_deficit is not True or board_need.bench_space <= 0:
            return abstain(
                Phase4EXPreferenceReason.BOARD_DEVELOPMENT_NEED_NOT_ESTABLISHED
            )
        return decided(
            Phase4EXPreference.PREFER_LEFT
            if left_development
            else Phase4EXPreference.PREFER_RIGHT,
            Phase4EXPreferenceReason.BOARD_DEVELOPMENT_NEED,
        )

    if (
        left.stage2c_kind is not None
        and right.stage2c_kind is not None
        and left.stage2c_kind == right.stage2c_kind
        and left.phase5_selected
        and right.phase5_selected
    ):
        return decided(
            Phase4EXPreference.EQUIVALENT_POLICY,
            Phase4EXPreferenceReason.SAME_FAMILY_NO_CROSS_FAMILY_POLICY,
        )

    if (
        left.stage2c_kind is not None
        and right.stage2c_kind is not None
        and left.stage2c_kind != right.stage2c_kind
    ):
        return abstain(Phase4EXPreferenceReason.CONFLICTING_NONTERMINAL_PREP)

    if (
        Phase4EXCandidateFamily.HEALING_SURVIVAL in left.families
        and Phase4EXCandidateFamily.HEALING_SURVIVAL in right.families
    ):
        return abstain(Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE)

    return abstain(Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE)


def phase4ex_preference_matrix_facts(
    candidates: Sequence[Phase4EXCandidateFacts],
    board_need: Phase4EXBoardNeedFacts,
    phase5: Phase5StrategicLiveFacts,
) -> Tuple[Phase4EXPreferenceFacts, ...]:
    """Build exactly one canonical relation for each unordered candidate pair."""
    ordered = tuple(sorted(
        tuple(candidates),
        key=lambda candidate: candidate.origin_option_index,
    ))
    relations: List[Phase4EXPreferenceFacts] = []
    for left_ordinal, left in enumerate(ordered):
        for right in ordered[left_ordinal + 1:]:
            relations.append(
                phase4ex_preference_facts(left, right, board_need, phase5)
            )
    return tuple(relations)


def phase4ex_resolution_facts(
    candidates: Sequence[Phase4EXCandidateFacts],
    preferences: Sequence[Phase4EXPreferenceFacts],
) -> Phase4EXResolutionFacts:
    """Validate the pairwise matrix and expose only canonical preference edges."""
    source_candidates = tuple(candidates)
    source_preferences = tuple(preferences)
    raw_indices = tuple(candidate.origin_option_index for candidate in source_candidates)
    candidate_indices = tuple(sorted(set(raw_indices)))

    def resolution(
        *,
        abstained: bool,
        reason: Phase4EXPreferenceReason,
        edges: Sequence[Tuple[int, int]] = (),
        cycle: bool = False,
        missing: bool = False,
        supported: bool = False,
        exact: bool = False,
        applicable: bool = False,
        invalid: bool = False,
    ) -> Phase4EXResolutionFacts:
        return Phase4EXResolutionFacts(
            candidate_indices=candidate_indices,
            preferred_edges=tuple(sorted(set(edges))) if not abstained else (),
            abstained=abstained,
            reason=reason,
            cycle_detected=cycle,
            missing_relation=missing,
            supported=supported,
            exact=exact,
            policy_applicable=applicable,
            invalid_preference_detected=invalid,
        )

    if len(raw_indices) != len(candidate_indices):
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.INVALID_PREFERENCE_SET,
            invalid=True,
        )

    candidate_map = {candidate.origin_option_index: candidate for candidate in source_candidates}
    if any(
        not candidate.legal
        or not candidate.supported
        or not candidate.exact_public_facts
        for candidate in source_candidates
    ):
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.INEXACT_PUBLIC_FACTS,
            invalid=True,
        )

    expected_pairs = {
        (left, right)
        for ordinal, left in enumerate(candidate_indices)
        for right in candidate_indices[ordinal + 1:]
    }
    seen_pairs: set[Tuple[int, int]] = set()
    edges: List[Tuple[int, int]] = []
    edge_reasons: List[Phase4EXPreferenceReason] = []
    has_abstain = False

    for preference in source_preferences:
        left = preference.left_origin_option_index
        right = preference.right_origin_option_index
        pair = tuple(sorted((left, right)))
        if (
            left == right
            or left not in candidate_map
            or right not in candidate_map
            or pair not in expected_pairs
            or pair in seen_pairs
        ):
            return resolution(
                abstained=True,
                reason=Phase4EXPreferenceReason.INVALID_PREFERENCE_SET,
                invalid=True,
            )
        seen_pairs.add(pair)

        if preference.preference != Phase4EXPreference.ABSTAIN and (
            preference.supported is not True
            or preference.exact_public_facts is not True
            or preference.policy_applicable is not True
        ):
            return resolution(
                abstained=True,
                reason=Phase4EXPreferenceReason.INVALID_PREFERENCE_SET,
                invalid=True,
            )
        if preference.preference == Phase4EXPreference.ABSTAIN:
            has_abstain = True
            continue
        if preference.preference == Phase4EXPreference.PREFER_LEFT:
            edges.append((left, right))
            edge_reasons.append(preference.reason)
        elif preference.preference == Phase4EXPreference.PREFER_RIGHT:
            edges.append((right, left))
            edge_reasons.append(preference.reason)
        elif preference.preference == Phase4EXPreference.EQUIVALENT_POLICY:
            continue
        else:
            return resolution(
                abstained=True,
                reason=Phase4EXPreferenceReason.INVALID_PREFERENCE_SET,
                invalid=True,
            )

    if seen_pairs != expected_pairs:
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE,
            missing=True,
        )
    if has_abstain:
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.CONFLICTING_NONTERMINAL_PREP,
            supported=True,
            exact=True,
            applicable=False,
        )
    if not edges:
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE,
            supported=True,
            exact=True,
            applicable=False,
        )

    adjacency = {index: set() for index in candidate_indices}
    for preferred, less_preferred in edges:
        adjacency[preferred].add(less_preferred)
    visiting: set[int] = set()
    visited: set[int] = set()

    def has_cycle(node: int) -> bool:
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for child in adjacency[node]:
            if has_cycle(child):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    if any(has_cycle(node) for node in candidate_indices if node not in visited):
        return resolution(
            abstained=True,
            reason=Phase4EXPreferenceReason.PREFERENCE_CYCLE,
            cycle=True,
            supported=True,
            exact=True,
            applicable=False,
        )

    strict_reasons = tuple(dict.fromkeys(edge_reasons))
    return resolution(
        abstained=False,
        reason=(
            strict_reasons[0]
            if len(strict_reasons) == 1
            else Phase4EXPreferenceReason.INSUFFICIENT_POLICY_EVIDENCE
        ),
        edges=edges,
        supported=True,
        exact=True,
        applicable=True,
    )


def apply_phase4ex_preference_ordering(
    board: BoardView,
    results: Sequence[SimulationResult],
    phase5: Phase5StrategicLiveFacts,
) -> Tuple[Tuple[SimulationResult, ...], Optional[Phase4EXResolutionFacts]]:
    """Stable post-Phase5 transport for fully resolved Phase4EX preferences only."""
    source_results = tuple(results)
    result_by_index = {result.index: result for result in source_results}
    if len(result_by_index) != len(source_results):
        return source_results, None

    all_candidates = phase4ex_candidate_facts(board, source_results, phase5)
    activated: List[Phase4EXCandidateFacts] = []
    for candidate in all_candidates:
        result = result_by_index.get(candidate.origin_option_index)
        option = getattr(result, "option", None) if result is not None else None
        outcome = getattr(result, "outcome", None) if result is not None else None
        score = getattr(result, "action_score", None) if result is not None else None
        terminal = bool(
            isinstance(outcome, ImmediateOutcome)
            and (
                outcome.wins_game is True
                or outcome.knockout is True
                or outcome.prizes_taken > 0
            )
        )
        if (
            result is None
            or option is None
            or score is None
            or getattr(option, "type", None) == OptionType.ATTACK
            or score.tier != TIER_HIGH_VALUE_PREP
            or terminal
        ):
            continue
        activated.append(candidate)

    if len(activated) < 2:
        return source_results, None
    if any(
        not candidate.legal
        or not candidate.supported
        or not candidate.exact_public_facts
        for candidate in activated
    ):
        return source_results, None

    threat = OpponentPublicThreatEvaluator.evaluate(board)
    board_need = phase4ex_board_need_facts(board, phase5, threat=threat)
    if not board_need.supported or not board_need.exact_public_facts:
        return source_results, None

    candidate_tuple = tuple(activated)
    preferences = phase4ex_preference_matrix_facts(
        candidate_tuple,
        board_need,
        phase5,
    )
    resolution = phase4ex_resolution_facts(candidate_tuple, preferences)
    if (
        resolution.abstained
        or not resolution.preferred_edges
        or resolution.missing_relation
        or resolution.cycle_detected
        or resolution.invalid_preference_detected
        or resolution.supported is not True
        or resolution.exact is not True
        or resolution.policy_applicable is not True
    ):
        return source_results, resolution

    activated_indices = tuple(
        result.index
        for result in source_results
        if result.index in resolution.candidate_indices
    )
    if set(activated_indices) != set(resolution.candidate_indices):
        return source_results, resolution

    incoming: Dict[int, set[int]] = {
        index: set() for index in resolution.candidate_indices
    }
    outgoing: Dict[int, set[int]] = {
        index: set() for index in resolution.candidate_indices
    }
    for preferred, less_preferred in resolution.preferred_edges:
        if preferred not in outgoing or less_preferred not in incoming:
            return source_results, resolution
        outgoing[preferred].add(less_preferred)
        incoming[less_preferred].add(preferred)

    remaining = set(resolution.candidate_indices)
    ordered_indices: List[int] = []
    while remaining:
        chosen: Optional[int] = None
        for index in activated_indices:
            if index in remaining and not (incoming[index] & remaining):
                chosen = index
                break
        if chosen is None:
            return source_results, resolution
        ordered_indices.append(chosen)
        remaining.remove(chosen)

    if tuple(ordered_indices) == activated_indices:
        return source_results, resolution

    ordered_results = [result_by_index[index] for index in ordered_indices]
    ordered_iter = iter(ordered_results)
    updated: List[SimulationResult] = []
    activated_set = set(resolution.candidate_indices)
    for result in source_results:
        if result.index in activated_set:
            updated.append(next(ordered_iter))
        else:
            updated.append(result)
    return tuple(updated), resolution


def _phase4_uncertain_action_facts(
    board: BoardView,
    result: SimulationResult,
) -> Optional[Phase4UncertainActionFacts]:
    option = getattr(result, "option", None)
    if getattr(option, "type", None) == OptionType.ATTACK:
        return None
    outcome = getattr(result, "outcome", None)
    if not isinstance(outcome, ImmediateOutcome):
        return None

    evidence_reasons: List[str] = []

    def evidence(name: str, present: bool) -> bool:
        if present:
            evidence_reasons.append(name)
        return present

    self_preparation = any((
        evidence("enables_attack", outcome.enables_attack),
        evidence("enabled_attack_ids", bool(outcome.enabled_attack_ids)),
        evidence("avoids_wall", outcome.avoids_wall),
        evidence("improves_damage", outcome.improves_damage),
        evidence("completes_next_attacker", outcome.completes_next_attacker),
    ))
    opponent_disruption = any((
        evidence("breaks_engine", outcome.breaks_engine),
        evidence("removes_tool", outcome.removes_tool),
        evidence("board_energy_removed", outcome.board_energy_removed > 0),
    ))
    board_development = any((
        evidence(
            "develops_bench_next_attacker",
            outcome.develops_bench_next_attacker,
        ),
        evidence("completes_evolution_line", outcome.completes_evolution_line),
        evidence(
            "completed_same_line_attackers",
            outcome.completed_same_line_attackers > 0,
        ),
        evidence(
            "post_evolution_ready_attack_count",
            outcome.post_evolution_ready_attack_count > 0,
        ),
    ))
    healing_survival = any((
        evidence("healed_damage", outcome.healed_damage > 0),
        evidence("recovered_energy_count", outcome.recovered_energy_count > 0),
        evidence("next_knockout_avoided", outcome.next_knockout_avoided),
        evidence("avoids_prize_loss", outcome.avoids_prize_loss),
        evidence("prizes_preserved", outcome.prizes_preserved > 0),
        evidence("avoids_board_out", outcome.avoids_board_out),
        evidence("preserves_primary_pokemon", outcome.preserves_primary_pokemon),
        evidence("evolution_hp_gain", outcome.evolution_hp_gain > 0),
    ))
    has_evidence = any((
        self_preparation,
        opponent_disruption,
        board_development,
        healing_survival,
    ))
    legal = _result_option_is_current(board, result)
    if not legal:
        uncertainty_reasons = ("action_not_current",)
    elif not outcome.supported:
        uncertainty_reasons = (
            tuple(outcome.reasons)
            or ("immediate_outcome_unsupported",)
        )
    elif not has_evidence:
        uncertainty_reasons = ("no_existing_uncertain_action_evidence",)
    else:
        uncertainty_reasons = tuple(
            reason
            for present, reason in (
                (self_preparation, "prepared_outcome_not_confirmed"),
                (opponent_disruption, "opponent_reply_after_disruption_unknown"),
                (board_development, "development_continuation_unknown"),
                (healing_survival, "survival_continuation_unknown"),
            )
            if present
        )
    uncertain_action_supported = (
        legal
        and outcome.supported
        and has_evidence
        and bool(uncertainty_reasons)
    )
    return Phase4UncertainActionFacts(
        option_index=result.index,
        option_type=getattr(option, "type", None),
        legal=legal,
        immediate_outcome_supported=outcome.supported,
        self_preparation=self_preparation,
        opponent_disruption=opponent_disruption,
        board_development=board_development,
        healing_survival=healing_survival,
        evidence_reasons=tuple(evidence_reasons),
        uncertainty_reasons=uncertainty_reasons,
        uncertain_action_supported=uncertain_action_supported,
    )


def phase4_current_value_gate_facts(
    board: BoardView,
    results: Sequence[SimulationResult],
) -> Phase4CurrentValueGateFacts:
    current = current_direct_attack_candidate_facts(board, results)
    current_candidates = current.candidates
    current_states = tuple(
        classify_direct_attack_candidate(candidate.facts)
        for candidate in current_candidates
    )
    supported_candidates = tuple(
        candidate
        for candidate in current_candidates
        if candidate.facts.supported
    )

    def protected_candidate(
        candidate: DirectAttackShadowCandidate,
    ) -> bool:
        return (
            candidate.facts.supported
            and candidate.facts.confirmed_loss is not True
        )

    current_has_immediate_win = any(
        protected_candidate(candidate)
        and candidate.facts.candidate_wins_game is True
        for candidate in current_candidates
    )
    current_has_confirmed_ko = any(
        protected_candidate(candidate)
        and candidate.facts.opponent_active_ko is True
        for candidate in current_candidates
    )
    current_has_confirmed_prize_gain = any(
        protected_candidate(candidate)
        and candidate.facts.immediate_prizes_taken is not None
        and candidate.facts.immediate_prizes_taken > 0
        for candidate in current_candidates
    )
    current_has_confirmed_loss = any(
        candidate.facts.supported
        and candidate.facts.confirmed_loss is True
        for candidate in current_candidates
    )
    current_has_reply_unknown = (
        DirectAttackCandidateState.REPLY_UNKNOWN in current_states
    )
    current_has_overall_unsupported = (
        DirectAttackCandidateState.OVERALL_UNSUPPORTED in current_states
    )
    current_has_partial_unknown = (
        DirectAttackCandidateState.PARTIAL_UNKNOWN in current_states
    )
    current_has_confirmed_non_ko_no_prize = any(
        candidate.facts.supported
        and candidate.facts.confirmed_loss is not True
        and candidate.facts.candidate_wins_game is False
        and candidate.facts.opponent_active_ko is False
        and candidate.facts.immediate_prizes_taken == 0
        for candidate in current_candidates
    )
    uncertain_actions = tuple(
        facts
        for result in results
        for facts in (_phase4_uncertain_action_facts(board, result),)
        if facts is not None
    )
    uncertain_action_supported = any(
        facts.uncertain_action_supported for facts in uncertain_actions
    )

    protected_reasons = tuple(
        reason
        for present, reason in (
            (
                current_has_immediate_win,
                Phase4CurrentValueGateReason.CURRENT_IMMEDIATE_WIN,
            ),
            (
                current_has_confirmed_ko,
                Phase4CurrentValueGateReason.CURRENT_CONFIRMED_KO,
            ),
            (
                current_has_confirmed_prize_gain,
                Phase4CurrentValueGateReason.CURRENT_CONFIRMED_PRIZE_GAIN,
            ),
        )
        if present
    )
    if protected_reasons:
        gate_open = False
        gate_reasons = protected_reasons
    elif not uncertain_action_supported:
        gate_open = False
        gate_reasons = (
            Phase4CurrentValueGateReason.UNCERTAIN_ACTION_UNSUPPORTED,
        )
    else:
        open_reasons: List[Phase4CurrentValueGateReason] = []
        if not current_candidates:
            open_reasons.append(
                Phase4CurrentValueGateReason.NO_LEGAL_CURRENT_ATTACK
            )
        if current_candidates and not supported_candidates:
            open_reasons.append(
                Phase4CurrentValueGateReason.NO_SUPPORTED_CURRENT_ATTACK
            )
        if current_has_overall_unsupported:
            open_reasons.append(
                Phase4CurrentValueGateReason.CURRENT_HAS_OVERALL_UNSUPPORTED
            )
        if current_has_reply_unknown:
            open_reasons.append(
                Phase4CurrentValueGateReason.CURRENT_HAS_REPLY_UNKNOWN
            )
        if current_has_partial_unknown:
            open_reasons.append(
                Phase4CurrentValueGateReason.CURRENT_HAS_PARTIAL_UNKNOWN
            )
        if current_has_confirmed_loss:
            open_reasons.append(
                Phase4CurrentValueGateReason.CURRENT_HAS_CONFIRMED_LOSS
            )
        if current_has_confirmed_non_ko_no_prize:
            open_reasons.append(
                Phase4CurrentValueGateReason.CURRENT_CONFIRMED_NON_KO_NO_PRIZE
            )
        gate_open = bool(open_reasons)
        gate_reasons = tuple(open_reasons) or (
            Phase4CurrentValueGateReason.CURRENT_VALUE_NOT_GATE_ELIGIBLE,
        )

    return Phase4CurrentValueGateFacts(
        current_candidates=current_candidates,
        current_candidate_count=len(current_candidates),
        current_supported_candidate_count=len(supported_candidates),
        current_states=current_states,
        current_has_immediate_win=current_has_immediate_win,
        current_has_confirmed_ko=current_has_confirmed_ko,
        current_has_confirmed_prize_gain=current_has_confirmed_prize_gain,
        current_has_confirmed_loss=current_has_confirmed_loss,
        current_has_reply_unknown=current_has_reply_unknown,
        current_has_overall_unsupported=current_has_overall_unsupported,
        current_has_partial_unknown=current_has_partial_unknown,
        current_has_confirmed_non_ko_no_prize=(
            current_has_confirmed_non_ko_no_prize
        ),
        uncertain_actions=uncertain_actions,
        uncertain_action_supported=uncertain_action_supported,
        gate_open=gate_open,
        gate_reason=gate_reasons[0],
        gate_reasons=gate_reasons,
    )
class Stage2cStrategicActionLineKind(str, Enum):
    SAFE_PRE_KO_BASIC_PLAY = "SAFE_PRE_KO_BASIC_PLAY"
    HAND_BASIC_DEPLOYMENT = "HAND_BASIC_DEPLOYMENT"
    EVOLUTION_CONTINUATION = "EVOLUTION_CONTINUATION"


@dataclass(frozen=True)
class Stage2cStrategicActionLineFacts:
    origin_option_index: int
    origin_option_type: Any
    origin_option_card_id: Optional[int]
    origin_target_card_id: Optional[int]
    origin_target_serial: Optional[int]
    action_line_kind: Stage2cStrategicActionLineKind
    current_attack_lines: Tuple[ActivePositionCurrentAttackLineFacts, ...]
    current_attack_option_index: Optional[int]
    current_attack_id: Optional[int]
    continuation_attack_option_indices: Tuple[int, ...]
    continuation_attack_ids: Tuple[int, ...]
    continuation_confirmed: Optional[bool]
    current_attack_is_nonwinning_ko: Optional[bool]
    attack_preserved_after_origin: Optional[bool]
    current_direct_win_exists: Optional[bool]
    current_direct_knockout_exists: Optional[bool]
    current_non_ko_attack_exists: Optional[bool]
    bench_space_before: Optional[int]
    bench_count_before: Optional[int]
    bench_slot_consumed: Optional[bool]
    other_legal_basic_option_indices: Tuple[int, ...]
    same_card_in_play_count: Optional[int]
    duplicate_deployment: Optional[bool]
    role: Optional[str]
    chewtle_drednaw_in_hand: Optional[bool]
    drednaw_in_play: Optional[bool]
    drednaw_remaining_possible: Optional[bool]
    accessible_drednaw_line_count: Optional[int]
    bruxish_already_in_play: Optional[bool]
    bruxish_counterattack_contract_supported: Optional[bool]
    bruxish_counterline_role_live: Optional[bool]
    evolution_relation_exact: Optional[bool]
    supported: bool
    exact: bool
    blocking_high_value_evolution_exists: Optional[bool] = None
    blocking_high_value_evolution_option_indices: Tuple[int, ...] = ()
    unsupported_reason: Optional[str] = None
    reasons: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if self.supported:
            if not self.exact or self.unsupported_reason is not None:
                raise ValueError("incomplete_supported_stage2c_strategic_action_line")
        elif self.exact or not self.unsupported_reason:
            raise ValueError("unsupported_stage2c_strategic_action_line_must_fail_closed")


