# ============================================================
# Policy
# ============================================================
class Policy:
    def __init__(self, board: BoardView):
        self.b = board
        self.outcome = ImmediateOutcomeEvaluator(board)
        self._surfing_beach_candidate_cache: Dict[
            Tuple[int, bool],
            Tuple[SwitchTargetAttackFacts, ...],
        ] = {}
        self._current_attack_candidate_cache: Optional[
            AttackCandidateCollection
        ] = None
        self._surfing_beach_target_outcome_cache: Dict[
            int, Optional[ImmediateOutcome]
        ] = {}
        self._surfing_beach_entry_outcome_cache: Dict[
            Tuple[int, bool], Optional[ImmediateOutcome]
        ] = {}
        self._resolved_outcome_cache: Dict[int, ImmediateOutcome] = {}

    def score(self, index: int, option: Any) -> float:
        context = self.b.select.context
        if option.type == OptionType.NUMBER:
            return self.score_count(option)
        if option.type in {OptionType.YES, OptionType.NO}:
            return self.score_yes_no(option)
        if (
            context == SelectContext.DISCARD_TOOL_CARD
            and self.effect_id() == TOOL_SCRAPPER
        ):
            return self.score_tool_scrapper_target_option(
                index,
                option,
            )
        if context == SelectContext.TO_ACTIVE:
            return self.score_promotion_target(option)
        if context in {SelectContext.SETUP_ACTIVE_POKEMON, SelectContext.SETUP_BENCH_POKEMON}:
            return self.score_setup(option)
        if context in {SelectContext.TO_HAND, SelectContext.TO_FIELD, SelectContext.TO_BENCH, SelectContext.LOOK}:
            if self.effect_id() == SALVATORE and self.b.option_target(option) is not None:
                return self.score_target_or_card(option)
            return self.score_card_selection(option)
        if context in {SelectContext.DISCARD, SelectContext.TO_DECK, SelectContext.TO_DECK_BOTTOM, SelectContext.DISCARD_CARD_OR_ATTACHED_CARD}:
            return self.score_discard(option)
        if context in {SelectContext.DAMAGE_COUNTER, SelectContext.DAMAGE_COUNTER_ANY, SelectContext.DAMAGE}:
            return self.score_damage_target(option)
        if context in {SelectContext.REMOVE_DAMAGE_COUNTER, SelectContext.HEAL}:
            return self.score_heal_target(option)
        if context in {SelectContext.SWITCH, SelectContext.ATTACH_FROM, SelectContext.ATTACH_TO, SelectContext.EFFECT_TARGET, SelectContext.EVOLVES_FROM, SelectContext.EVOLVES_TO}:
            return self.score_target_or_card(option)
        if context in {SelectContext.DISCARD_ENERGY, SelectContext.DISCARD_ENERGY_CARD, SelectContext.TO_HAND_ENERGY, SelectContext.TO_DECK_ENERGY, SelectContext.SWITCH_ENERGY, SelectContext.SWITCH_ENERGY_CARD}:
            return self.score_energy_selection(option)
        return self.score_main(option)

    def score_main(self, option: Any) -> float:
        if option.type == OptionType.ATTACK or option.attackId is not None:
            return self.score_attack(option)
        if option.type == OptionType.END:
            return self.score_end()
        if option.type == OptionType.RETREAT:
            return self.score_retreat(option)
        if option.type == OptionType.PLAY:
            return self.score_play(option)
        if option.type == OptionType.ATTACH:
            return self.score_attach(option)
        if option.type == OptionType.EVOLVE:
            return self.score_evolve(option)
        if option.type == OptionType.ABILITY:
            return self.score_ability(option)
        if option.type == OptionType.CARD:
            return self.score_card_selection(option)
        return 0.0

    def ultra_ball_target_policy(self, facts: UltraBallTargetFacts) -> SearchTargetPolicy:
        role = "no_current_role"
        useful = False
        development_value = 0.0
        if not facts.searchable:
            role = "not_searchable"
        elif facts.setup_only_target:
            role = "setup_role_live" if facts.setup_role_live else "setup_window_closed"
            useful = facts.setup_role_live
            development_value = 1.0 if useful else 0.0
        elif facts.evolution_base_in_play and not facts.duplicate_in_hand:
            role = "current_evolution_needed"
            useful = True
            development_value = 3.0
        elif (
            facts.evolution_access_selected is True
            and facts.same_turn_deployable
            and not facts.duplicate_in_hand
            and not facts.duplicate_in_play
        ):
            role = "deployable_evolution_base"
            useful = True
            development_value = 2.5 if facts.target_id == HITODEMAN else 2.0
        elif (
            facts.bench_guard_needed
            and facts.same_turn_deployable
            and not facts.duplicate_in_hand
            and not facts.duplicate_in_play
        ):
            role = "bench_damage_guard"
            useful = True
            development_value = 3.0
        return SearchTargetPolicy(role=role, useful=useful, development_value=development_value)

    def useful_ultra_ball_targets(
        self,
        *,
        after_ultra_ball_cost: bool = False,
    ) -> Tuple[Tuple[UltraBallTargetFacts, SearchTargetPolicy], ...]:
        candidates = []
        for facts in self.b.ultra_ball_target_facts_in_deck(
            after_ultra_ball_cost=after_ultra_ball_cost,
        ):
            target_policy = self.ultra_ball_target_policy(facts)
            if target_policy.useful:
                candidates.append((facts, target_policy))
        return tuple(candidates)

    def recommended_ultra_ball_target(
        self,
        *,
        after_ultra_ball_cost: bool = False,
    ) -> Optional[Tuple[UltraBallTargetFacts, SearchTargetPolicy]]:
        useful = self.useful_ultra_ball_targets(
            after_ultra_ball_cost=after_ultra_ball_cost,
        )
        if not useful:
            return None
        return max(
            useful,
            key=lambda item: (
                item[1].development_value,
                -item[0].target_id,
            ),
        )

    def ultra_ball_evolutions_to_preserve(self) -> Tuple[int, ...]:
        cost = self.b.ultra_ball_cost_facts()
        if (
            not cost.supported
            or cost.remaining_discard_count is None
        ):
            return ()

        preservable = tuple(
            evolution_id
            for evolution_id in cost.last_access_evolution_ids
            if self.b.can_preserve_evolution_access_after_ultra_ball_cost(
                evolution_id
            ) is True
        )
        if not preservable:
            return ()

        # Preserve every last-access line when the remaining cost can be paid
        # without discarding any of them.
        nonprotected_capacity = (
            len(cost.selectable_card_ids)
            - len(cost.last_access_evolution_ids)
        )
        if nonprotected_capacity >= cost.remaining_discard_count:
            return preservable

        # When all last-access lines cannot survive together, Ultra Ball will
        # ultimately search only one card. Preserve the best individually
        # viable line rather than collapsing every line to unavailable.
        ranked: List[
            Tuple[float, int, int]
        ] = []
        for evolution_id in preservable:
            base_id = self.b.deck_base_for_evolution(evolution_id)
            facts = self.b.ultra_ball_target_facts(
                base_id,
                after_ultra_ball_cost=True,
            )
            if facts is None:
                continue
            target_policy = self.ultra_ball_target_policy(facts)
            if not target_policy.useful:
                continue
            ranked.append(
                (
                    target_policy.development_value,
                    -facts.target_id,
                    int(evolution_id),
                )
            )
        if not ranked:
            return ()
        return (max(ranked)[2],)

    def poke_pad_target_policy(self, facts: PokePadTargetFacts) -> SearchTargetPolicy:
        role = "no_current_role"
        useful = False
        development_value = 0.0
        if facts.setup_only_target:
            role = "setup_window_closed"
        elif not facts.searchable:
            role = "not_searchable"
        elif not facts.same_turn_deployable:
            role = "bench_unavailable"
        elif facts.bench_guard_needed and not facts.duplicate_in_hand and not facts.duplicate_in_play:
            role = "bench_damage_guard"
            useful = True
            development_value = 4.0
        elif facts.turbo_flare_energy_target:
            role = "turbo_flare_attack_pipeline"
            useful = True
            development_value = 3.0
            if facts.target_id == HITODEMAN and self.b.wants_starmie_axis():
                development_value += 0.25
        elif facts.evolution_line_shortage:
            role = "evolution_line_shortage"
            useful = True
            development_value = 2.0 + min(
                0.5,
                0.1 * max(0, facts.evolution_demand - facts.base_supply),
            )
        elif facts.board_out_buffer:
            role = "board_out_buffer"
            useful = True
            development_value = 1.0
        return SearchTargetPolicy(role=role, useful=useful, development_value=development_value)

    def useful_poke_pad_targets(self) -> Tuple[Tuple[PokePadTargetFacts, SearchTargetPolicy], ...]:
        candidates = []
        for facts in self.b.poke_pad_target_facts_in_deck():
            target_policy = self.poke_pad_target_policy(facts)
            if target_policy.useful:
                candidates.append((facts, target_policy))
        return tuple(candidates)

    def recommended_poke_pad_target(self) -> Optional[PokePadTargetFacts]:
        useful = self.useful_poke_pad_targets()
        if not useful:
            return None
        return max(
            useful,
            key=lambda item: (item[1].development_value, -item[0].target_id),
        )[0]

    def best_retained_poke_pad_attack(
        self,
    ) -> Optional[AttackOutcomeCandidate]:
        candidates = self.outcome.retained_non_ko_attack_candidates()
        if not candidates:
            return None

        def key(
            candidate: AttackOutcomeCandidate,
        ) -> Tuple[Any, ...]:
            attack = self.b.attack(candidate.attack_id)
            pressure = self.attack_pressure_value_for_attack(
                attack,
                candidate.outcome,
                candidate.can_continue_attack is True,
            )
            return (
                pressure,
                -(
                    candidate.option_index
                    if candidate.option_index is not None
                    else candidate.attack_index
                ),
            )

        return max(candidates, key=key)

    def poke_pad_play_outcome(
        self,
        option: Any,
        base: Optional[ImmediateOutcome] = None,
    ) -> ImmediateOutcome:
        if base is None:
            base = self.outcome.evaluate_poke_pad_play(option)
        if not base.supported:
            return base
        recommended = self.recommended_poke_pad_target()
        if recommended is None:
            return replace(
                base,
                reasons=base.reasons + (
                    "poke_pad_no_useful_target",
                ),
            )
        target_policy = self.poke_pad_target_policy(recommended)
        retained = self.best_retained_poke_pad_attack()
        reachable_attack_id = None
        reachable_damage = 0
        reachable_can_continue_attack = False
        pressure = 0.0
        retained_reasons: Tuple[str, ...] = ()
        if retained is not None:
            reachable_attack_id = retained.attack_id
            reachable_damage = retained.outcome.damage
            reachable_can_continue_attack = (
                retained.can_continue_attack is True
            )
            retained_reasons = (
                "poke_pad_preserves_current_non_ko_attack",
            )
            if retained.can_continue_attack is None:
                retained_reasons += (
                    "reachable_attack_continuation_unknown",
                )
            attack = self.b.attack(retained.attack_id)
            if attack is not None:
                pressure = self.attack_pressure_value_for_attack(
                    attack,
                    retained.outcome,
                    retained.can_continue_attack is True,
                )
        return replace(
            base,
            development_value=target_policy.development_value,
            recommended_target_id=recommended.target_id,
            reachable_attack_id=reachable_attack_id,
            reachable_damage=reachable_damage,
            reachable_can_continue_attack=(
                reachable_can_continue_attack
            ),
            reachable_attack_pressure=pressure,
            reasons=base.reasons + retained_reasons + (
                f"poke_pad_reachable_{recommended.reachable_pipeline_state}",
                f"poke_pad_target_{target_policy.role}",
            ),
        )

    def best_boss_play_semantic_outcome(self) -> Optional[ImmediateOutcome]:
        scored = tuple(
            (
                self.score_boss_outcome(outcome),
                outcome,
            )
            for outcome in (
                self.outcome.evaluate_boss_target(target)
                for target in self.b.opp_bench
            )
        )
        if not scored:
            return None
        score, outcome = max(scored, key=lambda item: item[0])
        if (
            score <= 0
            or not outcome.supported
            or outcome.blocked
            or not (outcome.avoids_wall or outcome.breaks_engine)
        ):
            return None
        return outcome

    def best_suguri_switch_play_outcome(self) -> Optional[ImmediateOutcome]:
        active_data = self.b.data(self.b.pid(self.b.active))
        if active_data is None or active_data.basic:
            return None
        scored = tuple(
            (
                self.score_switch_target_outcome(outcome, "suguri"),
                outcome,
            )
            for outcome in (
                self.outcome.evaluate_switch_target(target, "suguri")
                for target in self.b.bench
            )
        )
        if not scored:
            return None
        score, outcome = max(scored, key=lambda item: item[0])
        if (
            score <= 0
            or not outcome.supported
            or not (
                outcome.reachable_wins_game
                or outcome.enables_knockout
                or outcome.improves_damage
                or outcome.enables_attack
            )
        ):
            return None
        return outcome

    def resolved_outcome_for_option(
        self,
        option: Any,
        raw_outcome: ImmediateOutcome,
    ) -> ImmediateOutcome:
        cache_key = id(option)
        cached = self._resolved_outcome_cache.get(cache_key)
        if cached is not None:
            return cached

        resolved = raw_outcome
        cid = self.b.option_card(option)
        if (
            option.type == OptionType.PLAY
            and cid == BEFEHL_VON_BOSS
            and raw_outcome.reasons == ("boss_play_no_reachable_prize_attack",)
        ):
            planned = self.best_boss_play_semantic_outcome()
            if planned is not None:
                resolved = replace(
                    planned,
                    reachable_damage=planned.damage,
                )
        elif (
            option.type == OptionType.PLAY
            and cid == SUGURI
            and not (
                raw_outcome.reachable_wins_game
                or raw_outcome.reachable_knockout
            )
        ):
            planned = self.best_suguri_switch_play_outcome()
            if planned is not None:
                resolved = planned
        elif option.type == OptionType.PLAY and cid == POKE_PAD:
            resolved = self.poke_pad_play_outcome(
                option,
                base=raw_outcome,
            )
        elif option.type == OptionType.PLAY and cid == SURFING_BEACH:
            planned = self.best_surfing_beach_play_outcome(option)
            if planned is not None:
                resolved = planned
        elif (
            option.type == OptionType.ABILITY
            and self.outcome.is_surfing_beach_ability(option)
        ):
            planned = self.recommended_surfing_beach_outcome(option)
            if planned is not None:
                resolved = planned
        else:
            target = self.b.option_target(option)
            if (
                target is not None
                and self.effect_id() == SURFING_BEACH
                and (
                    "surfing_beach_switch_requires_policy_resolution"
                    in raw_outcome.reasons
                )
            ):
                planned = (
                    self.recommended_surfing_beach_outcome_for_target(
                        target
                    )
                )
                if planned is not None:
                    resolved = planned

        self._resolved_outcome_cache[cache_key] = resolved
        return resolved

    def action_score(self, option: Any, legacy_score: float, outcome: ImmediateOutcome) -> ActionScore:
        if legacy_score <= SCORE_FORBIDDEN // 2:
            return ActionScore(TIER_FORBIDDEN, legacy=legacy_score)
        if option.type == OptionType.ATTACK or option.attackId is not None:
            return self.attack_action_score(option, legacy_score, outcome)
        cid = self.b.option_card(option)
        if (
            self.b.select.context == SelectContext.MAIN
            and option.type == OptionType.ATTACH
            and cid == IGNITION_ENERGY
            and not self.ignition_has_same_turn_unique_value(option, outcome)
        ):
            return ActionScore(
                TIER_BLOCKED_OR_BAD_ACTION,
                legacy=legacy_score,
            )
        is_surfing_beach_play = (
            option.type == OptionType.PLAY
            and cid == SURFING_BEACH
        )
        is_surfing_beach_ability = (
            option.type == OptionType.ABILITY
            and self.outcome.is_surfing_beach_ability(option)
        )
        if is_surfing_beach_play or is_surfing_beach_ability:
            surfing_overwrite_value = bool(
                is_surfing_beach_play
                and legacy_score > 0
                and self.outcome.is_surfing_beach_play_ability_available(option)
            )
            planned = (
                outcome
                if outcome.supported and outcome.target_id is not None
                else self._surfing_beach_entry_outcome_cache.get(
                    (id(option), is_surfing_beach_play)
                )
            )
            if planned is None:
                if surfing_overwrite_value:
                    return ActionScore(
                        TIER_LOW_VALUE_ACTION,
                        resource=max(0, legacy_score),
                    )
                return ActionScore(
                    TIER_FORBIDDEN,
                    risk=1,
                    legacy=legacy_score,
                )
            pressure = self.surfing_beach_candidate_pressure(planned)
            if planned.reachable_wins_game or planned.reachable_knockout:
                return ActionScore(
                    TIER_PRESERVE_WIN_OR_KO_PREP,
                    immediate=planned.reachable_prizes_taken,
                    pressure=pressure,
                    legacy=legacy_score,
                )
            useful_non_ko_switch = (
                planned.enables_attack
                or planned.improves_damage
                or "survival_retreat" in planned.reasons
                or "role_handoff" in planned.reasons
            )
            if useful_non_ko_switch and (
                pressure > 0
                or "survival_retreat" in planned.reasons
            ):
                return ActionScore(
                    TIER_HIGH_VALUE_PREP,
                    pressure=pressure,
                    legacy=legacy_score,
                )
            if surfing_overwrite_value:
                return ActionScore(
                    TIER_LOW_VALUE_ACTION,
                    resource=max(0, legacy_score),
                )
            return ActionScore(
                TIER_BLOCKED_OR_BAD_ACTION,
                pressure=pressure,
                risk=1,
                legacy=legacy_score,
            )
        surfing_switch_target = (
            self.b.option_target(option)
            if self.effect_id() == SURFING_BEACH
            else None
        )
        if surfing_switch_target is not None:
            planned = (
                outcome
                if outcome.supported and outcome.target_id is not None
                else None
            )
            if planned is None:
                return ActionScore(
                    TIER_FORBIDDEN,
                    risk=1,
                    legacy=legacy_score,
                )
            pressure = self.surfing_beach_candidate_pressure(planned)
            if planned.reachable_wins_game or planned.reachable_knockout:
                return ActionScore(
                    TIER_PRESERVE_WIN_OR_KO_PREP,
                    immediate=planned.reachable_prizes_taken,
                    pressure=pressure,
                    legacy=legacy_score,
                )
            if (
                planned.enables_attack
                or planned.improves_damage
                or "survival_retreat" in planned.reasons
                or "role_handoff" in planned.reasons
            ):
                return ActionScore(
                    TIER_HIGH_VALUE_PREP,
                    pressure=pressure,
                    legacy=legacy_score,
                )
            return ActionScore(
                TIER_BLOCKED_OR_BAD_ACTION,
                pressure=pressure,
                risk=1,
                legacy=legacy_score,
            )
        if option.type == OptionType.ATTACH and cid == HERO_CAPE:
            if not outcome.supported:
                return ActionScore(
                    TIER_BLOCKED_OR_BAD_ACTION,
                    legacy=legacy_score,
                )
            if outcome.next_knockout_avoided:
                return ActionScore(
                    TIER_HIGH_VALUE_PREP,
                    legacy=legacy_score,
                )
            return ActionScore(
                TIER_BLOCKED_OR_BAD_ACTION,
                legacy=legacy_score,
            )
        if (
            option.type == OptionType.PLAY
            and cid == TANKER
        ) or (
            self.effect_id() == TANKER
            and cid is not None
        ):
            candidate = self.night_stretcher_candidate_for_option(option)
            if candidate is None:
                return ActionScore(TIER_BLOCKED_OR_BAD_ACTION)
            development = self.night_stretcher_development_value(candidate)
            if candidate.returns_to_hand_only:
                return ActionScore(
                    TIER_BLOCKED_OR_BAD_ACTION,
                    resource=1,
                    legacy=self.night_stretcher_identity_tiebreak(candidate),
                )
            if self.night_stretcher_is_deferred_until_evolution(candidate):
                return ActionScore(
                    TIER_LOW_VALUE_ACTION,
                    resource=1,
                    legacy=self.night_stretcher_identity_tiebreak(candidate),
                )
            return ActionScore(
                TIER_HIGH_VALUE_PREP if self.night_stretcher_is_concrete_same_turn(candidate) else TIER_LOW_VALUE_ACTION,
                development=development,
                legacy=self.night_stretcher_identity_tiebreak(candidate),
            )
        if option.type == OptionType.PLAY and cid == POKE_PAD:
            planned = outcome
            if not planned.supported or planned.development_value <= 0:
                return ActionScore(
                    TIER_BLOCKED_OR_BAD_ACTION,
                    risk=1,
                    legacy=legacy_score,
                )
            if planned.reachable_attack_id is not None:
                return ActionScore(
                    TIER_NON_KO_ATTACK,
                    pressure=planned.reachable_attack_pressure,
                    development=planned.development_value,
                )
            return ActionScore(
                TIER_LOW_VALUE_ACTION,
                development=planned.development_value,
            )
        if self.effect_id() == POKE_PAD and cid is not None:
            facts = self.b.poke_pad_target_facts(
                cid,
                visible_search_candidate=True,
            )
            if facts is None:
                return ActionScore(TIER_FORBIDDEN)
            target_policy = self.poke_pad_target_policy(facts)
            if facts.setup_only_target or not facts.same_turn_deployable:
                return ActionScore(
                    TIER_LOW_VALUE_ACTION,
                    risk=1,
                )
            return ActionScore(
                TIER_LOW_VALUE_ACTION,
                development=target_policy.development_value,
            )
        is_wally_action = (
            option.type == OptionType.PLAY and cid == WALLY_COMPASSION
        ) or (
            self.effect_id() == WALLY_COMPASSION
            and self.b.option_target(option) is not None
        )
        if is_wally_action and outcome.supported:
            if self.wally_preservation_is_high_value(outcome):
                return ActionScore(
                    TIER_HIGH_VALUE_PREP,
                    immediate=outcome.prizes_preserved,
                    pressure=int(outcome.avoids_board_out),
                    development=outcome.healed_damage,
                    resource=outcome.recovered_energy_count,
                    risk=outcome.board_energy_removed,
                    legacy=legacy_score,
                )
            if legacy_score >= 0:
                return ActionScore(
                    TIER_LOW_VALUE_ACTION,
                    legacy=legacy_score,
                )
        if option.type == OptionType.PLAY and cid == SALVATORE and legacy_score >= 0 and not (
            outcome.reachable_attack_id is not None
            or outcome.expected_reachable_attack_id is not None
            or outcome.avoids_board_out
        ):
            return ActionScore(
                TIER_LOW_VALUE_ACTION,
                development=(
                    0
                    if (
                        outcome.equivalent_evolution_available
                        or self.has_competing_current_development_option()
                    )
                    else outcome.development_value
                ),
                resource=0,
                legacy=legacy_score,
            )
        handoff_pressure_score = self.cinderace_handoff_pressure_score(outcome, legacy_score)
        if handoff_pressure_score is not None:
            return handoff_pressure_score
        if outcome.supported and outcome.wins_game:
            return ActionScore(TIER_WIN, immediate=outcome.prizes_taken, legacy=legacy_score)
        if outcome.supported and outcome.knockout:
            return ActionScore(TIER_KO, immediate=outcome.prizes_taken, pressure=outcome.damage, legacy=legacy_score)
        if outcome.supported and outcome.reachable_wins_game:
            return ActionScore(
                TIER_PRESERVE_WIN_OR_KO_PREP,
                immediate=outcome.reachable_prizes_taken,
                pressure=outcome.reachable_damage,
                resource=max(0, min(legacy_score, 200000)),
                risk=outcome.retreat_energy_cost * 18000 + outcome.important_energy_loss * 70000,
                legacy=legacy_score,
            )
        if outcome.supported and outcome.reachable_knockout:
            return ActionScore(
                TIER_PRESERVE_WIN_OR_KO_PREP,
                immediate=outcome.reachable_prizes_taken,
                pressure=outcome.reachable_damage,
                resource=max(0, min(legacy_score, 200000)),
                risk=outcome.retreat_energy_cost * 18000 + outcome.important_energy_loss * 70000,
                legacy=legacy_score,
            )
        if (
            option.type == OptionType.PLAY
            and cid == BEFEHL_VON_BOSS
            and outcome.supported
            and legacy_score > 0
            and (outcome.avoids_wall or outcome.breaks_engine)
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                pressure=outcome.reachable_damage,
                legacy=legacy_score,
            )
        if (
            option.type == OptionType.PLAY
            and cid == SUGURI
            and outcome.supported
            and legacy_score > 0
            and "suguri_switch" in outcome.reasons
            and (outcome.enables_attack or outcome.improves_damage)
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                pressure=outcome.reachable_damage,
                legacy=legacy_score,
            )
        if (
            option.type == OptionType.PLAY
            and cid == JUDGE
            and self.judge_dead_hand_recovery_live()
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                legacy=legacy_score,
            )
        if (
            option.type == OptionType.RETREAT
            and outcome.supported
            and not outcome.blocked
            and legacy_score > 0
            and (
                outcome.improves_damage
                or "survival_retreat" in outcome.reasons
            )
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                legacy=legacy_score,
            )
            
        if (
            option.type == OptionType.PLAY
            and cid == SALVATORE
            and outcome.supported
            and (
                outcome.avoids_board_out
                or (
                    outcome.reachable_attack_id is not None
                    and outcome.improves_damage
                )
            )
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                pressure=outcome.reachable_damage,
                development=outcome.development_value,
                legacy=legacy_score,
            )
        if (
            outcome.supported
            and outcome.expected_reachable_attack_id is not None
            and (
                outcome.expected_reachable_wins_game
                or outcome.expected_reachable_knockout
                or (
                    option.type == OptionType.PLAY
                    and cid == SALVATORE
                    and outcome.improves_damage
                )
            )
            and self.expected_search_chain_is_high_value(outcome)
        ):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                immediate=outcome.expected_reachable_prizes_taken,
                pressure=outcome.expected_reachable_damage,
                resource=max(0, min(legacy_score, 200000)),
                legacy=legacy_score,
            )
        attach_pressure_score = self.active_attach_reachable_pressure_score(option, legacy_score, outcome)
        if attach_pressure_score is not None:
            return attach_pressure_score
        bench_water_pressure_score = self.bench_water_attach_reachable_pressure_score(
            option, legacy_score, outcome
        )
        if bench_water_pressure_score is not None:
            return bench_water_pressure_score
        if self.water_attach_is_exact_no_op(option, legacy_score, outcome):
            return ActionScore(
                TIER_BLOCKED_OR_BAD_ACTION,
                legacy=legacy_score,
            )
        if self.active_evolution_has_clear_attack_improvement(option):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                development=self.prep_development_value(option, legacy_score),
                resource=max(0, min(legacy_score, 200000)),
                legacy=legacy_score,
            )
        if self.is_high_value_attack_preserving_prep(option, legacy_score):
            return ActionScore(
                TIER_HIGH_VALUE_PREP,
                development=self.prep_development_value(option, legacy_score),
                resource=max(0, min(legacy_score, 200000)),
                legacy=legacy_score,
            )
        if (
            self.b.select.context == SelectContext.MAIN
            and legacy_score < 0
            and option.type not in {OptionType.END, OptionType.RETREAT}
        ):
            return ActionScore(TIER_BLOCKED_OR_BAD_ACTION, legacy=legacy_score)
        if legacy_score <= SCORE_LAST_RESORT:
            return ActionScore(TIER_BLOCKED_OR_BAD_ACTION, risk=legacy_score, legacy=legacy_score)
        return ActionScore(TIER_LOW_VALUE_ACTION, resource=max(0, legacy_score), legacy=legacy_score)

    def night_stretcher_candidate_key(self, facts: NightStretcherCandidateFacts) -> Tuple[Any, ...]:
        return (
            not facts.returns_to_hand_only,
            facts.same_turn_attack_enabled,
            facts.same_turn_retreat_enabled,
            facts.board_out_avoided,
            facts.next_attacker_completed,
            facts.same_turn_attack_gap_reduced,
            facts.next_attacker_gap_reduced and facts.same_turn_attach_available,
            facts.same_turn_usable,
            facts.next_attacker_gap_reduced,
            facts.next_turn_evolution_supported,
            -(facts.target_serial if facts.target_serial is not None else 10**9),
        )

    def recommended_night_stretcher_candidate(self) -> Optional[NightStretcherCandidateFacts]:
        facts = self.b.night_stretcher_recovery_facts()
        if not facts:
            return None
        return max(facts, key=self.night_stretcher_candidate_key)

    def night_stretcher_candidate_for_option(self, option: Any) -> Optional[NightStretcherCandidateFacts]:
        if option.type == OptionType.PLAY and self.b.option_card(option) == TANKER:
            return self.recommended_night_stretcher_candidate()
        if self.effect_id() != TANKER:
            return None
        cid = self.b.option_card(option)
        source_cards = self.b.cards_in_area(option.area, option.playerIndex)
        card = None
        if source_cards is not None and option.index is not None and 0 <= option.index < len(source_cards):
            card = source_cards[option.index]
        serial = getattr(card, "serial", getattr(option, "serial", None))
        if cid is None:
            return None
        return self.b.night_stretcher_candidate_facts(
            card if card is not None else SimpleNamespace(id=cid, serial=serial)
        )

    def night_stretcher_development_value(self, facts: NightStretcherCandidateFacts) -> int:
        if facts.returns_to_hand_only:
            return 0
        if facts.same_turn_attack_enabled or facts.same_turn_retreat_enabled:
            return 7
        if facts.board_out_avoided:
            return 6
        if facts.next_attacker_completed:
            return 5
        if facts.same_turn_attack_gap_reduced:
            return 4
        if facts.next_attacker_gap_reduced and facts.same_turn_attach_available:
            return 3
        if facts.next_turn_evolution_supported and facts.same_turn_usable:
            return 2
        if facts.same_turn_usable:
            return 1
        if facts.next_attacker_gap_reduced or facts.next_turn_evolution_supported:
            return 1
        return 0

    def night_stretcher_identity_tiebreak(self, facts: NightStretcherCandidateFacts) -> int:
        return -(facts.target_serial if facts.target_serial is not None else 10**9)

    def night_stretcher_is_concrete_same_turn(self, facts: NightStretcherCandidateFacts) -> bool:
        return any(
            (
                facts.same_turn_attack_gap_reduced,
                facts.same_turn_attack_enabled,
                facts.same_turn_retreat_enabled,
                facts.next_attacker_completed and facts.same_turn_attach_available,
                facts.board_out_avoided,
            )
        )

    def night_stretcher_is_deferred_until_evolution(
        self,
        facts: NightStretcherCandidateFacts,
    ) -> bool:
        if not (
            facts.same_turn_attack_enabled
            or facts.same_turn_attack_gap_reduced
        ):
            return False
        active_data = self.b.data(self.b.pid(self.b.active))
        if active_data is None or not getattr(active_data, "basic", False):
            return False
        return any(
            option.type == OptionType.EVOLVE
            for _, option in self.b.iter_options()
        )

    def night_stretcher_policy_value(self, facts: Optional[NightStretcherCandidateFacts]) -> float:
        if facts is None:
            return -8000
        if facts.returns_to_hand_only:
            return -1000
        if facts.same_turn_attack_enabled:
            return 90000
        if facts.same_turn_retreat_enabled:
            return 88000
        if facts.board_out_avoided:
            return 84000
        if facts.next_attacker_completed:
            return 82000
        if facts.same_turn_attack_gap_reduced:
            return 74000
        if facts.next_attacker_gap_reduced and facts.same_turn_attach_available:
            return 70000
        if facts.same_turn_usable:
            return 52000
        if facts.next_attacker_gap_reduced:
            return 32000
        if facts.next_turn_evolution_supported:
            return 26000
        return -1000

    def wally_preservation_is_high_value(self, outcome: ImmediateOutcome) -> bool:
        return wally_preservation_fact_is_high_value(outcome)

    @staticmethod
    def _played_basic_has_ability(
        card_data: Any,
    ) -> bool:
        for attribute in ("ability", "abilities"):
            value = getattr(card_data, attribute, None)
            if value not in (None, "", (), []):
                return True
        return False

    def _best_current_nonwinning_knockout(
        self,
    ) -> Optional[
        Tuple[Any, ImmediateOutcome, float, int]
    ]:
        candidates: List[
            Tuple[Any, ImmediateOutcome, float, int]
        ] = []

        for index, candidate in self.b.iter_options():
            if (
                candidate.type != OptionType.ATTACK
                and candidate.attackId is None
            ):
                continue

            attack_outcome = self.outcome.evaluate_attack(
                candidate
            )

            if (
                not attack_outcome.supported
                or attack_outcome.blocked
                or not attack_outcome.knockout
                or attack_outcome.wins_game
            ):
                continue

            candidates.append((
                candidate,
                attack_outcome,
                self.score_attack(candidate),
                index,
            ))

        if not candidates:
            return None

        return max(
            candidates,
            key=lambda item: (
                item[1].prizes_taken,
                item[1].damage,
                item[2],
                -item[3],
            ),
        )

    def _basic_play_preserves_current_knockout(
        self,
        option: Any,
        attack_option: Any,
    ) -> bool:
        played_card_id = self.b.option_card(option)
        if played_card_id is None:
            return False

        played_card_data = self.b.data(played_card_id)

        # 場に出した瞬間に公開Abilityが影響するBasicは、
        # この最小修正では安全を証明できないため対象外。
        if (
            played_card_data is None
            or self._played_basic_has_ability(
                played_card_data
            )
        ):
            return False

        attack = self.b.attack(
            attack_option.attackId
        )
        if attack is None:
            return False

        text = _normalized_attack_text(attack)

        # Basic PLAYによって変化するのは、
        # 自分の手札枚数・Bench数・場のPokémon数。
        # それらをdamage入力に使うAttackは対象外にする。
        changed_own_state_markers = (
            "your hand",
            "cards in your hand",
            "your benched pokemon",
            "pokemon on your bench",
            "your pokemon in play",
            "pokemon you have in play",
            "number of your pokemon",
        )

        return not any(
            marker in text
            for marker in changed_own_state_markers
        )


    def best_current_attack_outcome(self) -> Optional[ImmediateOutcome]:
        outcomes: List[ImmediateOutcome] = []
        for _, candidate in self.b.iter_options():
            if candidate.type != OptionType.ATTACK and candidate.attackId is None:
                continue
            outcome = self.outcome.evaluate_attack(candidate)
            if outcome.supported and not outcome.blocked:
                outcomes.append(outcome)
        if not outcomes:
            return None
        return max(outcomes, key=lambda outcome: (outcome.wins_game, outcome.knockout, outcome.prizes_taken, outcome.damage))

    def cinderace_handoff_improves_current_turn(self, outcome: ImmediateOutcome) -> bool:
        if not (
            self.b.pid(self.b.active) == CINDERACE
            and self.b.cinderace_can_accelerate()
            and self.b.has_bench_energy_receiver()
            and "role_handoff" in outcome.reasons
        ):
            return False
        current = self.best_current_attack_outcome()
        if current is not None and current.wins_game:
            return False
        if outcome.reachable_wins_game:
            return True
        current_prizes = current.prizes_taken if current is not None else 0
        if outcome.reachable_prizes_taken > current_prizes:
            return True
        current_knockout = bool(current and current.knockout)
        if outcome.reachable_knockout and not current_knockout:
            return True
        return bool(
            not current_knockout
            and not outcome.reachable_knockout
            and outcome.reachable_attack_id is not None
            and outcome.improves_damage
        )

    def cinderace_handoff_pressure_score(
        self,
        outcome: ImmediateOutcome,
        legacy_score: float,
    ) -> Optional[ActionScore]:
        if not self.cinderace_handoff_improves_current_turn(outcome):
            return None
        risk = outcome.retreat_energy_cost * 18000 + outcome.important_energy_loss * 70000
        if outcome.reachable_wins_game:
            return ActionScore(
                TIER_WIN,
                immediate=outcome.reachable_prizes_taken,
                pressure=outcome.reachable_damage,
                risk=risk,
                legacy=legacy_score,
            )
        if outcome.reachable_knockout:
            return ActionScore(
                TIER_KO,
                immediate=outcome.reachable_prizes_taken,
                pressure=outcome.reachable_damage,
                risk=risk,
                legacy=legacy_score,
            )
        return ActionScore(
            TIER_NON_KO_ATTACK,
            pressure=self.reachable_attack_pressure_value(outcome),
            resource=max(0, min(legacy_score, 200000)),
            risk=risk,
            legacy=legacy_score,
        )

    def expected_search_chain_is_high_value(self, outcome: ImmediateOutcome) -> bool:
        if outcome.expected_hit_probability < 0.25:
            return False
        direct = self.best_current_attack_outcome()
        if direct is not None and (direct.wins_game or direct.knockout):
            return False
        direct_damage = direct.damage if direct is not None else 0
        direct_threshold = direct_damage
        if direct is not None and self.b.opp_active is not None and direct.damage * 2 >= hp_left(self.b.opp_active):
            direct_threshold += 80
        if direct_damage >= 200 and outcome.expected_reachable_prizes_taken < 1.0:
            return False
        expected_value = outcome.expected_reachable_damage + outcome.expected_reachable_prizes_taken * 120
        return expected_value > max(30, direct_threshold)

    def attack_action_score(self, option: Any, legacy_score: float, outcome: ImmediateOutcome) -> ActionScore:
        if not outcome.supported or outcome.blocked:
            return ActionScore(TIER_BLOCKED_OR_BAD_ACTION, risk=legacy_score, legacy=legacy_score)
        if outcome.wins_game:
            return ActionScore(TIER_WIN, immediate=outcome.prizes_taken, pressure=outcome.damage, legacy=legacy_score)
        if outcome.knockout:
            return ActionScore(TIER_KO, immediate=outcome.prizes_taken, pressure=outcome.damage, legacy=legacy_score)
        return ActionScore(
            TIER_NON_KO_ATTACK,
            pressure=self.attack_pressure_value(option, outcome),
            legacy=legacy_score,
        )

    def attack_pressure_value(self, option: Any, outcome: ImmediateOutcome) -> float:
        attack = self.b.attack(option.attackId)
        return self.attack_pressure_value_for_attack(attack, outcome, self.can_continue_same_attack(attack))

    def attack_pressure_value_for_attack(
        self,
        attack: Any,
        outcome: ImmediateOutcome,
        can_continue_attack: bool,
    ) -> float:
        target = self.b.opp_active
        if attack is None or target is None or outcome.damage <= 0:
            return 0
        active_hp = max(1, hp_left(target))
        active_pressure = outcome.damage * 1000
        active_pressure += (outcome.damage / active_hp) * 45000
        if active_hp - outcome.damage <= 100:
            active_pressure += 18000
        if can_continue_attack and outcome.damage * 2 >= active_hp:
            active_pressure += (25000 + self.b.prize_value(target) * 8000) * NEXT_TURN_PRESSURE_DISCOUNT
        bench_pressure = self.bench_attack_pressure_value(attack, can_continue_attack)
        return active_pressure + bench_pressure

    def can_continue_same_attack(self, attack: Any) -> bool:
        active = self.b.active
        return active is not None and self.b.can_pay_attack(active, attack)

    def attack_bench_damage_amount(self, attack: Any) -> int:
        return attack_bench_damage_amount(attack)

    def bench_attack_pressure_value(self, attack: Any, can_continue_attack: Optional[bool] = None) -> float:
        bench_damage = self.attack_bench_damage_amount(attack)
        if bench_damage <= 0:
            return 0
        if can_continue_attack is None:
            can_continue_attack = self.can_continue_same_attack(attack)
        best = 0.0
        for target in self.b.opp_bench:
            target_id = self.b.pid(target)
            target_hp = max(1, hp_left(target))
            important = (
                target_id in self.b.plan_pressure_targets()
                or target_id in LUCARIO_ENGINE
                or target_id in DURALUDON_LINE
                or target_id in CRUSTLE_LINE
                or target_id in EX_ATTACK_WALLS
                or target_id in ALAKAZAM_LINE
                or target_id in DREEPY_LINE
                or target_id in {DRAGAPULT_EX, BUDEW, SHAYMIN}
            )
            value = bench_damage * (450 if important else 120)
            value += (bench_damage / target_hp) * (45000 if important else 8000)
            if bench_damage >= target_hp:
                value += 60000 + self.b.prize_value(target) * 12000
            if can_continue_attack and bench_damage * 2 >= target_hp:
                value += (50000 + self.b.prize_value(target) * 12000) * NEXT_TURN_PRESSURE_DISCOUNT
            if important:
                value += 12000
            best = max(best, value)
        return best

    def active_attach_reachable_pressure_score(
        self,
        option: Any,
        legacy_score: float,
        outcome: ImmediateOutcome,
    ) -> Optional[ActionScore]:
        if option.type != OptionType.ATTACH or self.b.option_target(option) is not self.b.active:
            return None
        if not outcome.supported or outcome.reachable_attack_id is None:
            return None
        if outcome.reachable_attack_id not in outcome.enabled_attack_ids:
            return None
        if outcome.reachable_wins_game or outcome.reachable_knockout or outcome.reachable_prizes_taken > 0:
            return None
        reachable_pressure = self.reachable_attack_pressure_value(outcome)
        current_pressure = self.best_current_non_ko_attack_pressure()
        if current_pressure is None or reachable_pressure <= current_pressure:
            return None
        return ActionScore(
            TIER_NON_KO_ATTACK,
            pressure=reachable_pressure,
            resource=max(0, min(legacy_score, 200000)),
            legacy=legacy_score,
        )

    def bench_water_attach_reachable_pressure_score(
        self,
        option: Any,
        legacy_score: float,
        outcome: ImmediateOutcome,
    ) -> Optional[ActionScore]:
        target = self.b.option_target(option)
        if (
            option.type != OptionType.ATTACH
            or self.b.option_card(option) != BASIC_WATER_ENERGY
            or target is None
            or target is self.b.active
            or target not in self.b.bench
        ):
            return None
        if not outcome.supported or outcome.blocked or outcome.reachable_attack_id is None:
            return None
        if outcome.reachable_attack_id not in outcome.enabled_attack_ids:
            return None
        if not any(
            reason in outcome.reasons
            for reason in {
                "attach_access_via_retreat",
                "attach_access_via_surfing_beach",
            }
        ):
            return None
        if (
            outcome.reachable_wins_game
            or outcome.reachable_knockout
            or outcome.reachable_prizes_taken > 0
        ):
            return None
        reachable_pressure = self.reachable_attack_pressure_value(outcome)
        current_pressure = self.best_current_non_ko_attack_pressure()
        if current_pressure is None or reachable_pressure <= current_pressure:
            return None
        return ActionScore(
            TIER_NON_KO_ATTACK,
            pressure=reachable_pressure,
            resource=max(0, min(legacy_score, 200000)),
            legacy=legacy_score,
        )

    def water_attach_is_exact_no_op(
        self,
        option: Any,
        legacy_score: float,
        outcome: ImmediateOutcome,
    ) -> bool:
        return (
            self.b.select.context == SelectContext.MAIN
            and legacy_score <= 0
            and option.type == OptionType.ATTACH
            and self.b.option_card(option) == BASIC_WATER_ENERGY
            and outcome.supported
            and not outcome.blocked
            and not outcome.enables_attack
            and not outcome.enabled_attack_ids
            and outcome.reachable_attack_id is None
            and outcome.reachable_damage == 0
            and not outcome.reachable_knockout
            and outcome.reachable_prizes_taken == 0
            and not outcome.reachable_wins_game
            and not outcome.improves_damage
            and not outcome.knockout
            and not outcome.wins_game
            and outcome.damage == 0
            and outcome.reasons == ("no_new_attack",)
        )

    def reachable_attack_pressure_value(self, outcome: ImmediateOutcome) -> float:
        attack = self.b.attack(outcome.reachable_attack_id)
        if attack is None:
            return 0
        pressure_outcome = ImmediateOutcome(
            supported=outcome.supported,
            blocked=outcome.blocked,
            damage=outcome.reachable_damage,
            knockout=outcome.reachable_knockout,
            prizes_taken=outcome.reachable_prizes_taken,
            wins_game=outcome.reachable_wins_game,
            target_id=outcome.target_id,
            target_serial=outcome.target_serial,
            reasons=outcome.reasons,
        )
        return self.attack_pressure_value_for_attack(
            attack,
            pressure_outcome,
            outcome.reachable_can_continue_attack,
        )

    def best_current_non_ko_attack_pressure(self) -> Optional[float]:
        best: Optional[float] = None
        for _, option in self.b.iter_options():
            attack_id = getattr(option, "attackId", None)
            if getattr(option, "type", None) != OptionType.ATTACK or attack_id is None:
                continue
            outcome = self.outcome.evaluate_attack(option)
            if not outcome.supported or outcome.blocked or outcome.knockout or outcome.wins_game:
                return None
            value = self.attack_pressure_value(option, outcome)
            best = value if best is None else max(best, value)
        return best

    def has_current_non_ko_attack_option(self) -> bool:
        for _, option in self.b.iter_options():
            if option.type != OptionType.ATTACK and option.attackId is None:
                continue
            outcome = self.outcome.evaluate_attack(option)
            if outcome.supported and not outcome.blocked and not outcome.knockout and not outcome.wins_game:
                return True
        return False

    def current_attack_outcomes(self) -> Tuple[ImmediateOutcome, ...]:
        outcomes = []
        for _, option in self.b.iter_options():
            if option.type != OptionType.ATTACK and option.attackId is None:
                continue
            outcomes.append(self.outcome.evaluate_attack(option))
        return tuple(outcomes)

    def active_evolution_has_clear_attack_improvement(self, option: Any) -> bool:
        if option.type != OptionType.EVOLVE or self.b.option_target(option) is not self.b.active:
            return False

        evolved_facts = tuple(fact for fact in self.b.active_evolution_attack_facts(option) if fact.supported)
        unblocked_evolved = tuple(fact for fact in evolved_facts if not fact.blocked)
        if not unblocked_evolved:
            return False

        current_outcomes = self.current_attack_outcomes()
        if any(outcome.supported and not outcome.blocked and (outcome.wins_game or outcome.knockout) for outcome in current_outcomes):
            return False

        current_supported = tuple(outcome for outcome in current_outcomes if outcome.supported)
        current_best_damage = max(
            (
                outcome.damage
                for outcome in current_supported
                if not outcome.blocked and not outcome.knockout and not outcome.wins_game
            ),
            default=0,
        )
        current_has_only_blocked_attacks = bool(current_supported) and not any(
            not outcome.blocked for outcome in current_supported
        )

        if any(fact.wins_game for fact in unblocked_evolved):
            return True
        if any(fact.knockout for fact in unblocked_evolved):
            return True
        if current_has_only_blocked_attacks:
            return True

        evolved_best_damage = max((fact.damage for fact in unblocked_evolved), default=0)
        return evolved_best_damage >= current_best_damage + ACTIVE_EVOLVE_CLEAR_DAMAGE_GAIN
    

    
    def is_high_value_attack_preserving_prep(self, option: Any, legacy_score: float) -> bool:
        if legacy_score <= 0 or not self.has_current_non_ko_attack_option():
            return False
        if option.type == OptionType.PLAY:
            cid = self.b.option_card(option)
            if cid in {
                BEFEHL_VON_BOSS,
                SURFING_BEACH,
                WALLY_COMPASSION,
                SALVATORE,
                ULTRA_BALL,
            }:
                return False
            return legacy_score >= 50000
        
        
        if option.type == OptionType.EVOLVE:
            target = self.b.option_target(option)
            return target is not None and target is not self.b.active and legacy_score >= 50000
        return False

    def has_competing_current_development_option(self) -> bool:
        for _, option in self.b.iter_options():
            if (
                option.type == OptionType.PLAY
                and self.b.is_basic_pokemon(self.b.option_card(option))
                and self.score_pokemon_play(self.b.option_card(option))
                > SCORE_FORBIDDEN
            ):
                return True
            if option.type == OptionType.EVOLVE:
                return True
            if option.type == OptionType.ATTACH:
                attach_outcome = self.outcome.evaluate_attach(option)
                if (
                    attach_outcome.supported
                    and (
                        attach_outcome.enables_attack
                        or attach_outcome.enables_knockout
                        or attach_outcome.improves_damage
                    )
                ):
                    return True
        return False

    def prep_development_value(self, option: Any, legacy_score: float) -> float:
        if option.type == OptionType.EVOLVE:
            return max(legacy_score, 120000)
        if option.type == OptionType.PLAY:
            return min(max(legacy_score, 60000), 260000)
        return max(0, legacy_score)
    def score_promotion_target(self, option: Any) -> float:
        target = self.b.option_target(option)
        if target is None or target not in self.b.bench:
            return SCORE_FORBIDDEN

        candidate_states: Dict[int, Tuple[bool, int, int]] = {}
        ready_candidate_exists = False
        reachable_candidate_exists = False

        for _, candidate in self.b.iter_options():
            candidate_target = self.b.option_target(candidate)
            if (
                candidate_target is None
                or candidate_target not in self.b.bench
            ):
                continue

            candidate_role = self.b.role_facts(candidate_target)
            candidate_damage = self.outcome._best_unblocked_damage_from(
                candidate_target
            )
            candidate_ready = bool(
                candidate_role.ready_if_promoted
                and candidate_damage > 0
            )
            reachable_damage = 0

            if not candidate_ready and not bool(
                getattr(candidate_target, "appearThisTurn", False)
            ):
                for evolution_id in tuple(dict.fromkeys(self.b.hand_ids)):
                    if not self.b.evolves_from(evolution_id, candidate_target):
                        continue
                    projected = object.__new__(BoardView)
                    projected.__dict__.update(self.b.__dict__)
                    projected.active = candidate_target
                    projected.bench = [
                        pokemon
                        for pokemon in self.b.bench
                        if pokemon is not candidate_target
                    ]
                    projected.all_my_pokemon = [candidate_target] + list(
                        projected.bench
                    )
                    projected.me = SimpleNamespace(**vars(self.b.me))
                    projected.me.active = [candidate_target]
                    projected.me.bench = list(projected.bench)
                    evolution_option = SimpleNamespace(
                        type=OptionType.EVOLVE,
                        cardId=evolution_id,
                        attackId=None,
                        area=None,
                        index=None,
                        playerIndex=self.b.my_index,
                        inPlayArea=AreaType.ACTIVE,
                        inPlayIndex=0,
                        toolIndex=None,
                        energyIndex=None,
                        serial=None,
                        number=None,
                    )
                    reachable_damage = max(
                        reachable_damage,
                        max(
                            (
                                fact.damage
                                for fact in projected.active_evolution_attack_facts(
                                    evolution_option
                                )
                                if fact.supported
                                and not fact.blocked
                                and fact.damage > 0
                            ),
                            default=0,
                        ),
                    )

            candidate_states[id(candidate_target)] = (
                candidate_ready,
                candidate_damage,
                reachable_damage,
            )
            ready_candidate_exists = ready_candidate_exists or candidate_ready
            reachable_candidate_exists = (
                reachable_candidate_exists or reachable_damage > 0
            )

        target_state = candidate_states.get(id(target))
        if target_state is None:
            return SCORE_FORBIDDEN
        target_ready, target_damage, target_reachable_damage = target_state

        # Actual > exactly reachable > unsupported future expectation.
        if ready_candidate_exists:
            if not target_ready:
                return SCORE_LAST_RESORT
            selected_damage = target_damage
        elif reachable_candidate_exists:
            if target_reachable_damage <= 0:
                return SCORE_LAST_RESORT
            selected_damage = target_reachable_damage
        else:
            # No combat evidence: keep the existing stable fallback.
            return self.score_card_selection(option)

        knockout_bonus = (
            SCORE_PREFERRED // 4
            if (
                self.b.opp_active is not None
                and selected_damage >= hp_left(self.b.opp_active)
            )
            else 0
        )

        return (
            SCORE_PREFERRED // 2
            + knockout_bonus
            + selected_damage * 1000
            + hp_left(target)
        )

    def score_setup(self, option: Any) -> float:
        cid = self.b.option_card(option)
        if self.b.select.context == SelectContext.SETUP_ACTIVE_POKEMON:
            if cid == CINDERACE and self.b.cinderace_setup_role_live():
                return SCORE_FORCED + 5000
            if cid == HITODEMAN:
                return 9000
            if cid == YUKIWARASHI:
                return 7600
            if cid == YVELTAL:
                return 4200
            if cid == SHAYMIN:
                return 2500
            return self.basic_score(cid)
        if cid == CINDERACE:
            return SCORE_FORBIDDEN
        if cid == HITODEMAN:
            return 9000
        if cid == YUKIWARASHI:
            return 7600 if self.b.count_in_play(HITODEMAN) > 0 else 6200
        if cid == SHAYMIN and self.b.needs_shaymin_bench_guard():
            return 12000
        if cid == YVELTAL:
            return 3000
        return self.basic_score(cid)

    def basic_score(self, cid: Optional[int]) -> float:
        if not self.b.is_basic_pokemon(cid):
            return SCORE_FORBIDDEN
        data = self.b.data(cid)
        return 1000 + (0 if data is None else data.hp)

    def score_attack(self, option: Any) -> float:
        attack = self.b.attack(option.attackId)
        if attack is None:
            return SCORE_FORBIDDEN
        outcome = self.outcome.evaluate_attack(option)
        if not outcome.supported:
            return SCORE_FORBIDDEN
        attacker = self.b.active
        if outcome.blocked:
            if self.has_effective_attack_option() or self.has_real_development_option():
                return SCORE_FORBIDDEN
            return SCORE_LAST_RESORT + 100
        score = SCORE_PREFERRED + outcome.damage * 100

        if outcome.wins_game:
            return SCORE_FORCED + 500000
        if outcome.knockout:
            score += SCORE_FORCED // 2 + outcome.prizes_taken * 120000
        if self.b.pid(attacker) in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX} and not outcome.knockout and not self.b.bench:
            if any(card in self.b.hand_ids for card in {POFIN, TANKER, ULTRA_BALL, POKEGEAR, LILLIE_DETERMINATION}):
                return 40000 + outcome.damage * 100
        if self.b.pid(attacker) in {SHAYMIN, YUKIMENOKO} and not outcome.knockout and self.has_real_development_option():
            return 2000 + outcome.damage * 100
        if attack.attackId in {WATER_GUN, CHILLY} and not outcome.knockout and self.has_real_development_option():
            if outcome.target_id == BUDEW:
                return 180000 + outcome.damage * 100
            if not self.b.bench:
                return 2000 + outcome.damage * 100
            return 30000 + outcome.damage * 100
        if self.b.active_has_ignition():
            score += SCORE_FORCED // 3
            if attack.attackId in {NEBULA_BEAM, ABSOLUTE_SNOW}:
                score += SCORE_FORCED // 3
        if attack.attackId == TURBO_FLARE:
            if self.b.has_bench_energy_receiver():
                if any(card in self.b.hand_ids for card in {POFIN, ULTRA_BALL, POKEGEAR, SALVATORE, MEGA_SIGNAL, LILLIE_DETERMINATION, CRISPIN, TANKER}):
                    return 50000
                turbo_score = SCORE_PREFERRED + 100000
                if self.b.count_in_play(MEGA_STARMIE_EX) == 0 and self.b.count_in_play(MEGA_YUKIMENOKO_EX) == 0:
                    turbo_score += 120000
                if not any(card in self.b.hand_ids for card in {ULTRA_BALL, SALVATORE, MEGA_STARMIE_EX}):
                    turbo_score += 70000
                return turbo_score
            return 0
        if attack.attackId in self.b.plan_attack_ids():
            score += 45000
        if attack.attackId == NEBULA_BEAM:
            score += 120000
            if self.b.opponent_profile() in {"STEEL", "WALL", "LUCARIO"}:
                score += 220000
            if self.b.opp_active is not None and self.b.pid(self.b.opp_active) in EX_ATTACK_WALLS | DURALUDON_LINE:
                score += 260000
        if attack.attackId == JETTING_BLOW:
            score += 90000
            if any(a.attackId == NEBULA_BEAM for a in self.b.legal_attack_options()) and self.b.opponent_profile() in {"STEEL", "WALL"} and not outcome.knockout:
                score -= 180000
            if self.b.opponent_profile() in {"STEEL", "WALL"} and not outcome.knockout and self.has_active_nebula_enabling_attach_option():
                score = min(score, 250000 + outcome.damage * 100)
        if attack.attackId == RESENTFUL_REFRAIN:
            score += safe_int(self.b.opp.handCount) * 6000
            if self.b.opponent_profile() == "ALAKAZAM":
                score += 140000
        if attack.attackId == ABSOLUTE_SNOW:
            score += 70000
            if self.b.opponent_profile() == "LUCARIO" or self.b.active_in_danger():
                score += 90000
        if attack.attackId in {WATER_GUN, CHILLY} and not outcome.knockout:
            score -= 140000
        if self.b.pid(attacker) in {HITODEMAN, YUKIWARASHI} and not outcome.knockout and self.has_real_development_option():
            score -= 160000
        return score

    def has_effective_attack_option(self) -> bool:
        for _, option in self.b.iter_options():
            if option.type != OptionType.ATTACK and option.attackId is None:
                continue
            outcome = self.outcome.evaluate_attack(option)
            if outcome.supported and not outcome.blocked:
                return True
        return False

    def has_real_development_option(self) -> bool:
        for _, option in self.b.iter_options():
            if option.type in {OptionType.PLAY, OptionType.ATTACH, OptionType.EVOLVE, OptionType.ABILITY}:
                if self.score_main(option) > 3000:
                    return True
        return False

    def score_end(self) -> float:
        if self.b.is_attack_choice_phase() and self.has_effective_attack_option():
            return SCORE_FORBIDDEN
        if self.has_effective_attack_option():
            penalty = SCORE_FORBIDDEN // 2
            if self.b.active_has_ignition():
                penalty = SCORE_FORBIDDEN
            return penalty
        if self.has_real_development_option():
            return SCORE_FORBIDDEN
        return -100

    def score_retreat(self, option: Any) -> float:
        outcome = self.outcome.evaluate_retreat(option)
        if not outcome.supported:
            return SCORE_FORBIDDEN
        score = -8000
        if "retreat_no_target" in outcome.reasons:
            return SCORE_FORBIDDEN
        if (
            self.b.pid(self.b.active) == CINDERACE
            and self.b.cinderace_can_accelerate()
            and self.b.has_bench_energy_receiver()
            and not self.cinderace_handoff_improves_current_turn(outcome)
        ):
            return SCORE_FORBIDDEN
        if outcome.retreat_energy_cost > 0 and not (
            "switch_enables_win" in outcome.reasons
            or outcome.enables_knockout
            or outcome.enables_attack
            or outcome.improves_damage
            or "survival_retreat" in outcome.reasons
            or "role_handoff" in outcome.reasons
        ):
            return SCORE_FORBIDDEN
        if "switch_enables_win" in outcome.reasons:
            return SCORE_FORCED + 400000
        if outcome.enables_knockout:
            score += SCORE_FORCED // 2
        if outcome.enables_attack:
            score += 160000
        if "role_handoff" in outcome.reasons:
            score += 140000
        if outcome.improves_damage:
            score += 90000
        if "survival_retreat" in outcome.reasons:
            score += 90000
        if "retreat_from_ready_attacker" in outcome.reasons and not (
            "survival_retreat" in outcome.reasons
            or outcome.enables_knockout
            or outcome.enables_attack
            or "role_handoff" in outcome.reasons
            or outcome.improves_damage
        ):
            score -= 90000
        score -= outcome.retreat_energy_cost * 18000
        score -= outcome.important_energy_loss * 70000
        return score

    def judge_has_important_non_supporter_action(self) -> bool:
        for _, option in self.b.iter_options():
            cid = self.b.option_card(option)
            if option.type == OptionType.PLAY:
                if self.b.is_supporter(cid):
                    continue
                if self.score_main(option) > 6000:
                    return True
                continue
            if option.type == OptionType.EVOLVE:
                if self.score_evolve(option) > 6000:
                    return True
                continue
            if option.type != OptionType.ATTACH or not self.b.is_energy(cid):
                continue
            outcome = self.outcome.evaluate_attach(option)
            if not outcome.supported:
                continue
            if (
                outcome.enables_attack
                or outcome.enables_knockout
                or outcome.improves_damage
                or self.score_attach(option) > 6000
            ):
                return True
        return False

    def judge_dead_hand_recovery_live(self) -> bool:
        direct = self.best_current_attack_outcome()
        if direct is not None and (direct.wins_game or direct.knockout):
            return False

        important_non_supporter_action = (
            self.judge_has_important_non_supporter_action()
        )
        hand_facts = self.b.hand_activity_facts()
        non_judge_activities = tuple(
            activity
            for card_id, activity in hand_facts.activities
            if card_id != JUDGE
        )
        live_now_card_ids = {
            card_id
            for card_id, activity in hand_facts.activities
            if (
                card_id != JUDGE
                and activity == HAND_ACTIVITY_LIVE_NOW
            )
        }
        live_now_legal_option = any(
            candidate.type
            in {
                OptionType.PLAY,
                OptionType.ATTACH,
                OptionType.EVOLVE,
            }
            and self.b.option_card(candidate) in live_now_card_ids
            for _, candidate in self.b.iter_options()
        )
        if (
            important_non_supporter_action
            or live_now_legal_option
        ):
            return False

        low_activity_count = sum(
            activity == HAND_ACTIVITY_LOW
            for activity in non_judge_activities
        )
        keep_count = sum(
            activity == HAND_ACTIVITY_KEEP
            for activity in non_judge_activities
        )
        activity_iter = iter(non_judge_activities)
        first_activity = next(activity_iter, None)
        small_dead_hand = (
            first_activity in {None, HAND_ACTIVITY_LOW}
            and next(activity_iter, None) is None
        )
        low_activity_dead_hand = (
            low_activity_count > keep_count
        )
        return bool(small_dead_hand or low_activity_dead_hand)

    def score_play(self, option: Any) -> float:
        cid = self.b.option_card(option)
        if cid is None:
            return SCORE_FORBIDDEN
        if self.b.is_supporter(cid) and self.b.state.supporterPlayed:
            return SCORE_FORBIDDEN
        if cid == POFIN:
            if self.b.bench_space <= 0:
                return SCORE_FORBIDDEN
            score = 65000 if self.b.needs_basic() else 9000
            if self.b.opponent_profile() == "LUCARIO":
                score += 18000
            return score
        if cid == SALVATORE:
            if not self.b.salvatore_live():
                return -8000
            return SCORE_PREFERRED + 125000
        if cid == ULTRA_BALL:
            if len(self.b.hand_ids) < 3:
                return -20000
            recommended = self.recommended_ultra_ball_target(
                after_ultra_ball_cost=True
            )
            if recommended is None:
                return -8000
            _facts, target_policy = recommended
            search_value = target_policy.development_value * 40000
            deployable_basic_scores = [
                self.score_pokemon_play(self.b.option_card(candidate))
                for _, candidate in self.b.iter_options()
                if (
                    candidate.type == OptionType.PLAY
                    and self.b.is_basic_pokemon(
                        self.b.option_card(candidate)
                    )
                )
            ]
            meaningful_basic_scores = [
                score
                for score in deployable_basic_scores
                if score > 0
            ]
            if meaningful_basic_scores:
                return min(
                    search_value,
                    max(meaningful_basic_scores) - 1,
                )
            return search_value
        if cid == MEGA_SIGNAL:
            if self.b.needs_mega_starmie() or self.b.needs_mega_yuki():
                return 78000
            return -8000
        if cid == POKE_PAD:
            useful = self.useful_poke_pad_targets()
            return max(
                (target_policy.development_value for _, target_policy in useful),
                default=-8000,
            )
        if cid == POKEGEAR:
            facts = self.b.pokegear_supporter_facts()
            if facts.no_target_confirmed:
                return -8000
            if facts.live_supporter_count > 0:
                return 58000
            if facts.supporter_remaining_possible:
                return 26000
            return 6000
        if cid == LILLIE_DETERMINATION:
            if self.b.state.supporterPlayed:
                return SCORE_FORBIDDEN
            facts = self.b.hand_activity_facts()
            if any(card_id == SALVATORE and activity == HAND_ACTIVITY_LIVE_NOW for card_id, activity in facts.activities):
                return -12000
            if facts.hand_size <= 2 or self.b.needs_basic():
                return 70000
            if facts.hand_size <= 4 and facts.lillie_effect.shuffle_count >= 3:
                return 70000
            if facts.hand_size <= 4 and facts.low_activity_ratio >= 0.5:
                return 70000
            if facts.low_activity_ratio >= 0.8 and facts.lillie_effect.shuffle_count >= 5:
                return 86000
            if facts.low_activity_ratio >= 0.6 and facts.lillie_effect.shuffle_count >= 4:
                return 56000
            if facts.low_activity_ratio <= 0.25 and facts.live_now_count + facts.keep_count >= max(1, facts.hand_size - 1):
                return 8000
            return 16000
        if cid == JUDGE:
            direct = self.best_current_attack_outcome()
            if direct is not None and (direct.wins_game or direct.knockout):
                return 6000

            important_non_supporter_action = (
                self.judge_has_important_non_supporter_action()
            )
            if self.b.opponent_profile() == "ALAKAZAM":
                hand_reduction = max(
                    0,
                    safe_int(getattr(self.b.opp, "handCount", 0)) - 4,
                )
                if (
                    hand_reduction > 0
                    and not important_non_supporter_action
                ):
                    return 40000 + hand_reduction * 12000

            if not self.judge_dead_hand_recovery_live():
                return SCORE_FORBIDDEN
            return 6000
        if cid == SUGURI:
            direct = self.best_current_attack_outcome()
            if direct is not None and (direct.wins_game or direct.knockout):
                return 6000
            boosted = self.outcome.evaluate_suguri_damage_boost()
            if boosted.reachable_knockout:
                return 94000
            if self.best_suguri_switch_play_outcome() is not None:
                return 88000
            return SCORE_FORBIDDEN
        if cid == HILDA:
            if (
                self.b.needs_mega_starmie()
                or self.b.needs_mega_yuki()
                or self.b.starmie_needs_energy()
            ):
                return 62000
            return SCORE_FORBIDDEN
        if cid == CRISPIN:
            facts = self.b.active_energy_facts()
            if facts.key_attack_id is not None and not facts.key_attack_ready:
                missing_types = set(facts.key_attack_missing_types)
                has_required_energy = True
                if EnergyType.WATER in missing_types and not facts.water_remaining_possible:
                    has_required_energy = False
                if EnergyType.DARKNESS in missing_types and not facts.dark_remaining_possible:
                    has_required_energy = False
                if EnergyType.COLORLESS in missing_types and not (facts.water_remaining_possible or facts.dark_remaining_possible):
                    has_required_energy = False
                if has_required_energy:
                    return 82000 if facts.key_attack_missing_units <= 1 else 62000
            return 9000
        if cid == TANKER:
            return self.night_stretcher_policy_value(
                self.recommended_night_stretcher_candidate()
            )
        if cid == WALLY_COMPASSION:
            outcome = self.outcome.evaluate_wally_play(option)
            if outcome.supported and (
                self.b.wally_live()
                or self.wally_preservation_is_high_value(outcome)
            ):
                return self.wally_effect_legacy_value(outcome)
            return -16000
        if cid == BEFEHL_VON_BOSS:
            return self.score_boss()
        if cid == SURFING_BEACH:
            return self.score_surfing_beach_play(option)
        if cid == HERO_CAPE:
            return max(
                (self.score_hero_cape_target(target) for target in self.b.all_my_pokemon),
                default=SCORE_FORBIDDEN,
            )
        if cid == TOOL_SCRAPPER:
            return self.score_tool_scrapper_outcome(self.outcome.evaluate_tool_scrapper_play(option))
        if cid == ENERGY_SWITCH:
            outcome = self.outcome.evaluate_energy_switch_play(option)
            if (
                outcome.additional_card_consumed
                and not outcome.reachable_wins_game
                and not outcome.reachable_knockout
                and outcome.reachable_attack_id is None
            ):
                return -1000 if outcome.equivalent_normal_attach_available else 3000
            return 36000 if self.b.starmie_needs_energy() else 3000
        if self.b.is_pokemon(cid):
            return self.score_pokemon_play(cid)
        if cid in self.b.plan_setup_cards():
            return 15000
        return 0

    def score_hero_cape_target(self, target: Optional[Pokemon]) -> float:
        roi = self.b.hero_cape_target_roi(target)
        if roi == "invalid":
            return SCORE_FORBIDDEN
        if roi == "prevents_active_knockout":
            return 90000 + self.b.prize_value(target) * 20000 + self.b.energy_count(target) * 10000
        return -12000

    def _surfing_beach_candidate_facts(
        self,
        option: Any,
        *,
        after_stadium_play: bool,
    ) -> Tuple[SwitchTargetAttackFacts, ...]:
        key = (id(option), after_stadium_play)
        cached = self._surfing_beach_candidate_cache.get(key)
        if cached is None:
            cached = self.outcome.surfing_beach_candidate_facts(
                option,
                after_stadium_play=after_stadium_play,
            )
            self._surfing_beach_candidate_cache[key] = cached
        return cached

    def _current_attack_candidates(
        self,
    ) -> AttackCandidateCollection:
        if self._current_attack_candidate_cache is None:
            self._current_attack_candidate_cache = (
                self.outcome.current_active_attack_candidates()
            )
        return self._current_attack_candidate_cache

    def _attack_candidate_pressure(
        self,
        candidate: AttackOutcomeCandidate,
    ) -> float:
        attack = self.b.attack(candidate.attack_id)
        return self.attack_pressure_value_for_attack(
            attack,
            candidate.outcome,
            candidate.can_continue_attack is True,
        )

    def _best_attack_candidate(
        self,
        collection: AttackCandidateCollection,
    ) -> Optional[AttackOutcomeCandidate]:
        supported = tuple(
            candidate
            for candidate in collection.candidates
            if candidate.outcome.supported
            and not candidate.outcome.blocked
        )
        if not supported:
            return None
        return max(
            supported,
            key=lambda candidate: (
                candidate.outcome.wins_game,
                candidate.outcome.knockout,
                candidate.outcome.prizes_taken,
                self._attack_candidate_pressure(candidate),
                -candidate.attack_index,
            ),
        )

    def _surfing_beach_target_for_facts(
        self,
        facts: SwitchTargetAttackFacts,
    ) -> Optional[Pokemon]:
        if not 0 <= facts.bench_index < len(self.b.bench):
            return None
        target = self.b.bench[facts.bench_index]
        if (
            self.b.pid(target) != facts.target_id
            or getattr(target, "serial", None)
            != facts.target_serial
        ):
            return None
        return target

    def _surfing_beach_outcome_from_facts(
        self,
        facts: SwitchTargetAttackFacts,
    ) -> ImmediateOutcome:
        target = self._surfing_beach_target_for_facts(facts)
        active = self.b.active
        if target is None or active is None:
            return ImmediateOutcome(
                supported=False,
                reasons=("surfing_beach_target_fact_mismatch",),
            )

        target_candidate = facts.attack_candidate
        target_outcome = (
            target_candidate.outcome
            if target_candidate is not None
            else None
        )
        target_supported = bool(
            target_outcome is not None
            and target_outcome.supported
            and not target_outcome.blocked
        )
        current_collection = self._current_attack_candidates()
        current_candidate = self._best_attack_candidate(
            current_collection
        )
        current_unknown = bool(
            current_candidate is None
            and current_collection.unsupported_reasons
        )
        current_known_no_attack = bool(
            current_candidate is None
            and current_collection.no_legal_attack_confirmed
        )

        target_pressure = (
            self._attack_candidate_pressure(target_candidate)
            if target_candidate is not None and target_supported
            else 0.0
        )
        current_pressure = (
            self._attack_candidate_pressure(current_candidate)
            if current_candidate is not None
            else 0.0
        )
        comparison_supported = not current_unknown
        enables_attack = bool(
            comparison_supported
            and current_known_no_attack
            and target_supported
        )
        improves_pressure = bool(
            comparison_supported
            and current_candidate is not None
            and target_supported
            and target_pressure > current_pressure
        )
        enables_knockout = bool(
            comparison_supported
            and target_supported
            and target_outcome is not None
            and target_outcome.knockout
            and not current_candidate.outcome.knockout
        ) if current_candidate is not None else bool(
            comparison_supported
            and current_known_no_attack
            and target_supported
            and target_outcome is not None
            and target_outcome.knockout
        )
        enables_win = bool(
            comparison_supported
            and target_supported
            and target_outcome is not None
            and target_outcome.wins_game
            and not current_candidate.outcome.wins_game
        ) if current_candidate is not None else bool(
            comparison_supported
            and current_known_no_attack
            and target_supported
            and target_outcome is not None
            and target_outcome.wins_game
        )

        target_damage = (
            target_outcome.damage
            if target_supported and target_outcome is not None
            else 0
        )
        role_handoff = self.outcome._role_handoff(
            active,
            target,
            target_damage,
        )
        reasons: List[str] = [
            "switch_target",
            "surfing_beach_switch",
        ]
        if target_candidate is None:
            if facts.no_legal_attack_confirmed:
                reasons.append("switch_target_no_payable_attack")
            reasons.extend(facts.unsupported_reasons)
        elif not target_supported:
            reasons.extend(target_outcome.reasons)
            reasons.extend(facts.unsupported_reasons)
        if current_unknown:
            reasons.extend(
                (
                    "current_active_attack_unsupported",
                    *current_collection.unsupported_reasons,
                )
            )
        if enables_attack:
            reasons.append("retreat_enables_attack")
        if enables_knockout:
            reasons.append("switch_enables_knockout")
        if enables_win:
            reasons.append("switch_enables_win")
        if improves_pressure:
            reasons.extend(
                (
                    "retreat_improves_damage",
                    "switch_improves_attack_pressure",
                )
            )
        elif comparison_supported:
            reasons.append("retreat_no_damage_improvement")
        if role_handoff:
            reasons.append("role_handoff")
        if facts.survival:
            reasons.append("survival_retreat")
        if (
            target_candidate is not None
            and target_candidate.can_continue_attack is None
        ):
            reasons.append("reachable_attack_continuation_unknown")
        if (
            self.outcome._zero_energy_mega_wall(
                target,
                target_damage,
            )
            and not facts.survival
            and not enables_knockout
        ):
            reasons.append("zero_energy_mega_wall")
        if (
            self.b.pid(active) == CINDERACE
            and self.b.cinderace_can_accelerate()
            and self.b.has_bench_energy_receiver()
        ):
            reasons.append("retreat_from_ready_attacker")

        supported = bool(
            target_supported
            or facts.survival
            or role_handoff
        )
        return ImmediateOutcome(
            supported=supported,
            damage=0,
            knockout=False,
            prizes_taken=0,
            wins_game=False,
            enables_attack=enables_attack,
            enables_knockout=enables_knockout,
            reachable_attack_id=(
                target_candidate.attack_id
                if target_supported and target_candidate is not None
                else None
            ),
            reachable_damage=target_damage,
            reachable_attack_pressure=target_pressure,
            reachable_knockout=bool(
                target_supported
                and target_outcome is not None
                and target_outcome.knockout
            ),
            reachable_prizes_taken=(
                target_outcome.prizes_taken
                if target_supported and target_outcome is not None
                else 0
            ),
            reachable_wins_game=bool(
                target_supported
                and target_outcome is not None
                and target_outcome.wins_game
            ),
            reachable_can_continue_attack=bool(
                target_supported
                and target_candidate is not None
                and target_candidate.can_continue_attack is True
            ),
            improves_damage=improves_pressure,
            target_id=facts.target_id,
            target_serial=facts.target_serial,
            reasons=tuple(dict.fromkeys(reasons)),
        )

    def surfing_beach_candidate_pressure(
        self,
        outcome: ImmediateOutcome,
    ) -> float:
        if not outcome.supported:
            return 0.0
        if outcome.reachable_attack_pressure > 0:
            return outcome.reachable_attack_pressure
        if outcome.reachable_attack_id is None:
            return 0.0
        return self.reachable_attack_pressure_value(outcome)

    def _surfing_beach_tie_key(
        self,
        facts: SwitchTargetAttackFacts,
    ) -> Tuple[int, int]:
        attack_index = (
            facts.attack_candidate.attack_index
            if facts.attack_candidate is not None
            else 10**6
        )
        # Earlier Bench slot and earlier printed attack order match the
        # follow-up SWITCH option order.
        return (-facts.bench_index, -attack_index)

    def _recommended_surfing_beach_outcome(
        self,
        option: Any,
        *,
        after_stadium_play: bool,
        target: Optional[Pokemon] = None,
    ) -> Optional[ImmediateOutcome]:
        cache_key = (id(option), after_stadium_play)
        if (
            target is None
            and cache_key in self._surfing_beach_entry_outcome_cache
        ):
            return self._surfing_beach_entry_outcome_cache[cache_key]
        ranked: List[
            Tuple[float, Tuple[int, int], ImmediateOutcome]
        ] = []
        for facts in self._surfing_beach_candidate_facts(
            option,
            after_stadium_play=after_stadium_play,
        ):
            candidate_target = self._surfing_beach_target_for_facts(
                facts
            )
            if candidate_target is None:
                continue
            if target is not None and candidate_target is not target:
                continue
            outcome = self._surfing_beach_outcome_from_facts(facts)
            if not outcome.supported:
                continue
            ranked.append(
                (
                    self.score_switch_target_outcome(
                        outcome,
                        "surfing_beach",
                    ),
                    self._surfing_beach_tie_key(facts),
                    outcome,
                )
            )
        if not ranked:
            if target is None:
                self._surfing_beach_entry_outcome_cache[cache_key] = None
            return None
        result = max(
            ranked,
            key=lambda item: (item[0], item[1]),
        )[2]
        if target is None:
            self._surfing_beach_entry_outcome_cache[cache_key] = result
        return result

    def best_surfing_beach_play_outcome(
        self,
        option: Any,
    ) -> Optional[ImmediateOutcome]:
        return self._recommended_surfing_beach_outcome(
            option,
            after_stadium_play=True,
        )

    def recommended_surfing_beach_outcome(
        self,
        option: Any,
    ) -> Optional[ImmediateOutcome]:
        return self._recommended_surfing_beach_outcome(
            option,
            after_stadium_play=False,
        )

    def recommended_surfing_beach_outcome_for_target(
        self,
        target: Pokemon,
    ) -> Optional[ImmediateOutcome]:
        active = self.b.active
        if (
            active is None
            or target not in self.b.bench
            or not self.outcome._can_surfing_beach_switch(
                active,
                target,
            )
        ):
            return None
        target_key = id(target)
        if target_key in self._surfing_beach_target_outcome_cache:
            return self._surfing_beach_target_outcome_cache[target_key]
        # During the follow-up SWITCH selection there is no current ABILITY
        # option object to reuse. Build the same target × attack facts with a
        # synthetic legal identity-independent target pass.
        collection = self.outcome.switch_target_attack_candidates(target)
        try:
            bench_index = self.b.bench.index(target)
        except ValueError:
            return None
        facts_list: List[SwitchTargetAttackFacts] = []
        if collection.candidates:
            for candidate in collection.candidates:
                facts_list.append(
                    SwitchTargetAttackFacts(
                        target_id=self.b.pid(target),
                        target_serial=getattr(target, "serial", None),
                        bench_index=bench_index,
                        attack_candidate=candidate,
                        no_legal_attack_confirmed=(
                            collection.no_legal_attack_confirmed
                        ),
                        unsupported_reasons=(
                            collection.unsupported_reasons
                        ),
                        survival=self.outcome._survival_retreat_reason(
                            self.b.active
                        ) if self.b.active is not None else False,
                    )
                )
        else:
            facts_list.append(
                SwitchTargetAttackFacts(
                    target_id=self.b.pid(target),
                    target_serial=getattr(target, "serial", None),
                    bench_index=bench_index,
                    attack_candidate=None,
                    no_legal_attack_confirmed=(
                        collection.no_legal_attack_confirmed
                    ),
                    unsupported_reasons=(
                        collection.unsupported_reasons
                    ),
                    survival=self.outcome._survival_retreat_reason(
                        self.b.active
                    ) if self.b.active is not None else False,
                )
            )
        ranked = []
        for facts in facts_list:
            outcome = self._surfing_beach_outcome_from_facts(facts)
            if not outcome.supported:
                continue
            ranked.append(
                (
                    self.score_switch_target_outcome(
                        outcome,
                        "surfing_beach",
                    ),
                    self._surfing_beach_tie_key(facts),
                    outcome,
                )
            )
        if not ranked:
            self._surfing_beach_target_outcome_cache[target_key] = None
            return None
        result = max(
            ranked,
            key=lambda item: (item[0], item[1]),
        )[2]
        self._surfing_beach_target_outcome_cache[target_key] = result
        return result

    def score_surfing_beach_play(self, option: Any) -> float:
        stadium = getattr(getattr(self.b, "state", None), "stadium", None) or ()
        current = stadium[0] if stadium else None
        current_id = getattr(current, "id", None) if current is not None else None
        if current is not None and current_id is None:
            return 0
        if current_id == SURFING_BEACH:
            return -12000
        if current is not None:
            owner = getattr(current, "playerIndex", None)
            my_index = getattr(
                self.b,
                "my_index",
                getattr(self.b.state, "yourIndex", None),
            )
            if (
                owner is not None
                and my_index is not None
                and int(owner) != int(my_index)
            ):
                return 42000
        return 0

    def score_boss(self) -> float:
        if not self.b.opp_bench:
            return SCORE_FORBIDDEN
        best = SCORE_FORBIDDEN
        for pokemon in self.b.opp_bench:
            best = max(best, self.score_boss_outcome(self.outcome.evaluate_boss_target(pokemon)))
        return best

    def score_boss_outcome(self, outcome: ImmediateOutcome) -> float:
        if not outcome.supported:
            return SCORE_FORBIDDEN
        if outcome.wins_game:
            return SCORE_FORCED + 700000
        score = 0.0
        if outcome.knockout:
            score += SCORE_PREFERRED + outcome.prizes_taken * 140000
        if outcome.avoids_wall and outcome.damage > 0:
            score += 220000
        if outcome.breaks_engine:
            score += 160000
        if outcome.damage > 0:
            score += outcome.damage * 500
        if outcome.target_id == SHAYMIN and self.b.opponent_profile() == "BENCH_DAMAGE":
            score += 20000
        if outcome.reasons == ("boss_target", "boss_no_effective_attack"):
            score -= 50000
        return score

    def score_tool_scrapper_outcome(self, outcome: ImmediateOutcome) -> float:
        if not outcome.supported:
            return -8000
        if outcome.wins_game:
            return SCORE_FORCED + 500000
        if outcome.knockout:
            return SCORE_FORCED // 2 + outcome.prizes_taken * 140000
        if outcome.enables_knockout:
            return SCORE_PREFERRED + 180000
        if "removes_hp_boost_tool" in outcome.reasons:
            return SCORE_PREFERRED + 70000
        if "removes_key_tool" in outcome.reasons:
            return 80000
        if outcome.removes_tool:
            return 22000
        return -8000

    def score_tool_scrapper_target_option(
        self,
        option_index: int,
        option: Any,
    ) -> float:
        facts = self.b.tool_scrapper_target_facts(
            option_index,
            option,
        )
        if (
            facts is None
            or not facts.attached_to_opponent
            or not facts.currently_attached
            or facts.already_selected
        ):
            return SCORE_FORBIDDEN
        target = self.b.option_target(option)
        outcome = self.outcome.evaluate_tool_scrapper_target(
            target,
            facts.tool_index,
        )
        if not outcome.removes_tool:
            return SCORE_FORBIDDEN
        return max(
            1,
            self.score_tool_scrapper_outcome(outcome),
        )

    def score_pokemon_play(self, cid: int) -> float:
        if self.b.bench_space <= 0:
            return SCORE_FORBIDDEN
        if cid == CINDERACE:
            return SCORE_FORBIDDEN
        if cid == HITODEMAN:
            return 72000
        if cid == YUKIWARASHI:
            return 42000 if self.b.opponent_profile() in {"ALAKAZAM", "BENCH_DAMAGE"} else 28000
        if cid == SHAYMIN:
            if self.b.needs_shaymin_bench_guard() and self.b.count_in_play(SHAYMIN) == 0:
                return 105000
            return -10000
        if cid == YVELTAL:
            return 14000
        return 1000

    def ignition_equivalent_water_attach_available(
        self,
        option: Any,
        ignition_outcome: ImmediateOutcome,
    ) -> bool:
        if (
            option.type != OptionType.ATTACH
            or self.b.option_card(option) != IGNITION_ENERGY
            or not ignition_outcome.supported
            or ignition_outcome.blocked
            or ignition_outcome.reachable_attack_id is None
            or ignition_outcome.reachable_attack_id
            not in ignition_outcome.enabled_attack_ids
        ):
            return False
        target = self.b.option_target(option)
        if target is None:
            return False
        equivalent_energy_ids = {BASIC_WATER_ENERGY}
        if self.b.pid(target) == CINDERACE:
            equivalent_energy_ids.add(BASIC_DARK_ENERGY)
        for _, candidate in self.b.iter_options():
            if (
                candidate.type != OptionType.ATTACH
                or self.b.option_card(candidate) not in equivalent_energy_ids
                or self.b.option_target(candidate) is not target
            ):
                continue
            normal_outcome = self.outcome.evaluate_attach(candidate)
            if (
                normal_outcome.supported == ignition_outcome.supported
                and normal_outcome.blocked == ignition_outcome.blocked
                and normal_outcome.target_id == ignition_outcome.target_id
                and normal_outcome.target_serial == ignition_outcome.target_serial
                and normal_outcome.reachable_attack_id
                == ignition_outcome.reachable_attack_id
                and normal_outcome.reachable_attack_id
                in normal_outcome.enabled_attack_ids
                and normal_outcome.reachable_damage
                == ignition_outcome.reachable_damage
                and normal_outcome.reachable_knockout
                == ignition_outcome.reachable_knockout
                and normal_outcome.reachable_wins_game
                == ignition_outcome.reachable_wins_game
                and normal_outcome.reachable_prizes_taken
                == ignition_outcome.reachable_prizes_taken
            ):
                return True
        return False

    def ignition_has_same_turn_unique_value(
        self,
        option: Any,
        attach_outcome: ImmediateOutcome,
    ) -> bool:
        if (
            option.type != OptionType.ATTACH
            or self.b.option_card(option) != IGNITION_ENERGY
            or not attach_outcome.supported
            or attach_outcome.blocked
        ):
            return False
        target = self.b.option_target(option)
        if target is None:
            return False
        if self.b.pid(target) == CINDERACE:
            return bool(
                target is self.b.active
                and self.b.energy_count(target) == 0
                and not self.b.cinderace_can_accelerate()
                and attach_outcome.reachable_attack_id == TURBO_FLARE
                and TURBO_FLARE in attach_outcome.enabled_attack_ids
                and self.has_live_turbo_flare_receiver()
                and self.has_turbo_flare_energy_in_deck()
                and not self.active_status_blocks_attack()
                and not self.ignition_equivalent_water_attach_available(
                    option,
                    attach_outcome,
                )
            )
        if (
            attach_outcome.reachable_attack_id is None
            or attach_outcome.reachable_attack_id
            not in attach_outcome.enabled_attack_ids
        ):
            return False
        return not self.ignition_equivalent_water_attach_available(
            option,
            attach_outcome,
        )

    def score_attach(self, option: Any) -> float:
        cid = self.b.option_card(option)
        target = self.b.option_target(option)
        if cid is None or target is None:
            return SCORE_FORBIDDEN
        target_id = self.b.pid(target)
        if cid == HERO_CAPE:
            return self.score_hero_cape_target(target)
        attach_outcome = self.outcome.evaluate_attach(option)
        if cid in {BASIC_WATER_ENERGY, BASIC_DARK_ENERGY, IGNITION_ENERGY} and not attach_outcome.supported:
            return SCORE_FORBIDDEN
        if (
            cid in {BASIC_WATER_ENERGY, BASIC_DARK_ENERGY}
            and target is self.b.active
            and target_id == CINDERACE
            and TURBO_FLARE in attach_outcome.enabled_attack_ids
            and self.has_live_turbo_flare_receiver()
            and self.has_turbo_flare_energy_in_deck()
            and not self.active_status_blocks_attack()
        ):
            return 210000
        if cid == IGNITION_ENERGY:
            if not self.ignition_has_same_turn_unique_value(option, attach_outcome):
                return -40000
            if target_id == CINDERACE:
                if not self.b.has_bench_energy_receiver():
                    return -40000
                return 12000 if attach_outcome.enables_attack else -40000
            if "ignition_immediate_attack" in attach_outcome.reasons:
                score = SCORE_PREFERRED + 220000
                if NEBULA_BEAM in attach_outcome.enabled_attack_ids:
                    score += 160000
                if ABSOLUTE_SNOW in attach_outcome.enabled_attack_ids:
                    score += 100000
                return score
            if attach_outcome.enables_attack:
                if target_id == MEGA_STARMIE_EX:
                    return 130000
                if target_id == MEGA_YUKIMENOKO_EX:
                    return 100000 if self.b.opponent_profile() == "ALAKAZAM" else 85000
                return 70000
            return -40000
        if cid == BASIC_WATER_ENERGY:
            score = self.score_water_attach(target)
            if NEBULA_BEAM in attach_outcome.enabled_attack_ids:
                score += 180000
            elif attach_outcome.enables_attack:
                score += 90000
            return score
        if cid == BASIC_DARK_ENERGY:
            score = self.score_dark_attach(target)
            if NEBULA_BEAM in attach_outcome.enabled_attack_ids:
                score += 150000
            elif attach_outcome.enables_attack:
                score += 70000
            return score
        return 1000

    def score_water_attach(self, target: Pokemon) -> float:
        tid = self.b.pid(target)
        count = self.b.energy_count(target)
        main_axis_available = self.main_axis_attach_target_available(BASIC_WATER_ENERGY)
        if tid == MEGA_STARMIE_EX:
            return 140000 + (3 - min(3, count)) * 45000
        if tid == HITODEMAN:
            return 85000 if self.b.visible_or_unknown_in_deck(MEGA_STARMIE_EX) or MEGA_STARMIE_EX in self.b.hand_ids else 42000
        if tid == CINDERACE and count == 0 and self.b.has_bench_energy_receiver():
            return 12000 if main_axis_available else 76000
        if tid == MEGA_YUKIMENOKO_EX:
            return 70000 if self.b.opponent_profile() in {"ALAKAZAM", "BENCH_DAMAGE"} else 50000
        if tid == YUKIWARASHI:
            return 50000 if self.b.opponent_profile() == "ALAKAZAM" else 42000
        if tid in UTILITY_POKEMON:
            return SCORE_FORBIDDEN
        return 0

    def score_dark_attach(self, target: Pokemon) -> float:
        tid = self.b.pid(target)
        count = self.b.energy_count(target)
        main_axis_available = self.main_axis_attach_target_available(BASIC_DARK_ENERGY)
        if tid == CINDERACE and count == 0 and self.b.has_bench_energy_receiver():
            return 12000 if main_axis_available else 60000
        if tid == MEGA_STARMIE_EX and count >= 1 and count < 3:
            return 90000
        if tid == YVELTAL:
            if target is self.b.active and not self.b.bench and any(card in self.b.hand_ids for card in {POFIN, ULTRA_BALL, POKEGEAR, SALVATORE, MEGA_SIGNAL, LILLIE_DETERMINATION, CRISPIN}):
                return 0
            if main_axis_available:
                return 0
            return 36000
        if tid == MEGA_YUKIMENOKO_EX and count >= 1 and count < 3:
            return 28000
        if tid == MEGA_STARMIE_EX and count == 0:
            return -50000
        return -5000

    def main_axis_attach_target_available(self, energy_id: int) -> bool:
        for pokemon in self.b.all_my_pokemon:
            tid = self.b.pid(pokemon)
            count = self.b.energy_count(pokemon)
            if energy_id == BASIC_WATER_ENERGY:
                if tid == MEGA_STARMIE_EX and count < 3:
                    return True
                if tid == HITODEMAN and (self.b.visible_or_unknown_in_deck(MEGA_STARMIE_EX) or MEGA_STARMIE_EX in self.b.hand_ids):
                    return True
                if tid == MEGA_YUKIMENOKO_EX and count < 3:
                    return True
                if tid == YUKIWARASHI and (self.b.visible_or_unknown_in_deck(MEGA_YUKIMENOKO_EX) or MEGA_YUKIMENOKO_EX in self.b.hand_ids):
                    return True
            if energy_id == BASIC_DARK_ENERGY:
                if tid == MEGA_STARMIE_EX and count >= 1 and count < 3:
                    return True
                if tid == MEGA_YUKIMENOKO_EX and count >= 1 and count < 3:
                    return True
        return False

    def has_active_nebula_enabling_attach_option(self) -> bool:
        for _, option in self.b.iter_options():
            if option.type != OptionType.ATTACH:
                continue
            if self.b.option_target(option) is not self.b.active:
                continue
            outcome = self.outcome.evaluate_attach(option)
            if outcome.supported and NEBULA_BEAM in outcome.enabled_attack_ids:
                return True
        return False

    def active_status_blocks_attack(self) -> bool:
        return self.outcome.active_status_blocks_attack()

    def has_live_turbo_flare_receiver(self) -> bool:
        for pokemon in self.b.bench:
            tid = self.b.pid(pokemon)
            if self.b.energy_count(pokemon) >= 3:
                continue
            if tid == MEGA_STARMIE_EX:
                return True
            if tid == HITODEMAN and (self.b.visible_or_unknown_in_deck(MEGA_STARMIE_EX) or MEGA_STARMIE_EX in self.b.hand_ids):
                return True
            if tid == MEGA_YUKIMENOKO_EX:
                return True
            if tid == YUKIWARASHI and (self.b.visible_or_unknown_in_deck(MEGA_YUKIMENOKO_EX) or MEGA_YUKIMENOKO_EX in self.b.hand_ids):
                return True
        return False

    def has_turbo_flare_energy_in_deck(self) -> bool:
        if self.b.deck_view:
            return BASIC_WATER_ENERGY in self.b.deck_ids or BASIC_DARK_ENERGY in self.b.deck_ids
        for energy_id in (BASIC_WATER_ENERGY, BASIC_DARK_ENERGY):
            known_out = self.b.hand_ids.count(energy_id) + self.b.discard_ids.count(energy_id)
            known_out += sum(self.b.energies(pokemon).count(energy_id) for pokemon in self.b.all_my_pokemon)
            if known_out < DECK.count(energy_id):
                return True
        return False

    def score_evolve(self, option: Any) -> float:
        cid = self.b.option_card(option)
        target = self.b.option_target(option)
        if cid == MEGA_STARMIE_EX:
            score = 180000
            if target is not None and target is not self.b.active:
                score += 30000
            if self.b.opponent_profile() in {"LUCARIO", "STEEL", "WALL"}:
                score += 140000
        elif cid == MEGA_YUKIMENOKO_EX:
            if self.b.opponent_profile() == "ALAKAZAM":
                score = 140000
            elif self.b.opponent_profile() == "BENCH_DAMAGE":
                score = 90000
            elif self.b.opponent_profile() in {"LUCARIO", "STEEL", "WALL"}:
                score = 45000
            else:
                score = 70000
        else:
            return 5000

        if target is None:
            return score

        base_id = HITODEMAN if cid == MEGA_STARMIE_EX else YUKIWARASHI
        if self.b.pid(target) != base_id or hp_left(target) <= 0:
            return score

        evo_data = self.b.data(cid)
        real_evo_data = CARD_TABLE.get(cid)
        evo_hp = safe_int(getattr(evo_data, "hp", 0) or getattr(real_evo_data, "hp", 0))
        before_hp = safe_int(getattr(target, "maxHp", 0) or getattr(self.b.data(base_id), "hp", 0))
        if evo_hp <= before_hp:
            return score

        active_key_attack_attach = False
        for _, candidate in self.b.iter_options():
            if candidate.type == OptionType.ATTACH and self.b.option_target(candidate) is self.b.active:
                outcome = self.outcome.evaluate_attach(candidate)
                if outcome.supported and any(attack_id in outcome.enabled_attack_ids for attack_id in {NEBULA_BEAM, ABSOLUTE_SNOW}):
                    active_key_attack_attach = True

        energy_count = self.b.energy_count(target)
        same_line_has_more_energy = any(
            pokemon is not target
            and self.b.pid(pokemon) == base_id
            and self.b.energy_count(pokemon) > energy_count
            for pokemon in self.b.all_my_pokemon
        )

        if target is self.b.active:
            if same_line_has_more_energy:
                return score
            usable_facts = tuple(
                fact
                for fact in self.b.active_evolution_attack_facts(option)
                if fact.supported and not fact.blocked
            )
            if not usable_facts:
                return score
            hp_gain_score = min(160000, max(0, evo_hp - before_hp) * 600)
            score += hp_gain_score
            score += 220000
            score += 140000
            score += energy_count * 60000
            score += 260000
            if any(fact.attack_id in {NEBULA_BEAM, ABSOLUTE_SNOW} for fact in usable_facts):
                score += 70000
            return score

        active = self.b.active
        if active is not None and self.b.pid(active) == base_id and self.b.energy_count(active) > energy_count:
            return score
        if active_key_attack_attach and energy_count == 0:
            return score

        hp_gain_score = min(160000, max(0, evo_hp - before_hp) * 600)
        score += hp_gain_score
        score += 220000
        score += 140000
        score += min(2, energy_count) * 60000
        if self.outcome.has_energy_payable_unblocked_active_attack():
            score += 140000
        same_mega_count = self.b.count_in_play(cid)
        if same_mega_count == 0:
            score += 120000
        elif same_mega_count == 1:
            score += 300000
        else:
            score += 60000
        return score

    def score_ability(self, option: Any) -> float:
        cid = self.b.option_card(option)
        if cid == CINDERACE:
            return SCORE_FORCED
        if self.outcome.is_surfing_beach_ability(option):
            if self.recommended_surfing_beach_outcome(option) is None:
                return SCORE_FORBIDDEN - 1
        return 20000

    def score_yes_no(self, option: Any) -> float:
        yes = option.type == OptionType.YES
        context = self.b.select.context
        cid = None
        if self.b.select.contextCard is not None:
            cid = self.b.select.contextCard.id
        if context == SelectContext.IS_FIRST:
            return 2000 if yes else 1000
        if context == SelectContext.MULLIGAN:
            return -1000 if yes else 1000
        if context == SelectContext.ACTIVATE:
            if cid == CINDERACE:
                return SCORE_FORCED if yes else SCORE_FORBIDDEN
            return 5000 if yes else 0
        if context == SelectContext.FIRST_EFFECT and cid == SUGURI:
            direct = self.best_current_attack_outcome()
            if direct is not None and (direct.knockout or direct.wins_game):
                return 1000
            boosted_score = 1000
            boosted = self.outcome.evaluate_suguri_damage_boost()
            if boosted.reachable_knockout:
                boosted_score = 94000
            active_data = self.b.data(self.b.pid(self.b.active))
            switch_score = (
                1000
                if active_data is None or active_data.basic
                else 0
            )
            if self.best_suguri_switch_play_outcome() is not None:
                switch_score = max(switch_score, 88000)
            return switch_score if yes else boosted_score
        return 1000 if yes else 0

    def score_count(self, option: Any) -> float:
        number = safe_int(option.number)
        context = self.b.select.context
        if context == SelectContext.DRAW_COUNT:
            return number
        if context in {SelectContext.DAMAGE_COUNTER_COUNT, SelectContext.REMOVE_DAMAGE_COUNTER_COUNT}:
            return number
        return number

    def hilda_evolution_candidate_facts(
        self,
        cid: Optional[int],
    ) -> Optional[HildaEvolutionCandidateFacts]:
        data = self.b.data(cid)
        if (
            cid is None
            or data is None
            or data.cardType != CardType.POKEMON
            or bool(getattr(data, "basic", False))
        ):
            return None
        bases = [
            pokemon
            for pokemon in self.b.all_my_pokemon
            if self.b.card_evolves_from_card(cid, self.b.pid(pokemon))
        ]
        completed_same_line_count = self.b.count_in_play(cid)
        currently_evolvable = any(
            not bool(getattr(pokemon, "appearThisTurn", False))
            for pokemon in bases
        )
        attack_axis_gap: Optional[int] = None
        attack_axis_damage = 0
        same_turn_attack_connected = False
        for pokemon in bases:
            tokens = tuple(self.b.energy_tokens_as(pokemon, cid))
            for attack_id in getattr(data, "attacks", ()):
                attack = self.b.attack(attack_id)
                if attack is None:
                    continue
                gap = self.b.attack_energy_gap(attack, tokens)
                if attack_axis_gap is None or gap.missing_units < attack_axis_gap:
                    attack_axis_gap = gap.missing_units
                if (
                    pokemon is self.b.active
                    and not bool(getattr(pokemon, "appearThisTurn", False))
                    and self.outcome.active_can_declare_attack_this_turn()
                    and gap.ready
                    and not self.b.attack_blocked_for_card(
                        cid,
                        self.b.opp_active,
                        attack,
                    )
                ):
                    same_turn_attack_connected = True
                    attack_axis_damage = max(
                        attack_axis_damage,
                        self.b.resolved_attack_damage_for_card(
                            cid,
                            attack,
                            self.b.opp_active,
                        )[0],
                    )
        base_in_play = bool(bases)
        missing_evolution_line = completed_same_line_count == 0
        if not base_in_play:
            current_value = 0.01
        else:
            # Current evolution legality, missing-line completion and the
            # closest current attack axis are each represented once.
            structural_value = (
                int(currently_evolvable) * 2
                + int(missing_evolution_line)
                + (
                    1 / (1 + attack_axis_gap)
                    if attack_axis_gap is not None
                    else 0
                )
            )
            current_value = (
                attack_axis_damage + structural_value
            ) / (1 + completed_same_line_count)
        return HildaEvolutionCandidateFacts(
            target_id=cid,
            legal=True,
            base_in_play=base_in_play,
            currently_evolvable=currently_evolvable,
            missing_evolution_line=missing_evolution_line,
            same_turn_attack_connected=same_turn_attack_connected,
            completed_same_line_count=completed_same_line_count,
            attack_axis_gap=attack_axis_gap,
            attack_axis_damage=attack_axis_damage,
            current_value=current_value,
        )

    def hilda_energy_candidate_facts(
        self,
        cid: Optional[int],
    ) -> Optional[HildaEnergyCandidateFacts]:
        if cid is None or not self.b.is_energy(cid):
            return None
        attach_available = not bool(
            getattr(self.b.state, "energyAttached", False)
        )
        discarded_at_end = cid == IGNITION_ENERGY
        best_key: Optional[Tuple[Any, ...]] = None
        best_values: Tuple[
            Optional[int],
            Optional[int],
            bool,
            int,
            Optional[int],
            Optional[int],
            int,
            Tuple[int, ...],
            int,
            float,
        ] = (None, None, False, 0, None, None, 0, (), 0, 0.01)
        if attach_available:
            for pokemon in self.b.all_my_pokemon:
                projected_ids = [self.b.pid(pokemon)]
                if not bool(getattr(pokemon, "appearThisTurn", False)):
                    projected_ids.extend(
                        evolution_id
                        for evolution_id in dict.fromkeys(self.b.hand_ids)
                        if (
                            evolution_id != self.b.pid(pokemon)
                            and self.b.card_evolves_from_card(
                                evolution_id,
                                self.b.pid(pokemon),
                            )
                        )
                    )
                for projected_id in projected_ids:
                    projected_target = SimpleNamespace(id=projected_id)
                    added_tokens = energy_tokens_for_attach(
                        cid,
                        projected_target,
                    )
                    pokemon_data = self.b.data(projected_id)
                    if added_tokens is None or pokemon_data is None:
                        continue
                    target_is_evolution = not bool(
                        getattr(pokemon_data, "basic", False)
                    )
                    best_before: Optional[int] = None
                    best_after: Optional[int] = None
                    best_reduction = 0
                    enabled_ids: List[int] = []
                    enabled_damage = 0
                    current_tokens = tuple(
                        self.b.energy_tokens_as(pokemon, projected_id)
                    )
                    for attack_id in getattr(pokemon_data, "attacks", ()):
                        attack = self.b.attack(attack_id)
                        if attack is None:
                            continue
                        before = self.b.attack_energy_gap(
                            attack,
                            current_tokens,
                        )
                        after = self.b.attack_energy_gap(
                            attack,
                            current_tokens + tuple(added_tokens),
                        )
                        reduction = max(
                            0,
                            before.missing_units - after.missing_units,
                        )
                        if reduction > best_reduction:
                            best_reduction = reduction
                            best_before = before.missing_units
                            best_after = after.missing_units
                        if (
                            pokemon is self.b.active
                            and self.outcome.active_can_declare_attack_this_turn()
                            and not before.ready
                            and after.ready
                            and not self.b.attack_blocked_for_card(
                                projected_id,
                                self.b.opp_active,
                                attack,
                            )
                        ):
                            enabled_ids.append(attack_id)
                            enabled_damage = max(
                                enabled_damage,
                                self.b.resolved_attack_damage_for_card(
                                    projected_id,
                                    attack,
                                    self.b.opp_active,
                                )[0],
                            )
                    retained_gap_reduction = (
                        best_reduction
                        if not discarded_at_end
                        else 0
                    )
                    current_value = (
                        enabled_damage
                        + len(enabled_ids)
                        if enabled_ids
                        else retained_gap_reduction
                    )
                    key = (
                        bool(enabled_ids),
                        enabled_damage,
                        len(enabled_ids),
                        retained_gap_reduction,
                        best_reduction,
                    )
                    if best_key is None or key > best_key:
                        best_key = key
                        best_values = (
                            projected_id,
                            getattr(pokemon, "serial", None),
                            target_is_evolution,
                            len(added_tokens),
                            best_before,
                            best_after,
                            best_reduction,
                            tuple(enabled_ids),
                            enabled_damage,
                            max(0.01, current_value),
                        )
        (
            best_target_id,
            best_target_serial,
            best_target_is_evolution,
            provided_units,
            gap_before,
            gap_after,
            gap_reduction,
            enabled_attack_ids,
            enabled_attack_damage,
            current_value,
        ) = best_values
        return HildaEnergyCandidateFacts(
            target_id=cid,
            legal=True,
            same_turn_attach_available=attach_available,
            best_attach_target_id=best_target_id,
            best_attach_target_serial=best_target_serial,
            best_target_is_evolution=best_target_is_evolution,
            provided_colorless_units=provided_units,
            attack_gap_before=gap_before,
            attack_gap_after=gap_after,
            attack_gap_reduction=gap_reduction,
            enabled_attack_ids=enabled_attack_ids,
            enabled_attack_damage=enabled_attack_damage,
            discarded_at_end_of_turn=discarded_at_end,
            current_value=current_value,
        )

    def score_card_selection(self, option: Any) -> float:
        cid = self.b.option_card(option)
        effect = self.effect_id()
        if effect == POFIN:
            if not self.b.is_poffin_target(cid):
                return SCORE_FORBIDDEN
            if cid == HITODEMAN:
                return 120000
            if cid == YUKIWARASHI:
                return 70000 if self.b.opponent_profile() == "ALAKAZAM" else 32000
            return 1000
        if effect == POKE_PAD:
            facts = self.b.poke_pad_target_facts(
                cid,
                visible_search_candidate=True,
            )
            if facts is None:
                return SCORE_FORBIDDEN
            target_policy = self.poke_pad_target_policy(facts)
            if target_policy.useful:
                return target_policy.development_value
            if facts.setup_only_target or not facts.same_turn_deployable:
                return -8000
            if facts.duplicate_in_hand or facts.duplicate_in_play:
                return 0
            # Mandatory-selection tiebreak only. This does not make the
            # corresponding Poké Pad PLAY useful.
            return 0.01
        if effect == ULTRA_BALL:
            facts = self.b.ultra_ball_target_facts(
                cid,
                visible_search_candidate=True,
            )
            if facts is None:
                return SCORE_FORBIDDEN
            target_policy = self.ultra_ball_target_policy(facts)
            if target_policy.useful:
                return target_policy.development_value * 40000
            # Mandatory-selection tiebreak only. A legal roleless target
            # remains selectable without making the preceding PLAY useful.
            return 0.01 if facts.setup_only_target else 0.02
        if effect == MEGA_SIGNAL:
            if not self.b.is_mega_signal_target(cid):
                return SCORE_FORBIDDEN
            if cid == MEGA_STARMIE_EX:
                return 150000
            if cid == MEGA_YUKIMENOKO_EX:
                return 110000 if self.b.opponent_profile() == "ALAKAZAM" else 24000
            return 0
        if effect == SALVATORE:
            if cid == MEGA_STARMIE_EX and self.b.is_salvatore_target(cid):
                return 180000
            if cid == MEGA_YUKIMENOKO_EX and self.b.is_salvatore_target(cid):
                return 150000 if self.b.opponent_profile() == "ALAKAZAM" else 30000
            return SCORE_FORBIDDEN
        if effect == POKEGEAR:
            return self.score_pokegear_candidate(cid)
        if effect == TANKER:
            candidate = self.night_stretcher_candidate_for_option(option)
            return (
                self.night_stretcher_policy_value(candidate)
                if candidate is not None
                else SCORE_FORBIDDEN
            )
        if effect == HILDA:
            evolution_facts = self.hilda_evolution_candidate_facts(cid)
            if evolution_facts is not None:
                return max(0.01, evolution_facts.current_value)
            energy_facts = self.hilda_energy_candidate_facts(cid)
            if energy_facts is not None:
                return max(0.01, energy_facts.current_value)
            return SCORE_FORBIDDEN
        if effect == CRISPIN:
            if cid == BASIC_WATER_ENERGY:
                return 140000
            if cid == BASIC_DARK_ENERGY:
                return 90000
            return SCORE_FORBIDDEN
        return self.card_need_score(cid)

    def score_pokegear_candidate(self, cid: Optional[int]) -> float:
        if not self.b.is_supporter(cid):
            return SCORE_FORBIDDEN

        needs_recovery = (
            not self.outcome.has_energy_payable_unblocked_active_attack()
            or self.b.needs_basic()
            or self.b.needs_mega_starmie()
            or self.b.needs_mega_yuki()
            or self.b.starmie_needs_energy()
            or len(self.b.hand_ids) <= 3
        )

        if cid == SALVATORE and self.b.salvatore_live():
            return 180000 if needs_recovery else 160000
        if cid == WALLY_COMPASSION and self.b.wally_live():
            return 130000
        if cid in {JUDGE, SUGURI}:
            return self.score_play(SimpleNamespace(type=OptionType.PLAY, cardId=cid))
        if cid == CRISPIN and self.b.starmie_needs_energy():
            return 125000 if needs_recovery else 110000
        if cid == LILLIE_DETERMINATION:
            if needs_recovery and len(self.b.hand_ids) <= 6:
                return 90000
            if len(self.b.hand_ids) <= 3:
                return 80000
            return 1000
        if cid == BEFEHL_VON_BOSS:
            boss_score = self.score_boss()
            if needs_recovery and boss_score < SCORE_PREFERRED:
                return min(boss_score, -20000)
            return boss_score
        return 1000

    def score_target_or_card(self, option: Any) -> float:
        target = self.b.option_target(option)
        cid = self.b.option_card(option)
        effect = self.effect_id()
        if target is not None:
            if effect == SALVATORE:
                outcome = self.outcome.evaluate_salvatore_target(target)
                if not outcome.supported:
                    return SCORE_FORBIDDEN
                attack_value = (
                    outcome.reachable_damage
                    if outcome.reachable_attack_id is not None
                    else outcome.expected_reachable_damage
                )
                return (
                    outcome.development_value
                    + attack_value
                    + max(
                        outcome.same_turn_attack_option_count,
                        outcome.post_evolution_ready_attack_count,
                    )
                )
            if effect == WALLY_COMPASSION:
                outcome = self.outcome.evaluate_wally_target(target)
                return self.wally_effect_legacy_value(outcome) if outcome.supported else SCORE_FORBIDDEN
            if effect == HERO_CAPE:
                return self.score_hero_cape_target(target)
            if effect == TOOL_SCRAPPER:
                return self.score_tool_scrapper_outcome(self.outcome.evaluate_tool_scrapper_target(target, option.toolIndex))
            if effect == BEFEHL_VON_BOSS:
                return self.score_boss_outcome(self.outcome.evaluate_boss_target(target))
            if effect == SUGURI:
                return self.score_switch_target(target, "suguri")
            if effect == SURFING_BEACH:
                return self.score_switch_target(target, "surfing_beach")
            if self.b.select.context == SelectContext.SWITCH:
                if effect is not None:
                    return SCORE_FORBIDDEN
                return self.score_switch_target(target, "retreat")
            if effect == CINDERACE and self.b.select.context in {SelectContext.ATTACH_FROM, SelectContext.ATTACH_TO}:
                return self.score_turbo_flare_attach_target(target)
            return self.target_value(target)
        if cid is not None:
            return self.score_card_selection(option)
        return 0

    def score_turbo_flare_attach_target(self, target: Pokemon) -> float:
        if target not in self.b.all_my_pokemon:
            return SCORE_FORBIDDEN
        pid = self.b.pid(target)
        count = self.b.energy_count(target)
        if pid == MEGA_STARMIE_EX:
            return 230000 + max(0, 3 - count) * 45000 if count < 3 else 15000
        if pid == HITODEMAN:
            if self.b.remaining_possible(MEGA_STARMIE_EX) or MEGA_STARMIE_EX in self.b.hand_ids:
                return 180000 + max(0, 2 - count) * 25000
            return 70000
        if pid == MEGA_YUKIMENOKO_EX:
            if count >= 3:
                return 10000
            base = 150000 if self.b.opponent_profile() in {"ALAKAZAM", "BENCH_DAMAGE"} else 85000
            return base + max(0, 3 - count) * 25000
        if pid == YUKIWARASHI:
            return 95000 if self.b.opponent_profile() == "ALAKAZAM" else 45000
        if pid in UTILITY_POKEMON or pid == CINDERACE:
            return -50000
        return 0

    def score_switch_target_outcome(
        self,
        outcome: ImmediateOutcome,
        source: str = "retreat",
    ) -> float:
        if not outcome.supported:
            return SCORE_FORBIDDEN
        if "switch_enables_win" in outcome.reasons:
            return SCORE_FORCED + 400000
        if outcome.enables_knockout:
            return SCORE_FORCED // 2 + 180000
        if outcome.target_id == SHAYMIN and self.b.needs_shaymin_bench_guard() and "survival_retreat" not in outcome.reasons:
            return SCORE_FORBIDDEN
        if (
            self.b.pid(self.b.active) == CINDERACE
            and self.b.cinderace_can_accelerate()
            and self.b.has_bench_energy_receiver()
            and not self.cinderace_handoff_improves_current_turn(outcome)
        ):
            return SCORE_FORBIDDEN
        if "zero_energy_mega_wall" in outcome.reasons and "survival_retreat" not in outcome.reasons:
            return SCORE_FORBIDDEN
        if "retreat_from_ready_attacker" in outcome.reasons and "retreat_improves_damage" not in outcome.reasons and "survival_retreat" not in outcome.reasons:
            return SCORE_FORBIDDEN // 3

        score = (
            self.surfing_beach_candidate_pressure(outcome)
            if source == "surfing_beach"
            else 0.0
        )
        if "survival_retreat" in outcome.reasons:
            score += 100000
        if outcome.enables_attack:
            score += 150000
        if outcome.improves_damage:
            score += 90000
        if outcome.target_id in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX} and outcome.enables_attack:
            score += 90000
        if outcome.target_id in {CINDERACE, YVELTAL, SHAYMIN} and "survival_retreat" in outcome.reasons:
            score += 30000
        if "surfing_beach_switch" in outcome.reasons:
            score += 35000
        score -= outcome.retreat_energy_cost * 12000
        score -= outcome.important_energy_loss * 60000
        return score

    def score_switch_target(
        self,
        target: Pokemon,
        source: str = "retreat",
    ) -> float:
        if source == "surfing_beach":
            outcome = self.recommended_surfing_beach_outcome_for_target(
                target
            )
            if outcome is None:
                return SCORE_FORBIDDEN
            return self.score_switch_target_outcome(
                outcome,
                source,
            )
        return self.score_switch_target_outcome(
            self.outcome.evaluate_switch_target(target, source),
            source,
        )

    def score_damage_target(self, option: Any) -> float:
        outcome = self.outcome.evaluate_attack_effect_target(option)
        if outcome.supported:
            return self.score_attack_effect_target_outcome(outcome)
        if self.b.select.context == SelectContext.DAMAGE:
            return SCORE_LAST_RESORT
        target = self.b.option_target(option)
        if target is None:
            return SCORE_FORBIDDEN
        mine = target in self.b.all_my_pokemon
        if mine:
            return SCORE_FORBIDDEN
        score = self.target_value(target)
        if target is self.b.opp_active:
            score += 60000
        if hp_left(target) <= 50:
            score += 50000
        return score

    def score_attack_effect_target_outcome(self, outcome: ImmediateOutcome) -> float:
        if not outcome.supported:
            return SCORE_FORBIDDEN
        if outcome.wins_game:
            return SCORE_FORCED + 350000
        score = SCORE_PREFERRED + outcome.damage * 1000
        if outcome.knockout:
            score += SCORE_FORCED // 2 + outcome.prizes_taken * 120000
        if "effect_hits_engine" in outcome.reasons:
            score += 90000
        return score

    def score_heal_target(self, option: Any) -> float:
        target = self.b.option_target(option)
        if target is None or target not in self.b.all_my_pokemon:
            return SCORE_FORBIDDEN
        if self.effect_id() == WALLY_COMPASSION:
            outcome = self.outcome.evaluate_wally_target(target)
            return self.wally_effect_legacy_value(outcome) if outcome.supported else SCORE_FORBIDDEN
        if self.b.pid(target) in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX}:
            return damage_on(target) * 1000 + self.b.energy_count(target) * 20000
        return damage_on(target) * 100

    def wally_effect_legacy_value(self, outcome: ImmediateOutcome) -> float:
        if not outcome.supported:
            return 0
        return outcome.healed_damage * 1000 + outcome.recovered_energy_count * 20000

    def score_energy_selection(self, option: Any) -> float:
        cid = self.b.option_card(option)
        if cid is None and option.energyIndex is not None:
            target = self.b.option_target(option)
            energies = target.energyCards if target is not None else []
            if 0 <= option.energyIndex < len(energies):
                cid = energies[option.energyIndex].id
        context = self.b.select.context
        if context in {SelectContext.TO_HAND_ENERGY, SelectContext.SWITCH_ENERGY, SelectContext.SWITCH_ENERGY_CARD}:
            if cid == BASIC_WATER_ENERGY:
                return 100000
            if cid == BASIC_DARK_ENERGY:
                return 60000
            return 1000
        if cid == BASIC_WATER_ENERGY:
            return SCORE_FORBIDDEN
        if cid == IGNITION_ENERGY:
            return 50000
        if cid == BASIC_DARK_ENERGY:
            return -10000
        return 0

    def drednaw_discard_copy_is_required(self, option: Any) -> bool:
        if (
            self.b.select.context
            not in {
                SelectContext.DISCARD,
                SelectContext.DISCARD_CARD_OR_ATTACHED_CARD,
                SelectContext.TO_DECK,
                SelectContext.TO_DECK_BOTTOM,
            }
            or self.b.option_card(option) != DREDNAW
        ):
            return False

        hand_count = self.b.hand_ids.count(DREDNAW)
        visible_demand = (
            self.b.count_in_play(CHEWTLE)
            + self.b.hand_ids.count(CHEWTLE)
        )
        required_count = min(
            hand_count,
            visible_demand
            if visible_demand > 0
            else int(self.b.remaining_possible(CHEWTLE)),
        )
        if required_count <= 0:
            return False
        if hand_count <= required_count:
            return True

        hand_copies = tuple(
            (index, card, getattr(card, "serial", None))
            for index, card in enumerate(self.b.hand)
            if getattr(card, "id", None) == DREDNAW
        )
        if len(hand_copies) != hand_count:
            return True

        serials = tuple(serial for _, _, serial in hand_copies)
        serial_identity_exact = (
            all(type(serial) is int for serial in serials)
            and len(set(serials)) == len(serials)
        )
        if not serial_identity_exact:
            return True

        option_serial = getattr(option, "serial", None)
        if type(option_serial) is not int or option_serial not in serials:
            return True

        protected_serials = set(sorted(serials)[:required_count])
        return option_serial in protected_serials

    def score_discard(self, option: Any) -> float:
        cid = self.b.option_card(option)
        if cid is None:
            return 0
        if self.drednaw_discard_copy_is_required(option):
            return SCORE_FORBIDDEN
        if self.effect_id() == ULTRA_BALL:
            if cid in self.ultra_ball_evolutions_to_preserve():
                return SCORE_FORBIDDEN
        if cid == CINDERACE:
            return (
                SCORE_LAST_RESORT
                if self.b.cinderace_setup_role_live()
                else 6000
            )
        if cid == MEGA_STARMIE_EX:
            return -34000000 if self.b.count_in_play(HITODEMAN) or self.b.needs_mega_starmie() else -300000
        if cid == HITODEMAN:
            return -32000000 if self.b.count_in_play(HITODEMAN) == 0 else -250000
        if cid == BASIC_WATER_ENERGY:
            return -30000000 if self.b.starmie_needs_energy() else -2000000
        if cid == SALVATORE:
            return -35000000 if self.b.salvatore_live() else -200000
        if cid == SHAYMIN and self.b.needs_shaymin_bench_guard():
            return -22000000 if self.b.count_in_play(SHAYMIN) == 0 else -100000
        if cid == HERO_CAPE:
            return -25000000 if any(self.b.pid(p) in {MEGA_STARMIE_EX, MEGA_YUKIMENOKO_EX} and not p.tools for p in self.b.all_my_pokemon) else -150000
        if cid == MEGA_SIGNAL:
            return -5000000 if self.b.needs_mega_starmie() or self.b.needs_mega_yuki() else 2000
        if cid in IMPORTANT_CARDS:
            return SCORE_LAST_RESORT
        if cid in {TOOL_SCRAPPER, WALLY_COMPASSION, HERO_CAPE, SALVATORE, POFIN, ULTRA_BALL}:
            return SCORE_LAST_RESORT
        if cid == YVELTAL:
            return 2000
        if cid == SHAYMIN and not self.b.needs_shaymin_bench_guard():
            return 4000
        if cid == YUKIWARASHI and self.b.count_in_play(YUKIWARASHI) >= 2:
            return 5000
        if cid == MEGA_YUKIMENOKO_EX and self.b.opponent_profile() not in {"ALAKAZAM", "BENCH_DAMAGE"}:
            return 4000
        data = self.b.data(cid)
        if data is not None and data.cardType in {CardType.STADIUM, CardType.TOOL}:
            return 3000
        if data is not None and data.cardType == CardType.SUPPORTER and self.b.state.supporterPlayed:
            return 2500
        return 0

    def target_value(self, pokemon: Optional[Pokemon]) -> float:
        if pokemon is None:
            return SCORE_FORBIDDEN
        pid = self.b.pid(pokemon)
        score = hp_left(pokemon) * -30 + damage_on(pokemon) * 100
        score += self.b.prize_value(pokemon) * 30000
        if pokemon is self.b.opp_active:
            score += 30000
        if pid in self.b.plan_pressure_targets():
            score += 85000
        if pid in LUCARIO_ENGINE:
            score += 120000
        if pid == MEGA_LUCARIO_EX:
            score += 100000
        if pid in DURALUDON_LINE:
            score += 90000
        if pid in CRUSTLE_LINE | EX_ATTACK_WALLS:
            score += 90000
        if pid in ALAKAZAM_LINE:
            score += 85000
        if pid in DREEPY_LINE | {DRAGAPULT_EX}:
            score += 80000
        if pid == BUDEW:
            score += 120000
        if pid == SHAYMIN:
            score += 30000
        if self.b.energy_count(pokemon) >= 2:
            score += 25000
        return score

    def card_need_score(self, cid: Optional[int]) -> float:
        if cid is None:
            return SCORE_FORBIDDEN
        if cid == HITODEMAN:
            return 145000 if cid in self.b.plan_setup_cards() else 120000
        if cid == MEGA_STARMIE_EX:
            base = 130000 if self.b.count_in_play(HITODEMAN) else 40000
            return base + (45000 if cid in self.b.plan_setup_cards() else 0)
        if cid == BASIC_WATER_ENERGY:
            return 90000
        if cid == SALVATORE:
            base = 125000 if cid in self.b.plan_setup_cards() else 85000
            return base if self.b.salvatore_live() else 10000
        if cid == CRISPIN:
            return 70000 if self.b.starmie_needs_energy() else 10000
        if cid == YUKIWARASHI:
            return 55000 if self.b.opponent_profile() == "ALAKAZAM" else 35000
        if cid == MEGA_YUKIMENOKO_EX:
            return 80000 if self.b.opponent_profile() == "ALAKAZAM" else 50000
        if cid == CINDERACE:
            return 65000 if self.b.cinderace_setup_role_live() else 0
        if cid == SHAYMIN and self.b.needs_shaymin_bench_guard() and self.b.count_in_play(SHAYMIN) == 0:
            return 95000
        return 1000

    def effect_id(self) -> Optional[int]:
        if self.b.select.effect is not None:
            return self.b.select.effect.id
        if self.b.select.contextCard is not None:
            return self.b.select.contextCard.id
        return None







def _stage2b4_counterline_option_index(
    board: BoardView,
    option: Any,
) -> Optional[int]:
    indexes = tuple(index for index, candidate in board.iter_options() if candidate is option)
    return indexes[0] if len(indexes) == 1 else None


def _stage2b4_counterline_step_effect_id(
    board: BoardView,
    option: Optional[Any],
    *,
    route_origin: Optional[ActiveBenchTransitionOrigin],
    projected_followup_action: bool,
) -> Optional[int]:
    """Return the effect identity of this action step, never the route as a whole."""
    if projected_followup_action or option is None:
        return None
    option_type = getattr(option, "type", None)
    if option_type in {OptionType.ATTACH, OptionType.RETREAT}:
        return None
    option_card_id = board.option_card(option)
    if option_card_id in {SURFING_BEACH, SUGURI}:
        return option_card_id
    select = getattr(board, "select", None)
    effect_id = getattr(getattr(select, "effect", None), "id", None)
    context_card_id = getattr(getattr(select, "contextCard", None), "id", None)
    expected = (
        SURFING_BEACH
        if route_origin == ActiveBenchTransitionOrigin.SURFING_BEACH
        else SUGURI
        if route_origin == ActiveBenchTransitionOrigin.SUGURI
        else None
    )
    if expected is not None and effect_id == expected:
        return expected
    if expected is not None and context_card_id == expected:
        return expected
    return None


def _stage2b4_current_action_step_facts(
    board: BoardView,
    option: Any,
    *,
    step_index: int,
    target: Optional[Any],
    route_origin: Optional[ActiveBenchTransitionOrigin],
    legality_exact: bool,
    unsupported_reason: Optional[str] = None,
) -> Stage2b4CounterlineActionStepFacts:
    option_index = _stage2b4_counterline_option_index(board, option)
    option_type = getattr(option, "type", None)
    option_card_id = board.option_card(option)
    target_card_id = None if target is None else board.pid(target)
    target_serial = None if target is None else getattr(target, "serial", None)
    identity_exact = bool(
        type(option_index) is int
        and isinstance(option_type, OptionType)
        and type(target_card_id) is int
        and type(target_serial) is int
    )
    reason = unsupported_reason
    if reason is None and not identity_exact:
        reason = "stage2b4_counterline_action_step_identity_unresolved"
    return Stage2b4CounterlineActionStepFacts(
        step_index=step_index,
        option_index=option_index,
        option_type=option_type if isinstance(option_type, OptionType) else None,
        option_card_id=option_card_id if type(option_card_id) is int else None,
        option_effect_id=_stage2b4_counterline_step_effect_id(
            board,
            option,
            route_origin=route_origin,
            projected_followup_action=False,
        ),
        target_card_id=target_card_id if type(target_card_id) is int else None,
        target_serial=target_serial if type(target_serial) is int else None,
        route_origin=route_origin,
        current_observation_option=True,
        projected_followup_action=False,
        identity_exact=identity_exact,
        legality_exact=bool(identity_exact and legality_exact and reason is None),
        unsupported_reason=reason,
        reasons=("stage2b4_counterline_current_action_step",)
        + ((reason,) if reason else ()),
    )


def _stage2b4_projected_bomb_attach_step_facts(
    projected_after_switch: Optional[BoardView],
    *,
    step_index: int,
    expected_target_card_id: Optional[int],
    expected_target_serial: Optional[int],
    route_origin: Optional[ActiveBenchTransitionOrigin],
    bomb_card: Optional[Any],
    projection_reason: Optional[str],
    attach_legality_proven: bool,
) -> Stage2b4CounterlineActionStepFacts:
    projected_active = (
        None if projected_after_switch is None else getattr(projected_after_switch, "active", None)
    )
    target_card_id = (
        None
        if projected_after_switch is None or projected_active is None
        else projected_after_switch.pid(projected_active)
    )
    target_serial = None if projected_active is None else getattr(projected_active, "serial", None)
    projected_bombs = tuple(
        card
        for card in tuple(
            getattr(projected_after_switch, "hand", ()) if projected_after_switch is not None else ()
        )
        if getattr(card, "id", None) == DELUXE_BOMB
    )
    bomb_serial = None if bomb_card is None else getattr(bomb_card, "serial", None)
    bomb_identity_exact = bool(
        len(projected_bombs) == 1
        and bomb_card is not None
        and getattr(bomb_card, "id", None) == DELUXE_BOMB
        and type(bomb_serial) is int
        and getattr(projected_bombs[0], "id", None) == DELUXE_BOMB
        and getattr(projected_bombs[0], "serial", None) == bomb_serial
    )
    target_identity_exact = bool(
        type(target_card_id) is int
        and type(target_serial) is int
        and target_card_id == expected_target_card_id
        and target_serial == expected_target_serial
    )
    tool_state = None if projected_active is None else getattr(projected_active, "tools", None)
    identity_exact = bool(bomb_identity_exact and target_identity_exact)
    legality_exact = bool(
        identity_exact
        and projection_reason is None
        and attach_legality_proven
        and tool_state is not None
        and not tuple(tool_state or ())
    )
    reason = None
    if not identity_exact or not legality_exact:
        reason = "stage2b4_counterline_followup_action_identity_unresolved"
    return Stage2b4CounterlineActionStepFacts(
        step_index=step_index,
        option_index=None,
        option_type=OptionType.ATTACH,
        option_card_id=DELUXE_BOMB,
        option_effect_id=None,
        target_card_id=target_card_id if type(target_card_id) is int else None,
        target_serial=target_serial if type(target_serial) is int else None,
        route_origin=route_origin,
        current_observation_option=False,
        projected_followup_action=True,
        identity_exact=identity_exact,
        legality_exact=legality_exact,
        unsupported_reason=reason,
        reasons=("stage2b4_counterline_projected_followup_action_step",)
        + ((reason,) if reason else ()),
    )


def _stage2b4_action_plan_candidates_for_option(
    policy: Any,
    option: Any,
) -> Tuple[Stage2b4ActionPlanFacts, ...]:
    """Enumerate Stage2b4 route facts without Policy selection or ranking."""
    board = policy.b
    option_entries = tuple(board.iter_options())
    origin_indexes = tuple(index for index, candidate in option_entries if candidate is option)
    if len(origin_indexes) != 1:
        return ()
    origin_index = origin_indexes[0]
    cid = board.option_card(option)
    target = board.option_target(option)
    bombs = tuple(
        card
        for card in tuple(getattr(board, "hand", ()) or ())
        if getattr(card, "id", None) == DELUXE_BOMB
    )
    bomb_card = (
        bombs[0]
        if len(bombs) == 1 and type(getattr(bombs[0], "serial", None)) is int
        else None
    )
    plans: List[Stage2b4ActionPlanFacts] = []
    switch_entries: List[Tuple[Any, str, ActiveBenchTransitionOrigin, float, float]] = []
    for _, candidate in option_entries:
        candidate_id = board.option_card(candidate)
        if (
            candidate.type == OptionType.ABILITY
            and policy.outcome.is_surfing_beach_ability(candidate)
        ):
            switch_entries.append(
                (candidate, "surfing_beach", ActiveBenchTransitionOrigin.SURFING_BEACH, 0.0, 0.0)
            )
        elif candidate.type == OptionType.PLAY and candidate_id == SURFING_BEACH:
            switch_entries.append(
                (candidate, "surfing_beach", ActiveBenchTransitionOrigin.SURFING_BEACH, 0.0, 0.0)
            )
        elif candidate.type == OptionType.RETREAT:
            candidate_outcome = policy.outcome.evaluate_retreat(candidate)
            if candidate_outcome.supported:
                cost = float(candidate_outcome.retreat_energy_cost)
                switch_entries.append(
                    (
                        candidate,
                        "retreat",
                        ActiveBenchTransitionOrigin.RETREAT,
                        cost,
                        float(
                            candidate_outcome.retreat_energy_cost
                            + candidate_outcome.important_energy_loss * 3
                        ),
                    )
                )
        elif (
            candidate.type == OptionType.PLAY
            and candidate_id == SUGURI
            and not bool(getattr(getattr(board, "state", None), "supporterPlayed", False))
        ):
            switch_entries.append(
                (candidate, "suguri", ActiveBenchTransitionOrigin.SUGURI, 1.0, 1.5)
            )

    attach_candidate_by_serial: Dict[int, Tuple[Any, DeluxeBombAttachCandidateFacts]] = {}
    for attach_candidate in deluxe_bomb_strategy_facts(board).attach_candidates:
        attach_index = attach_candidate.option_index
        serial = attach_candidate.target_serial
        if (
            attach_candidate.attach_legal_now is True
            and type(attach_index) is int
            and type(serial) is int
        ):
            matches = tuple(
                candidate
                for index, candidate in option_entries
                if index == attach_index
                and getattr(candidate, "type", None) == OptionType.ATTACH
                and board.option_card(candidate) == DELUXE_BOMB
                and getattr(board.option_target(candidate), "serial", None) == serial
            )
            if len(matches) == 1 and serial not in attach_candidate_by_serial:
                attach_candidate_by_serial[serial] = (matches[0], attach_candidate)
            elif len(matches) != 1 or serial in attach_candidate_by_serial:
                attach_candidate_by_serial.pop(serial, None)

    def append_fact_plan(
        *,
        action_kind: str,
        projected: Optional[BoardView],
        reason: Optional[str],
        target_pokemon: Optional[Any],
        origin: Optional[ActiveBenchTransitionOrigin],
        action_count: int,
        remaining_actions: int,
        resource_cost: float,
        risk: float,
        action_steps: Tuple[Stage2b4CounterlineActionStepFacts, ...],
    ) -> None:
        if projected is None:
            return
        integrated = stage2b4_integrated_counterline_facts(
            projected,
            route_enumeration_complete=True,
            current_non_ko_attack_pressure=None,
            current_direct_win_exists=False,
            current_direct_knockout_exists=False,
        )
        integrated_reason = integrated.unsupported_reason
        followup_only_limitation = (
            integrated_reason in _STAGE2B4_COUNTERLINE_FOLLOWUP_LIMITATION_REASONS
        )
        step_reason = next(
            (step.unsupported_reason for step in action_steps if step.unsupported_reason),
            None,
        )
        sequence_reason = None
        if len(action_steps) != action_count or tuple(
            step.step_index for step in action_steps
        ) != tuple(range(action_count)):
            sequence_reason = "stage2b4_counterline_action_step_sequence_unresolved"
        final_reason = reason or step_reason or sequence_reason or (
            None if integrated.supported or followup_only_limitation else integrated_reason
        )
        projected_active = getattr(projected, "active", None)
        plans.append(
            Stage2b4CounterlineRoutePlanFacts(
                supported=final_reason is None,
                action_kind=action_kind,
                option_type=getattr(option, "type", None),
                card_id=cid,
                target_id=None if target_pokemon is None else board.pid(target_pokemon),
                target_serial=None
                if target_pokemon is None
                else getattr(target_pokemon, "serial", None),
                route_origin=origin,
                action_count=action_count,
                remaining_actions=remaining_actions,
                integrated_facts=integrated,
                resource_cost=resource_cost,
                risk=risk,
                unsupported_reason=final_reason,
                reasons=("stage2b4_fact_only_action_plan", action_kind)
                + ((final_reason,) if final_reason else ()),
                projected_active_card_id=None
                if projected_active is None
                else projected.pid(projected_active),
                projected_active_serial=None
                if projected_active is None
                else getattr(projected_active, "serial", None),
                action_steps=action_steps,
            )
        )

    if option.type == OptionType.ATTACH and cid == DELUXE_BOMB and target is not None:
        serial = getattr(target, "serial", None)
        attach_candidates = deluxe_bomb_strategy_facts(board).attach_candidates
        exact_attach = next(
            (
                candidate
                for candidate in attach_candidates
                if candidate.option_index == origin_index
                and candidate.target_serial == serial
                and candidate.attach_legal_now is True
            ),
            None,
        )
        if exact_attach is not None and bomb_card is not None and type(serial) is int:
            attach_step = _stage2b4_current_action_step_facts(
                board,
                option,
                step_index=0,
                target=target,
                route_origin=None,
                legality_exact=True,
            )
            if target is board.active:
                projected, reason = _stage2b4_project_board(
                    board, attach_bomb_to_serial=serial, bomb_card=bomb_card
                )
                append_fact_plan(
                    action_kind="deluxe_bomb_attach_active",
                    projected=projected,
                    reason=reason,
                    target_pokemon=target,
                    origin=None,
                    action_count=1,
                    remaining_actions=0,
                    resource_cost=1.0,
                    risk=0.5,
                    action_steps=(attach_step,),
                )
            elif board.pid(target) == BRUXISH:
                for switch_option, route_name, origin, route_resource, route_risk in tuple(switch_entries):
                    projected, reason = _stage2b4_project_board(
                        board,
                        attach_bomb_to_serial=serial,
                        bomb_card=bomb_card,
                        switch_target_serial=serial,
                    )
                    switch_step = _stage2b4_current_action_step_facts(
                        board,
                        switch_option,
                        step_index=1,
                        target=target,
                        route_origin=origin,
                        legality_exact=reason is None,
                    )
                    append_fact_plan(
                        action_kind=f"deluxe_bomb_attach_bench_then_{route_name}",
                        projected=projected,
                        reason=reason,
                        target_pokemon=target,
                        origin=origin,
                        action_count=2,
                        remaining_actions=1,
                        resource_cost=1.0 + route_resource,
                        risk=0.5 + route_risk,
                        action_steps=(attach_step, switch_step),
                    )

    is_surfing_entry = (
        option.type == OptionType.ABILITY
        and policy.outcome.is_surfing_beach_ability(option)
    ) or (option.type == OptionType.PLAY and cid == SURFING_BEACH)
    is_retreat_entry = option.type == OptionType.RETREAT
    is_suguri_play = option.type == OptionType.PLAY and cid == SUGURI
    is_suguri_switch_choice = (
        getattr(getattr(board, "select", None), "context", None) == SelectContext.FIRST_EFFECT
        and getattr(getattr(getattr(board, "select", None), "contextCard", None), "id", None)
        == SUGURI
        and option.type == OptionType.YES
    )
    current_switch_target = (
        target
        if getattr(getattr(board, "select", None), "context", None) == SelectContext.SWITCH
        else None
    )
    route_origin: Optional[ActiveBenchTransitionOrigin] = None
    route_name: Optional[str] = None
    route_reason: Optional[str] = None
    resource_cost = 0.0
    risk = 0.0
    targets: Tuple[Any, ...] = ()
    if is_surfing_entry:
        route_origin = ActiveBenchTransitionOrigin.SURFING_BEACH
        route_name = "surfing_beach"
        targets = tuple(pokemon for pokemon in board.bench if board.pid(pokemon) == BRUXISH)
    elif is_retreat_entry:
        retreat_outcome = policy.outcome.evaluate_retreat(option)
        if retreat_outcome.supported:
            route_origin = ActiveBenchTransitionOrigin.RETREAT
            route_name = "retreat"
            resource_cost = float(retreat_outcome.retreat_energy_cost)
            risk = float(
                retreat_outcome.retreat_energy_cost
                + retreat_outcome.important_energy_loss * 3
            )
            targets = tuple(
                pokemon for pokemon in board.bench if board.pid(pokemon) == BRUXISH
            )
    elif is_suguri_play:
        if not bool(getattr(getattr(board, "state", None), "supporterPlayed", False)):
            route_origin = ActiveBenchTransitionOrigin.SUGURI
            route_name = "suguri"
            resource_cost = 1.0
            risk = 1.5
            targets = tuple(
                pokemon for pokemon in board.bench if board.pid(pokemon) == BRUXISH
            )
    elif is_suguri_switch_choice:
        route_origin = ActiveBenchTransitionOrigin.SUGURI
        route_name = "suguri"
        resource_cost = 1.0
        risk = 1.5
        targets = tuple(pokemon for pokemon in board.bench if board.pid(pokemon) == BRUXISH)
    elif current_switch_target is not None and board.pid(current_switch_target) == BRUXISH:
        effect = policy.effect_id()
        if effect == SURFING_BEACH:
            route_origin = ActiveBenchTransitionOrigin.SURFING_BEACH
            route_name = "surfing_beach_target"
        elif effect == SUGURI:
            route_origin = ActiveBenchTransitionOrigin.SUGURI
            route_name = "suguri_target"
            resource_cost = 1.0
            risk = 1.5
        else:
            route_name = "transition_origin_unresolved"
            route_reason = "stage2b4_counterline_transition_origin_unresolved"
        targets = (current_switch_target,)

    if route_name is not None:
        for bruxish_target in targets:
            serial = getattr(bruxish_target, "serial", None)
            if type(serial) is not int:
                continue
            projected, reason = _stage2b4_project_board(
                board, switch_target_serial=serial, remove_deluxe_bomb_access=True
            )
            first_step = _stage2b4_current_action_step_facts(
                board,
                option,
                step_index=0,
                target=bruxish_target,
                route_origin=route_origin,
                legality_exact=reason is None and route_reason is None,
                unsupported_reason=route_reason,
            )
            append_fact_plan(
                action_kind=route_name,
                projected=projected,
                reason=route_reason or reason,
                target_pokemon=bruxish_target,
                origin=route_origin,
                action_count=1,
                remaining_actions=0,
                resource_cost=resource_cost,
                risk=risk,
                action_steps=(first_step,),
            )
            if route_reason is not None:
                continue
            attach_entry = attach_candidate_by_serial.get(serial)
            future_followup_context = current_switch_target is not None or is_suguri_switch_choice
            attach_legality_proven = attach_entry is not None or future_followup_context
            diagnostic_followup = bool(bombs) and (attach_legality_proven or future_followup_context)
            if not attach_legality_proven and not diagnostic_followup:
                continue
            projected_after_switch, switch_projection_reason = _stage2b4_project_board(
                board,
                switch_target_serial=serial,
            )
            second_step = _stage2b4_projected_bomb_attach_step_facts(
                projected_after_switch,
                step_index=1,
                expected_target_card_id=board.pid(bruxish_target),
                expected_target_serial=serial,
                route_origin=route_origin,
                bomb_card=bomb_card,
                projection_reason=switch_projection_reason,
                attach_legality_proven=attach_legality_proven,
            )
            if second_step.identity_exact and second_step.legality_exact:
                projected_bomb, reason_bomb = _stage2b4_project_board(
                    board,
                    attach_bomb_to_serial=serial,
                    bomb_card=bomb_card,
                    switch_target_serial=serial,
                )
            else:
                projected_bomb = projected_after_switch or projected
                reason_bomb = "stage2b4_counterline_followup_action_identity_unresolved"
            append_fact_plan(
                action_kind=f"{route_name}_then_deluxe_bomb_attach",
                projected=projected_bomb,
                reason=reason_bomb,
                target_pokemon=bruxish_target,
                origin=route_origin,
                action_count=2,
                remaining_actions=1,
                resource_cost=resource_cost + 1.0,
                risk=risk + 0.5,
                action_steps=(first_step, second_step),
            )
    return tuple(plans)

def _stage2b4_counterline_route_kind(
    attack_fact: Stage2b4CounterlineAttackFacts,
) -> Stage2b4CounterlineRouteKind:
    bruxish = attack_fact.bruxish_trigger_confirmed
    bomb = attack_fact.deluxe_bomb_trigger_confirmed
    if bruxish is True and bomb is True and attack_fact.combined_damage_counters == 15:
        return Stage2b4CounterlineRouteKind.DELUXE_BOMB_AND_BRUXISH
    if bruxish is True and bomb is False and attack_fact.combined_damage_counters == 3:
        return Stage2b4CounterlineRouteKind.BRUXISH_ONLY
    if bomb is True and bruxish is False and attack_fact.combined_damage_counters == 12:
        return Stage2b4CounterlineRouteKind.DELUXE_BOMB_ONLY
    return Stage2b4CounterlineRouteKind.UNRESOLVED


def _stage2b4_counterline_action_line_from_attack(
    board: BoardView,
    option: Any,
    option_index: int,
    plan: Stage2b4ActionPlanFacts,
    attack_fact: Stage2b4CounterlineAttackFacts,
) -> Stage2b4CounterlineActionLineFacts:
    route_kind = _stage2b4_counterline_route_kind(attack_fact)
    reasons: List[str] = []
    diagnostic_reasons: List[str] = []
    if plan.unsupported_reason:
        reasons.append(plan.unsupported_reason)
    if attack_fact.unsupported_reason:
        if (
            attack_fact.unsupported_reason
            in _STAGE2B4_COUNTERLINE_FOLLOWUP_LIMITATION_REASONS
        ):
            diagnostic_reasons.append(attack_fact.unsupported_reason)
        else:
            reasons.append(attack_fact.unsupported_reason)

    target_serial = plan.target_serial
    matching_targets = tuple(
        pokemon
        for pokemon in tuple(getattr(board, "all_my_pokemon", ()) or ())
        if getattr(pokemon, "serial", None) == target_serial
    )
    if type(target_serial) is not int or len(matching_targets) != 1:
        reasons.append("stage2b4_counterline_origin_target_identity_unresolved")
    elif board.pid(matching_targets[0]) != plan.target_id:
        reasons.append("stage2b4_counterline_origin_target_card_mismatch")
    if plan.option_type != getattr(option, "type", None):
        reasons.append("stage2b4_counterline_origin_option_type_mismatch")

    action_steps = tuple(getattr(plan, "action_steps", ()) or ())
    if (
        len(action_steps) != plan.action_count
        or tuple(step.step_index for step in action_steps)
        != tuple(range(plan.action_count))
    ):
        reasons.append("stage2b4_counterline_action_step_sequence_unresolved")
    for step in action_steps:
        if not step.identity_exact or not step.legality_exact:
            reasons.append(
                step.unsupported_reason
                or "stage2b4_counterline_action_step_identity_unresolved"
            )
        if (
            step.target_serial != plan.target_serial
            or step.target_card_id != plan.target_id
        ):
            reasons.append("stage2b4_counterline_action_step_target_mismatch")
        if step.current_observation_option:
            if type(step.option_index) is not int:
                reasons.append("stage2b4_counterline_action_step_identity_unresolved")
            else:
                matches = tuple(
                    candidate
                    for index, candidate in board.iter_options()
                    if index == step.option_index
                )
                if len(matches) != 1:
                    reasons.append("stage2b4_counterline_action_step_identity_unresolved")
                else:
                    current = matches[0]
                    if getattr(current, "type", None) != step.option_type:
                        reasons.append("stage2b4_counterline_action_step_identity_unresolved")
                    current_card_id = board.option_card(current)
                    if (
                        step.option_card_id is not None
                        and current_card_id != step.option_card_id
                    ):
                        reasons.append("stage2b4_counterline_action_step_identity_unresolved")
        elif not step.projected_followup_action or step.option_index is not None:
            reasons.append("stage2b4_counterline_followup_action_identity_unresolved")

    if attack_fact.holder_serial != plan.target_serial:
        reasons.append("stage2b4_counterline_holder_serial_mismatch")
    if attack_fact.holder_id != plan.target_id:
        reasons.append("stage2b4_counterline_holder_card_mismatch")
    if (
        getattr(plan, "projected_active_serial", None) != attack_fact.holder_serial
        or getattr(plan, "projected_active_card_id", None) != attack_fact.holder_id
    ):
        reasons.append("stage2b4_counterline_projected_active_holder_mismatch")

    if route_kind == Stage2b4CounterlineRouteKind.UNRESOLVED:
        reasons.append("stage2b4_counterline_trigger_state_unresolved")
    if attack_fact.can_attack_with_current_energy is not True:
        reasons.append(
            "stage2b4_counterline_opponent_attack_payability_unresolved"
            if attack_fact.can_attack_with_current_energy is None
            else "stage2b4_counterline_opponent_attack_non_payable"
        )
    if attack_fact.drednaw_followup_supported is True:
        if type(attack_fact.drednaw_serial) is not int:
            reasons.append("stage2b4_counterline_drednaw_identity_unresolved")
        else:
            drednaw_matches = tuple(
                pokemon
                for pokemon in tuple(getattr(board, "all_my_pokemon", ()) or ())
                if board.pid(pokemon) == DREDNAW
                and getattr(pokemon, "serial", None) == attack_fact.drednaw_serial
            )
            if len(drednaw_matches) != 1:
                reasons.append("stage2b4_counterline_drednaw_identity_unresolved")
            ready_drednaw = tuple(
                fact
                for fact in plan.integrated_facts.drednaw_facts.drednaw_facts
                if fact.hard_crunch_payable is True
                and fact.hard_crunch_damage_now is not None
                and type(fact.drednaw_serial) is int
            )
            if len({fact.drednaw_serial for fact in ready_drednaw}) > 1:
                reasons.append("stage2b4_counterline_multiple_drednaw_followups_unresolved")
    clean = tuple(dict.fromkeys(reason for reason in reasons if reason))
    core_attack_supported = bool(
        attack_fact.supported
        or attack_fact.unsupported_reason
        in _STAGE2B4_COUNTERLINE_FOLLOWUP_LIMITATION_REASONS
    )
    continuity_reasons = {
        "stage2b4_counterline_holder_serial_mismatch",
        "stage2b4_counterline_holder_card_mismatch",
        "stage2b4_counterline_projected_active_holder_mismatch",
        "stage2b4_counterline_action_step_target_mismatch",
    }
    continuity_exact = not any(reason in continuity_reasons for reason in clean)
    transported_route_kind = (
        route_kind if continuity_exact else Stage2b4CounterlineRouteKind.UNRESOLVED
    )
    supported = (
        plan.supported
        and core_attack_supported
        and attack_fact.can_attack_with_current_energy is True
        and transported_route_kind != Stage2b4CounterlineRouteKind.UNRESOLVED
        and len(action_steps) == plan.action_count
        and all(step.identity_exact and step.legality_exact for step in action_steps)
        and not clean
    )
    holder_survives = (
        None
        if attack_fact.holder_knocked_out is None
        else not attack_fact.holder_knocked_out
    )
    combined = (
        True
        if transported_route_kind == Stage2b4CounterlineRouteKind.DELUXE_BOMB_AND_BRUXISH
        else None
        if (
            attack_fact.bruxish_trigger_confirmed is None
            or attack_fact.deluxe_bomb_trigger_confirmed is None
        )
        else False
    )
    return Stage2b4CounterlineActionLineFacts(
        origin_option_index=option_index,
        origin_option_type=plan.option_type,
        origin_option_card_id=plan.card_id,
        origin_target_card_id=plan.target_id,
        origin_target_serial=plan.target_serial,
        action_kind=plan.action_kind,
        route_origin=plan.route_origin,
        action_count=plan.action_count,
        remaining_actions=plan.remaining_actions,
        action_steps=action_steps,
        supported=supported,
        exact=supported,
        route_kind=transported_route_kind,
        opponent_attack_id=attack_fact.attack_id,
        opponent_attacker_card_id=attack_fact.opponent_active_id,
        opponent_attacker_serial=attack_fact.opponent_active_serial,
        holder_card_id=attack_fact.holder_id,
        holder_serial=attack_fact.holder_serial,
        bruxish_trigger_confirmed=attack_fact.bruxish_trigger_confirmed,
        deluxe_bomb_trigger_confirmed=attack_fact.deluxe_bomb_trigger_confirmed,
        combined_trigger_confirmed=combined,
        counter_damage_counters=(
            attack_fact.combined_damage_counters if continuity_exact else None
        ),
        counter_damage_amount=(
            attack_fact.combined_damage_amount if continuity_exact else None
        ),
        attacker_knocked_out=(
            attack_fact.attacker_knocked_out if continuity_exact else None
        ),
        holder_knocked_out=attack_fact.holder_knocked_out,
        holder_survives=holder_survives,
        simultaneous_knockout=attack_fact.simultaneous_knockout,
        drednaw_followup_supported=attack_fact.drednaw_followup_supported,
        drednaw_serial=attack_fact.drednaw_serial,
        drednaw_hard_crunch_damage=attack_fact.drednaw_hard_crunch_damage,
        integrated_facts=plan.integrated_facts,
        unsupported_reason=clean[0] if clean else None,
        reasons=("stage2b4_counterline_action_line_fact", plan.action_kind)
        + tuple(dict.fromkeys(diagnostic_reasons))
        + clean,
    )

def stage2b4_counterline_action_line_collection_facts(
    policy: Any,
    option: Any,
) -> Stage2b4CounterlineActionLineCollectionFacts:
    entries = tuple(policy.b.iter_options())
    indexes = tuple(index for index, candidate in entries if candidate is option)
    if len(indexes) != 1:
        reason = "stage2b4_counterline_origin_option_identity_unresolved"
        return Stage2b4CounterlineActionLineCollectionFacts(
            origin_option_index=None,
            origin_option_type=getattr(option, "type", None),
            origin_option_card_id=policy.b.option_card(option),
            action_plans=(),
            routes=(),
            supported=False,
            exact=False,
            unsupported_reason=reason,
            reasons=(reason,),
        )
    option_index = indexes[0]
    plans = _stage2b4_action_plan_candidates_for_option(policy, option)
    routes: List[Stage2b4CounterlineActionLineFacts] = []
    for plan in plans:
        if plan.integrated_facts is None:
            continue
        for attack_fact in plan.integrated_facts.attack_facts:
            if attack_fact.can_attack_with_current_energy is False:
                continue
            if (
                attack_fact.bruxish_trigger_confirmed is False
                and attack_fact.deluxe_bomb_trigger_confirmed is False
            ):
                continue
            routes.append(
                _stage2b4_counterline_action_line_from_attack(
                    policy.b, option, option_index, plan, attack_fact
                )
            )
    if not plans:
        reason = "stage2b4_counterline_no_fact_only_route"
    elif not routes:
        reason = "stage2b4_counterline_no_trigger_route"
    else:
        reason = None
    supported = bool(routes) and all(route.supported for route in routes)
    exact = supported and all(route.exact for route in routes)
    if routes and not supported and reason is None:
        reason = next(
            (route.unsupported_reason for route in routes if route.unsupported_reason),
            "stage2b4_counterline_route_unresolved",
        )
    return Stage2b4CounterlineActionLineCollectionFacts(
        origin_option_index=option_index,
        origin_option_type=getattr(option, "type", None),
        origin_option_card_id=policy.b.option_card(option),
        action_plans=plans,
        routes=tuple(routes),
        supported=supported,
        exact=exact,
        unsupported_reason=reason,
        reasons=("stage2b4_counterline_action_line_collection",)
        + ((reason,) if reason else ()),
    )


def stage2b4_counterline_action_line_collections(
    policy: Any,
) -> Tuple[Stage2b4CounterlineActionLineCollectionFacts, ...]:
    collections: List[Stage2b4CounterlineActionLineCollectionFacts] = []
    for _, option in policy.b.iter_options():
        collection = stage2b4_counterline_action_line_collection_facts(policy, option)
        if collection.action_plans or collection.routes:
            collections.append(collection)
    return tuple(collections)






def _stage2c_current_attack_state(policy: Policy) -> Tuple[bool, bool, bool]:
    direct_win = False
    direct_ko = False
    non_ko = False
    for _, candidate in policy.b.iter_options():
        if candidate.type != OptionType.ATTACK and candidate.attackId is None:
            continue
        attack_outcome = policy.outcome.evaluate_attack(candidate)
        if not attack_outcome.supported or attack_outcome.blocked:
            continue
        direct_win = direct_win or attack_outcome.wins_game
        direct_ko = direct_ko or attack_outcome.knockout
        non_ko = non_ko or (
            not attack_outcome.wins_game and not attack_outcome.knockout
        )
    return direct_win, direct_ko, non_ko
def _stage2c_bruxish_after_play_counterline_role_live(
    board: BoardView,
    option: Any,
) -> Optional[bool]:
    """Return exact after-PLAY Bruxish counterline liveness, or None if unresolved."""
    if (
        option.type != OptionType.PLAY
        or board.option_card(option) != BRUXISH
        or board.count_in_play(BRUXISH) > 0
    ):
        return False
    contract = _stage2b2a_bruxish_counterattack_contract(board)
    if not contract.supported:
        return False
    projected, played_serial, reason = _stage2b4_project_bruxish_play_board(board, option)
    if projected is None or type(played_serial) is not int:
        if reason in {
            "stage2b4_basic_play_bench_full",
            "stage2b4_basic_play_option_identity_unresolved",
        }:
            return False
        return None

    projected_policy = Policy(projected)
    collections = stage2b4_counterline_action_line_collections(projected_policy)
    unresolved = False
    route_kinds = {
        Stage2b4CounterlineRouteKind.BRUXISH_ONLY,
        Stage2b4CounterlineRouteKind.DELUXE_BOMB_AND_BRUXISH,
    }
    for collection in collections:
        for route in collection.routes:
            if (
                route.holder_card_id != BRUXISH
                or route.holder_serial != played_serial
            ):
                continue
            if (
                route.supported
                and route.exact
                and route.bruxish_trigger_confirmed is True
                and route.route_kind in route_kinds
            ):
                return True
            if (
                route.bruxish_trigger_confirmed is None
                or not route.supported
                or not route.exact
            ):
                unresolved = True
    return None if unresolved else False


def _stage2c_hand_basic_role(
    board: BoardView,
    cid: Optional[int],
    option: Optional[Any] = None,
) -> Tuple[str, Optional[bool], float]:
    if cid == CHEWTLE:
        unevolved = board.count_in_play(CHEWTLE)
        drednaw_in_hand = DREDNAW in board.hand_ids
        drednaw_in_play = board.count_in_play(DREDNAW) > 0
        drednaw_remaining = board.remaining_possible(DREDNAW)
        if unevolved > 0:
            return ("chewtle_duplicate_without_open_line", False, 1000.0)
        if drednaw_in_hand:
            return ("chewtle_drednaw_in_hand", True, 68000.0)
        if drednaw_in_play and drednaw_remaining:
            return ("chewtle_second_drednaw_line", True, 68000.0)
        if not drednaw_in_play and drednaw_remaining:
            return ("chewtle_drednaw_remaining", True, 56000.0)
        return ("chewtle_no_drednaw_access", False, 1000.0)
    if cid == BRUXISH:
        if board.count_in_play(BRUXISH) > 0:
            return ("bruxish_already_in_play", False, 1000.0)
        contract = _stage2b2a_bruxish_counterattack_contract(board)
        if not contract.supported:
            return ("bruxish_counterline_contract_unavailable", False, 1000.0)
        if option is None:
            return ("bruxish_counterline_role_unknown", None, 1000.0)
        role_live = _stage2c_bruxish_after_play_counterline_role_live(board, option)
        if role_live is True:
            return ("bruxish_counterline_board_supply", True, 62000.0)
        if role_live is False:
            return ("bruxish_counterline_not_live", False, 1000.0)
        return ("bruxish_counterline_role_unknown", None, 1000.0)
    return ("not_stage2c_basic", False, 1000.0)
def hand_basic_deployment_facts(
    policy: Policy,
    option: Any,
    outcome: ImmediateOutcome,
) -> HandBasicDeploymentFacts:
    board = policy.b
    option_index = next(
        (index for index, candidate in board.iter_options() if candidate is option),
        None,
    )
    cid = board.option_card(option)
    in_hand = cid in board.hand_ids if cid is not None else False
    legal = bool(
        option.type == OptionType.PLAY
        and cid in {CHEWTLE, BRUXISH}
        and in_hand
        and board.is_basic_pokemon(cid)
        and board.bench_space > 0
        and outcome.supported
        and not outcome.blocked
    )
    direct_win, direct_ko, non_ko = _stage2c_current_attack_state(policy)
    role, role_live, role_value = _stage2c_hand_basic_role(board, cid, option)
    same_count = board.count_in_play(cid) if cid is not None else 0
    drednaw_in_hand = DREDNAW in board.hand_ids
    drednaw_in_play = board.count_in_play(DREDNAW) > 0
    drednaw_remaining = board.remaining_possible(DREDNAW)
    accessible = (
        board.hand_ids.count(DREDNAW)
        + board.count_in_play(DREDNAW)
        + board.remaining_possible_count(DREDNAW)
    )
    duplicate = bool(
        (cid == BRUXISH and same_count > 0)
        or (cid == CHEWTLE and same_count > 0)
    )
    higher = False
    if legal and board.bench_space == 1:
        for _, candidate in board.iter_options():
            if candidate is option or candidate.type != OptionType.PLAY:
                continue
            other_id = board.option_card(candidate)
            if (
                other_id is None
                or other_id not in board.hand_ids
                or not board.is_basic_pokemon(other_id)
            ):
                continue
            if other_id in {CHEWTLE, BRUXISH}:
                other_value = _stage2c_hand_basic_role(board, other_id, candidate)[2]
            else:
                other_value = policy.score_pokemon_play(other_id)
            if other_value > role_value:
                higher = True
                break
    reserved = board.bench_space == 1 and higher
    high_value = bool(
        legal and role_live and not duplicate and not reserved
        and not direct_win and not direct_ko
    )
    reason = None
    if cid not in {CHEWTLE, BRUXISH}:
        reason = "stage2c_not_target_basic"
    elif not in_hand:
        reason = "stage2c_play_option_not_in_hand"
    elif not legal:
        reason = "stage2c_basic_play_not_legal"
    return HandBasicDeploymentFacts(
        supported=legal,
        option_index=option_index,
        card_id=cid,
        card_is_in_hand=in_hand,
        legal_basic_play=legal,
        bench_space_before=board.bench_space,
        bench_count_before=len(board.bench),
        same_card_in_play_count=same_count,
        duplicate_deployment=duplicate,
        current_direct_win_exists=direct_win,
        current_direct_knockout_exists=direct_ko,
        current_non_ko_attack_exists=non_ko,
        role=role,
        chewtle_line_live=role_live if cid == CHEWTLE else None,
        drednaw_in_hand=drednaw_in_hand,
        drednaw_in_play=drednaw_in_play,
        drednaw_remaining_possible=drednaw_remaining,
        accessible_drednaw_line_count=accessible,
        bruxish_counterline_role_live=role_live if cid == BRUXISH else None,
        bruxish_already_in_play=board.count_in_play(BRUXISH) > 0,
        higher_priority_basic_exists=higher,
        reserved_last_bench_slot=reserved,
        high_value_deployment=high_value,
        unsupported_reason=reason,
        reasons=(role,),
    )
def stage2c_strategic_action_line_collection_facts(
    policy: Policy,
    results: Sequence[SimulationResult],
    *,
    current_position: Optional[ActivePositionCurrentLineCollectionFacts] = None,
    counterline_collections: Optional[
        Sequence[Stage2b4CounterlineActionLineCollectionFacts]
    ] = None,
) -> Stage2cStrategicActionLineCollectionFacts:
    """Build Stage2c preparation Lines as shadow Facts without ranking actions."""
    board = policy.b
    current = (
        active_position_current_line_facts(board, results)
        if current_position is None
        else current_position
    )
    counterlines = tuple(
        stage2b4_counterline_action_line_collections(policy)
        if counterline_collections is None
        else counterline_collections
    )
    entries = tuple(board.iter_options())
    result_by_index = {result.index: result for result in results}

    def current_state() -> Tuple[Optional[bool], Optional[bool], Optional[bool]]:
        if not current.supported or not current.exact:
            return None, None, None
        lines = current.candidate_lines
        if not lines:
            return False, False, False
        if any(
            line.terminal_win is None or line.opponent_active_ko is None
            for line in lines
        ):
            return None, None, None
        direct_win = any(line.terminal_win is True for line in lines)
        direct_ko = any(
            line.terminal_win is not True and line.opponent_active_ko is True
            for line in lines
        )
        non_ko = any(
            line.terminal_win is False and line.opponent_active_ko is False
            for line in lines
        )
        return direct_win, direct_ko, non_ko

    direct_win, direct_ko, non_ko = current_state()

    def current_attack_identity(
        lines: Sequence[ActivePositionCurrentAttackLineFacts],
    ) -> Tuple[Tuple[int, ...], Tuple[int, ...], Optional[str]]:
        option_indexes: List[int] = []
        attack_ids: List[int] = []
        for line in lines:
            if (
                not line.supported
                or not line.exact
                or type(line.attack_option_index) is not int
                or type(line.attack_id) is not int
            ):
                return (), (), "stage2c_current_attack_identity_unresolved"
            option_indexes.append(line.attack_option_index)
            attack_ids.append(line.attack_id)
        return (
            tuple(dict.fromkeys(option_indexes)),
            tuple(dict.fromkeys(attack_ids)),
            None,
        )

    def objective_basic_indexes(origin_index: int) -> Tuple[int, ...]:
        if board.bench_space <= 0:
            return ()
        out: List[int] = []
        for index, candidate in entries:
            if index == origin_index or candidate.type != OptionType.PLAY:
                continue
            cid = board.option_card(candidate)
            if (
                type(cid) is int
                and cid in board.hand_ids
                and board.is_basic_pokemon(cid)
            ):
                out.append(index)
        return tuple(out)

    def basic_role_fields(cid: Optional[int], option: Any) -> Tuple[
        Optional[str], Optional[bool], Optional[bool], Optional[bool],
        Optional[int], Optional[bool], Optional[bool], Optional[bool],
        Optional[int], Optional[bool],
    ]:
        same_count = board.count_in_play(cid) if type(cid) is int else None
        duplicate = None if same_count is None else same_count > 0
        drednaw_in_hand = DREDNAW in board.hand_ids
        drednaw_in_play = board.count_in_play(DREDNAW) > 0
        drednaw_remaining = board.remaining_possible(DREDNAW)
        accessible = (
            board.hand_ids.count(DREDNAW)
            + board.count_in_play(DREDNAW)
            + board.remaining_possible_count(DREDNAW)
        )
        if cid == CHEWTLE:
            if duplicate:
                role = "chewtle_duplicate_without_open_line"
            elif drednaw_in_hand:
                role = "chewtle_drednaw_in_hand"
            elif drednaw_in_play and drednaw_remaining:
                role = "chewtle_second_drednaw_line"
            elif not drednaw_in_play and drednaw_remaining:
                role = "chewtle_drednaw_remaining"
            else:
                role = "chewtle_no_drednaw_access"
            bruxish_already = None
            bruxish_contract_supported = None
            bruxish_role = None
        elif cid == BRUXISH:
            bruxish_already = board.count_in_play(BRUXISH) > 0
            contract = _stage2b2a_bruxish_counterattack_contract(board)
            bruxish_contract_supported = bool(contract.supported)
            role, bruxish_role, _ = _stage2c_hand_basic_role(board, cid, option)
        else:
            role = "ordinary_basic"
            bruxish_already = None
            bruxish_contract_supported = None
            bruxish_role = None
        return (
            role,
            duplicate,
            drednaw_in_hand,
            drednaw_in_play,
            accessible,
            bruxish_already,
            bruxish_contract_supported,
            bruxish_role,
            same_count,
            drednaw_remaining,
        )

    def make_line(
        *,
        origin_index: int,
        option: Any,
        kind: Stage2cStrategicActionLineKind,
        attack_lines: Sequence[ActivePositionCurrentAttackLineFacts],
        target_card_id: Optional[int] = None,
        target_serial: Optional[int] = None,
        current_attack_is_nonwinning_ko: Optional[bool] = None,
        attack_preserved_after_origin: Optional[bool] = None,
        continuation_confirmed: Optional[bool] = None,
        blocking_high_value_evolution_exists: Optional[bool] = None,
        blocking_high_value_evolution_option_indices: Tuple[int, ...] = (),
        evolution_relation_exact: Optional[bool] = None,
        supported: bool = True,
        reason: Optional[str] = None,
        extra_reasons: Tuple[str, ...] = (),
    ) -> Stage2cStrategicActionLineFacts:
        cid = board.option_card(option)
        attack_indexes, attack_ids, attack_reason = current_attack_identity(attack_lines)
        if supported and attack_reason is not None:
            supported = False
            reason = attack_reason
        continuation_indexes = attack_indexes if continuation_confirmed is True else ()
        continuation_ids = attack_ids if continuation_confirmed is True else ()
        (
            role, duplicate, dred_in_hand, dred_in_play, accessible,
            brux_already, brux_contract_supported, brux_role,
            same_count, dred_remaining,
        ) = basic_role_fields(cid, option)
        is_basic_origin = kind in {
            Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY,
            Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT,
        }
        return Stage2cStrategicActionLineFacts(
            origin_option_index=origin_index,
            origin_option_type=getattr(option, "type", None),
            origin_option_card_id=cid,
            origin_target_card_id=target_card_id,
            origin_target_serial=target_serial,
            action_line_kind=kind,
            current_attack_lines=tuple(attack_lines),
            current_attack_option_index=(attack_indexes[0] if len(attack_indexes) == 1 else None),
            current_attack_id=(attack_ids[0] if len(attack_ids) == 1 else None),
            continuation_attack_option_indices=continuation_indexes,
            continuation_attack_ids=continuation_ids,
            continuation_confirmed=continuation_confirmed,
            current_attack_is_nonwinning_ko=current_attack_is_nonwinning_ko,
            attack_preserved_after_origin=attack_preserved_after_origin,
            current_direct_win_exists=direct_win,
            current_direct_knockout_exists=direct_ko,
            current_non_ko_attack_exists=non_ko,
            bench_space_before=board.bench_space if is_basic_origin else None,
            bench_count_before=len(board.bench) if is_basic_origin else None,
            bench_slot_consumed=(board.bench_space > 0) if is_basic_origin else None,
            other_legal_basic_option_indices=(
                objective_basic_indexes(origin_index) if is_basic_origin else ()
            ),
            same_card_in_play_count=same_count if is_basic_origin else None,
            duplicate_deployment=duplicate if is_basic_origin else None,
            role=role if is_basic_origin else "evolution_continuation",
            chewtle_drednaw_in_hand=(dred_in_hand if cid == CHEWTLE else None),
            drednaw_in_play=(dred_in_play if cid == CHEWTLE else None),
            drednaw_remaining_possible=(dred_remaining if cid == CHEWTLE else None),
            accessible_drednaw_line_count=(accessible if cid == CHEWTLE else None),
            bruxish_already_in_play=(brux_already if cid == BRUXISH else None),
            bruxish_counterattack_contract_supported=(
                brux_contract_supported if cid == BRUXISH else None
            ),
            bruxish_counterline_role_live=(brux_role if cid == BRUXISH else None),
            blocking_high_value_evolution_exists=(
                blocking_high_value_evolution_exists
                if kind == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT
                else None
            ),
            blocking_high_value_evolution_option_indices=(
                blocking_high_value_evolution_option_indices
                if kind == Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT
                else ()
            ),
            evolution_relation_exact=evolution_relation_exact,
            supported=supported,
            exact=supported,
            unsupported_reason=(None if supported else reason or "stage2c_strategic_line_unresolved"),
            reasons=("stage2c_strategic_action_line", kind.value) + extra_reasons
            + (() if supported else (reason or "stage2c_strategic_line_unresolved",)),
        )

    def hand_blocking_high_value_evolution_facts() -> Tuple[Optional[bool], Tuple[int, ...]]:
        if (
            not current.supported
            or not current.exact
            or direct_win is None
            or direct_ko is None
            or non_ko is None
        ):
            return None, ()
        if direct_win is not False or direct_ko is not False or non_ko is not True:
            return None, ()
        evolution_option_indexes = tuple(
            option_index
            for option_index, option in entries
            if option.type == OptionType.EVOLVE
        )
        legal_evolutions = current_legal_evolution_options(policy)
        legal_evolution_indexes = tuple(
            option_index for option_index, _, _, _ in legal_evolutions
        )
        if set(legal_evolution_indexes) != set(evolution_option_indexes):
            return None, ()
        high_value_indexes = tuple(
            dict.fromkeys(
                option_index
                for option_index, evolution_option, _, _ in legal_evolutions
                if _stage2c_existing_high_value_evolution(policy, evolution_option)
            )
        )
        return bool(high_value_indexes), high_value_indexes

    blocking_high_value_evolution_exists, blocking_high_value_evolution_option_indices = (
        hand_blocking_high_value_evolution_facts()
    )

    lines: List[Stage2cStrategicActionLineFacts] = []
    current_lines = tuple(current.candidate_lines)

    # SAFE_PRE_KO_BASIC_PLAY: preserve every exact tied non-winning KO identity.
    ko_lines = tuple(
        line for line in current_lines
        if line.supported and line.exact
        and line.terminal_win is False
        and line.opponent_active_ko is True
    )
    for origin_index, option in entries:
        if option.type != OptionType.PLAY:
            continue
        cid = board.option_card(option)
        result = result_by_index.get(origin_index)
        is_basic = type(cid) is int and board.is_basic_pokemon(cid)
        safe_shape = bool(
            is_basic
            and result is not None
            and result.option is option
            and result.outcome.supported
            and not result.outcome.blocked
            and result.outcome.adds_board_out_buffer
            and len(board.bench) == 0
            and board.bench_space > 0
        )
        if safe_shape and direct_win is not True and ko_lines:
            preservation: List[bool] = []
            for attack_line in ko_lines:
                matches = tuple(
                    candidate for index, candidate in entries
                    if index == attack_line.attack_option_index
                    and candidate.type == OptionType.ATTACK
                    and getattr(candidate, "attackId", None) == attack_line.attack_id
                )
                preservation.append(
                    len(matches) == 1
                    and policy._basic_play_preserves_current_knockout(option, matches[0])
                )
            preserved = bool(preservation) and all(preservation)
            lines.append(make_line(
                origin_index=origin_index,
                option=option,
                kind=Stage2cStrategicActionLineKind.SAFE_PRE_KO_BASIC_PLAY,
                attack_lines=ko_lines,
                current_attack_is_nonwinning_ko=True,
                attack_preserved_after_origin=preserved,
                continuation_confirmed=preserved,
                supported=preserved,
                reason=None if preserved else "stage2c_safe_pre_ko_attack_not_preserved",
                extra_reasons=("nonwinning_ko_attack",),
            ))

        if cid not in {CHEWTLE, BRUXISH}:
            continue
        legal = bool(
            type(cid) is int
            and cid in board.hand_ids
            and board.is_basic_pokemon(cid)
            and board.bench_space > 0
            and result is not None
            and result.option is option
            and result.outcome.supported
            and not result.outcome.blocked
        )
        reason = None if legal else "stage2c_hand_basic_deployment_not_exact"
        hand_continuation: Optional[bool] = None
        if legal and current.supported and current.exact:
            if direct_win is None or direct_ko is None or non_ko is None:
                hand_continuation = None
            elif direct_win or direct_ko or non_ko is not True:
                hand_continuation = False
            else:
                preservation: List[bool] = []
                for attack_line in current_lines:
                    if (
                        not attack_line.supported
                        or not attack_line.exact
                        or attack_line.terminal_win is not False
                        or attack_line.opponent_active_ko is not False
                        or type(attack_line.attack_option_index) is not int
                        or type(attack_line.attack_id) is not int
                    ):
                        preservation.append(False)
                        continue
                    matches = tuple(
                        candidate for index, candidate in entries
                        if index == attack_line.attack_option_index
                        and candidate.type == OptionType.ATTACK
                        and getattr(candidate, "attackId", None) == attack_line.attack_id
                    )
                    preservation.append(
                        len(matches) == 1
                        and policy._basic_play_preserves_current_knockout(
                            option, matches[0]
                        )
                    )
                hand_continuation = bool(preservation) and all(preservation)
        lines.append(make_line(
            origin_index=origin_index,
            option=option,
            kind=Stage2cStrategicActionLineKind.HAND_BASIC_DEPLOYMENT,
            attack_lines=current_lines,
            attack_preserved_after_origin=hand_continuation,
            continuation_confirmed=hand_continuation,
            blocking_high_value_evolution_exists=blocking_high_value_evolution_exists,
            blocking_high_value_evolution_option_indices=(
                blocking_high_value_evolution_option_indices
            ),
            supported=legal and current.supported and current.exact,
            reason=(reason if not legal else current.unsupported_reason),
            extra_reasons=(
                "objective_deployment_facts",
                "current_nonko_attack_continuation_exact"
                if hand_continuation is True
                else "current_nonko_attack_continuation_not_proven",
            ),
        ))

    def evolution_preserves_current_attack(
        option: Any,
        target: Any,
        attack_lines: Sequence[ActivePositionCurrentAttackLineFacts],
    ) -> bool:
        target_id = board.pid(target) if target is not None else None
        target_serial = getattr(target, "serial", None) if target is not None else None
        if type(target_id) is not int or type(target_serial) is not int:
            return False
        bench_matches = tuple(
            pokemon
            for pokemon in tuple(board.bench)
            if getattr(pokemon, "serial", None) == target_serial
            and board.pid(pokemon) == target_id
        )
        board_matches = tuple(
            pokemon
            for pokemon in tuple(board.all_my_pokemon)
            if getattr(pokemon, "serial", None) == target_serial
            and board.pid(pokemon) == target_id
        )
        active = getattr(board, "active", None)
        if (
            len(bench_matches) != 1
            or len(board_matches) != 1
            or bench_matches[0] is not board_matches[0]
            or active is target
            or (
                active is not None
                and getattr(active, "serial", None) == target_serial
                and board.pid(active) == target_id
            )
        ):
            return False

        changed_state_markers = (
            "your hand",
            "cards in your hand",
            "your benched pokemon",
            "pokemon on your bench",
            "your bench",
            "your pokemon in play",
            "pokemon you have in play",
            "number of your pokemon",
            "evolved pokemon",
            "evolution pokemon",
            "basic pokemon",
            "stage 1",
            "stage 2",
        )
        preservation: List[bool] = []
        for attack_line in attack_lines:
            if (
                not attack_line.supported
                or not attack_line.exact
                or attack_line.terminal_win is not False
                or attack_line.opponent_active_ko is not False
                or type(attack_line.attack_option_index) is not int
                or type(attack_line.attack_id) is not int
            ):
                preservation.append(False)
                continue
            matches = tuple(
                candidate
                for index, candidate in entries
                if index == attack_line.attack_option_index
                and candidate.type == OptionType.ATTACK
                and getattr(candidate, "attackId", None) == attack_line.attack_id
            )
            if len(matches) != 1:
                preservation.append(False)
                continue
            attack = board.attack(attack_line.attack_id)
            if attack is None:
                preservation.append(False)
                continue
            text = _normalized_attack_text(attack)
            preservation.append(
                not any(marker in text for marker in changed_state_markers)
            )
        return bool(preservation) and all(preservation)

    legal_evolutions = current_legal_evolution_options(policy)

    # EVOLUTION_CONTINUATION: exact legal Stage2c bench evolution only.
    for origin_index, option in entries:
        if option.type != OptionType.EVOLVE:
            continue
        evolution_id = board.option_card(option)
        target = board.option_target(option)
        target_id = board.pid(target) if target is not None else None
        target_serial = getattr(target, "serial", None) if target is not None else None
        if target_id not in {CHEWTLE, BRUXISH}:
            continue
        legal_matches = tuple(
            (index, candidate, legal_target_id, legal_target_serial)
            for index, candidate, legal_target_id, legal_target_serial in legal_evolutions
            if index == origin_index
            and candidate is option
            and legal_target_id == target_id
            and legal_target_serial == target_serial
        )
        identity_exact = bool(
            type(evolution_id) is int
            and type(target_id) is int
            and type(target_serial) is int
            and len(legal_matches) == 1
            and len(tuple(
                pokemon for pokemon in board.all_my_pokemon
                if getattr(pokemon, "serial", None) == target_serial
                and board.pid(pokemon) == target_id
            )) == 1
        )
        relation_exact = bool(
            identity_exact
            and board.evolves_from(evolution_id, target)
            and board.deck_evolution_for_base(target_id) == evolution_id
        )
        state_exact = (
            direct_win is not None and direct_ko is not None and non_ko is not None
        )
        supported = bool(
            identity_exact
            and relation_exact
            and state_exact
            and direct_win is False
            and direct_ko is False
            and non_ko is True
            and current.supported
            and current.exact
        )
        continuation = False
        if supported:
            continuation = evolution_preserves_current_attack(
                option, target, current_lines
            )
        reason = None
        if not identity_exact:
            reason = "stage2c_evolution_origin_identity_unresolved"
        elif not relation_exact:
            reason = "stage2c_evolution_relation_unresolved"
        elif not state_exact:
            reason = "stage2c_current_attack_state_unresolved"
        elif direct_win or direct_ko or non_ko is not True:
            reason = "stage2c_evolution_continuation_attack_state_not_applicable"
        lines.append(make_line(
            origin_index=origin_index,
            option=option,
            kind=Stage2cStrategicActionLineKind.EVOLUTION_CONTINUATION,
            attack_lines=current_lines,
            target_card_id=target_id,
            target_serial=target_serial if type(target_serial) is int else None,
            evolution_relation_exact=relation_exact if identity_exact else None,
            attack_preserved_after_origin=continuation if supported else False,
            continuation_confirmed=continuation if supported else False,
            supported=supported,
            reason=reason,
            extra_reasons=(
                "deck_evolution_relation",
                "bench_evolution_current_attack_continuation_exact"
                if continuation
                else "bench_evolution_current_attack_continuation_not_proven",
            ),
        ))

    supported = bool(lines) and all(line.supported for line in lines)
    exact = supported and all(line.exact for line in lines)
    reason = next(
        (line.unsupported_reason for line in lines if line.unsupported_reason),
        None,
    )
    if not lines:
        reason = "stage2c_no_strategic_action_line_origin"
    return Stage2cStrategicActionLineCollectionFacts(
        current_position=current,
        counterline_collections=counterlines,
        lines=tuple(lines),
        supported=supported,
        exact=exact,
        unsupported_reason=reason,
        reasons=("stage2c_strategic_action_line_collection",)
        + ((reason,) if reason else ()),
    )


def current_legal_evolution_options(
    policy: Policy,
) -> Tuple[Tuple[int, Any, int, int], ...]:
    out = []
    for option_index, option in policy.b.iter_options():
        if option.type != OptionType.EVOLVE:
            continue
        evolution_id = policy.b.option_card(option)
        target = policy.b.option_target(option)
        target_id = policy.b.pid(target) if target is not None else None
        target_serial = getattr(target, "serial", None) if target is not None else None
        if (
            type(evolution_id) is not int
            or type(target_id) is not int
            or type(target_serial) is not int
        ):
            continue
        matches = [
            pokemon
            for pokemon in policy.b.all_my_pokemon
            if getattr(pokemon, "serial", None) == target_serial
        ]
        if (
            len(matches) != 1
            or policy.b.pid(matches[0]) != target_id
            or not policy.b.evolves_from(evolution_id, matches[0])
        ):
            continue
        out.append((option_index, option, target_id, target_serial))
    return tuple(out)


def _stage2c_is_line_continuation_evolution(
    policy: Policy,
    option: Any,
    target_id: int,
) -> bool:
    evolution_id = policy.b.option_card(option)
    return bool(
        target_id in {CHEWTLE, BRUXISH}
        and type(evolution_id) is int
        and policy.b.deck_evolution_for_base(target_id) == evolution_id
    )


def _stage2c_existing_high_value_evolution(
    policy: Policy,
    option: Any,
) -> bool:
    legacy_score = policy.score_evolve(option)
    outcome = policy.outcome.evaluate_active_evolution(option)
    if outcome.supported and not outcome.blocked and (
        outcome.wins_game
        or outcome.knockout
        or outcome.reachable_wins_game
        or outcome.reachable_knockout
    ):
        return True
    if policy.active_evolution_has_clear_attack_improvement(option):
        return True
    return policy.is_high_value_attack_preserving_prep(option, legacy_score)


def _stage2c_existing_evolution_precedes_deployment(
    policy: Policy,
    evolution_option: Any,
    deployment_legacy_score: float,
    current_non_ko_attack_exists: bool,
) -> bool:
    if current_non_ko_attack_exists:
        return _stage2c_existing_high_value_evolution(
            policy,
            evolution_option,
        )
    return (
        policy.score_evolve(evolution_option)
        > deployment_legacy_score
    )







# ============================================================
# Non-mutating candidate ordering
# ============================================================
class GameSimulator:
    def __init__(self, board: BoardView, policy: Optional[Policy] = None):
        self.b = board
        self.policy = policy or Policy(board)
        self.outcome = self.policy.outcome

    def rank_options(self) -> List[SimulationResult]:
        results = [
            self.evaluate_candidate(index, option)
            for index, option in self.b.iter_options()
        ]
        results, _ = apply_phase5_confirmed_live_results(
            self.b,
            results,
        )
        strategic_policy = getattr(self, "policy", None)
        strategic_facts: Optional[Phase5StrategicLiveFacts] = None
        if strategic_policy is not None:
            results, strategic_facts = apply_phase5_strategic_live_results(
                self.b,
                results,
                strategic_policy,
            )
        end_result = next(
            (
                result
                for result in results
                if result.option.type == OptionType.END
            ),
            None,
        )
        ranked = tuple(sorted(
            results,
            key=lambda result: self._rank_result_key(result, end_result),
            reverse=True,
        ))
        if strategic_facts is not None:
            ranked, _ = apply_phase4ex_preference_ordering(
                self.b,
                ranked,
                strategic_facts,
            )
        return list(ranked)

    def evaluate_candidate(self, index: int, option: Any) -> SimulationResult:
        score = self.policy.score(index, option)
        raw_outcome = self._outcome_for(option)
        outcome = self.policy.resolved_outcome_for_option(
            option,
            raw_outcome,
        )
        if hasattr(self.policy, "action_score"):
            action_score = self.policy.action_score(option, score, outcome)
        else:
            action_score = ActionScore(self._legacy_action_tier(score), legacy=score)
        return SimulationResult(
            index=index,
            option=option,
            policy_score=score,
            tier=self._tier(score),
            outcome=outcome,
            action_score=action_score,
        )

    def _outcome_for(self, option: Any) -> ImmediateOutcome:
        if option.type == OptionType.ATTACK or option.attackId is not None:
            return self.outcome.evaluate_attack(option)
        if option.type == OptionType.ABILITY and self.outcome.is_surfing_beach_ability(option):
            return self.outcome.evaluate_surfing_beach_ability(option)
        if option.type == OptionType.ATTACH:
            return self.outcome.evaluate_attach(option)
        if option.type == OptionType.RETREAT:
            return self.outcome.evaluate_retreat(option)
        if option.type == OptionType.EVOLVE:
            return self.outcome.evaluate_active_evolution(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == ENERGY_SWITCH:
            return self.outcome.evaluate_energy_switch_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == TOOL_SCRAPPER:
            return self.outcome.evaluate_tool_scrapper_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == SALVATORE:
            return self.outcome.evaluate_salvatore_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == WALLY_COMPASSION:
            return self.outcome.evaluate_wally_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == POKEGEAR:
            return self.outcome.evaluate_pokegear_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == POKE_PAD:
            return self.outcome.evaluate_poke_pad_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == BEFEHL_VON_BOSS:
            return self.outcome.evaluate_boss_play(option)
        if option.type == OptionType.PLAY and self.b.option_card(option) == SUGURI:
            return self.outcome.evaluate_suguri_damage_boost()
        if (
            option.type == OptionType.PLAY
            and self.b.is_basic_pokemon(
                self.b.option_card(option)
            )
        ):
            return (
                self.outcome.evaluate_basic_pokemon_play(
                    option
                )
            )
        if (
            option.type == OptionType.NO
            and self.b.select.context == SelectContext.FIRST_EFFECT
            and getattr(self.b.select.contextCard, "id", None) == SUGURI
        ):
            return self.outcome.evaluate_suguri_damage_boost()

        target = self.b.option_target(option)
        if target is not None:
            effect = self.policy.effect_id()
            if effect == SALVATORE:
                return self.outcome.evaluate_salvatore_target(target)
            if effect == WALLY_COMPASSION:
                return self.outcome.evaluate_wally_target(target)
            if effect == TOOL_SCRAPPER:
                return self.outcome.evaluate_tool_scrapper_target(target, option.toolIndex)
            if effect == BEFEHL_VON_BOSS:
                return self.outcome.evaluate_boss_target(target)
            if effect == SUGURI:
                return self.outcome.evaluate_switch_target(target, "suguri")
            if effect == SURFING_BEACH or self.b.select.context == SelectContext.SWITCH:
                source = "surfing_beach" if effect == SURFING_BEACH else "retreat"
                return self.outcome.evaluate_switch_target(target, source)
            if self.b.select.context == SelectContext.DAMAGE:
                return self.outcome.evaluate_attack_effect_target(option)
        cid = self.b.option_card(option)
        if cid is not None and self.policy.effect_id() == SALVATORE:
            return self.outcome.evaluate_salvatore_evolution_candidate(option)
        if cid is not None and self.policy.effect_id() == POKEGEAR:
            return self.outcome.evaluate_pokegear_candidate(option)
        if cid is not None and self.policy.effect_id() == POKE_PAD:
            return self.outcome.evaluate_poke_pad_candidate(option)
        return ImmediateOutcome(supported=False, reasons=("simulator_no_immediate_outcome",))

    def _tier(self, score: float) -> str:
        if score <= SCORE_FORBIDDEN // 2:
            return "forbidden"
        if score >= SCORE_FORCED:
            return "forced"
        if score >= SCORE_PREFERRED:
            return "preferred"
        return "normal"

    def _legacy_action_tier(self, score: float) -> int:
        if score <= SCORE_FORBIDDEN // 2:
            return TIER_FORBIDDEN
        if score >= SCORE_FORCED:
            return TIER_WIN
        if score >= SCORE_PREFERRED:
            return TIER_HIGH_VALUE_PREP
        if score <= SCORE_LAST_RESORT:
            return TIER_BLOCKED_OR_BAD_ACTION
        return TIER_LOW_VALUE_ACTION

    def _rank_result_key(self, result: SimulationResult, end_result: Optional[SimulationResult]) -> Tuple[Any, ...]:
        if self._retreat_supported_only_loses_to_end(result, end_result):
            outcome = result.outcome
            action = result.action_score
            return (
                action.tier,
                action.immediate,
                action.pressure,
                action.development,
                action.resource,
                -action.risk,
                False,
                outcome.wins_game,
                outcome.knockout,
                outcome.prizes_taken,
                not outcome.blocked,
                outcome.enables_knockout,
                outcome.enables_attack,
                outcome.improves_damage,
                outcome.damage,
                -outcome.important_energy_loss,
                -outcome.retreat_energy_cost,
                action.legacy,
                -result.index,
            )
        return self._result_key(result)

    def _retreat_supported_only_loses_to_end(
        self,
        result: SimulationResult,
        end_result: Optional[SimulationResult],
    ) -> bool:
        if end_result is None or result.option.type != OptionType.RETREAT:
            return False
        action = result.action_score
        end_action = end_result.action_score
        if (
            action.tier,
            action.immediate,
            action.pressure,
            action.development,
            action.resource,
            -action.risk,
        ) != (
            end_action.tier,
            end_action.immediate,
            end_action.pressure,
            end_action.development,
            end_action.resource,
            -end_action.risk,
        ):
            return False
        if result.policy_score >= end_result.policy_score:
            return False
        return not self._retreat_has_clear_immediate_benefit(result.outcome)

    def _retreat_has_clear_immediate_benefit(self, outcome: ImmediateOutcome) -> bool:
        if (
            outcome.reachable_wins_game
            or outcome.reachable_knockout
            or outcome.reachable_prizes_taken > 0
            or outcome.reachable_attack_id is not None
            or outcome.enables_knockout
            or outcome.enables_attack
            or outcome.improves_damage
            or outcome.damage > 0
            or outcome.wins_game
            or outcome.knockout
            or outcome.prizes_taken > 0
        ):
            return True
        benefit_reasons = {
            "status_clear",
            "retreat_clears_status",
            "retreat_enables_attack",
            "retreat_improves_damage",
            "switch_enables_knockout",
            "switch_enables_win",
            "bypasses_ex_wall",
            "avoids_wall",
        }
        return any(reason in benefit_reasons for reason in outcome.reasons)

    def _result_key(self, result: SimulationResult) -> Tuple[Any, ...]:
        outcome = result.outcome
        action = result.action_score
        return (
            action.tier,
            action.immediate,
            action.pressure,
            action.development,
            action.resource,
            -action.risk,
            outcome.supported,
            outcome.wins_game,
            outcome.knockout,
            outcome.prizes_taken,
            not outcome.blocked,
            outcome.enables_knockout,
            outcome.enables_attack,
            outcome.improves_damage,
            outcome.damage,
            -outcome.important_energy_loss,
            -outcome.retreat_energy_cost,
            action.legacy,
            -result.index,
        )


# ============================================================
# Action selection
# ============================================================
def choose_indices(board: BoardView) -> List[int]:
    ranked = GameSimulator(board).rank_options()
    if not ranked:
        return []
    minimum = safe_int(board.select.minCount)
    maximum = safe_int(board.select.maxCount)
    if maximum <= 0:
        maximum = 1
    if (
        board.select.context == SelectContext.DISCARD_TOOL_CARD
        and card_id(board.select.effect) == TOOL_SCRAPPER
    ):
        chosen = [
            result.index
            for result in ranked
            if result.policy_score > SCORE_FORBIDDEN // 2
        ][:maximum]
        board.record_tool_scrapper_selections(chosen)
        return sorted(chosen)
    if maximum == 1:
        return [ranked[0].index]
    chosen = [result.index for result in ranked if result.policy_score > SCORE_FORBIDDEN // 2][:maximum]
    if len(chosen) < minimum:
        chosen = [result.index for result in ranked[:minimum]]
    return sorted(chosen)


def agent(obs, config=None):
    if not isinstance(obs, Observation):
        obs = to_observation_class(obs)
    if obs.select is None:
        _reset_current_turn_supporter_tracking()
        _reset_tool_scrapper_selection_tracking()
        return list(DECK)
    if obs.current is None:
        _reset_current_turn_supporter_tracking()
        _reset_tool_scrapper_selection_tracking()
        return []
    board = BoardView(obs)
    return choose_indices(board)
